."}, [80]={hint="루잔에게 악마의 하수인 머리 6개를 가져가야 합니다.", desc="임프를 소환하는 시험의 골짜기 경로입니다. 이미 죽음의 종소리 마을에서 해금했다면 건너뛰세요."}, [81]={npc="루잔", tgt="루잔", desc="임프를 소환하는 시험의 골짜기 경로입니다. 이미 죽음의 종소리 마을에서 해금했다면 건너뛰세요."}, [82]={npc="루잔", tgt="루잔"}, [83]={hint="주리타 파게이즈와 대화하십시오."}, [84]={npc="주리타 파게이즈", tgt="주리타 파게이즈"}, [85]={npc="고르넥", tgt="고르넥", desc="몸 풀기를 제출해야 석판을 줍니다."}, [86]={hint="성스러운 서판을 읽어보고 시험의 골짜기의 동굴 막사 밖에 있는 켄자이와 대화하십시오.", desc="몸 풀기를 제출해야 석판을 줍니다."}, [87]={npc="켄자이", tgt="켄자이", desc="몸 풀기를 제출해야 석판을 줍니다."}, [88]={npc="켄자이", tgt="켄자이"}, [89]={hint="듀로타에 있는 타이진과 대화하십시오."}, [90]={npc="타이진", tgt="타이진"}, [91]={npc="고르넥", tgt="고르넥", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [92]={hint="Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [93]={npc="마이아", tgt="마이아", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [94]={npc="고르넥", tgt="고르넥", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [95]={hint="상형 문자로 된 서판을 읽어보고 시험의 골짜기의 동굴 막사 입구 근처에 있는 마이아와 대화하십시오.", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [96]={npc="마이아", tgt="마이아", desc="몸 풀기를 제출한 뒤 마법사 훈련사를 찾아가세요."}, [97]={text="시험의 골짜기를 떠나 센진 마을 방향으로 길을 따라갑니다."}}},
    ["01-2"] = {name="듀로타", nameA="듀로타: {a:367} & {a:362}", shortA="듀로타: {a:367} +", tips={{k="取捨", text="보급품 조달은 해둘 만합니다. 캔버스 천 조각은 타이라가드 요새의 다른 퀘스트와 함께 모으세요."}, {k="取捨", text="배신자 처단을 먼저 완료해야 From The Wreckage....(난파선)를 받을 수 있습니다. 이 퀘스트와 장로 보르날의 퀘스트(나약한 정신)를 한 번에 묶어 진행하세요."}, {k="取捨", text="어둠의 틈 던전 연계 퀘스트는 남겨 두세요. 성난불길 협곡에 갈 생각이라면 스랄에게서 내부의 배신자( → →)를 받으세요. 에 필요한 장교 휘장은 북쪽 불타는 칼날단 지역에서 얻을 수 있습니다."}, {k="提醒", text="12레벨이 안 됐다면 보급로 확보, 해골 바위굴, 저 아래에서 온 위협의 앞부분을 해두세요.", s={{"12레벨이 안 됐다면 보급로 확보, 해골 바위굴, 저 아래에서 온 위협의 앞부분을 해두세요"}}}}, danger={[1]="타이라가드 요새의 계단과 문틀에서는 위층의 선원이 함께 내려오기 쉽습니다. 먼저 외벽과 입구를 정리하세요.", [2]="북쪽 해안의 바다 거인은 나가 지역에서 돌아다닙니다. 주변 몹을 먼저 정리한 뒤 싸우고, 버티기 어려우면 해안으로 물러나세요."}, grind={[1]={mob="쿨 티라스 해병", note="밀집한 일반 몹입니다. 성채 통로에서는 몹이 추가로 붙기 쉬우니 바깥쪽부터 잡으세요. 타이라가드 요새에서 보급품 조달에 필요한 캔버스 천 조각도 함께 모으세요."}, [2]={mob="서슬갈기일족 전투호위병", note="칼바위 언덕 서쪽에 일반 몹이 모여 있습니다. 순찰이 합류할 수 있으니 야영지 가장자리부터 유인하세요. 영토 침범과 함께 진행할 수 있습니다."}, [3]={mob="먼지바람일족 폭풍마녀", note="북부 듀로타에 일반 몹이 모여 있고 시전하는 몹도 있습니다. 엄폐물을 이용해 가까이 유인하세요. 보급로 확보를 하거나 오그리마에 들어가기 전에 12레벨을 채우세요."}}, supply={[1]={npc="트라예시르"}, [2]={npc="여관주인 그로스크"}, [3]={npc="우아크"}, [4]={npc="여관주인 그로스크"}, [5]={npc="그와트"}, [6]={npc="도라스"}}, steps={[1]={npc="우코르", tgt="우코르", desc="시험의 골짜기에서 센진 마을로 가는 길에서 우코르를 찾으세요."}, [2]={hint="센진 마을에 있는 가드린 장로와 대화하십시오."}, [3]={npc="장로 가드린", tgt="장로 가드린"}, [4]={npc="라르 프라울터스크", tgt="라르 프라울터스크"}, [5]={npc="벨린 팡", tgt="벨린 팡"}, [6]={npc="장로 보르날", tgt="장로 보르날"}, [7]={npc="장로 가드린", tgt="장로 가드린"}, [8]={npc="장로 가드린", tgt="장로 가드린"}, [9]={npc="장로 가드린", tgt="장로 가드린"}, [10]={npc="벨린 팡", tgt="벨린 팡"}, [11]={npc="살티", tgt="살티"}, [12]={npc="장로 보르날", tgt="장로 보르날"}, [13]={npc="파줄라", tgt="파줄라", tag="선택사항", desc="마력 추출 재료를 얻을 수 있을 때만 진행하세요."}, [14]={text="먼저 칼바위 언덕에 들르세요"}, [15]={hint="듀로타 남부에서 능선그늘 거미 6마리와 능선그늘 잠복꾼 6마리를 처치한 후, 칼바위 언덕에 있는 가르톡에게 보고해야 합니다."}, [16]={hint="일지를 칼바위 언덕 근처에 있는 브라크에게 가져가야 합니다.", tag="선택사항"}, [17]={npc="브라크", tgt="브라크", tag="선택사항"}, [18]={npc="브라크", tgt="브라크", tag="선택사항"}, [19]={hint="브라크의 작은 모닥불 주위에 앉은