    ["01-3"] = {name="나라체 야영지", tips={{k="交通", text="다른 종족 시작 지역이라면 블러드후프 마을로 간 뒤 길을 따라 남쪽 붉은구름 고원의 나라체 야영지로 가세요. 전체 이동 경로는 맨 위를 참고하세요."}, {k="取捨", text="칼날가시 협곡에서 한 번에 힘의 의식, 족장 뾰족어금니 처치!, 전투멧돼지를 함께 하세요. 지도를 얻었다면 나라체 야영지에 대한 공격도 받으세요."}, {k="提醒", text="6레벨이 안 됐다면 칼날가시 협곡 외곽에서 전투멧돼지나 뾰족털 가시멧돼지를 처치한 뒤 블러드후프 마을로 가세요.", s={{"6레벨이 안 됐다면 칼날가시 협곡 외곽에서 전투멧돼지나 뾰족털 가시멧돼지를 처치한 뒤 블러드후프 마을로 가세요"}}}}, danger={[1]="칼날가시 협곡의 가시멧돼지는 좁은 비탈목에 몰려 있습니다. 족장 뾰족어금니를 잡기 전에 비탈을 먼저 정리하고, 물러날 때는 붉은구름 고원 쪽으로 가세요."}, grind={[1]={mob="초원타조", note="나라체 야영지 남동쪽 우물 옆에 일반 몹이 밀집해 있고 대부분 중립입니다. 한 마리씩 유인하세요. 사냥의 시작을 하며 함께 잡으세요."}, [2]={mob="산지퓨마", note="붉은구름 고원 남쪽 비탈에 일반 몹이 밀집해 있고 대부분 중립입니다. 한 마리씩 유인하며 계속되는 사냥에 필요한 가죽을 모으세요."}, [3]={mob="뾰족털일족 전투멧돼지", note="칼날가시 협곡의 일반 몹은 가시멧돼지와 섞여 있습니다. 바깥쪽부터 정리하고, 전투멧돼지 및 힘의 의식과 함께 진행하세요."}}, supply={[1]={npc="브롱크 스틸레이지"}, [2]={npc="무단 선그레인"}, [3]={npc="카우니 소프트브리즈"}}, steps={[1]={npc="나라체 야영지 선물교환권", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="나라체 야영지 선물교환권이 있을 때만 수락하세요. 선물교환권은 해당 종족 캐릭터를 만들 때 가방에 들어 있는 시작 아이템입니다. 마우스 오른쪽 버튼으로 사용하세요. 지도에는 수락 위치가 없습니다."}, [2]={hint="보른 스카이시어에게 나라체 야영지 선물교환권을 가져가야 합니다.", tag="선택사항", desc="나라체 야영지 선물교환권이 있을 때만 수락하세요."}, [3]={npc="보른 스카이시어", tgt="보른 스카이시어", tag="선택사항", desc="나라체 야영지 선물교환권이 있을 때만 수락하세요."}, [4]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [5]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [6]={hint="나라체 야영지에 있는 그룰 호크윈드가 초원타조 깃털 7개와 초원타조 고기 7덩이를 가져다 달라고 부탁했습니다."}, [7]={hint="족장 호크윈드가 나라체 야영지 남동쪽에 있는 우물 근처에서 그의 어머니를 찾아봐 달라고 부탁했습니다."}, [8]={npc="대모 호크윈드", tgt="대모 호크윈드"}, [9]={npc="대모 호크윈드", tgt="대모 호크윈드"}, [10]={hint="우물에 있는 물병을 집어서 우물에서 북서쪽에 있는 나라체 야영지의 족장 호크윈드에게 가져가야 합니다.", desc="대모 호크윈드 곁에 있는 우물에서 물병을 얻으세요."}, [11]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [12]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [13]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [14]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [15]={npc="용사 윈드페더", tgt="용사 윈드페더"}, [16]={hint="나라체 야영지의 그룰 호크윈드가 산지퓨마 모피 10필을 가져다 달라고 부탁했습니다."}, [17]={hint="나라체 야영지 정남쪽에 있는 언덕에 사는 예언자 그레이텅을 찾아가야 합니다."}, [18]={npc="예언자 그레이텅", tgt="예언자 그레이텅"},