desc="선행 퀘스트 넋 나간 좀비를 완료한 뒤 직업 훈련사에게서 시작 퀘스트를 받으세요."}, [48]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스"}, [49]={hint="오래된 두루마리를 읽고 데스넬에 있는 맥시밀리언과 대화해야 합니다."}, [50]={npc="맥시밀리언", tgt="맥시밀리언"}, [51]={npc="벤야 말선드", tgt="벤야 말선드", desc="죽음의 종소리 마을 경로입니다. 퀘스트 자체는 호드 흑마법사 모두 받을 수 있습니다."}, [52]={hint="벤야 말선드에게 덜그럭거리는 해골 3개를 가져가야 합니다.", desc="죽음의 종소리 마을 경로입니다. 퀘스트 자체는 호드 흑마법사 모두 받을 수 있습니다."}, [53]={npc="벤야 말선드", tgt="벤야 말선드", desc="죽음의 종소리 마을 경로입니다. 퀘스트 자체는 호드 흑마법사 모두 받을 수 있습니다."}, [54]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스", desc="넋 나간 좀비를 제출해야 두루마리를 줍니다."}, [55]={hint="성스러운 두루마리를 읽고 데스넬의 교회에 있는 어둠의 <name> 듀스텐과 대화해야 합니다.", desc="넋 나간 좀비를 제출해야 두루마리를 줍니다."}, [56]={npc="어둠의사제 듀스텐", tgt="어둠의사제 듀스텐", desc="넋 나간 좀비를 제출해야 두루마리를 줍니다."}, [57]={npc="어둠의사제 듀스텐", tgt="어둠의사제 듀스텐"}, [58]={hint="티리스팔 숲에 있는 어둠의<name> 베릴과 대화해야 합니다."}, [59]={npc="어둠의사제 베릴", tgt="어둠의사제 베릴"}, [60]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스", desc="먼저 넋 나간 좀비를 제출하세요."}, [61]={hint="상형 문자로 된 두루마리를 읽고 데스넬 교회에 있는 이자벨라와 대화해야 합니다.", desc="먼저 넋 나간 좀비를 제출하세요."}, [62]={npc="이자벨라", tgt="이자벨라", desc="먼저 넋 나간 좀비를 제출하세요."}, [63]={text="죽음의 종소리 마을에서 동쪽 길로 나가 브릴로 가세요."}}},
    ["01-6"] = {name="티리스팔 숲", nameA="티리스팔 숲: {a:159}", tips={{k="提醒", text="중요한 정보을 받지 않았다면 브릴 여관과 처음 받을 수 있는 퀘스트부터 시작하세요.", s={{"중요한 정보을 받지 않았다면 브릴 여관과 처음 받을 수 있는 퀘스트부터 시작하세요"}}}, {k="取捨", text="붉은십자군, 거미, 무덤풀 목표는 남동쪽에서 한 번에 진행하세요. 북쪽 해안 멀록과 아가만드는 한 번의 이동으로 묶을 수 있습니다. 가까운 곳부터 제출하고, 12레벨이 되면 크로스로드로 가세요."}, {k="取捨", text="여관 옆의 죽음의 한기에는 굵은 실이 필요하니 가는 길에 상인에게서 구입하세요. 포세이큰을 위한 가죽에 쓸 북쪽 해안 멀록 가죽이 아직 부족하면 다음에 북쪽 해안에 갈 때 마무리하세요."}, {k="取捨", text="은빛 여명회의 지역 퀘스트 2개를 마치면 반다리온 성채를 받을 수 있습니다. 오크/트롤/언데드 전용. 성채 후속 퀘스트 일부는 언데드 전용입니다. 크로스로드로 서둘러 간다면 지역 퀘스트 2개를 마친 뒤 떠나세요.", s={{"은빛 여명회의 지역 퀘스트 2개를 마치면 반다리온 성채를 받을 수 있습니다"}, {"오크/트롤/언데드 전용"}, {"성채 후속 퀘스트 일부는 언데드 전용입니다"}, {"크로스로드로 서둘러 간다면 지역 퀘스트 2개를 마친 뒤 떠나세요"}}}, {k="提醒", text="12레벨이 안 됐다면 붉은십자군과의 전쟁, 아가만드가 납골당 또는 은빛 여명회 은빛 여명회 사절/저주받은 자들의 교단/전쟁의 잔재을 받을 수 있는 대로, 현재 위치에 맞게 먼저 하세요.", s={{"12레벨이 안 됐다면 붉은십자군과의 전쟁, 아가만드가 납골당 또는 은빛 여명회 은빛 여명회 사절/저주받은 자들의 교단/전쟁의 잔재을 받을 수 있는 대로, 현재 위치에 맞게 먼저 하세요"}}}}, danger={[1]="남동쪽 묘지에는 블러드 좀비와 떠도는 유령이 섞여 있어 앞뒤로 협공당하기 쉽습니다. 묘지 가장자리를 따라 정리하고 퇴로를 남겨 두세요."}, grind={[1]={mob="붉은십자군 선교사", note="브릴 남서쪽에 시전하는 일반 몹이 흩어져 있습니다. 첫 붉은십자군 퀘스트를 하며 야영지 바깥쪽에서 한 마리씩 유인하세요."}, [2]={mob="떠도는 영혼", note="남동쪽 묘지에 일반 몹이 모여 있고 블러드 좀비가 섞여 있습니다. 순찰을 조심하세요. 후방 경비와 무덤풀 퀘스트를 함께 하세요."}, [3]={mob="암흑 수련사", note="남동쪽 은빛 여명회 퀘스트 근처에 일반 몹이 밀집해 있고 어둠의 집행자가 섞여 있습니다. 어둠의 집행자가 붙지 않도록 야영지 가장자리에서 한 마리씩 유인하세요. 11레벨 이후 12레벨까지 채우세요."}}, supply={[1]={npc="여관주인 리니"}, [2]={npc="아베 윈터스"}, [3]={npc="여관주인 리니"}, [4]={npc="미시즈 윈터스"}, [5]={npc="도라스"}}, steps={[1]={npc="죽음의경비병 시머", tgt="죽음의경비병 시머"}, [2]={npc="고르도", tgt="고르도"}, [3]={hint="데스넬 북쪽에 있는 농장에서 티리스팔 호박을 10개 훔친 다음 브릴에 있는 연금술사 요한에게 가져가야 합니다."}, [4]={hint="어둠풀 3개를 채집해 브릴 공동묘지에 있는 초보연금술사 홀랜드에게 가져가야 합니다."}, [5]={hint="브릴에 있는 집행관 자이건드에게 붉은십자군 문서를 전달해야 합니다."}, [6]={npc="집행관 자이건드", tgt="집행관 자이건드"}, [7]={npc="연금술사 요한", tgt="연금술사 요한"}, [8]={npc="초보연금술사 홀랜드", tgt="초보연금술사 홀랜드"}, [9]={text="브릴에 도착하면 여관주인 리니에게서 귀환석 위치를 설정하세요(61.72, 52.05)."}, [10]={npc="연금술사 요한", tgt="연금술사 요한"}, [11]={hint="사로잡힌 붉은십자군 광신도에게 줄무