c="두루마리로 정체를 드러내세요. 생물이 공격을 멈출 때까지 싸운 뒤 영혼 상자를 사용하고, 마지막으로 바닥의 용기를 주우세요."}, [203]={hint="아나스타샤 하트웰의 뒤에 있는 현신의 주문서와 속박의 상자를 집어야 합니다. 언더시티에 있는 아나스타샤 하트웰에게 채워진 속박의 상자 3개와, 속박의 상자, 현신의 주문서를 가져가야 합니다.", desc="두루마리로 정체를 드러내세요. 생물이 공격을 멈출 때까지 싸운 뒤 영혼 상자를 사용하고, 마지막으로 바닥의 용기를 주우세요."}, [204]={npc="아나스타샤 하트웰", tgt="아나스타샤 하트웰", desc="두루마리로 정체를 드러내세요. 생물이 공격을 멈출 때까지 싸운 뒤 영혼 상자를 사용하고, 마지막으로 바닥의 용기를 주우세요."}, [205]={npc="아나스타샤 하트웰", tgt="아나스타샤 하트웰"}, [206]={hint="조셉 그레고리안에게 리넨 10개와 달라란 마나석 6개를 가져가야 합니다."}, [207]={npc="조셉 그레고리안", tgt="조셉 그레고리안"}, [208]={npc="조셉 그레고리안", tgt="조셉 그레고리안", star={"하급 마법불꽃 로브", {"MAGE"}}}, [209]={hint="퀘스트 목표를 완료하세요."}, [210]={npc="조셉 그레고리안", tgt="조셉 그레고리안", star={"하급 마법불꽃 로브", {"MAGE"}}}, [211]={text="미리 설정해 둔 귀환석으로 불모의 땅 크로스로드로 돌아가세요. 귀환석을 쓸 수 없다면 언더시티를 나와 브릴 남쪽 탑에서 자페타(60.74, 58.87, 서쪽 승강장)에게 오그리마행 비행선인지 확인하고 탑승하세요. 내린 뒤 오그리마에서 크로스로드로 날아가세요."}}},
    ["05-d3"] = {name="로데론의 폐허", entrance="언더시티 72.41, 11.37", pickup="먼저 티리스팔 숲 브릴의 리네아에게 후방 경비 진행도를 확인하세요. 리네아는 후방 경비 버전도 제공해요(오크와 언데드 전용). 은빛소나무 숲에 가기 전에 브릴에서 비행선을 내려 리네아와 크리스토프를 들르세요. 세펄커에서는 먼저 타비사에게서 두려움에 찬 부탁을 받고 죽음의 비법 → 죽음의 비법 → 죽음의 비법을 완료하세요. 언더시티 연금술 구역에서는 그레이브와 모빈을 찾으세요. 이 여섯 종류의 퀘스트는 던전 단계에서 제출하세요.", pickupS={{"먼저 티리스팔 숲 브릴의 리네아에게 후방 경비 진행도를 확인하세요"}, {"리네아는 후방 경비 버전도 제공해요(오크와 언데드 전용)", {race={"Orc", "Scourge"}}}, {"은빛소나무 숲에 가기 전에 브릴에서 비행선을 내려 리네아와 크리스토프를 들르세요"}, {"세펄커에서는 먼저 타비사에게서 두려움에 찬 부탁을 받고 죽음의 비법 → 죽음의 비법 → 죽음의 비법을 완료하세요"}, {"언더시티 연금술 구역에서는 그레이브와 모빈을 찾으세요"}, {"이 여섯 종류의 퀘스트는 던전 단계에서 제출하세요"}}, tips={{k="動線", text="입구 → 왕의 골목에서 쇠퇴송곳니 → 언데드 클리어 → 남작을 죽이고 문장을 약탈 → 묘지에서 라스마엘, 서쪽에서 에드워드. 시장의 포세이큰과 남서쪽 굴뚝의 빅터는 선택 사항입니다."}, {k="取捨", text="호드는 16~20레벨에 한 번 우선으로 돌 수 있습니다. 은빛소나무 숲 제조법 연계를 끝내지 않았다면 공동묘지 퀘스트를 먼저 한 뒤 파티를 모으세요. 쇠퇴송곳니도 함께 집계됩니다."}, {k="說明", text="입구는 언더시티 위쪽, 티리스팔 숲 지상의 로데론의 폐허에 있습니다. 언더시티 지도 좌표를 사용하세요. 폐허 안으로 들어가 왼쪽 위 돌계단을 오르세요. 지하 승강기 쪽으로는 가지 마세요.", s={{"입구는 언더시티 위쪽, 티리스팔 숲 지상의 로데론의 폐허에 있습니다"}, {"언더시티 지도 좌표를 사용하세요"}, {"폐허 안으로 들어가 왼쪽 위 돌계단을 오르세요"}, {"지하 승강기 쪽으로는 가지 마세요"}}}}, steps={[1]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", desc="티리스팔 숲 브릴에서 이미 완료했다면 건너뛰세요."}, [2]={hint="피투성이 좀비 8명과 떠도는 영혼 8명을 처치한 다음 초소로 돌아가 리니아에게 보고해야 합니다.", desc="티리스팔 숲 브릴에서 이미 완료했다면 건너뛰세요."}, [3]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", desc="티리스팔 숲 브릴에서 이미 완료했다면 건너뛰세요."}, [4]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", preText="후방 경비"}, [5]={hint="죽음경비병 리니아에게 너덜토막의 심장을 가져가야 합니다."}, [6]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아"}, [7]={npc="죽음경비병 크리스토프", tgt="죽음경비병 크리스토프", desc="선행 퀘스트 후방 경비에는 종족 제한이 있습니다. 다른 종족은 크리스토프가 이 퀘스트를 제공하는지 확인하세요.", preText="후방 경비"}, [8]={npc="타비사 하트위버", tgt="타비사 하트위버"}, [9]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", desc="은빛소나무 숲 세펄커에서 이 단계를 이미 시작했다면 현재 진행도대로 이어서 제출하고 다시 하지 마세요."}, [10]={hint="불곰 심장 6개와 땅거미 점액 6개를 모아 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다.", desc="은빛소나무 숲 세펄커에서 이 단계를 이미 시작했다면 현재 진행도대로 이어서 제출하고 다시 하지 마세요."}, [11]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="은빛소나무 숲 세펄커에서 이 단계를 이미 시작했다면 현재 진행도대로 이어서 제출하고 다시 하지 마세요."}, [12]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="버나드의 일기는 장작나무 마을 여관에 있어요.", preText="죽음의 비법"}, [13]={hint="장작나무 마을에서 베랄드의 일지를 찾아 공동묘지에 있는 연금술사 렌퍼럴에게 가져가야 합니다.", desc="버나드의 일기는 장작나무 마을 여관에 있어요."}, [14]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", desc="버나드의 일기는 장작나무 마을 여관에 있어요."}, [15]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", preText="죽음의 비법"}, [16]={hint="호수늪지이끼 6개, 호수덤불이끼 6개, 그리고 굳어진 종양 1개를 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다."}, [17]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [18]={npc="시어도어 그리프스", tgt="시어도어 그리프스", preText="죽음의 비법"}, [19]={npc="모빈 라이트베인", tgt="모빈 라이트베인"}, [20]={text="로데론의 폐허 입구"}, [21]={hint="로데론의 폐허에 있는 쇠퇴송곳니에게서 고독성 변종을 채취해 언더시티에 있는 시어도어 그리프스에게 가져가야 합니다.", desc="위치: 입구에서 거미 지역(네루비안)을 지나 왕의 골목에서 순찰하는 쇠퇴송곳니를 찾으세요.", spot="입구에서 거미 지역(네루비안)을 지나 왕의 골목에서 순찰하는 쇠퇴송곳니를 찾으세요."}, [22]={hint="언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다.", desc="위치: 왕의 골목, 전망대, 묘지로 이어지는 본길을 따라 언데드 전리품을 얻으세요.", spot="왕의 골목, 전망대, 묘지로 이어지는 본길을 따라 언데드 전리품을 얻으세요."}, [23]={npc="흉측한 머리", npcObj=true, tag="게임 내 확인이 필요합니다", desc="남작을 처치하고 혐오스러운 머리를 얻은 뒤 아이템에서 수락하세요. 블리자드의 11월 6일 핫픽스 이후 호드는 레벨 15에 받을 수 있어요."}, [24]={npc="로데론의 문장", npcObj=true, tag="게임 내 확인이 필요합니다", desc="로데론의 문장은 후보 지점이 여러 곳이니, 거미 안뜰, 탑, 잠긴 방의 상호작용 가능한 물체를 길을 따라 확인하세요."}, [25]={hint="로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.", desc="위치: 라스마엘 묘지 서쪽에서 구울 옆의 에드워드에게 다가가세요. 순서: 시체에 다가가기 전에 25번 단계를 먼저 하세요.", spot="라스마엘 묘지 서쪽에서 구울 옆의 에드워드에게 다가가세요."}, [26]={hint="브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다.", desc="위치: 당기기 전에 로데론 묘지의 라스마엘 주변 공간을 정리하세요.", spot="당기기 전에 로데론 묘지의 라스마엘 주변 공간을 정리하세요."}, [27]={npc="시어도어 그리프스", tgt="시어도어 그리프스"}, [28]={npc="모빈 라이트베인", tgt="모빈 라이트베인"}, [29]={hint="로데론의 문장을 언더시티에 있는 오란 스네이크레이드에게 가져가야 합니다.", desc="로데론의 문장은 후보 지점이 여러 곳이니, 거미 안뜰, 탑, 잠긴 방의 상호작용 가능한 물체를 길을 따라 확인하세요."}, [30]={npc="오란 스네이크레이드", tgt="오란 스네이크레이드"}, [31]={hint="흉측한 머리를 언더시티에 있는 수석 연금술사 파라넬에게 전달해야 합니다.", desc="남작을 처치하고 혐오스러운 머리를 얻은 뒤 아이템에서 수락하세요. 블리자드의 11월 6일 핫픽스 이후 호드는 레벨 15에 받을 수 있어요."}, [32]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [33]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", preText="끝없는 고통"}, [34]={hint="남작의 머리카락을 언더시티에 있는 오스마르의 몸으로 가져가야 합니다."}, [35]={npc="미완성 누더기골렘", tgt="미완성 누더기골렘"}, [36]={npc="미완성 누더기골렘", tgt="미완성 누더기골렘", preText="끝없는 고통"}, [37]={hint="알아낸 정보를 언더시티에 있는 수석 연금술사 파라넬에게 보고해야 합니다."}, [38]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [39]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="독성 해골버섯은 무역 구역의 타반 그리스트에게서, 부식초는 약초 훈련사 옆에서, 고통의 정수는 도적 지구의 독약 상인에게서 구하세요.", preText="끝없는 고통"}, [40]={hint="언더시티의 수석 연금술사 파라넬을 위해 상업 지구에 있는 타우니 그리제트에게서 유독한 해골갓을, 전문 약초채집사 근처에서 물집풀을, 도적 지구 독 상인에게서 괴로움의 정수를 입수해야 합니다.", desc="독성 해골버섯은 무역 구역의 타반 그리스트에게서, 부식초는 약초 훈련사 옆에서, 고통의 정수는 도적 지구의 독약 상인에게서 구하세요."}, [41]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="독성 해골버섯은 무역 구역의 타반 그리스트에게서, 부식초는 약초 훈련사 옆에서, 고통의 정수는 도적 지구의 독약 상인에게서 구하세요."}, [42]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="오스마 위쪽의 장치에 쉬익거리는 혈청을 주입하세요.", preText="끝없는 고통"}, [43]={hint="수석 연금술사 파라넬이 말한 대로 오스마르의 몸 위 장치에 쉭쉭거리는 혈청을 주입해야 합니다.", desc="오스마 위쪽의 장치에 쉬익거리는 혈청을 주입하세요."}, [44]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="오스마 위쪽의 장치에 쉬익거리는 혈청을 주입하세요."}, [45]={npc="죽음경비병 크리스토프", tgt="죽음경비병 크리스토프"}, [46]={npc="타비사 하트위버", tgt="타비사 하트위버"}}},
    ["02-10"] = {name="불모의 땅", nameA="불모의 땅: {a:392} & {a:378}", shortA="불모의 땅: {a:392} +", tips={{k="交通", text="북쪽 루프를 마치면 귀환석으로 크로스로드에 돌아가 야영지 퀘스트를 먼저 제출한 뒤 톱니항으로 날아가세요. 처음 타우라조 야영지에 가면 비행 지점을 여세요."}, {k="取捨", text="부족 간의 전쟁, 그 이름은 올그라, 타오르는 증오는 겹치는 목표라 함께 해둘 만합니다. 타오르는 증오에는 엄니 60개가 필요하니, 부족하면 가방에 남겨 두세요. 레벨이 충분해지면 따로 반복 사냥하지 않아도 됩니다."}, {k="取捨", text="돌발톱 산맥으로 이어지는 진질에게 보내는 편지, 지즈 피직스은 다음 정류장에서 제출하세요. 동굴이끼거미알는 알을 먼저 모아 두었다가 다음에 톱니항을 지날 때 제출하세요. 잿빛 골짜기 사냥 대회와 선택인 전쟁노래부족 보고서은 잿빛 골짜기에서 하세요."}, {k="取捨", text="20레벨 엘리트 현상 수배: 브루즈, 켄타우로스 이벤트 반격!, 국경 퀘스트 억울한 누명, 정당한 응징은 파티로 하세요. 북쪽 성채 호위는 길가 몹이 추가로 붙기 쉬우니 건너뛰어도 됩니다."}, {k="取捨", text="광부의 행운은 드랍률이 낮으니, 안 나오면 경로의 뒷부분으로 넘어가세요. 희귀 퀘스트 4개는 희귀 몹을 만나 아이템을 얻었을 때만 시작됩니다."}, {k="提醒", text="23레벨이 안 됐다면 들판을 비워라 지점(47.11, 77.38)에서 도마뱀과 잠복자를 계속 잡거나 남쪽으로 가서 갠의 땅 회복을 받으세요. 통곡의 동굴 입구는 약 47.70, 35.00이며 18~23레벨 진행을 권장합니다. 불모의 땅 크로스로드에서 열린 송곳니의 드루이드 우두머리, 불뱀꽃, 톱니항의 99년 묵은 와인, 영리해지는 음료, 동굴 밖 바위 턱의 돌연변이 통가죽, 돌연변이 짐승 섬멸 을 함께 가져가도 됩니다.", s={{"23레벨이 안 됐다면 들판을 비워라 지점(47.11, 77.38)에서 도마뱀과 잠복자를 계속 잡거나 남쪽으로 가서 갠의 땅 회복을 받으세요"}, {"통곡의 동굴 입구는 약 47.70, 35.00이며 18~23레벨 진행을 권장합니다"}, {"불모의 땅 크로스로드에서 열린 송곳니의 드루이드 우두머리, 불뱀꽃, 톱니항의 99년 묵은 와인, 영리해지는 음료, 동굴 밖 바위 턱의 돌연변이 통가죽, 돌연변이 짐승 섬멸 을 함께 가져가도 됩니다"}}}}, danger={[1]="들판을 비워라의 엘리트 약탈자가 일반 몹 사이를 순찰합니다. 바깥쪽 도마뱀만 잡고, 전투 한가운데를 가로지르지 마세요.", [2]="먼지진흙 습지 국경에는 얼라이언스 병사가 무리 지어 있습니다. 파티가 없으면 억울한 누명, 정당한 응징(97250)을 건너뛰세요."}, grind={[1]={mob="폭풍도마뱀", note="들판을 비워라 지역은 일반 몹이 밀집해 있습니다. 풀밭을 돌며 잡고, 엘리트 격분한 약탈자를 조심하고 전투 한가운데는 피하세요."}, [2]={mob="긴발톱 빗송곳니하이에나", note="천둥도마뱀과 같은 풀밭에 일반 몹이 밀집해 있습니다. 다른 플레이어가 같은 구역을 정리 중이면 야영지를 옮기지 말고 바깥쪽에서 다른 몹을 잡으세요."}}, supply={[1]={npc="데브락"}, [2]={npc="브라고크"}, [3]={npc="여관주인 윌리"}, [4]={npc="그라즐릭스"}, [5]={npc="여관주인 윌리"}, [6]={npc="재지크"}, [7]={npc="오무사 썬더혼"}, [8]={npc="여관주인 비울라"}, [9]={npc="사누예 룬토템"}}, steps={[1]={text="은빛소나무 숲 Sepulcher에서 이미 크로스로드로 돌아왔다면 야영지에서 퀘스트를 받으세요. 중간에 합류해 아직 동부 왕국에 있다면 귀환석으로 크로스로드로 돌아가세요. 귀환석을 쓸 수 없다면 브릴 남쪽 탑의 오그리마행 비행선을 타고 오그리마에서 크로스로드로 날아가세요. 크로스로드 귀환석은 북쪽 라인을 끝낼 때까지 남겨 두세요."}, [2]={npc="만크릭", tgt="만크릭"}, [3]={npc="만크릭", tgt="만크릭"}, [4]={npc="코란", tgt="코란"}, [5]={npc="톨크", tgt="톨크"}, [6]={hint="크로스로드에 있는 셀그라 다크쏜에게 에체야키의 통가죽을 가져가야 합니다."}, [7]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜", desc="불모의 땅 크로스로드에서 이미 제출했다면 건너뛰세요."}, [8]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [9]={hint="칼날바람일족 암살자들에게서 하피 부대장의 반지 6개를 모아 크로스로드에 있는 달소크 스위프트대거에게 가져가야 합니다.", desc="불모의 땅 크로스로드에서 완료하지 않았을 때만 하세요."}, [10]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거", desc="불모의 땅 크로스로드에서 이미 제출했다면 건너뛰세요."}, [11]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [12]={text="크로스로드에서 톱니항으로 날아갈 때 앞의 비행 지점 두 곳을 이미 열었다면 바로 비행하세요. 톱니항 비행 지점을 열지 않았다면 동쪽 대로를 따라 도시로 들어가 브라고크(63.08, 37.16)에게서 여세요. 불모의 땅 크로스로드에서 이미 받은 사모플랜지는 그대로 두세요."}, [13]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [14]={npc="선장 탈로타스 브라이트썬", tgt="선장 탈로타스 브라이트썬"}, [15]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [16]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [17]={npc="부두주임 디지위그", tgt="부두주임 디지위그", tag="선택사항", desc="북쪽 광산에 들를 때만 받으세요."}, [18]={npc="현상수배!", npcObj=true, tag="선택사항", desc="20레벨 엘리트입니다. 파티를 구할 때만 수락하세요."}, [19]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈", tag="선택사항", desc="통곡의 동굴을 갈 계획일 때만 수락하세요."}, [20]={text="톱니항 북쪽 통로로 나와 슬러지 늪지로 가며 북쪽 들판도 함께 정리하세요. 처음 방문에서 사모플랜지를 받지 않았다면 먼저 스퍼터밸브에게서 받으세요."}, [21]={hint="투자개발회사 연구 시설의 제어장치로 접근해야 합니다."}, [22]={npc="제어 장치", npcObj=true}, [23]={npc="제어 장치", npcObj=true}, [24]={hint="연료 제어 밸브, 압력 조절 밸브, 주제어 밸브를 잠근 다음 제어장치로 돌아가십시오."}, [25]={npc="제어 장치", npcObj=true}, [26]={npc="제어 장치", npcObj=true}, [27]={hint="땜장이 스니글즈에게서 제어장치 열쇠를 구해야 합니다."}, [28]={npc="제어 장치", npcObj=true}, [29]={npc="제어 장치", npcObj=true}, [30]={hint="톱니항에 있는 부두주임 디지위그가 투자개발회사 감독이나 투자개발회사 집행자로부터 고양이눈 에메랄드를 가져다 달라고 부탁했습니다.", tag="선택사항", desc="고양이눈 에메랄드는 드랍률이 낮습니다. 지나가는 길에만 잡고, 오래 잡지 마세요."}, [31]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="시동 열쇠를 가진 작업반장을 처치하고 위즐크랭크에게 가져가세요."}, [32]={hint="위즐크랭크에게 시동 열쇠를 가져다주어야 합니다.", desc="시동 열쇠를 가진 작업반장을 처치하고 위즐크랭크에게 가져가세요."}, [33]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="시동 열쇠를 가진 작업반장을 처치하고 위즐크랭크에게 가져가세요."}, [34]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="수락하면 바로 호위가 시작됩니다. 먼저 체력을 회복하고 근처 몹을 처리하세요."}, [35]={hint="위즐크랭크와 그가 훔쳐 낸 고블린 벌목기를 톱니항에 있는 스퍼터밸브에게로 호위해 가야 합니다.", desc="슬러지 늪지를 벗어날 때까지 호위하고, 대화가 끝나고 퀘스트가 완료될 때까지 기다리세요."}, [36]={hint="불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오."}, [37]={npc="카드라크", tgt="카드라크"}, [38]={npc="카드라크", tgt="카드라크", tag="선택사항", desc="잿빛 골짜기 토막나무 초소에서 받는 김에 진행하세요. 받은 뒤 보고서 묶음을 우클릭해 열어 세 사절에게 전할 전쟁노래부족 보고서를 얻고, 각 사절의 최신 답변을 보관하세요."}, [39]={npc="브랑 와일드고어", tgt="브랑 와일드고어"}, [40]={npc="브랑 와일드고어", tgt="브랑 와일드고어"}, [41]={hint="불모의 땅에 있는 우두머리 사바나 암사자와 우두머리 사바나 사자에게서 사바나 사자 가죽 6개를 채취해야 합니다."}, [42]={hint="불모의 땅에 놓인 용수철 덫에서 덫에 걸린 사냥감 8마리를 모아야 합니다."}, [43]={npc="브랑 와일드고어", tgt="브랑 와일드고어"}, [44]={npc="브랑 와일드고어", tgt="브랑 와일드고어"}, [45]={npc="브랑 와일드고어", tgt="브랑 와일드고어"}, [46]={hint="가죽 묶음을 불모의 땅 메마른 언덕이 내려다보이는 산등성이에 있는 은둔자에게 가져가야 합니다."}, [47]={npc="테리 롱드링크", tgt="월튼"}, [48]={npc="테리 롱드링크", tgt="월튼"}, [49]={hint="부서진 짐마차로 가서 쿨 티란이 이곳에 온 이유를 자세히 알아봐야 합니다."}, [50]={npc="테리 롱드링크", tgt="월튼"}, [51]={npc="테리 롱드링크", tgt="월튼", tag="선택사항", desc="호위 대상이 포위당하면 먼저 떨어져 있는 해군을 유인해 처치하고, 테리를 처치하는 이벤트가 끝날 때까지 기다렸다가 제출하세요."}, [52]={hint="월튼이 테리 롱드링크와 쿨 티라스 해병을 상대하는 동안 살아남도록 도와야 합니다.", tag="선택사항", desc="호위 대상이 포위당하면 먼저 떨어져 있는 해군을 유인해 처치하고, 테리를 처치하는 이벤트가 끝날 때까지 기다렸다가 제출하세요."}, [53]={npc="테리 롱드링크", tgt="월튼", tag="선택사항", desc="호위 대상이 포위당하면 먼저 떨어져 있는 해군을 유인해 처치하고, 테리를 처치하는 이벤트가 끝날 때까지 기다렸다가 제출하세요."}, [54]={hint="붉은깃털 세레나를 처치하고 그 증거로 그녀의 머리카락을 크로스로드에 있는 달소크 스위프트대거에게 가져가야 합니다."}, [55]={text="북쪽을 모두 정리한 뒤 귀환석으로 크로스로드로 돌아가세요. 귀환석이 대기 중이면 큰길을 따라 남쪽으로 내려가세요. 세레나에게 제출하고 진질의 편지를 받은 뒤 톱니항으로 날아가세요."}, [56]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [57]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거", desc="돌발톱 산맥 해바위 은거지에서 돌발톱 입구 동굴에 있는 진질을 찾으세요."}, [58]={text="크로스로드에서 제출을 마친 뒤 톱니항으로 날아가 사모플랜지와 북쪽 라인 퀘스트를 제출하세요."}, [59]={hint="톱니항에 있는 스퍼터밸브에게 사모플랜지를 가져가야 합니다."}, [60]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [61]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [62]={npc="부두주임 디지위그", tgt="부두주임 디지위그", tag="선택사항"}, [63]={hint="브루즈의 등지느러미를 톱니항에 있는 가즈로에게 가져가야 합니다.", tag="선택사항", desc="파티를 구해 물속으로 들어가거나, 경비병 근처로 유인해 도움을 받으세요. 전리품을 얻을 만큼 충분한 피해를 꼭 입히세요."}, [64]={npc="가즈로", tgt="가즈로", tag="선택사항"}, [65]={text="남동쪽 해안, 타우라조 야영지에서 가시멧돼지 퀘스트 받기"}, [66]={hint="톱니항에 있는 가즈로를 위해 장화가 든 뱃짐과 망원경 렌즈를 찾아 와야 합니다.", desc="북쪽 성채 퀘스트와 함께 진행하세요. 먼저 남쪽바다 야영지마다 상자를 하나씩 여세요."}, [67]={hint="톱니항에 있는 선장 탈로타스 브라이트썬이 테라모어 휘장 10개를 모으고 경비대장 페어마운트, 포병 훼산, 포병 스미스를 처치해 달라고 부탁했습니다."}, [68]={npc="길사레즈 파이어바우", tgt="길사레즈 파이어바우", tag="선택사항", desc="준비가 됐을 때만 호위를 시작하세요. 먼저 탑 안의 대포와 휘장을 처리하세요."}, [69]={hint="길사레즈 파이어바우를 톱니항에 있는 브라이트썬 선장에게 데려가야 합니다.", tag="선택사항", desc="북쪽 성채에서 톱니항까지 길타레스를 따라가고, 퀘스트 완료가 확인된 뒤 파티를 떠나세요."}, [70]={npc="가즈로", tgt="가즈로"}, [71]={npc="선장 탈로타스 브라이트썬", tgt="선장 탈로타스 브라이트썬"}, [72]={npc="선장 탈로타스 브라이트썬", tgt="선장 탈로타스 브라이트썬", tag="선택사항"}, [73]={text="톱니항에서 남서쪽으로 죽은 오아시스와 랩터 둥지를 지나, 가는 길에 타우라조 야영지로 가세요."}, [74]={hint="베로그를 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다.", desc="여럿이 함께 정리하면 더 빠릅니다. 외침이 들리면 53.06, 41.74의 천막으로 가세요."}, [75]={hint="열대초원랩터를 처치하고 그들의 깃털을 모아야 합니다. 이 깃털을 열대초원랩터 둥지 3개에 사용한 다음 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오."}, [76]={hint="온전한 랩터 뿔 5개를 모아 톱니항에 있는 메보크 미지릭스에게 가져가야 합니다."}, [77]={hint="크로스로드에 있는 가즈록에게 도둑맞은 은화를 가져가야 합니다."}, [78]={hint="크로스로드에 있는 만크릭을 위해 그의 아내의 흔적을 찾아 돌아가야 합니다."}, [79]={text="타우라조 야영지에 도착해 아직 비행 지점을 열지 않았다면 오무사 썬더혼(44.45, 59.15)을 찾으세요. 크로스로드 귀환석은 돌발톱 산맥 해바위 은거지까지 남겨 두세요."}, [80]={npc="뻐드렁니", tgt="뻐드렁니"}, [81]={npc="테터낵 스틸포지", tgt="테터낵 스틸포지", tag="선택사항", desc="남쪽 끝에서 가시멧돼지를 잡을 때만 받으세요."}, [82]={npc="그런트 로그마르", tgt="그런트 로그마르", tag="선택사항", desc="영구 버전 파티 퀘스트입니다. 인원이 부족하면 건너뛰세요."}, [83]={text="크로스로드로 한 번 날아가 성난 갈퀴발톱 열대초원랩터, 전쟁으로 잃은 아내 등을 제출하고, 조른의 시작 퀘스트를 받은 뒤 남서쪽 켄타우로스를 잡으러 가거나 타우라조 야영지로 돌아가세요."}, [84]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [85]={npc="가즈록", tgt="가즈록"}, [86]={npc="만크릭", tgt="만크릭"}, [87]={npc="만크릭", tgt="만크릭", desc="먼저 전쟁으로 잃은 아내을 제출해야 받을 수 있습니다."}, [88]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [89]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [90]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [91]={hint="헤즈룰을 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다."}, [92]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [93]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트", tag="선택사항", desc="파티를 구한 뒤 받으세요. 켄타우로스 증원이 여러 차례로 나뉘어 몰려옵니다."}, [94]={hint="크로스로드 서쪽에 있는 렉타르 데스게이트에게 크롬자르의 깃발 조각을 가져가야 합니다.", tag="선택사항", desc="아군을 지키며 군벌 크롬자르를 처치하고 크롬자르의 깃발 조각 1개를 얻으세요."}, [95]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트", tag="선택사항"}, [96]={hint="타우라조 야영지에 있는 조른 스카이시어와 대화하십시오."}, [97]={npc="조른 스카이시어", tgt="조른 스카이시어"}, [98]={npc="조른 스카이시어", tgt="조른 스카이시어"}, [99]={text="타우라조 야영지 남쪽, 가시멧돼지와 천둥도마뱀을 한꺼번에 처리하세요"}, [100]={hint="뾰족털일족의 풍수사 6명, 가시마술사 12명, 흙점쟁이 12명을 처치해야 합니다. 임무를 완수한 후 불모의 땅, 타우라조 야영지에 있는 뻐드렁니에게 돌아가십시오."}, [101]={hint="크로스로드에 있는 만크릭에게 뾰족털 가시멧돼지 어금니 60개를 가져가야 합니다."}, [102]={hint="가시멧돼지를 처치하고 만크릭의 추모비에 바칠 올그라의 장식 4개를 모아야 합니다."}, [103]={hint="크로스로드에 있는 코란에게 실리시드의 알 12개와 갈퀴발톱 장갑을 가져가야 합니다."}, [104]={hint="먼지진흙 습지대와 맞닿은 불모의 땅 국경을 침범한 얼라이언스 병사들을 처치한 후, 타우라조 야영지에 있는 그런트 로그마르에게 가야 합니다.", tag="선택사항", desc="병사들은 따로 유인해 처치하고, 마지막에 격분한 약탈자를 잡으세요."}, [105]={npc="라코타마니의 발굽", npcObj=true, tag="선택사항", desc="희귀 몹 라코타마니를 만나 처치하고 발굽을 얻었을 때만 하세요."}, [106]={hint="타우라조 야영지에 있는 조른 스카이시어에게 라코타마니의 발굽을 가져가야 합니다.", tag="선택사항", desc="희귀 몹 라코타마니를 만나 처치하고 발굽을 얻었을 때만 하세요."}, [107]={npc="조른 스카이시어", tgt="조른 스카이시어", tag="선택사항", desc="희귀 몹 라코타마니를 만나 처치하고 발굽을 얻었을 때만 하세요."}, [108]={npc="오와탄카의 꼬리가시", npcObj=true, tag="선택사항", desc="희귀 몹 오와탄카를 만나 처치하고 꼬리 가시를 얻었을 때만 하세요."}, [109]={hint="타우라조 야영지에 있는 조른 스카이시어에게 오와탄카의 꼬리가시를 가져가야 합니다.", tag="선택사항", desc="희귀 몹 오와탄카를 만나 처치하고 꼬리 가시를 얻었을 때만 하세요."}, [110]={npc="조른 스카이시어", tgt="조른 스카이시어", tag="선택사항", desc="희귀 몹 오와탄카를 만나 처치하고 꼬리 가시를 얻었을 때만 하세요."}, [111]={npc="여왕 실리시드의 머리", npcObj=true, tag="선택사항", desc="희귀 몹 여왕 실리시드를 만나 처치하고 머리를 얻었을 때만 하세요."}, [112]={hint="조른 스카이시어에게 여왕 실리시드의 머리를 가져다주어야 합니다.", tag="선택사항", desc="희귀 몹 여왕 실리시드를 만나 처치하고 머리를 얻었을 때만 하세요."}, [113]={npc="조른 스카이시어", tgt="조른 스카이시어", tag="선택사항", desc="희귀 몹 여왕 실리시드를 만나 처치하고 머리를 얻었을 때만 하세요."}, [114]={npc="워시트 포우니의 깃털", npcObj=true, tag="선택사항", desc="희귀 몹 워시트 포우니를 만나 처치하고 깃털을 얻었을 때만 하세요."}, [115]={hint="타우라조 야영지에 있는 조른 스카이시어에게 워시트 포우니의 깃털을 가져가야 합니다.", tag="선택사항", desc="희귀 몹 워시트 포우니를 만나 처치하고 깃털을 얻었을 때만 하세요."}, [116]={npc="조른 스카이시어", tgt="조른 스카이시어", tag="선택사항", desc="희귀 몹 워시트 포우니를 만나 처치하고 깃털을 얻었을 때만 하세요."}, [117]={npc="뻐드렁니", tgt="뻐드렁니"}, [118]={npc="뻐드렁니", tgt="뻐드렁니", desc="이미 잡아 둔 혈석 파편이 있으면 바로 제출하고, 없을 때만 야영지 밖에서 하나 더 잡으세요."}, [119]={hint="불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 혈석을 가져가야 합니다.", desc="이미 잡아 둔 혈석 파편이 있으면 바로 제출하고, 없을 때만 야영지 밖에서 하나 더 잡으세요."}, [120]={npc="뻐드렁니", tgt="뻐드렁니", desc="이미 잡아 둔 혈석 파편이 있으면 바로 제출하고, 없을 때만 야영지 밖에서 하나 더 잡으세요."}, [121]={npc="뻐드렁니", tgt="뻐드렁니", tag="선택사항", desc="남쪽에서 우두머리 3마리를 모두 잡을 때만 받으세요."}, [122]={npc="그런트 로그마르", tgt="그런트 로그마르", tag="선택사항"}, [123]={text="레벨에 따라 먼 남쪽 구간을 추가하고, 마지막에 남은 퀘스트를 정리하세요"}, [124]={hint="불모의 땅, 타우라조 야영지에 있는 테터낵 스틸포지에게 서슬갈기일족의 기습용 단검, 불타는 마법봉, 그리고 전투용 방패를 가져가야 합니다.", tag="선택사항"}, [125]={hint="나크와 쿠즈, 로크를 처단하여 그들의 해골을 불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 가져가야 합니다.", tag="선택사항", desc="이름 있는 몹 3마리는 서로 다른 정착지에 있으니 좌표를 따라 정리하세요."}, [126]={npc="갠 스톤스파이어", tgt="갠 스톤스파이어", tag="선택사항", desc="23레벨 미만이고 이미 남쪽 끝에 있을 때만 하세요. 야영지의 드워프 두 종류를 함께 처치하고, 가는 길에 작업반장의 일지를 얻으세요."}, [127]={hint="갠 스톤스파이어가 바엘던 발굴인부 15명과 바엘던 현장감독 5명을 처치해 달라고 부탁했습니다.", tag="선택사항", desc="23레벨 미만이고 이미 남쪽 끝에 있을 때만 하세요. 야영지의 드워프 두 종류를 함께 처치하고, 가는 길에 작업반장의 일지를 얻으세요."}, [128]={npc="갠 스톤스파이어", tgt="갠 스톤스파이어", tag="선택사항", desc="23레벨 미만이고 이미 남쪽 끝에 있을 때만 하세요. 야영지의 드워프 두 종류를 함께 처치하고, 가는 길에 작업반장의 일지를 얻으세요."}, [129]={npc="[UNUSED] Sulhasa", tgt="[UNUSED] Sulhasa", desc="먼지진흙 습지 경계의 나무 위에 있는 [UNUSED] Sulhasa를 찾으세요."}, [130]={hint="불모의 땅 남부에 있는 술하사가 안전하게 나무에서 내려올 수 있도록 주위에 있는 폭풍도마뱀 7마리와 긴발톱 빗송곳니하이에나 7마리를 처치해야 합니다."}, [131]={npc="[UNUSED] Sulhasa", tgt="[UNUSED] Sulhasa"}, [132]={npc="뻐드렁니", tgt="뻐드렁니", tag="선택사항"}, [133]={npc="뻐드렁니", tgt="뻐드렁니", tag="선택사항", desc="마지막에 크로스로드로 돌아가면서 제출하세요."}, [134]={npc="테터낵 스틸포지", tgt="테터낵 스틸포지", tag="선택사항"}, [135]={text="조른 퀘스트 라인과 다른 정류장으로 이어지는 시작 퀘스트 2개를 마무리하세요"}, [136]={text="타우라조 야영지에서 북쪽으로 톱니항 서쪽까지 가는 길에 번개갈기와 이샤무헤일을 찾으세요. 신선한 얼룩말 시체를 얻으면 먼저 미끼 퀘스트를 완료하세요."}, [137]={hint="타우라조 야영지에 있는 조른 스카이시어에게 이샤무헤일의 송곳니를 가져가야 합니다.", desc="얼룩말 시체는 30분 후에 썩습니다."}, [138]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [139]={hint="톱니항에 있는 양조업자 드론에게 사바나 사자 어금니 5개, 초원타조 신장 5개와 천둥도마뱀의 뿔 1개를 가져가야 합니다.", tag="선택사항", desc="가는 길에 사자 송곳니, 새 콩팥, 도마뱀 뿔을 모으세요. 다 모으지 못했다면 건너뛰어도 됩니다."}, [140]={npc="양조업자 드론", tgt="양조업자 드론", tag="선택사항"}, [141]={npc="메보크 미지릭스", tgt="메보크 미지릭스", tag="선택사항", desc="먼저 랩터 뿔를 제출해야 합니다. 통곡의 동굴에 갈 계획일 때만 수락하세요."}, [142]={text="톱니항에서 타우라조 야영지로 날아가 조른에게 돌아가세요. 23레벨이고 잿빛 골짜기 사냥 시작 퀘스트를 하지 않는다면 크로스로드에서 서쪽 돌발톱 산맥으로 가세요."}, [143]={npc="조른 스카이시어", tgt="조른 스카이시어"}, [144]={npc="조른 스카이시어", tgt="조른 스카이시어", desc="잿빛 골짜기 토막나무 초소에서 제출하도록 보관하세요."}, [145]={npc="조른 스카이시어", tgt="조른 스카이시어", desc="야영지 밖 천둥도마뱀과 같은 경로입니다. 병 3개를 미리 준비하세요."}, [146]={hint="천둥도마뱀 피 3개를 모아 타우라조 야영지에 있는 조른 스카이시어에게 가져다주어야 합니다.", desc="야영지 밖 천둥도마뱀과 같은 경로입니다. 병 3개를 미리 준비하세요."}, [147]={npc="조른 스카이시어", tgt="조른 스카이시어", desc="야영지 밖 천둥도마뱀과 같은 경로입니다. 병 3개를 미리 준비하세요."}, [148]={npc="조른 스카이시어", tgt="조른 스카이시어"}, [149]={hint="천둥매를 찾아 처치하고 천둥매 날개를 타우라조 야영지에 있는 조른 스카이시어에게 가져가야 합니다."}, [150]={npc="조른 스카이시어", tgt="조른 스카이시어"}, [151]={text="크로스로드로 날아가 남은 퀘스트를 제출한 뒤, 서쪽으로 명예의 감시탑(35.26, 27.88)을 지나 돌발톱 산맥으로 가세요."}, [152]={npc="만크릭", tgt="만크릭"}, [153]={npc="만크릭", tgt="만크릭"}, [154]={npc="코란", tgt="코란"}, [155]={hint="불모의 땅, 크로스로드에 있는 톨크에게 로크의 해골을 가져가야 합니다.", tag="선택사항"}, [156]={npc="톨크", tgt="톨크", tag="선택사항"}, [157]={npc="소렉", tgt="소렉", tag="선택사항", desc="오그리마, 썬더 블러프, 언더시티의 훈련사에게서 받을 수 있습니다. 토름 레이지토템(57.24, 87.37), 발터스 파울러(47.40, 17.29)에게서도 같은 퀘스트를 받을 수 있습니다."}, [158]={hint="루가 레이지토템과 대화하십시오.", tag="선택사항", desc="오그리마, 썬더 블러프, 언더시티의 훈련사에게서 받을 수 있습니다."}, [159]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항", desc="오그리마, 썬더 블러프, 언더시티의 훈련사에게서 받을 수 있습니다."}, [160]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항", desc="타우라조 야영지 주변 퀘스트와 함께 진행하세요."}, [161]={hint="타우라조 야영지에 있는 루가 레이지토템에게 꿈틀거리는 더듬이 5개를 가져가야 합니다.", tag="선택사항", desc="타우라조 야영지 주변 퀘스트와 함께 진행하세요."}, [162]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항", desc="타우라조 야영지