    ["05-d5"] = {name="죽음의 폐광", entrance="서부 몰락지대 38.20, 77.50", pickup="은빛소나무 숲으로 가기 전에, 티리스팔 숲 반다리온 성채에서 다니사에게 외교 사건을 받고, 가는 길에 은빛소나무 숲과 펜리스 섬 선행 퀘스트를 끝내세요(언데드 성기사만 해당). 20레벨이 되면 공동묘지에서 루미나에게 달빛이 입 맞춘 칼날을 받고 트레반에게 메모를 받으세요(언데드 성기사만 해당). 불모의 땅 톱니항에서 배를 타고 무법항으로 가서, 가시덤불 골짜기를 따라 북쪽으로 그늘숲까지 간 뒤 서쪽의 문브룩으로 가세요.", pickupS={{"은빛소나무 숲으로 가기 전에, 티리스팔 숲 반다리온 성채에서 다니사에게 외교 사건을 받고, 가는 길에 은빛소나무 숲과 펜리스 섬 선행 퀘스트를 끝내세요(언데드 성기사만 해당)", {race={"Scourge"}, class={"PALADIN"}}}, {"20레벨이 되면 공동묘지에서 루미나에게 달빛이 입 맞춘 칼날을 받고 트레반에게 메모를 받으세요(언데드 성기사만 해당)", {race={"Scourge"}, class={"PALADIN"}}}, {"불모의 땅 톱니항에서 배를 타고 무법항으로 가서, 가시덤불 골짜기를 따라 북쪽으로 그늘숲까지 간 뒤 서쪽의 문브룩으로 가세요"}}, tips={{k="動線", text="입구 광산 갱도 → 라크조르 → 스니드 벌목장에서 목재 줍기 → 길니드 용광로 → 문을 폭파하고 선착장 진입 → 미스터 스마이트 → 선장 그린스킨 → 에드윈 밴클리프. 요리사는 배 아래층에 있습니다. 목재만 필요하면 스니드의 방에서 얻은 뒤 나가도 됩니다."}, {k="取捨", text="레벨링만 한다면 이 여정은 건너뛰어도 됩니다. 달빛이 입 맞춘 칼날은 스니드의 방까지 가서 목재만 모으면 됩니다(언데드 성기사만 해당). 파티가 마지막 우두머리의 장비를 원하면 끝까지 진행하세요.", s={{"레벨링만 한다면 이 여정은 건너뛰어도 됩니다"}, {"달빛이 입 맞춘 칼날은 스니드의 방까지 가서 목재만 모으면 됩니다(언데드 성기사만 해당)", {race={"Scourge"}, class={"PALADIN"}}}, {"파티가 마지막 우두머리의 장비를 원하면 끝까지 진행하세요"}}}, {k="說明", text="문브룩 광산 입구는 약 42.40, 70.40입니다. 먼저 건물로 들어가 아래층으로 내려간 뒤, 갱도를 따라 38.20, 77.50의 정식 입구로 가세요. 얼라이언스가 받는 데피아즈 퀘스트는 호드 목록에 넣지 않았습니다.", s={{"문브룩 광산 입구는 약 42.40, 70.40입니다"}, {"먼저 건물로 들어가 아래층으로 내려간 뒤, 갱도를 따라 38.20, 77.50의 정식 입구로 가세요"}, {"얼라이언스가 받는 데피아즈 퀘스트는 호드 목록에 넣지 않았습니다"}}}}, steps={[1]={npc="다니타 모르", tgt="다니타 모르"}, [2]={hint="은빛소나무 숲의 공동묘지로 이동한 후 트레반 롤을 찾아가 실종된 대지 고리회 여행자에 관해 얘기해야 합니다."}, [3]={npc="트레반 롤", tgt="트레반 롤"}, [4]={npc="트레반 롤", tgt="트레반 롤", preText="외교 사건"}, [5]={hint="죽음경비병 발드렌을 찾아가 최근 공동묘지를 지나간 정체불명의 대지 고리회 여행자들에 관해 얘기해야 합니다."}, [6]={npc="죽음경비병 발드렌", tgt="죽음경비병 발드렌"}, [7]={npc="죽음경비병 발드렌", tgt="죽음경비병 발드렌", preText="수상한 한 쌍"}, [8]={hint="동쪽의 펜리스 섬을 조사한 후, 대지 고리회 일행의 운명을 알아내야 합니다."}, [9]={npc="까맣게 탄 시체", npcObj=true}, [10]={npc="까맣게 탄 시체", npcObj=true, preText="암담한 운명"}, [11]={hint="북쪽의 펜리스 요새를 조사하고 실종된 대지 고리회 일행을 찾아야 합니다."}, [12]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [13]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", preText="펜리스 성채로"}, [14]={hint="썩은가죽 놀에게서 펜리스 섬 열쇠를 회수한 후, 열쇠를 사용해 루미나 윈드싱어를 구출해야 합니다."}, [15]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [16]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="은빛소나무 숲 공동묘지의 직업 퀘스트에 따라 바람구체자를 처리하세요.", preText="루미나 윈드싱어"}, [17]={hint="루미나 윈드싱어와 동행해 펜리스 요새에서 탈출하도록 도와야 합니다.", desc="은빛소나무 숲 공동묘지의 직업 퀘스트에 따라 바람구체자를 처리하세요."}, [18]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="은빛소나무 숲 공동묘지의 직업 퀘스트에 따라 바람구체자를 처리하세요."}, [19]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", preText="바람구체자의 분노"}, [20]={hint="공동묘지에서 루미나 윈드싱어와 대화해야 합니다."}, [21]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [22]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="퀘스트를 받은 뒤 트레반 롤과 대화해 무기 메모 1개를 받고, 퀘스트는 로그에 남겨 두세요.", preText="빚"}, [23]={text="죽음의 폐광 입구"}, [24]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", desc="획득률은 고블린 목공이 떨어뜨리는 흰돌참나무 목재만 기준입니다. 위치: 라크조르를 지나 벌목 작업장으로 들어가 스니드 옆의 목수를 처치하세요.", spot="라크조르를 지나 벌목 작업장으로 들어가 스니드 옆의 목수를 처치하세요."}, [25]={npc="트레반 롤", tgt="트레반 롤", desc="무기 메모, 흰돌 참나무, 그림자송곳니 성채의 마력 부여된 은괴, 코르석을 찾아서의 정화된 코르 보석을 모두 갖추고 제출하세요."}}},
    ["05-d4"] = {name="통곡의 동굴", entrance="불모의 땅 46.00, 36.30", pickup="불모의 땅 십자로에서 통가를 찾아 잊혀진 웅덩이 → 죽은 오아시스 → 변화된 생물을 완료한 뒤, 썬더 블러프에서 하뮬, 나라, 자마를 찾아가세요. 톱니항에서는 랩터 뿔를 먼저 제출한 뒤 영리해지는 음료과 99년 묵은 와인를 받으세요. 마지막으로 동굴 입구 위 바위 선반에서 날팍과 에브루를 찾으세요.", pickupS={{"불모의 땅 십자로에서 통가를 찾아 잊혀진 웅덩이 → 죽은 오아시스 → 변화된 생물을 완료한 뒤, 썬더 블러프에서 하뮬, 나라, 자마를 찾아가세요"}, {"톱니항에서는 랩터 뿔를 먼저 제출한 뒤 영리해지는 음료과 99년 묵은 와인를 받으세요"}, {"마지막으로 동굴 입구 위 바위 선반에서 날팍과 에브루를 찾으세요"}}, tips={{k="動線", text="얕은 물 입구의 여군주 아나콘드라 → 강 서쪽의 군주 코브란 → 수로로 돌아가 동쪽의 군주 피타스, 스컴, 군주 서펜티스, 불멸의 베르단 → 네 송곳니 우두머리를 모두 처치한 뒤 입구로 돌아와 제자를 호위하고 걸신들린 무타누스를 처치하세요. 양쪽 곁길을 지나며 불뱀꽃을 캐고, 돌연변이 통가죽과 통곡의 정수를 모으고, 돌연변이 몹을 정리하세요."}, {k="取捨", text="랩터 뿔를 제출하지 않으면 영리해지는 음료이 보이지 않습니다. 퀘스트 하나가 모자라다고 파티 전체가 입구에서 기다릴 필요는 없습니다. 불모의 땅 십자로 오아시스 연계를 이미 끝냈다면 진행 상황대로 하뮬 룬토템부터 이어 가세요."}, {k="說明", text="바깥 동굴 입구는 약 47.70, 35.00입니다. 무성한 오아시스에서 석굴로 들어가 통로를 지나면 더 안쪽에 던전 입구가 있습니다. 날팍과 에브루는 바깥 동굴 위쪽의 작은 동굴에 있으니, 퀘스트를 받은 뒤 내려가세요.", s={{"바깥 동굴 입구는 약 47.70, 35.00입니다"}, {"무성한 오아시스에서 석굴로 들어가 통로를 지나면 더 안쪽에 던전 입구가 있습니다"}, {"날팍과 에브루는 바깥 동굴 위쪽의 작은 동굴에 있으니, 퀘스트를 받은 뒤 내려가세요"}}}}, steps={[1]={npc="통가 룬토템", tgt="통가 룬토템"}, [2]={hint="통가 룬토템에게 발견한 내용을 보고해야 합니다."}, [3]={npc="통가 룬토템", tgt="통가 룬토템"}, [4]={npc="통가 룬토템", tgt="통가 룬토템", preText="잊혀진 웅덩이"}, [5]={hint="죽은 오아시스를 조사한 후 크로스로드에 있는 통가에게 돌아가야 합니다."}, [6]={npc="통가 룬토템", tgt="통가 룬토템"}, [7]={npc="통가 룬토템", tgt="통가 룬토템", preText="죽은 오아시스"}, [8]={hint="크로스로드에 있는 통가 룬토템에게 변형된 무쇠턱거북 등껍질 8개를 가져다주어야 합니다.", tag="대상: 오아시스 무쇠턱거북 / 오아시스 무쇠턱거북 새끼"}, [9]={npc="통가 룬토템", tgt="통가 룬토템"}, [10]={npc="통가 룬토템", tgt="통가 룬토템", preText="변화된 생물"}, [11]={hint="하뮬 룬토템과 대화하십시오."}, [12]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템"}, [13]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템", preText="하뮬 룬토템"}, [14]={hint="나라 와일드메인과 대화하십시오."}, [15]={npc="나라 와일드메인", tgt="나라 와일드메인"}, [16]={npc="나라 와일드메인", tgt="나라 와일드메인", preText="나라 와일드메인"}, [17]={npc="연금술사 자마", tgt="연금술사 자마"}, [18]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [19]={hint="온전한 랩터 뿔 5개를 모아 톱니항에 있는 메보크 미지릭스에게 가져가야 합니다."}, [20]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [21]={npc="메보크 미지릭스", tgt="메보크 미지릭스", preText="랩터 뿔"}, [22]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈"}, [23]={npc="날팍", tgt="날팍"}, [24]={npc="에브루", tgt="에브루"}, [25]={hint="톱니항에 있는 기중기 기사 비글퍼즈가 통곡의 동굴에 숨어 있는 광기의 매글리시에게서 99년 숙성된 포트 와인을 되찾아 달라고 부탁했습니다."}, [26]={text="통곡의 동굴 입구"}, [27]={hint="썬더 블러프에 있는 연금술사 자마가 불뱀꽃 10개를 모아 달라고 부탁했습니다.", desc="불뱀꽃은 던전 입구 앞 바깥 동굴에 자랍니다. 위치: 입구로 들어가 얕은 물길을 따라 불뱀꽃을 찾고, 양쪽 강변에서 캘 수 있는 식물을 모두 캐세요.", spot="입구로 들어가 얕은 물길을 따라 불뱀꽃을 찾고, 양쪽 강변에서 캘 수 있는 식물을 모두 캐세요."}, [28]={hint="통곡의 동굴에 있는 날팍이 돌연변이 통가죽 20개를 가져다 달라고 부탁했습니다.", desc="Deviate Slayer는 던전 입구 앞 바깥 동굴에 있습니다. 위치: 얕은 물 갈림길과 양쪽 곁길의 돌연변이 몹을 정리하고, 우두머리를 잡으며 가죽을 주우세요.", spot="얕은 물 갈림길과 양쪽 곁길의 돌연변이 몹을 정리하고, 우두머리를 잡으며 가죽을 주우세요."}, [29]={hint="통곡의 동굴에 있는 에브루가 돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해 달라고 부탁했습니다.", desc="위치: 얕은 물 갈림길을 먼저 정리한 뒤, 수로 서쪽과 동쪽 곁길에서 네 종류의 몹을 마저 처치하세요.", spot="얕은 물 갈림길을 먼저 정리한 뒤, 수로 서쪽과 동쪽 곁길에서 네 종류의 몹을 마저 처치하세요."}, [30]={hint="톱니항에 있는 메보크 미지릭스에게 통곡의 정수 6병을 가져가야 합니다.", desc="좌표는 던전 입구 밖의 포식성 세포괴물 위치입니다. 던전 안에서도 계속 모을 수 있습니다. 던전 입구 밖에서 탐식하는 점액괴물을 처치할 수 있습니다. 위치: 던전 안에서는 수로를 따라 점액괴물을 찾고, 통곡의 정수가 모자라면 더 모으세요.", spot="던전 안에서는 수로를 따라 점액괴물을 찾고, 통곡의 정수가 모자라면 더 모으세요."}, [31]={hint="코브란, 아나콘드라, 피타스, 서펜티스의 보석을 모아 썬더 블러프에 있는 나라 와일드메인에게 돌아가야 합니다.", desc="위치: 얕은 물에서 여군주 아나콘드라, 강 서쪽에서 군주 코브란, 강 동쪽에서 나머지 두 우두머리를 찾으세요.", spot="얕은 물에서 여군주 아나콘드라, 강 서쪽에서 군주 코브란, 강 동쪽에서 나머지 두 우두머리를 찾으세요."}, [32]={npc="빛나는 조각", npcObj=true, tag="게임 내 확인이 필요합니다", desc="드루이드 네 명을 정리한 뒤 입구로 돌아가 나랄렉스의 제자를 찾으세요. 호위와 의식을 마치고, 걸신들린 무타누스를 처치해 조각을 얻으세요."}, [33]={npc="날팍", tgt="날팍"}, [34]={npc="에브루", tgt="에브루"}, [35]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈"}, [36]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [37]={hint="톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오."}, [38]={npc="팔라 세이지윈드", tgt="팔라 세이지윈드"}, [39]={npc="팔라 세이지윈드", tgt="팔라 세이지윈드", preText="빛나는 조각"}, [40]={hint="장로의 봉우리에 있는 하뮬 룬토템에게 악몽의 조각을 가져가야 합니다."}, [41]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템"}, [42]={npc="나라 와일드메인", tgt="나라 와일드메인"}, [43]={npc="연금술사 자마", tgt="연금술사 자마"}}},
    ["02-11"] = {name="돌발톱 산맥", tips={{k="交通", text="해바위 은거지에 처음 오면 비행 지점을 열고 귀환석 위치를 설정하세요. 귀환석은 남쪽 고개 퀘스트를 제출하고 해바위 은거지로 돌아올 때까지 남겨 두고, 이후 톱니항으로 날아가세요."}, {k="取捨", text="해둘 만합니다. 땅거미 호수에서 가이아의 씨앗을 줍고 돌발톱 봉우리에서 세나리우스의 유산을 진행하세요. 씨앗을 제출한 뒤 그을린 골짜기 목표 4개를 한 번에 하세요. 버섯구름 봉우리 프리윈드 초소로 가는 길에 대승강기에서 휴가 통지서을 제출하세요."}, {k="取捨", text="나중에 지나갈 때 하세요. 은 잿빛 골짜기 토막나무 초소에서 오르다누스를 잡는 퀘스트입니다. 추가 지령~게렌조 렌치휘슬은 나중에 칼바람 바위산에 다시 갈 때만 이어서 하면 톱니항 왕복을 한 번 줄일 수 있습니다."}, {k="取捨", text="건너뛰어도 됩니다. 베스셀레스와 토석인이여 깨어나라는 엘리트를 잡아야 합니다. 진질의 숲의 마법은 여러 종류의 야수를 잡아야 하고 제출 장소가 남쪽 끝이므로, 재료가 이미 있을 때만 제출하세요."}, {k="提醒", text="25레벨이 안 됐다면 그을린 골짜기 외곽(약 32, 64)에서 블러드레이지 하피나 불 정령을 잡으세요. 먼저 혼자 있는 몹부터 한 마리씩 유인하세요.", s={{"25레벨이 안 됐다면 그을린 골짜기 외곽(약 32, 64)에서 블러드레이지 하피나 불 정령을 잡으세요"}, {"먼저 혼자 있는 몹부터 한 마리씩 유인하세요"}}}}, danger={[1]="그물누비 고개에는 엘리트 거미 베스셀레스가 있습니다. 먼저 주변의 작은 거미를 정리하세요. 파티가 없으면 건너뛰세요.", [2]="구릉바위 협곡의 동굴은 길이 좁습니다. 통을 열어 고게로크를 소환하기 전에 입구에서 통까지의 퇴로를 정리하세요."}, grind={[1]={mob="혈폭풍하피", note="그을린 골짜기 동쪽 입구에 일반 몹이 보통 밀도로 있습니다. 바깥쪽에서 혼자 있는 몹부터 고르고 순찰을 조심하세요. 23레벨부터 경험치를 채우기 좋습니다."}, [2]={mob="혈폭풍일족 바람마녀", note="그을린 골짜기 동쪽에 시전하는 일반 몹이 밀집해 있습니다. 산벽을 이용해 야영지에서 끌어내 둥지 무리가 한꺼번에 붙지 않게 하세요. 그을린 골짜기 퀘스트와 함께 진행하세요."}}, supply={[1]={npc="타름"}, [2]={npc="여관주인 자이카"}, [3]={npc="보른다"}, [4]={npc="여관주인 자이카"}, [5]={npc="그라우날"}, [6]={npc="지다"}}, steps={[1]={text="크로스로드에서 북서쪽 대로를 따라 돌발톱 산맥 입구로 가며, 먼저 불모의 땅의 시리스 스톤브레이크(35.26, 27.88)를 찾으세요."}, [2]={hint="돌발톱 산맥에 있는 시리스 스톤브레이크와 대화하십시오.", tag="불모의 땅 크로스로드에서 이미 받은 경우, 선택사항"}, [3]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="불모의 땅 크로스로드에서 이미 받은 경우, 선택사항"}, [4]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크"}, [5]={text="돌발톱 산맥 남쪽을 지나 말라카진으로 간 뒤, 거미 지역을 지나 칼바람 바위산으로 올라가세요."}, [6]={hint="돌발톱 산맥의 동굴에서 야영을 하는 진질에게 달소크의 편지를 전달하십시오.", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [7]={npc="의술사 진질", tgt="의술사 진질", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [8]={npc="젠질라", tgt="젠질라"}, [9]={npc="의술사 진질", tgt="의술사 진질", tag="선택사항"}, [10]={npc="현상수배: 베스셀레스", npcObj=true, tag="선택사항"}, [11]={hint="칼바람 바위산에 있는 지즈 피직스와 대화하십시오.", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [12]={npc="지즈 피직스", tgt="지즈 피직스", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [13]={npc="지즈 피직스", tgt="지즈 피직스"}, [14]={hint="말라카진에 있는 젠질라가 동굴이끼 땅거미 10마리와 동굴이끼 독거미 7마리를 처치해달라고 부탁했습니다."}, [15]={hint="톱니항에 있는 메보크 미지릭스에게 동굴이끼거미알 15개를 가져가야 합니다.", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [16]={hint="투자개발회사 나무꾼 15명을 처치한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오."}, [17]={hint="돌발톱 산맥에 있는 지즈 피직스를 위해 슈퍼 절단기 6000 설계도를 입수해야 합니다.", desc="설계도는 투자개발회사 채광 작업자가 떨어뜨립니다."}, [18]={npc="지즈 피직스", tgt="지즈 피직스"}, [19]={npc="지즈 피직스", tgt="지즈 피직스"}, [20]={hint="베스셀레스를 처치하고 그 증거로 베스셀레스의 송곳니를 들고 해바위 야영지의 마그그랜에게 가져가야 합니다.", tag="선택사항", desc="베스셀레스는 엘리트입니다. 이길 수 없으면 건너뛰세요."}, [21]={text="길을 따라 해바위 은거지로 올라가 탈름(45.12, 59.84)에게서 비행 지점을 열고, 여관주인 자이카(47.47, 62.13)에게서 귀환석 위치를 설정하세요. 남쪽 고개 퀘스트를 제출할 때까지 그대로 두세요."}, [22]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="선택사항"}, [23]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [24]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드"}, [25]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [26]={npc="츄나만", tgt="츄나만"}, [27]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [28]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [29]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [30]={text="땅거미 호수와 돌발톱 봉우리를 북쪽으로 돌아 올라가고, 왔던 길로 내려오세요. 해바위 은거지에서 씨앗을 제출한 뒤 서쪽으로 가세요."}, [31]={hint="해바위 야영지에 있는 탐라 윈드필드가 가이아 씨앗 10개를 모아다 달라고 부탁했습니다."}, [32]={hint="해바위 야영지 근처에 있는 브랠린 파이어핸드를 위해 세나리우스의 후예, 세나리우스의 딸, 그리고 세나리온 식물학자들을 각각 4명씩 처치해야 합니다."}, [33]={hint="말라카진에 있는 의술사 진질이 돌발톱 수액 5개, 황혼의 수염 5개, 순록의 눈 30개와 마룡 비늘 1개를 가져다 달라고 부탁했습니다.", tag="선택사항", desc="수사슴의 눈은 많이 나오니 세나리우스의 유산을 하며 지나가는 길에 모으고, 일부러 다 모으지 마세요."}, [34]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [35]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [36]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드"}, [37]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="선택사항"}, [38]={text="해바위 은거지에서 서쪽으로 그을린 골짜기에 들어가 하피, 태양석, 불 정령, 흙더미를 한 바퀴에 묶어 진행하세요."}, [39]={hint="해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 하피, 복병, 암살자, 약탈자를 각각 7마리씩 처치해달라고 부탁했습니다."}, [40]={hint="반짝이는 태양석 15개를 모로갈에게 가져가야 합니다."}, [41]={hint="해바위 야영지에 있는 츄나만에게 발화석 10개를 가져가야 합니다."}, [42]={hint="가이아 흙더미에 가이아 씨앗 10개를 심은 후, 마력 깃든 가이아 씨앗을 가지고 해바위 야영지에 있는 탐라에게 돌아가야 합니다.", desc="솟아오른 가이아 흙더미에 퀘스트 씨앗을 사용하세요."}, [43]={text="그을린 골짜기 한 바퀴를 마치면 동쪽 길로 해바위 은거지에 돌아가 한꺼번에 제출하세요. 귀환석은 말라카진과 고개에서 돌아올 때를 위해 남겨 두세요."}, [44]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [45]={npc="모르로갈", tgt="모르로갈"}, [46]={npc="츄나만", tgt="츄나만"}, [47]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [48]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="엘리트, 선택사항"}, [49]={hint="해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 갈퀴발톱을 처치하고 그 증거로 그녀의 유해를 가져오라고 부탁했습니다.", tag="엘리트, 선택사항", desc="블러드레이지 리퍼는 26레벨 엘리트이니 동료가 있을 때만 하세요."}, [50]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="엘리트, 선택사항"}, [51]={text="해바위 은거지에서 그을린 골짜기 퀘스트를 제출한 뒤 남동쪽 길로 내려가 선택 퀘스트인 구릉바위 협곡을 하거나, 바로 말라카진과 불모의 땅 고개로 가세요. 고개 퀘스트를 제출할 때까지 해바위 은거지 귀환석을 남겨 두세요."}, [52]={hint="구릉바위 협곡에 있는 동굴을 탐사한 다음 해바위 야영지에 있는 모르로갈에게 리조나이트 수정 10개를 가져가야 합니다.", tag="선택사항"}, [53]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [54]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [55]={hint="마력 깃든 리조나이트 수정으로 리조나이트 광석을 연 다음 고게로크를 처치해야 합니다. 그를 처치했다는 소식과 마력 깃든 리조나이트 수정을 들고 모르로갈에게 돌아가십시오.", tag="선택사항", desc="이 단계에서 20레벨 엘리트가 소환됩니다. 혼자라면 건너뛰어도 됩니다."}, [56]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [57]={npc="젠질라", tgt="젠질라"}, [58]={npc="의술사 진질", tgt="의술사 진질", tag="선택사항"}, [59]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크"}, [60]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="경험치가 충분하면 되돌아가지 않아도 됩니다, 선택사항"}, [61]={hint="벌목기 XT:4와 XT:9를 파괴한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오.", tag="경험치가 충분하면 되돌아가지 않아도 됩니다, 선택사항, 대상: XT:4/XT:9"}, [62]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="경험치가 충분하면 되돌아가지 않아도 됩니다, 선택사항"}, [63]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="썬더 블러프 전제조건, 선택사항"}, [64]={text="고개에서 시리스에게 제출한 뒤 귀환석으로 해바위 은거지에 돌아가 탈름에서 비행해 톱니항에서 알과 밀서를 제출하세요. 귀환석이 대기 중이면 고개에서 길을 따라 불모의 땅으로 들어가 크로스로드에서 톱니항으로 날아가세요."}, [65]={npc="메보크 미지릭스", tgt="메보크 미지릭스", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [66]={hint="불모의 땅에 있는 스퍼터밸브에게 봉인된 편지를 전달해야 합니다."}, [67]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [68]={npc="스퍼터밸브", tgt="스퍼터밸브", tag="나중에 지나갈 때 진행, 선택사항"}, [69]={text="선택 퀘스트 순결한 피의 선행 퀘스트를 하고 원로 마가타을 가지고 있다면 톱니항에서 썬더 블러프로 날아가 이어서 진행하세요. 썬더 블러프 비행 지점을 열지 않았고 가는 길에 열 계획도 없다면 이 퀘스트는 건너뛰고 톱니항에서 바로 오그리마로 날아가세요."}, [70]={hint="썬더 블러프에 있는 마가타와 대화하십시오.", tag="썬더 블러프 전제조건, 선택사항"}, [71]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프 전제조건, 선택사항"}, [72]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프 전제조건, 선택사항"}, [73]={hint="썬더 블러프의 예언의 웅덩이에 있는 연금술사 자마와 대화해야 합니다.", tag="썬더 블러프 전제조건, 선택사항"}, [74]={npc="연금술사 자마", tgt="연금술사 자마", tag="썬더 블러프 전제조건, 선택사항"}, [75]={npc="연금술사 자마", tgt="연금술사 자마", tag="썬더 블러프 전제조건, 선택사항"}, [76]={npc="비닉스", tgt="비닉스", tag="선택사항", desc="먼저 이 준비를 마친 뒤 은빛소나무 숲에서 젤토스의 뿔을 진행하세요. 던전 잠입 때 문을 여는 선택 방법입니다."}, [77]={hint="획득처: 투자개발회사 벌채꾼, 투자개발회사 운전수, 투자개발회사 나무꾼", tag="선택사항", desc="먼저 이 준비를 마친 뒤 은빛소나무 숲에서 젤토스의 뿔을 진행하세요. 던전 잠입 때 문을 여는 선택 방법입니다."}, [78]={npc="비닉스", tgt="비닉스", tag="선택사항", desc="먼저 이 준비를 마친 뒤 은빛소나무 숲에서 젤토스의 뿔을 진행하세요. 던전 잠입 때 문을 여는 선택 방법입니다."}, [79]={npc="우르쿄", tgt="우르쿄"}, [80]={hint="퀘스트 목표를 완료하세요."}, [81]={npc="우르쿄", tgt="우르쿄"}, [82]={text="썬더 블러프 선택 퀘스트를 마쳤다면 먼저 썬더 블러프에서 오그리마로 날아가세요. 오그리마를 나와 듀로타 비행선 탑의 프레자(50.82, 13.54)에게서 티리스팔 숲행 비행선인지 확인하고, 브릴 남쪽 탑에 내려 언더시티까지 걸어가세요. 이어서 힐스브래드 구릉지 타렌 밀농장으로 가세요."}}},
    ["02-12"] = {name="힐스브래드 구릉지", tips={{k="交通", text="처음에는 Sepulcher에서 타렌 밀농장까지 걸어가세요. 자라이즈에게서 비행 지점을 열고 셰이에게서 귀환석 위치를 설정하세요. 떠날 때는 언더시티에서 브릴 남쪽 탑까지 걸어가 오그리마행 비행선을 타세요."}, {k="取捨", text="추천: 서쪽 한 바퀴에서 힐스브래드 전투와 함께 괴로움의 비약과 고통의 비약을 모으세요. 을 반납하면 죽음의 전리품이 열리니, 이후 인간을 처치하며 두개골을 챙기세요."}, {k="取捨", text="추천: 죽음추적자 마소즈 주변에서 정찰병 지원와 죽음의 비약를 함께 하세요. 순결한 피을 받았다면 던홀드 요새 외곽까지 이어서 가세요. Forever XP는 한 바퀴를 마친 뒤에야 두개골을 채우지만, 여기서는 힐스브래드 전투부터 바로 챙기세요."}, {k="取捨", text="건너뛰기: 위험 인물 수배!의 대상이 없어서 되돌아가야 한다면 건너뛰고 바로 다음 지점으로 가세요. 던 가록은 힐스브래드 전투 때문에 몬스터가 많으니 혼자라면 더 높은 레벨에 하세요. 승패의 고지 서쪽 능선에는 고레벨 퓨마가 있으니 급하면 연계 전체를 건너뛰세요."}, {k="取捨", text="나중에 지나가며: 돌발톱 산맥 해바위 야영지에서 타렌 밀농장으로의 모험를 받았다면 던홀드 요새를 갈 때 순결한 피을 완료하세요. 썬더 블러프로의 귀환은 버섯구름 봉우리 높새바람 봉우리로 가져가되, 썬더 블러프를 지날 때 반납하세요."}, {k="取捨", text="나중에 지나가며: 죽음의 비약 → 죽음의 비약을 마친 뒤, 힐스브래드 구릉지 타렌 밀농장 구간에서 언더시티의 죽음의 비약를 받고 힐스브래드 해안에서 하세요."}, {k="取捨", text="나중에 지나가며: 지금 던홀드 요새의 포로 두 명을 구하고 싶다면 크루스크의 포로 구출을 함께 하세요. 같은 곳의 비밀결사대원 현상수배도 같이 할 수 있습니다. 알터랙 산맥 항목에 두 퀘스트의 전체 단계가 있습니다. 을 완료해야 29레벨에 침투가 이어집니다."}, {k="提醒", text="27레벨이 되면 버섯구름 봉우리 프리윈드 초소에 잠깐 들른 뒤 잿빛 골짜기로 가세요. 27레벨이 안 됐다면 서쪽 힐스브래드 농장(약 33, 42)에서 농부를 잡거나 던홀드 요새 외곽(약 77, 43)의 일반 비밀결사 조직원을 잡으세요. 파티가 있으면 던 가록에 도전할 수 있습니다.", s={{"27레벨이 되면 버섯구름 봉우리 프리윈드 초소에 잠깐 들른 뒤 잿빛 골짜기로 가세요"}, {"27레벨이 안 됐다면 서쪽 힐스브래드 농장(약 33, 42)에서 농부를 잡거나 던홀드 요새 외곽(약 77, 43)의 일반 비밀결사 조직원을 잡으세요"}, {"파티가 있으면 던 가록에 도전할 수 있습니다"}}}}, danger={[1]="던 가록의 소총병, 사제, 산지기는 계단 입구에서 서로 지원합니다. 파티로 바깥쪽부터 정리한 뒤 실내로 들어가 대위를 찾으세요.", [2]="서쪽 봉우리에 약병을 놓으려면 설인 동굴 위쪽을 지나야 합니다. 고레벨 산사자가 보이면 비탈을 따라 돌아가고, 가파른 비탈을 곧장 오르지 마세요."}, grind={[1]={mob="힐스브래드 농부", note="힐스브래드 농장 동쪽에 일반 몹이 보통 밀도로 있습니다. 농가 문 앞에 몰려 있는 무리를 피하세요. 지나가며 힐스브래드 인간 두개골도 모을 수 있습니다."}, [2]={note="농장 중앙에 일반 몹이 보통 밀도로 있습니다. 밭가를 따라 순찰하는 보병을 찾으세요. 의원과 농부가 함께 서 있는 집 안은 피하세요."}, [3]={mob="덩치큰 회색곰", note="던홀드 요새 북쪽 숲에는 일반 몹이 드물게 있습니다. 요새의 무리는 피하세요. 동쪽 주요 경로로 돌아오는 길에 몇 마리를 잡기 좋습니다."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="돌발톱 산맥 해바위 은거지에서 이미 언더시티에 들어갔다면 도시에서 출발하세요. 타렌 밀농장 비행 지점을 열었다면 바로 날아가고, 처음이라면 Sepulcher로 날아간 뒤 남쪽 길을 따라 은빛소나무 숲에서 힐스브래드로 이어지는 동쪽 도로로 가서, 구릉지를 지나 북쪽 갈림길로 타렌 밀농장에 가세요. Sepulcher 비행 지점을 열지 않았다면 언더시티에서 지상으로 이동하세요. 아직 칼림도어에 있다면 먼저 오그리마 성 밖에서 비행선을 타세요."}, [2]={text="처음 가면 자라이즈에게서 타렌 밀농장 비행 지점(60.14, 18.62)을 열고, 여관주인 셰이(62.78, 19.03)에게서 귀환석 위치를 설정하세요."}, [3]={hint="힐스브래드 구릉지의 타렌 밀농장에 있는 연금술사 라이던에게 렐퍼럴의 연구 결과를 가져가야 합니다."}, [4]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [5]={hint="타렌 밀농장에 있는 연금술사 라이던에게 자마의 쪽지를 가져가야 합니다.", tag="선택사항"}, [6]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [7]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="퀘스트 타렌 밀농장으로의 모험 필요, 선택사항"}, [8]={text="타렌 밀농장에서 퀘스트 모두 받기 → 서쪽의 곰, 거미, 사자, 농장"}, [9]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [10]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [11]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [12]={npc="위험!", npcObj=true, tag="선택사항"}, [13]={hint="타렌 밀농장에 있는 연금술사 라이던이 회색곰 혀 10개와 이끼거미 수액을 구해다 달라고 부탁했습니다."}, [14]={hint="타렌 밀농장에 있는 연금술사 라이던에게 산사자 피 10병을 가져가야 합니다."}, [15]={hint="힐스브래드 농노 6명, 힐스브래드 농부 6명, 그리고 농부 레이와 농부 게츠를 처치한 다음 타렌 밀농장에 있는 다살리아에게 보고해야 합니다."}, [16]={text="서쪽 첫 번째 루프를 마치면 귀환석으로 타렌 밀농장에 돌아가 제출하세요. 귀환석이 대기 중이면 큰길을 따라 마을로 돌아가세요."}, [17]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [18]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [19]={npc="죽음의경비병 삼사", tgt="죽음의경비병 삼사"}, [20]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [21]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [22]={hint="개구리 움피에게 괴로움의 비약을 먹여야 합니다."}, [23]={npc="움피", tgt="움피"}, [24]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [25]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [26]={text="두 번째 농장 루프 → 동쪽 던홀드와 진흙주둥이꽃 → 서쪽 대장간"}, [27]={hint="스탠리에게 고통의 비약을 먹여야 합니다."}, [28]={npc="스탠리", tgt="스탠리"}, [29]={hint="힐스브래드 소작농 15명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}, [30]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [31]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [32]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [33]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [34]={hint="타렌 밀농장에 있는 연금술사 라이던에게 순결한 피가 든 유리병 5병을 가져가야 합니다.", tag="선택사항"}, [35]={hint="고위집행관 다살리아의 최신 명령서를 타렌 밀농장 남쪽, 던 가록 바깥에 있는 죽음추적자 마소즈에게 전달해야 합니다."}, [36]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈"}, [37]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈", tag="정찰병 지원를 먼저 완료, 선택사항"}, [38]={hint="타렌 밀농장에 있는 연금술사 라이던에게 진흙주둥이꽃 6개를 가져가야 합니다."}, [39]={hint="대장장이 베링턴과 힐스브래드 견습대장장이 4명을 처치해야 합니다."}, [40]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [41]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [42]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [43]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="먼저 순결한 피을 완료하세요. 버섯구름 봉우리 프리윈드 초소에서 제출하세요., 선택사항"}, [44]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [45]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [46]={text="시청 → 광산 → 타렌 밀농장에서 제출"}, [47]={hint="집정관 번사이드와 힐스브래드 원로 5명을 처치해야 합니다. 힐스브래드 선언문을 파괴하고 힐스브래드 마을의 기록부를 빼내 와야 합니다. 그런 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오."}, [48]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [49]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [50]={hint="현장감독 본즈와 힐스브래드 광부 10명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}, [51]={hint="타렌 밀농장의 고위집행관 다살리아가 서기관 호레이스 화이트스티드, 민간인 윌키스, 광부 하켓, 농부 칼라바에 현상금을 걸었습니다.", tag="선택사항"}, [52]={hint="타렌 밀농장에 있는 죽음경비병 삼사가 힐스브래드 주민의 해골 30개를 가져다 달라고 부탁했습니다."}, [53]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [54]={npc="죽음의경비병 삼사", tgt="죽음의경비병 삼사"}, [55]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="선택사항"}, [56]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="파티, 선택사항"}, [57]={hint="던 가록으로 가서 던 가록 산악경비대 10명, 던 가록 소총병 8명, 던 가록 사제 4명과 부대장 아이언힐을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다.", tag="파티, 선택사항"}, [58]={hint="죽음추적자 마소즈를 위해 힐스브래드 구릉지 곳곳의 산봉우리에 연금술사 약병 3개를 놓은 후, 죽음추적자 마소즈에게 가야 합니다.", tag="고레벨, 선택사항"}, [59]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈", tag="선택사항"}, [60]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="파티, 선택사항"}, [61]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="퀘스트 힐스브래드 전투 필요, 선택사항"}, [62]={text="타렌 밀농장에서 언더시티로 날아가 죽음의 비약과 다살리아의 표창장을 제출하세요. 귀환석은 타렌 밀농장에 그대로 두세요."}, [63]={hint="언더시티에 있는 수석 연금술사 파라넬에게 진흙주둥이 합성물을 가져가야 합니다."}, [64]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [65]={hint="언더시티에 있는 바리마트라스에게 다살리아의 봉인된 추천서를 가져가야 합니다.", tag="선택사항"}, [66]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항"}, [67]={hint="힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다."}, [68]={npc="서지 히노트", tgt="서지 히노트"}, [69]={npc="서지 히노트", tgt="서지 히노트", desc="퀘스트 라인을 이어서 잔질의 손길을 치료하세요."}, [70]={hint="서지 히노트가 해독제를 만드는 동안 기다려야 합니다.", desc="퀘스트 라인을 이어서 잔질의 손길을 치료하세요."}, [71]={npc="서지 히노트", tgt="서지 히노트", desc="퀘스트 라인을 이어서 잔질의 손길을 치료하세요."}, [72]={npc="고급스러워 보이는 편지", npcObj=true, tag="선택사항", desc="고급스러운 편지는 직업 훈련사가 안내하는 시작 퀘스트입니다. 통로의 상자는 함정이니 함정 감지를 사용하세요."}, [73]={hint="힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.", tag="선택사항", desc="고급스러운 편지는 직업 훈련사가 안내하는 시작 퀘스트입니다. 통로의 상자는 함정이니 함정 감지를 사용하세요."}, [74]={npc="파라드", tgt="파라드", tag="선택사항", desc="고급스러운 편지는 직업 훈련사가 안내하는 시작 퀘스트입니다. 통로의 상자는 함정이니 함정 감지를 사용하세요."}, [75]={npc="라벤홀트의 경비병", tgt="라벤홀트의 경비병", tag="선택사항", desc="반복 가능한 평판 퀘스트입니다. 레벨업에는 꼭 필요하지 않습니다."}, [76]={hint="획득처: 비밀결사대 암살자, 비밀결사대 요술사, 비밀결사대 노상강도", tag="선택사항", desc="반복 가능한 평판 퀘스트입니다. 레벨업에는 꼭 필요하지 않습니다."}, [77]={npc="라벤홀트의 경비병", tgt="라벤홀트의 경비병", tag="선택사항", desc="반복 가능한 평판 퀘스트입니다. 레벨업에는 꼭 필요하지 않습니다."}, [78]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="던홀드 퀘스트와 함께 진행하세요."}, [79]={hint="힐스브래드 구릉지 던홀드 요새에서 군주 토마스를 찾아 처치한 후, 미로코스 사일런트폼에게 가야 합니다.", tag="선택사항", desc="던홀드 퀘스트와 함께 진행하세요."}, [80]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="던홀드 퀘스트와 함께 진행하세요."}, [81]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="은빛소나무 마을 밖에서 밀서를 받고 제출하는 퀘스트입니다. 최소 수락 레벨은 1이며 23레벨 이상을 권장합니다. 혼자 던전에 들어가야 한다면 비닉스의 폭약으로 안뜰 문을 열 수 있습니다."}, [82]={hint="그림자송곳니 성채에서 젤토스의 뿔을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다.", tag="선택사항", desc="은빛소나무 마을 밖에서 밀서를 받고 제출하는 퀘스트입니다. 최소 수락 레벨은 1이며 23레벨 이상을 권장합니다. 혼자 던전에 들어가야 한다면 비닉스의 폭약으로 안뜰 문을 열 수 있습니다."}, [83]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="은빛소나무 마을 밖에서 밀서를 받고 제출하는 퀘스트입니다. 최소 수락 레벨은 1이며 23레벨 이상을 권장합니다. 혼자 던전에 들어가야 한다면 비닉스의 폭약으로 안뜰 문을 열 수 있습니다."}, [84]={hint="Log", tag="선택사항", desc="후속 퀘스트는 우편으로 알려 줍니다. 우편을 받은 뒤 밀서 접선 지점으로 돌아가세요."}, [85]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="후속 퀘스트는 우편으로 알려 줍니다. 우편을 받은 뒤 밀서 접선 지점으로 돌아가세요."}, [86]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="최소 수락 레벨은 25이며, 소멸과 주의 분산을 배운 뒤에 하는 것을 권장합니다. 밀서 초대장을 받으면 은빛소나무 숲으로 돌아가세요."}, [87]={hint="붉은십자군 수도원에서 보스카의 눈을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다.", tag="선택사항", desc="최소 수락 레벨은 25이며, 소멸과 주의 분산을 배운 뒤에 하는 것을 권장합니다. 밀서 초대장을 받으면 은빛소나무 숲으로 돌아가세요."}, [88]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="최소 수락 레벨은 25이며, 소멸과 주의 분산을 배운 뒤에 하는 것을 권장합니다. 밀서 초대장을 받으면 은빛소나무 숲으로 돌아가세요."}, [89]={hint="Log", tag="선택사항", desc="후속 편지를 받았을 때만 돌아가세요."}, [90]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="후속 편지를 받았을 때만 돌아가세요."}, [91]={hint="타렌 밀농장에 있는 우물에서 빈 빨간색 물주머니를 채워 불모의 땅에 있는 브린에게 가져가야 합니다.", desc="가득 찬 물주머니를 버섯구름 봉우리 프리윈드 초소까지 보관하세요."}, [92]={npc="애살리스테", tgt="애살리스테"}, [93]={hint="퀘스트 목표를 완료하세요."}, [94]={npc="애살리스테", tgt="애살리스테"}, [95]={npc="아나스타샤 하트웰", tgt="아나스타샤 하트웰", tag="선택사항"}, [96]={hint="다이노와 대화하십시오.", tag="선택사항"}, [97]={npc="다이노", tgt="다이노", tag="선택사항"}, [98]={text="언더시티를 나와 브릴 남쪽 비행선 탑으로 가서 자페타(60.74, 58.87, 서쪽 승강장) 쪽에서 오그리마행 비행선을 기다리세요. 버섯구름 봉우리 프리윈드 초소로 갈 때 이 배를 탑니다. 이미 29레벨이고 프리윈드 초소를 마쳤다면 오그리마 도착 후 바로 잿빛 골짜기 토막나무 초소로 가세요."}}},
    ["05-d7"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="저습지 47.79, 56.16", pickup="돌발톱 산맥 해바위 야영지에서 24레벨이 되었다면 돌발톱에서 오그리마로 날아가 어둠의 틈에서 보르스탄에게 달라지는 입맛을 받으세요. 타렌 밀농장을 떠난 뒤 아라시 해머폴에서 자루크에게 용아귀 소문을 받고, 탄돌 다리와 던 모드르를 지나 텔겐 바위굴 일대의 산길로 가서 죽음의 추적자를 찾으세요. 용아귀 열기를 받은 뒤 던전에 들어가세요.", pickupS={{"돌발톱 산맥 해바위 야영지에서 24레벨이 되었다면 돌발톱에서 오그리마로 날아가 어둠의 틈에서 보르스탄에게 달라지는 입맛을 받으세요"}, {"타렌 밀농장을 떠난 뒤 아라시 해머폴에서 자루크에게 용아귀 소문을 받고, 탄돌 다리와 던 모드르를 지나 텔겐 바위굴 일대의 산길로 가서 죽음의 추적자를 찾으세요"}, {"용아귀 열기를 받은 뒤 던전에 들어가세요"}}, tips={{k="動線", text="동쪽 입구에서 늪을 서쪽으로 가로질러 솔트스파인을 처치합니다 → 풀숲 오솔길을 따라 덤불 랩터와 그늘이빨을 처치합니다 → 남서쪽 야영지에서 용아귀를 정리합니다 → 남쪽 발굴 현장에서 수호자 옆 패널을 작동시키고, 수호자를 처치한 뒤 유물을 얻습니다."}, {k="取捨", text="한 번 완주하면 고기, 용아귀 급송품, 마지막 우두머리의 유물을 함께 얻을 수 있습니다. 마지막 단계는 칼림도어로 돌아가야 하니 다음 오그리마 또는 썬더 블러프 일정에 맞춰 제출하세요."}, {k="說明", text="푸른색 정식 입구는 웰가르 발굴 현장 남동쪽 높은 비탈에 있습니다. 집결석, 죽음의 추적자, 던전 입구는 서로 다른 위치입니다.", s={{"푸른색 정식 입구는 웰가르 발굴 현장 남동쪽 높은 비탈에 있습니다"}, {"집결석, 죽음의 추적자, 던전 입구는 서로 다른 위치입니다"}}}}, steps={[1]={npc="보르스탄", tgt="보르스탄"}, [2]={npc="자루크", tgt="자루크"}, [3]={hint="저습지로 이동한 후 용아귀 야영지 위쪽 언덕에서 죽음추적자를 만나야 합니다."}, [4]={npc="죽음의 추적자", tgt="죽음의 추적자"}, [5]={npc="죽음의 추적자", tgt="죽음의 추적자", preText="용아귀 소문"}, [6]={text="Excavation Site: Wetlands 입구"}, [7]={hint="저습지의 발굴 현장에 진입해 덤불 랩터 고기를 가져와야 합니다.", desc="위치: 솔트스파인 호수를 지나 그늘이빨 앞 풀숲 오솔길을 따라 덤불 랩터를 처치하세요.", spot="솔트스파인 호수를 지나 그늘이빨 앞 풀숲 오솔길을 따라 덤불 랩터를 처치하세요."}, [8]={hint="발굴 현장 안에 있는 용아귀 군대를 물리친 후, 발견한 것을 가지고 밖에 있는 죽음추적자에게 가야 합니다.", desc="위치: 그늘이빨을 지나 발굴 현장으로 가서 야영지의 용아귀 부대를 처치하세요.", spot="그늘이빨을 지나 발굴 현장으로 가서 야영지의 용아귀 부대를 처치하세요."}, [9]={npc="티탄의 유물", npcObj=true, tag="게임 내 확인이 필요합니다", desc="마지막 우두머리인 유물 수호자를 처치하고 티탄의 유물을 주운 뒤, 아이템을 우클릭해 퀘스트를 받으세요."}, [10]={npc="죽음의 추적자", tgt="죽음의 추적자"}, [11]={npc="보르스탄", tgt="보르스탄"}, [12]={hint="티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가서 자세한 이야기를 해 줄 만한 사람을 찾아야 합니다.", desc="마지막 우두머리인 유물 수호자를 처치하고 티탄의 유물을 주운 뒤, 아이템을 우클릭해 퀘스트를 받으세요."}, [13]={npc="바샤나 룬토템", tgt="바샤나 룬토템"}, [14]={npc="바샤나 룬토템", tgt="바샤나 룬토템", desc="장로의 지식을 제출한 뒤 바샤나에게 퀘스트를 받으세요. 먼저 퀘스트가 유물을 다시 주는지 확인하세요. 재료가 지급되지 않으면 게임의 현재 상태를 따르세요.", preText="장로의 지식"}, [15]={hint="티탄의 유물을 멀고어 북서쪽의 하늘감시자 고원에 있는 멀른 어스퓨리에게 가져가야 합니다.", desc="장로의 지식을 제출한 뒤 바샤나에게 퀘스트를 받으세요. 먼저 퀘스트가 유물을 다시 주는지 확인하세요. 재료가 지급되지 않으면 게임의 현재 상태를 따르세요."}, [16]={npc="알라나 스톰워커", tgt="Muln Earthfury", desc="장로의 지식을 제출한 뒤 바샤나에게 퀘스트를 받으세요. 먼저 퀘스트가 유물을 다시 주는지 확인하세요. 재료가 지급되지 않으면 게임의 현재 상태를 따르세요."}}},
    ["05-d6"] = {name="그림자송곳니 성채", entrance="은빛소나무 숲 44.70, 67.80", pickup="은빛소나무 숲으로 가기 전에, 언더시티를 지나면서 연금술 구역에서 우르의 책을 받고, 공동묘지에서 하드렉과 달라르에게 그림자송곳니 성채의 죽음추적자과 아루갈의 최후를 받으세요. 흑마법사는 불모의 땅 타우라조 야영지 동쪽에서 소랜루크 수정구을 받을 수 있습니다(흑마법사만 해당). 죽음의 폐광 구간의 외교 사건부터 달빛이 입 맞춘 칼날까지 먼저 끝내고 달빛이 입 맞춘 칼날은 남겨 두세요(언데드 성기사만 해당). 힐스브래드로 가는 길에 동부 왕국으로 돌아온 뒤 먼저 은빛소나무 숲 공동묘지로 날아가서 남쪽으로 이동하세요.", pickupS={{"은빛소나무 숲으로 가기 전에, 언더시티를 지나면서 연금술 구역에서 우르의 책을 받고, 공동묘지에서 하드렉과 달라르에게 그림자송곳니 성채의 죽음추적자과 아루갈의 최후를 받으세요"}, {"흑마법사는 불모의 땅 타우라조 야영지 동쪽에서 소랜루크 수정구을 받을 수 있습니다(흑마법사만 해당)", {class={"WARLOCK"}}}, {"죽음의 폐광 구간의 외교 사건부터 달빛이 입 맞춘 칼날까지 먼저 끝내고 달빛이 입 맞춘 칼날은 남겨 두세요(언데드 성기사만 해당)", {race={"Scourge"}, class={"PALADIN"}}}, {"힐스브래드로 가는 길에 동부 왕국으로 돌아온 뒤 먼저 은빛소나무 숲 공동묘지로 날아가서 남쪽으로 이동하세요"}}, tips={{k="動線", text="입구에서 레실고어를 처치하고 아다만트를 풀어 줍니다 → 안뜰 오른쪽에서 빈센트를 찾습니다 → 연회장과 성벽을 지납니다 → 펜루스의 방에서 책을 챙깁니다 → 탑 길의 몹을 정리하고 늑대왕 난도스를 처치합니다 → 위층으로 올라가 아루갈을 처치하고 탁자를 확인합니다."}, {k="取捨", text="우르의 책과 아루갈의 최후는 던전 밖에서 제출하세요. 그림자송곳니 성채의 죽음추적자은 던전 안에서 빈센트에게 제출합니다. 22레벨 전에 파티가 불안하면 로데론의 폐허나 통곡의 동굴을 먼저 하세요."}, {k="說明", text="공동묘지에서 남쪽으로 내려가 장작나무 마을 북쪽 비탈길로 성에 들어가세요. 바깥문을 지나 안뜰 옆에 있는 곳이 진짜 던전 입구입니다. 달라란 숨겨진 우두머리를 잡으려면 아루갈의 탁자에서 검은 고서를 챙기고, 앰버밀 대홀의 지맥 장치에서 달라란의 고서를 만드세요.", s={{"공동묘지에서 남쪽으로 내려가 장작나무 마을 북쪽 비탈길로 성에 들어가세요"}, {"바깥문을 지나 안뜰 옆에 있는 곳이 진짜 던전 입구입니다"}, {"달라란 숨겨진 우두머리를 잡으려면 아루갈의 탁자에서 검은 고서를 챙기고, 앰버밀 대홀의 지맥 장치에서 달라란의 고서를 만드세요"}}}}, steps={[1]={npc="관리인 벨두거", tgt="관리인 벨두거"}, [2]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [3]={npc="달라 던위버", tgt="달라 던위버"}, [4]={npc="도안 카르한", tgt="도안 카르한", tag="선택사항", desc="제출하기 전에 검은심연의 나락에서 나머지 작은 조각 3개를 얻으세요. 두 권을 모두 완료한 뒤 제출합니다."}, [5]={text="그림자송곳니 성채 입구"}, [6]={hint="죽음추적자 아다만트와 죽음추적자 빈센트를 찾아야 합니다.", desc="위치: 레실고어를 처치한 뒤 감옥을 열고, 파수병을 따라 안뜰 계단을 올라 오른쪽으로 가세요.", spot="레실고어를 처치한 뒤 감옥을 열고, 파수병을 따라 안뜰 계단을 올라 오른쪽으로 가세요."}, [7]={npc="죽음의추적자 빈센트", tgt="죽음의추적자 빈센트", tag="게임 내 확인이 필요합니다", spot="안뜰 오른쪽, 죽음의추적자 빈센트"}, [8]={hint="언더시티의 연금술 실험실에 있는 관리인 벨두거에게 우르의 책을 가져가야 합니다.", desc="위치: 성벽을 지나 탑으로 올라가 펜루스의 방 왼쪽 책장 아래 칸의 책을 챙기세요.", spot="성벽을 지나 탑으로 올라가 펜루스의 방 왼쪽 책장 아래 칸의 책을 챙기세요."}, [9]={hint="소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", tag="선택사항", desc="위치: 탑 길을 따라 그림자송곳니 암흑영혼을 처치하세요. 흑마법사 퀘스트를 받았을 때만 주우세요.", spot="탑 길을 따라 그림자송곳니 암흑영혼을 처치하세요. 흑마법사 퀘스트를 받았을 때만 주우세요."}, [10]={hint="아루갈을 처치하고 그 증거로 그의 머리카락을 공동묘지에 있는 달라 던위버에게 가져가야 합니다.", desc="위치: 늑대왕 난도스를 처치한 뒤 위층으로 올라가 아루갈의 방에서 처치하세요.", spot="늑대왕 난도스를 처치한 뒤 위층으로 올라가 아루갈의 방에서 처치하세요."}, [11]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", tag="선택사항", desc="위치: 아루갈의 방 탁자에서 은괴를 찾으세요. 달빛이 입 맞춘 칼날을 받았을 때만 주우세요.", spot="아루갈의 방 탁자에서 은괴를 찾으세요. 달빛이 입 맞춘 칼날을 받았을 때만 주우세요."}, [12]={npc="달라 던위버", tgt="달라 던위버"}, [13]={npc="관리인 벨두거", tgt="관리인 벨두거"}, [14]={npc="도안 카르한", tgt="도안 카르한", tag="선택사항", desc="잿빛 골짜기 조각난 나무 초소에서 검은심연의 나락 작은 조각 3개를 모두 모은 뒤 불모의 땅에 제출하세요."}}},
    ["02-13"] = {name="버섯구름 봉우리", tips={{k="交通", text="오그리마에 들어가 타우라조 야영지로 날아간 뒤, 불모의 땅 남쪽 끝의 대승강기를 타고 골짜기로 내려가 프리윈드 초소에서 처음 비행 지점을 여세요. 신성한 불가 있을 때만 썬더 블러프를 거치세요."}, {k="取捨", text="해둘 만합니다. 돌발톱 산맥 해바위 은거지의 편지는 대승강기 경비병에게 바로 제출하세요. 프리윈드 초소 서쪽의 보급품 상자, 하피 3종, 인내의 시험은 같은 구역입니다."}, {k="取捨", text="나중에 지나갈 때 하세요. 영상에서는 잿빛 골짜기를 먼저 소개하고 중간에 버섯구름 봉우리에 한 번 들르라고 하지만, 여기서는 프리윈드 초소 짧은 방문을 잿빛 골짜기 주요 퀘스트 앞에 배치했습니다. 반짝이는 평원 전체 퀘스트는 버섯구름 봉우리 반짝이는 평원에 남겨 두세요."}, {k="取捨", text="건너뛰어도 됩니다. 라코타 호위, 표범 우리, 서쪽 순찰 후속 퀘스트는 시간이 오래 걸립니다. 동료가 있거나 가는 길에 목표가 있을 때만 하세요."}, {k="提醒", text="가시덩굴 우리에 가려면 입구는 대승강기 앞 불모의 땅 남쪽 끝에 있습니다. 이 구간의 예상 진행도에 못 미쳤다면 프리윈드 초소 서쪽의 비명 하피 비탈(약 27, 51)에서 경험치를 보충하세요.", s={{"가시덩굴 우리에 가려면 입구는 대승강기 앞 불모의 땅 남쪽 끝에 있습니다"}, {"이 구간의 예상 진행도에 못 미쳤다면 프리윈드 초소 서쪽의 비명 하피 비탈(약 27, 51)에서 경험치를 보충하세요"}}}}, danger={[1]="승강기 낙하는 치명적입니다. 프리윈드 초소 다리를 건너거나 북쪽 승강기를 탈 때는 승강대가 도착할 때까지 기다리세요.", [2]="하피 동굴의 보급품 상자를 열면 적이 나타납니다. 상자 옆 몹을 먼저 정리하고 퇴로를 확보한 뒤에 여세요."}, grind={[1]={mob="점박이하이에나", note="프리윈드 초소 서쪽 골짜기에 일반 몹이 보통 밀도로 있습니다. 골짜기 바닥에서 한 마리씩 잡고, 하피 야영지까지 돌아갈 필요는 없습니다."}, [2]={mob="회오리 하피", note="서쪽 하피 비탈에 일반 몹이 보통 밀도로 있고, 야영지에는 다른 하피도 함께 있습니다. 비탈 가장자리에서 혼자 있는 하피부터 고르세요. 비명 하피 퀘스트와 함께 진행할 수 있습니다."}}, supply={[1]={npc="니세"}, [2]={npc="여관주인 아베크와"}, [3]={npc="스타른"}, [4]={npc="여관주인 아베크와"}, [5]={npc="스타른"}, [6]={npc="몬타르"}, [7]={npc="오무사 썬더혼"}}, steps={[1]={text="브릴 남쪽 비행선 탑에서 자페타(60.74, 58.87, 서쪽 승강장)에게 오그리마행 비행선인지 확인하세요. 듀로타에 도착하면 오그리마로 들어가세요. 제출할 썬더 블러프로의 귀환이 있으면 먼저 썬더 블러프로 날아간 뒤 타우라조 야영지로 가고, 없으면 오그리마에서 바로 타우라조 야영지로 날아가세요. 아직 타렌 밀농장에 있다면 먼저 언더시티로 날아가 비행선을 타세요."}, [2]={hint="썬더 블러프에 있는 연금술사 자마에게 라이던의 독약을 가져가야 합니다.", tag="힐스브래드 구릉지 타렌 밀농장에서 이미 받은 경우, 선택사항"}, [3]={npc="연금술사 자마", tgt="연금술사 자마", tag="힐스브래드 구릉지 타렌 밀농장에서 이미 받은 경우, 선택사항"}, [4]={text="불모의 땅 남쪽 길을 따라 대승강기로 가서 북쪽 경비병과 만나세요."}, [5]={hint="마그그랜이 불모의 땅 구름 승강장에 있는 그리쉬 롱러너에게 통지서를 전해달라고 부탁했습니다.", tag="돌발톱 산맥 해바위 은거지에서 이미 받은 경우"}, [6]={npc="그리쉬 롱러너", tgt="그리쉬 롱러너", tag="돌발톱 산맥 해바위 은거지에서 이미 받은 경우"}, [7]={npc="용사 문혼", tgt="용사 문혼"}, [8]={hint="긴급 전갈을 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 가져가야 합니다."}, [9]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [10]={text="대승강기를 타고 골짜기 아래로 내려가 길을 따라 동쪽 프리윈드 초소로 간 뒤, 프리윈드 초소 승강기로 고원에 올라 니세(45.14, 49.11)에게서 비행 지점을 여세요. 이 구간에서는 귀환석 위치를 바꾸지 않습니다."}, [11]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [12]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [13]={npc="잔디아", tgt="잔디아"}, [14]={npc="잔디아", tgt="잔디아", desc="라우 클리프러너(46.14, 51.71)에게서도 같은 퀘스트를 받을 수 있습니다."}, [15]={npc="엘루", tgt="엘루"}, [16]={npc="현상수배: 아르낙 그림토템", npcObj=true}, [17]={text="먼저 프리윈드 초소 북쪽 켄타우로스 야영지를 돌고, 그다음 도른과 바람뱀 둥지로 가세요."}, [18]={hint="갈라크일족 척후병 12명, 갈라크일족 사냥꾼 10명, 갈라크일족 바람전사 6명을 처치한 후, 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 돌아가야 합니다."}, [19]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [20]={hint="믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.", desc="도른의 순간이동 지점 바로 앞에서 튀어나온 판자에서만 뛰어내리세요. 성공하면 도른에게 돌아갑니다."}, [21]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [22]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [23]={hint="높새바람 봉우리에 있는 하가르 라이트닝후프에게 괴상한 알을 가져가야 합니다."}, [24]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [25]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [26]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [27]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [28]={text="서쪽으로 가서 먼저 비명 하피와 보급품 상자를 처리한 뒤, 골짜기 바닥을 따라 바람둥지와 백사장 초소로 가세요."}, [29]={hint="도난당한 높새바람 보급품 8개를 높새바람 봉우리에 있는 잔디아에게 가져가야 합니다.", desc="비명을 잠재워라과 같은 구역입니다. 프리윈드 초소에서 서쪽으로 가서 하피 비탈을 따라 동굴 안의 상호작용 가능한 보급품 상자를 찾으세요. 게임에서 확인한 오브젝트 670338의 채집 지점 3곳입니다."}, [30]={hint="회오리 하피 5명과 회오리일족 약탈자 하피 5명, 회오리일족 바람마녀 하피 5명을 처치해야 합니다."}, [31]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다.", desc="동굴 바닥에서 보급품 상자를 부숴야 그렌카 블러드스크리치가 나옵니다. 먼저 동굴을 정리해도 됩니다."}, [32]={hint="높새바람 봉우리에 있는 엘루에게 마루둥지 와이번 알 10개를 가져가야 합니다."}, [33]={npc="파오카 스위프트마운틴", tgt="파오카 스위프트마운틴", tag="호위, 선택사항"}, [34]={hint="마루둥지에 있는 파오카 스위프트마운틴을 호위해 간 다음 백사장 야영지에 있는 모테가 파이어메인과 대화하십시오.", tag="호위, 선택사항", desc="파오카는 바람둥지 산비탈에 있습니다. 먼저 알을 줍고 출구 근처의 만티코어를 처치한 뒤 호위를 시작하세요."}, [35]={npc="모테가 파이어메인", tgt="모테가 파이어메인", tag="호위, 선택사항"}, [36]={hint="발견한 사실을 모테가 파이어메인에게 보고해야 합니다."}, [37]={npc="모테가 파이어메인", tgt="모테가 파이어메인"}, [38]={npc="모테가 파이어메인", tgt="모테가 파이어메인", tag="썬더 블러프로 비행하는 경우 수락, 선택사항"}, [39]={npc="위즐로 베어링샤이너", tgt="위즐로 베어링샤이너", tag="엘리트, 선택사항"}, [40]={hint="퓨마를 처치하고 초전도 장치와 퓨마 우리 열쇠를 위즐로 베어링샤이너에게 돌려주어야 합니다.", tag="엘리트, 선택사항", desc="우리를 열면 바로 전투가 시작됩니다. 야수는 엘리트이니 파티를 권장합니다."}, [41]={npc="위즐로 베어링샤이너", tgt="위즐로 베어링샤이너", tag="엘리트, 선택사항"}, [42]={npc="암살 지령", npcObj=true, tag="순찰 몹 드랍으로 시작, 선택사항", desc="갈라크 전령은 켄타우로스 야영지 사이를 순찰합니다. 암살 명령서를 주워 사용했을 때만 받으세요."}, [43]={hint="백사장 야영지에 있는 카나티 그레이클라우드에게 가서 암살 음모에 대해 경고해 주어야 합니다.", tag="순찰 몹 드랍으로 시작, 선택사항", desc="갈라크 전령은 켄타우로스 야영지 사이를 순찰합니다. 암살 명령서를 주워 사용했을 때만 받으세요."}, [44]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 몹 드랍으로 시작, 선택사항"}, [45]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 몹 드랍으로 시작, 선택사항"}, [46]={hint="켄타우로스의 공격으로부터 카나티 그레이클라우드를 보호해야 합니다.", tag="순찰 몹 드랍으로 시작, 선택사항", desc="수락하면 바로 습격이 시작됩니다. 먼저 체력과 마나를 회복하세요."}, [47]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 몹 드랍으로 시작, 선택사항"}, [48]={text="서쪽 비탈길로 먹구름 봉우리에 올라 밀서를 주운 뒤, 나무다리를 따라 북쪽으로 가세요."}, [49]={hint="먹구름 봉우리에 있는 비밀 쪽지 3개를 찾아 와야 합니다.", desc="약 31.5, 36.7의 비탈길로 나무다리에 올라가 세 야영지에서 밀서를 찾으세요."}, [50]={hint="아르낙 그림토템을 처치하고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 그 증거물을 갖다주어야 합니다."}, [51]={npc="라코타 윈드송", tgt="라코타 윈드송", tag="여력이 있을 때, 선택사항"}, [52]={hint="라코타 윈드송을 먹구름 봉우리에서 구출한 후, 높새바람 봉우리에 있는 탈리아 앰버하이드와 대화하십시오.", tag="여력이 있을 때, 선택사항", desc="먼저 우리 주변과 나무다리를 정리하세요. 라코타가 우리에서 나오면 끝까지 산 아래로 따라 내려가세요."}, [53]={hint="불꽃 용설란 10포기를 모아 썬더 블러프 장로의 봉우리에 있는 마가타 그림토템을 찾아가야 합니다.", tag="여력이 있을 때, 선택사항"}, [54]={text="프리윈드 초소로 돌아가 제출하세요. 인내의 시험은 북동쪽의 도른에게 제출하세요."}, [55]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [56]={npc="잔디아", tgt="잔디아"}, [57]={npc="잔디아", tgt="잔디아"}, [58]={npc="엘루", tgt="엘루"}, [59]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [60]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [61]={npc="탈리아 앰버하이드", tgt="탈리아 앰버하이드", tag="선택사항"}, [62]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="만났을 때만 진행, 선택사항"}, [63]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다.", tag="만났을 때만 진행, 선택사항", desc="서쪽 골짜기와 바람둥지 근처를 순찰하는 로크알림을 찾으세요."}, [64]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="만났을 때만 진행, 선택사항"}, [65]={text="제출할 신성한 불이 있고 썬더 블러프 비행 지점을 열었다면 프리윈드 초소에서 썬더 블러프로 날아가세요. 썬더 블러프에 가지 않을 거라면 다음 제출은 건너뛰고 바로 떠나는 단계로 가세요."}, [66]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프에서 제출, 선택사항"}, [67]={npc="브린", tgt="브린"}, [68]={npc="브린", tgt="브린", desc="잿빛 골짜기 토막나무 초소에서 물을 받은 뒤 불모의 땅으로 돌아와 제출하세요."}, [69]={text="지금 있는 프리윈드 초소나 썬더 블러프에서 비행하세요. 토막나무 초소 비행 지점을 열었다면 바로 날아가고, 처음이라면 먼저 크로스로드로 날아가 불모의 땅 북쪽 길을 따라 모르샨 방벽을 지난 뒤, 잿빛 골짜기 동쪽 대로를 따라 토막나무 초소에 도착하세요."}}},
    ["02-14"] = {name="잿빛 골짜기", tips={{k="交通", text="먼저 토막나무 초소, 그다음 조람가르 비행 지점을 여세요. 제출할 퀘스트에 따라 토막나무 초소, 해바위 은거지, 크로스로드로 가거나 조람가르에서 바로 오그리마로 날아가세요. 귀환석은 타렌 밀농장에 그대로 두세요."}, {k="取捨", text="해둘 만합니다. 토막나무 초소 남쪽의 선구자, 남서쪽 호수 정령, 북쪽 사티로스를 각각 한 바퀴씩 도세요. 조람가르의 퍼볼그와 동굴 부적 퀘스트는 함께 해결하세요."}, {k="取捨", text="건너뛰어도 됩니다. 사냥감 3마리가 순찰하니 가는 길에 마주쳤을 때만 잡으세요. 페이지가 다 모이지 않았다면 나중에 거래로 구하고 반복 사냥하지 마세요."}, {k="取捨", text="나중에 지나갈 때 하세요. 29레벨 이후 어차피 크로스로드와 오그리마로 간다면 곤충 떼의 위협를 먼저 받고, 오그리마에서 제출한 뒤 곤충 떼의 위협을 받으세요. 버섯구름 봉우리 반짝이는 평원에서 곤충 떼의 위협을 제출해야 곤충 떼의 위협을 받을 수 있습니다. 이번 구간 이동 경로와 맞지 않으면 건너뛰세요."}, {k="提醒", text="30레벨이 안 됐다면 사티로스(약 67, 57)나 엉겅퀴가죽 퍼볼그(약 32, 38)를 먼저 잡으세요. 파티가 있으면 조람 해안에서 검은심연의 나락을 갈 수 있고, 동료가 모이지 않았다면 이 구간을 계속 진행하세요.", s={{"30레벨이 안 됐다면 사티로스(약 67, 57)나 엉겅퀴가죽 퍼볼그(약 32, 38)를 먼저 잡으세요"}, {"파티가 있으면 조람 해안에서 검은심연의 나락을 갈 수 있고, 동료가 모이지 않았다면 이 구간을 계속 진행하세요"}}}}, danger={[1]="아스트라나르는 얼라이언스 마을이며 길가에 40레벨 파수꾼이 있습니다. 조람가르로 갈 때는 마을 밖으로 돌아가세요.", [2]="엉겅퀴 동굴의 퍼볼그가 좁은 통로를 막을 수 있습니다. 출구까지 먼저 정리한 뒤 상자를 열거나 루울 호위를 시작하세요."}, grind={[1]={mob="검은유혹의 그림자추적자", note="사티로스 야영지 바깥쪽에 일반 몹이 보통 밀도로 있습니다. 같은 종류의 순찰과 다른 사티로스가 접근하니 야영지 가장자리를 따라 정리하세요. 사티로스의 뿔도 함께 모을 수 있습니다."}, [2]={mob="우두머리 유령발늑대", note="토막나무 초소 북쪽 숲에 일반 몹이 보통 밀도로 있습니다. 탁 트인 곳에서 한 마리씩 잡으세요. 비행 지점과 가까워 사티로스 야영지에 들어가고 싶지 않을 때 경험치를 채우기 좋습니다."}, [3]={mob="사비안 도적", note="사비아 야영지에 일반 몹이 보통 밀도로 있습니다. 은신한 몹과 순찰을 조심하고, 바깥쪽을 먼저 정리한 뒤 안쪽으로 들어가세요. 29레벨 마지막 구간에 알맞고, 사티로스의 뿔도 함께 모을 수 있습니다."}}, supply={[1]={npc="불그라"}, [2]={npc="여관주인 카일리스크"}, [3]={npc="벌크럼"}, [4]={npc="여관주인 카일리스크"}, [5]={npc="벌크럼"}, [6]={npc="안드루크"}, [7]={npc="위크타르"}}, steps={[1]={text="토막나무 초소에 도착하면 불그라에게서 비행 지점(73.18, 61.59)을 여세요. 타렌 밀농장 귀환석은 동부 왕국으로 돌아올 때를 위해 남겨 두세요. 다른 곳에 설정해 둔 상태에서 잿빛 골짜기에서 쓰고 싶다면 여관주인 카일리스크(73.99, 60.65)에게서 설정하세요."}, [2]={hint="잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다.", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [3]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="톱니항/타우라조 야영지 구간에서 이미 받은 경우"}, [4]={npc="세나니 썬더하트", tgt="세나니 썬더하트"}, [5]={hint="퀘스트 목표를 완료하세요.", desc="같은 이름의 잿빛 골짜기 사냥 대회를 제출한 뒤에도 잿빛 골짜기 사냥 대회을 따로 해야 세 사냥감이 드랍하는 퀘스트를 받을 수 있습니다."}, [6]={npc="세나니 썬더하트", tgt="세나니 썬더하트"}, [7]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스"}, [8]={npc="픽셀", tgt="픽셀"}, [9]={npc="쿠레이빈", tgt="쿠레이빈"}, [10]={npc="구르다 레이지스카", tgt="구르다 레이지스카", tag="누락된 페이지가 있을 때 확인하세요, 선택사항"}, [11]={text="토막나무 초소 남쪽에서 먼저 선구자를 처치한 뒤 남서쪽 호수 지역으로 가세요."}, [12]={npc="뾰족발톱의 발톱", npcObj=true, tag="사냥감이 보일 때만 수락, 선택사항", desc="샤프탈론을 처치하고 발톱을 얻은 뒤, 가방의 발톱을 우클릭해 퀘스트를 받으세요."}, [13]={hint="뾰족발톱의 발톱을 잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="사냥감이 보일 때만 수락, 선택사항", desc="샤프탈론을 처치하고 발톱을 얻은 뒤, 가방의 발톱을 우클릭해 퀘스트를 받으세요."}, [14]={hint="잿빛 골짜기 정찰꾼 9명을 처치한 후 토막나무 주둔지에 있는 쿠레이빈에게 돌아가십시오."}, [15]={npc="전쟁노래부족 정찰병", tgt="전쟁노래부족 정찰병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항", desc="아직 묶음을 열지 않았다면 먼저 우클릭해 열어 전쟁노래부족 보고서를 얻고, 정찰병과 교환하세요."}, [16]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [17]={npc="전쟁노래부족 정찰병", tgt="전쟁노래부족 정찰병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [18]={npc="토렉", tgt="토렉", tag="호위, 선택사항"}, [19]={hint="은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오.", tag="호위, 선택사항", desc="호위를 수락하면 바로 전투가 시작되니, 토렉 근처에서 먼저 동료를 기다리세요."}, [20]={hint="돌발톱 토굴길에서 동쪽으로, 그리고 토막나무 주둔지에서 남서쪽으로 있는 미스트랄 호수에서 타락한 물의 정령 12마리를 처치해야 합니다."}, [21]={npc="더럽혀진 물구슬", npcObj=true, tag="드랍될 때만 진행, 선택사항", desc="호숫가에서 타이더레스를 찾으세요. 물구슬은 퀘스트 시작 아이템이니 주운 뒤 우클릭하세요."}, [22]={hint="잿빛 골짜기 토막나무 주둔지에 있는 마스토크 윌리히스에게 더럽혀진 물구슬을 가져가야 합니다.", tag="드랍될 때만 진행, 선택사항", desc="호숫가에서 타이더레스를 찾으세요. 물구슬은 퀘스트 시작 아이템이니 주운 뒤 우클릭하세요."}, [23]={npc="우르산고우스의 앞발", npcObj=true, tag="드랍될 때만 진행, 선택사항", desc="우르산고우스를 처치하고 발톱을 얻은 뒤, 가방의 발톱을 우클릭해 퀘스트를 받으세요."}, [24]={hint="우르산고우스의 앞발을 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="드랍될 때만 진행, 선택사항", desc="우르산고우스를 처치하고 발톱을 얻은 뒤, 가방의 발톱을 우클릭해 퀘스트를 받으세요."}, [25]={npc="샤둠브라의 머리", npcObj=true, tag="드랍될 때만 진행, 선택사항", desc="샤둠브라를 처치하고 머리를 얻은 뒤, 가방의 머리를 우클릭해 퀘스트를 받으세요."}, [26]={hint="샤둠브라의 머리를 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="드랍될 때만 진행, 선택사항", desc="샤둠브라를 처치하고 머리를 얻은 뒤, 가방의 머리를 우클릭해 퀘스트를 받으세요."}, [27]={text="호수를 따라 북동쪽으로 토막나무 초소로 돌아가며, 숲속의 오르다누스와 사티로스 야영지를 지나가세요. 마을로 돌아가기 전에 먼저 처치하세요."}, [28]={hint="오르다누스를 처치하고 그 증거로 그의 머리 장식을 해바위 야영지 근처에 있는 브랠린 파이어핸드에게 가져가야 합니다.", tag="돌발톱 산맥 해바위 은거지에서 이미 받은 경우, 선택사항"}, [29]={hint="사티로스의 뿔 16개를 모아 토막나무 주둔지에 있는 픽셀에게 가져가야 합니다."}, [30]={npc="전쟁노래부족 척후병", tgt="전쟁노래부족 척후병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [31]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [32]={npc="전쟁노래부족 척후병", tgt="전쟁노래부족 척후병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [33]={npc="쿠레이빈", tgt="쿠레이빈"}, [34]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스"}, [35]={npc="픽셀", tgt="픽셀"}, [36]={npc="에르톡 레이지터스크", tgt="에르톡 레이지터스크", tag="호위를 마쳤을 때만 제출, 선택사항"}, [37]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [38]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [39]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [40]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [41]={hint="퀘스트 목표를 완료하세요.", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [42]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="사냥감을 얻었을 때만 제출, 선택사항"}, [43]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스", tag="물구슬을 주웠을 때만 수락, 선택사항"}, [44]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스", tag="물구슬을 주웠을 때만 수락, 선택사항"}, [45]={hint="잃어버린 벌목기 조작설명서 열 두쪽을 찾아서 1장, 2장, 그리고 3장으로 합쳐야 합니다. 그런 다음 토막나무 주둔지 근처에 있는 구르다 레이지스카에게 돌려 주어야 합니다.", tag="페이지가 모두 있을 때만 진행, 선택사항", desc="빠진 페이지를 얻으려고 몹을 잡지 마세요. 가방의 페이지를 우클릭해 각 장을 조합하세요."}, [46]={npc="구르다 레이지스카", tgt="구르다 레이지스카", tag="페이지가 모두 있을 때만 진행, 선택사항"}, [47]={text="조람가르 전초기지 비행 지점을 열었다면 토막나무 초소에서 날아가세요. 처음이라면 잿빛 골짜기 대로를 따라 서쪽으로 가서 아스트라나르의 얼라이언스 경비병을 피해 서쪽 해안으로 돌아가세요. 도착하면 안드루크에게서 비행 지점(12.24, 33.80)을 여세요."}, [48]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 더럽혀진 물구슬을 가져가야 합니다.", tag="물구슬 시작 퀘스트가 있을 때, 선택사항"}, [49]={npc="제네우 생크리", tgt="제네우 생크리", tag="물구슬 시작 퀘스트가 있을 때, 선택사항"}, [50]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [51]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [52]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [53]={npc="카랑 아마카르", tgt="카랑 아마카르"}, [54]={npc="미쑤와", tgt="미쑤와"}, [55]={npc="마루카이", tgt="마루카이", tag="경험치를 보충할 저레벨 몹, 선택사항"}, [56]={hint="조람 해안에 있는 마루카이에게 성난지느러미일족의 머리 20개를 가져가야 합니다.", tag="경험치를 보충할 저레벨 몹, 선택사항"}, [57]={npc="마루카이", tgt="마루카이", tag="경험치를 보충할 저레벨 몹, 선택사항"}, [58]={text="전초기지에서 동쪽 길을 따라 엉겅퀴 마을로 가서 퍼볼그를 잡고, 마을 북쪽 동굴에서 부적을 얻으세요."}, [59]={hint="엉겅퀴일족 복수자와 주술사를 각각 12마리씩 처치해야 합니다. 조람 해안 동쪽에 있는 엉겅퀴 마을에 몰려 있을 것입니다. 임무를 마치면 잿빛 골짜기 조람가르 호드 전초기지로 가서 카랑 아마카르를 만나야 합니다."}, [60]={hint="조람가르 전초기지에 있는 미쑤와에게 트롤 부적 8개를 가져가야 합니다."}, [61]={npc="루울 스노우후프", tgt="루울 스노우후프", tag="호위, 선택사항"}, [62]={hint="루울을 호위해 탈출한 후, 토막나무 주둔지에 있는 야마 스노우후프와 대화하십시오.", tag="호위, 선택사항", desc="입구와 동굴 안에서 동시에 몹이 나올 수 있으니, 통로를 먼저 정리한 뒤 수락하세요."}, [63]={npc="카랑 아마카르", tgt="카랑 아마카르"}, [64]={npc="미쑤와", tgt="미쑤와"}, [65]={npc="카랑 아마카르", tgt="카랑 아마카르", tag="동쪽 야영지로 다시 가야 함, 선택사항"}, [66]={hint="썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다.", tag="동쪽 야영지로 다시 가야 함, 선택사항", desc="깃발을 꽂으면 몇 차례 적이 몰려옵니다. 주변을 먼저 정리하고 군중 제어 준비를 하세요."}, [67]={npc="카랑 아마카르", tgt="카랑 아마카르", tag="동쪽 야영지로 다시 가야 함, 선택사항"}, [68]={npc="머그래쉬", tgt="머그래쉬", tag="파티 호위, 선택사항"}, [69]={hint="머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오.", tag="파티 호위, 선택사항"}, [70]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="파티 호위, 선택사항"}, [71]={text="루울의 자유를 제출해야 하거나 토막나무 초소에 할 일이 남아 있으면 조람가르 전초기지에서 토막나무 초소로 날아가세요. 귀환석이 토막나무 초소에 설정돼 있고 쓸 수 있다면 바로 귀환석을 쓰세요. 호위를 하지 않았고 제출할 것도 없다면 조람가르 전초기지에 머물며 여기서 다음 목적지로 바로 날아가세요."}, [72]={npc="야마 스노우후프", tgt="야마 스노우후프", tag="호위를 마쳤다면, 선택사항"}, [73]={text="오르다누스을 완료했거나 추가 지령를 이어서 할 계획이라면 조람가르 전초기지나 토막나무 초소에서 해바위 은거지(45.12, 59.84)로 날아가세요. 돌발톱 산맥에서 할 일이 없으면 건너뛰세요."}, [74]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="돌발톱 산맥 해바위 은거지에서 이미 받은 경우, 선택사항"}, [75]={hint="돌발톱 산맥에 있는 지즈 피직스에게 새로운 명령을 전해야 합니다.", tag="이미 받았고 칼바람 바위산으로 돌아갈 계획이라면, 선택사항"}, [76]={npc="지즈 피직스", tgt="지즈 피직스", tag="이미 받았고 칼바람 바위산으로 돌아갈 계획이라면, 선택사항"}, [77]={npc="지즈 피직스", tgt="지즈 피직스", tag="이미 받았고 칼바람 바위산으로 돌아갈 계획이라면, 선택사항"}, [78]={hint="돌발톱 산맥에 있는 지즈 피직스에게 게렌조의 기계팔을 가져가야 합니다.", tag="이미 받았고 칼바람 바위산으로 돌아갈 계획이라면, 선택사항", desc="칼바람 바위산 북쪽 비탈을 따라 나무 발판에 올라가세요. 호수 바닥에서 찾지 마세요. 게렌조 렌치휘슬은 높은 플랫폼 위에 있습니다."}, [79]={npc="지즈 피직스", tgt="지즈 피직스", tag="이미 받았고 칼바람 바위산으로 돌아갈 계획이라면, 선택사항"}, [80]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="나중에 지나갈 때 또는 파티가 있을 때, 선택사항"}, [81]={hint="돌발톱 봉우리에 있는 갈퀴발톱굴로 가야 합니다. 문지기의 열쇠를 이용해 드루이드의 숨겨진 물건을 얻어야 합니다. 그 물건을 이용해 갈퀴발톱굴 저장고를 여십시오.", tag="나중에 지나갈 때 또는 파티가 있을 때, 선택사항", desc="문지기와 동굴 목표가 한곳에 몰려 있으니, 파티를 이뤘고 가는 길일 때만 깊이 들어가세요. 앞의 세 지점은 보관함 3곳이고, 마지막 지점은 돌발톱 봉우리 동굴 저장고입니다."}, [82]={npc="갈퀴발톱굴 저장고", npcObj=true, tag="나중에 지나갈 때 또는 파티가 있을 때, 선택사항"}, [83]={text="전쟁노래부족 보고서 3장을 모두 모은 뒤 크로스로드로 가서, 북쪽 길로 모르샨 방벽 옆의 카드라크(48.12, 5.42)를 찾으세요. 잿빛 골짜기 비행 지점을 열었다면 동쪽 대로를 따라 남쪽으로 내려가도 됩니다."}, [84]={hint="먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오.", tag="최신 보고서 3장이 모두 있을 때만 제출, 선택사항", desc="여기에서는 세 사절과 교환해 받은 최신 보고서 3장을 제출합니다. 묶음 열기와 교환은 앞 구간에서 이미 끝나 있어야 합니다."}, [85]={npc="카드라크", tgt="카드라크", tag="최신 보고서 3장이 모두 있을 때만 제출, 선택사항"}, [86]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날을 받은 뒤, 잿빛 골짜기 조람 해안에 도착하면 이 단계를 받으세요."}, [87]={hint="코르석을 잿빛 골짜기에 있는 울릭 프로스트베일에게 가져가야 합니다.", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날을 받은 뒤, 잿빛 골짜기 조람 해안에 도착하면 이 단계를 받으세요."}, [88]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날을 받은 뒤, 잿빛 골짜기 조람 해안에 도착하면 이 단계를 받으세요."}, [89]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", tag="선택사항", desc="재료 3가지가 모두 모이면 이 줄을 완료하세요. 죽음의 폐광은 서부 몰락지대에 있으며, 호드는 가시덤불 골짜기와 그늘숲을 거쳐 갈 수 있습니다. 획득률은 고블린 목공이 떨어뜨리는 흰돌참나무 목재만 기준입니다."}, [90]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="재료 3가지를 모두 모은 뒤 은빛소나무 숲으로 돌아가세요. 잿빛 골짜기에서 오그리마로 날아가 비행선으로 티리스팔 숲에 간 다음 Sepulcher로 날아가세요."}, [91]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="힐스브래드 구릉지 타렌 밀농장을 아직 안 했다면 그곳에 가는 김에 하세요. 이미 지났다면 Sepulcher에서 타렌 밀농장으로 날아가세요."}, [92]={hint="Speak with Ott and ask him to forge your blade.", tag="선택사항", desc="힐스브래드 구릉지 타렌 밀농장을 아직 안 했다면 그곳에 가는 김에 하세요. 이미 지났다면 Sepulcher에서 타렌 밀농장으로 날아가세요."}, [93]={npc="오트", tgt="오트", tag="선택사항", desc="힐스브래드 구릉지 타렌 밀농장을 아직 안 했다면 그곳에 가는 김에 하세요. 이미 지났다면 Sepulcher에서 타렌 밀농장으로 날아가세요."}, [94]={npc="오트", tgt="오트", tag="선택사항"}, [95]={hint="처치: 오트", tag="선택사항"}, [96]={npc="오트", tgt="오트", tag="선택사항"}, [97]={npc="오트", tgt="오트", tag="선택사항", desc="제출하면 달빛은 칼날을 얻습니다.", star={"달빛은 칼날", {"PALADIN"}}}, [98]={hint="오트의 걸작을 은빛소나무 숲에 있는 트레반 롤에게 가져가야 합니다.", tag="선택사항", desc="제출하면 달빛은 칼날을 얻습니다."}, [99]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="제출하면 달빛은 칼날을 얻습니다.", star={"달빛은 칼날", {"PALADIN"}}}, [100]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", tag="선택사항", desc="약 25레벨의 순찰 엘리트라 파티를 권합니다. 양손 도검이 필요합니다. 배우지 않았다면 언더시티 군사 지구에서 무기 대가 아키발드(57.31, 32.77)에게서 배우고 명중할 때까지 숙련도를 올리세요. 퀘스트를 제출하면 울프스베인을 얻습니다.", star={"울프스베인", {"PALADIN"}}}, [101]={hint="은빛소나무 숲에서 달빛은 칼날을 사용해 늙은 불꽃눈을 처단해야 합니다.", tag="선택사항", desc="약 25레벨의 순찰 엘리트라 파티를 권합니다. 양손 도검이 필요합니다. 배우지 않았다면 언더시티 군사 지구에서 무기 대가 아키발드(57.31, 32.77)에게서 배우고 명중할 때까지 숙련도를 올리세요. 퀘스트를 제출하면 울프스베인을 얻습니다."}, [102]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", tag="선택사항", desc="약 25레벨의 순찰 엘리트라 파티를 권합니다. 양손 도검이 필요합니다. 배우지 않았다면 언더시티 군사 지구에서 무기 대가 아키발드(57.31, 32.77)에게서 배우고 명중할 때까지 숙련도를 올리세요. 퀘스트를 제출하면 울프스베인을 얻습니다.", star={"울프스베인", {"PALADIN"}}}, [103]={hint="툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", tag="선택사항", desc="가시덩굴 우리의 플로지스톤이나 채광 재료가 없으면 장비 퀘스트는 일단 건너뛰세요."}, [104]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="가시덩굴 우리의 플로지스톤이나 채광 재료가 없으면 장비 퀘스트는 일단 건너뛰세요."}, [105]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", star={"투사 갑옷", {"WARRIOR"}}}, [106]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [107]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", star={"투사 갑옷", {"WARRIOR"}}}, [108]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [109]={hint="듀로타에 있는 울라엘레크와 대화하십시오.", tag="선택사항"}, [110]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [111]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항", desc="사티로스의 뿔과 같은 구역에서 잡을 수 있지만, 먼저 투사 갑옷을 완료하세요."}, [112]={hint="듀로타의 센진 마을에 있는 울라엘레크에게 사티로스 통발굽 7개를 가져가야 합니다.", tag="선택사항", desc="사티로스의 뿔과 같은 구역에서 잡을 수 있지만, 먼저 투사 갑옷을 완료하세요."}, [113]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항", desc="사티로스의 뿔과 같은 구역에서 잡을 수 있지만, 먼저 투사 갑옷을 완료하세요."}, [114]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [115]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [116]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [117]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [118]={hint="썬더 블러프에서 오름 스톤후프와 대화하십시오.", tag="선택사항"}, [119]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항"}, [120]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항", desc="파티가 있거나 레벨이 충분할 때만 장비를 위해 되돌아가세요."}, [121]={hint="썬더 블러프에 있는 오름 스톤후프에게 번개 뿔을 가져가야 합니다.", tag="선택사항", desc="파티가 있거나 레벨이 충분할 때만 장비를 위해 되돌아가세요."}, [122]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항", desc="파티가 있거나 레벨이 충분할 때만 장비를 위해 되돌아가세요."}, [123]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항"}, [124]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [125]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항"}, [126]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [127]={hint="언더시티에 있는 벨로라 나이틀리와 대화하십시오.", tag="선택사항"}, [128]={npc="벨로라 나이틀리", tgt="벨로라 나이틀리", tag="선택사항"}, [129]={npc="벨로라 나이틀리", tgt="벨로라 나이틀리", tag="선택사항", desc="습지를 따로 돌아가야 합니다. 레벨링만 한다면 건너뛰어도 됩니다."}, [130]={hint="언더시티에 있는 벨로라 나이틀리에게 단단한 용아귀부족 다리뼈 8개를 가져가야 합니다.", tag="선택사항", desc="습지를 따로 돌아가야 합니다. 레벨링만 한다면 건너뛰어도 됩니다."}, [131]={npc="벨로라 나이틀리", tgt="벨로라 나이틀리", tag="선택사항", desc="습지를 따로 돌아가야 합니다. 레벨링만 한다면 건너뛰어도 됩니다."}, [132]={npc="벨로라 나이틀리", tgt="벨로라 나이틀리", tag="선택사항"}, [133]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [134]={npc="벨로라 나이틀리", tgt="벨로라 나이틀리", tag="선택사항"}, [135]={hint="잿빛 골짜기에 있는 별가루의 폐허에서 빈 파란색 물주머니를 채워 불모의 땅에 있는 브린에게 가져가야 합니다.", desc="잿빛 골짜기에서 남서쪽으로 불모의 땅에 돌아와 제출하세요."}, [136]={npc="브린", tgt="브린", desc="잿빛 골짜기에서 남서쪽으로 불모의 땅에 돌아와 제출하세요."}, [137]={npc="브린", tgt="브린"}, [138]={hint="불모의 땅에 있는 이슬렌 워터시어에게 가득 찬 순수한 물을 가져가야 합니다."}, [139]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어"}, [140]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어", desc="힐스브래드 구릉지 타렌 밀농장에서 은빛소나무 숲을 지나는 길에 정화를 완료하세요."}, [141]={npc="다이노", tgt="다이노", tag="선택사항", desc="폭포 안쪽에 서서 퀘스트 병을 사용하세요."}, [142]={hint="오그리마에 있는 다이노에게 사비안 폭포수 견본을 가져가야 합니다.", tag="선택사항", desc="폭포 안쪽에 서서 퀘스트 병을 사용하세요."}, [143]={npc="다이노", tgt="다이노", tag="선택사항", desc="폭포 안쪽에 서서 퀘스트 병을 사용하세요."}, [144]={npc="다이노", tgt="다이노", tag="선택사항"}, [145]={hint="크로스로드에 있는 킬할라에게 미소띤 자매의 머리카락 12개를 가져가야 합니다.", tag="선택사항"}, [146]={npc="킬할라", tgt="킬할라", tag="선택사항"}, [147]={npc="킬할라", tgt="킬할라", tag="선택사항"}, [148]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [149]={npc="킬할라", tgt="킬할라", tag="선택사항"}, [150]={text="방금 북쪽에서 전쟁노래부족 보고서를 제출했다면 크로스로드에서 오그리마로 날아가세요. 그 밖에는 지금 있는 토막나무 초소, 조람가르 전초기지, 해바위 은거지에서 오그리마로 날아가세요. 30레벨 기술을 훈련한 뒤 프레자(50.82, 13.54) 쪽에서 티리스팔 숲행 비행선을 타고, 브릴에서 내려 언더시티로 가세요. 언더시티에서 제출이나 훈련이 필요 없다고 확신할 때만 타렌 밀농장에 설정해 둔 귀환석을 바로 쓰세요."}}},
    ["05-d8"] = {name="검은심연의 나락", entrance="잿빛 골짜기 16.50, 11.00", pickup="돌발톱 산맥 해바위 야영지에서 츄나만에게 검은심연의 나락으로...를 받고, 잿빛 골짜기 조람가르 전초기지의 제네우 생크리를 위해 남겨 두세요. 불모의 땅 톱니항과 타우라조 야영지에서 소랜루크 수정구을 미리 받을 수 있습니다(흑마법사만 해당). 은빛소나무 숲 공동묘지에서 달빛이 입 맞춘 칼날을 받고 로그에 남겨 두세요(언데드 성기사만 해당). 잿빛 골짜기 조람 해안에서 먼저 아쿠마이의 정수과 폐허 사이로을 받으세요. 바깥 동굴에서 쪽지를 얻었다면 던전에 들어가기 전에 전초기지에 제출하세요. 그다음 코르석을 찾아서를 받으세요(언데드 성기사만 해당).", pickupS={{"돌발톱 산맥 해바위 야영지에서 츄나만에게 검은심연의 나락으로...를 받고, 잿빛 골짜기 조람가르 전초기지의 제네우 생크리를 위해 남겨 두세요"}, {"불모의 땅 톱니항과 타우라조 야영지에서 소랜루크 수정구을 미리 받을 수 있습니다(흑마법사만 해당)"}, {"은빛소나무 숲 공동묘지에서 달빛이 입 맞춘 칼날을 받고 로그에 남겨 두세요(언데드 성기사만 해당)"}, {"잿빛 골짜기 조람 해안에서 먼저 아쿠마이의 정수과 폐허 사이로을 받으세요"}, {"바깥 동굴에서 쪽지를 얻었다면 던전에 들어가기 전에 전초기지에 제출하세요"}, {"그다음 코르석을 찾아서를 받으세요(언데드 성기사만 해당)"}}, tips={{k="動線", text="수로 동굴을 따라 가무라의 거북 웅덩이로 가서, 수중 곁동굴에서 타엘리드를 찾으세요 → 여군주 사레베스와 겔리하스트가 있는 갈림길을 지나 황혼 야영지에서 로구스 제트를 찾으세요. 황혼 야영지를 지나며 조각을 모으세요. (흑마법사만 해당) 달의 제단 폐허 다리 밑에서 돌을 클릭해 군주 아쿠아니스를 처치하고 구체를 얻으세요 → 성소로 돌아가 켈리스를 처치하세요 → 파티가 준비되면 화로를 하나씩 점화하고 아쿠마이의 둥지로 들어가세요."}, {k="取捨", text="바깥 동굴의 아쿠마이의 정수과 쪽지는 한 번에 처리할 수 있습니다. 쪽지는 드랍 안내용이라, 얻지 못해도 다른 퀘스트는 계속할 수 있습니다. 코르석을 찾아서를 받았다면 같은 판에 끝낼 수 있습니다(언데드 성기사만 해당).", s={{"바깥 동굴의 아쿠마이의 정수과 쪽지는 한 번에 처리할 수 있습니다"}, {"쪽지는 드랍 안내용이라, 얻지 못해도 다른 퀘스트는 계속할 수 있습니다"}, {"코르석을 찾아서를 받았다면 같은 판에 끝낼 수 있습니다(언데드 성기사만 해당)", {race={"Scourge"}, class={"PALADIN"}}}}}, {k="說明", text="조람 해안 북서쪽 폐허의 바깥 동굴에서 물로 들어가 수로를 따라 동굴 안으로 헤엄치고, 가장 안쪽까지 가면 던전 입구입니다. 켈리스 주변 화로는 각각 몹 무리를 부르니 하나씩 점화하세요.", s={{"조람 해안 북서쪽 폐허의 바깥 동굴에서 물로 들어가 수로를 따라 동굴 안으로 헤엄치고, 가장 안쪽까지 가면 던전 입구입니다"}, {"켈리스 주변 화로는 각각 몹 무리를 부르니 하나씩 점화하세요"}}}}, steps={[1]={npc="츄나만", tgt="츄나만"}, [2]={hint="잿빛 골짜기에 있는 제네우 생크리와 대화하십시오."}, [3]={npc="제네우 생크리", tgt="제네우 생크리"}, [4]={npc="제네우 생크리", tgt="제네우 생크리", desc="먼저 조람가르에서 받으세요."}, [5]={hint="잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.", desc="먼저 조람가르에서 받으세요."}, [6]={npc="축축한 쪽지", npcObj=true, tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다.", preText="검은심연의 나락으로..."}, [7]={hint="축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오.", tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다."}, [8]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다."}, [9]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항", desc="축축한 쪽지(고대 신들에 대한 충성)를 먼저 제출하고, 같은 NPC에게서 받으세요.", preText="고대 신들에 대한 충성"}, [10]={npc="제네우 생크리", tgt="제네우 생크리"}, [11]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날을 받아 퀘스트 로그에 두세요. 이 퀘스트를 완료해 정화된 코르 보석을 얻은 뒤에야 을 제출할 수 있습니다."}, [12]={hint="코르석을 잿빛 골짜기에 있는 울릭 프로스트베일에게 가져가야 합니다.", tag="선택사항"}, [13]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항"}, [14]={text="검은심연의 나락 입구"}, [15]={npc="은빛경비병 타엘리드", tgt="은빛경비병 타엘리드", tag="게임 내 확인이 필요합니다", desc="거북 웅덩이 근처 수중 통로에서 타엘리드를 찾아 퀘스트를 받고, 황혼의 제단으로 가세요."}, [16]={hint="검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", tag="선택사항", desc="위치: 겔리하스트의 수중 동굴을 지나 황혼 야영지에서 로구스 제트를 찾으세요.", spot="겔리하스트의 수중 동굴을 지나 황혼 야영지에서 로구스 제트를 찾으세요."}, [17]={hint="소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", tag="선택사항", desc="위치: 황혼 야영지에서 성소까지 가며 수행사제를 처치하고 조각 3개를 얻으세요.", spot="황혼 야영지에서 성소까지 가며 수행사제를 처치하고 조각 3개를 얻으세요."}, [18]={hint="황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", desc="위치: 물가로 올라 달의 성소로 들어가 황혼의 제단 앞에서 켈리스를 처치하세요. 순서: 18~19단계를 같은 판에 하려면 먼저 물속으로 간 뒤 성소로 들어가세요.", spot="물가로 올라 달의 성소로 들어가 황혼의 제단 앞에서 켈리스를 처치하세요."}, [19]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.", desc="위치: 달의 제단 폐허 다리 밑으로 잠수해 심연의 돌을 클릭하고 핵을 얻으세요. 순서: 돌을 클릭하기 전에 파티를 모으세요. 19단계의 군주 아쿠아니스가 나옵니다.", spot="달의 제단 폐허 다리 밑으로 잠수해 심연의 돌을 클릭하고 핵을 얻으세요."}, [20]={npc="이상한 물구슬", npcObj=true, tag="게임 내 확인이 필요합니다", desc="군주 아쿠아니스를 처치하고 구체를 주운 뒤, 아이템을 우클릭해 퀘스트를 받으세요."}, [21]={npc="제네우 생크리", tgt="제네우 생크리"}, [22]={npc="제네우 생크리", tgt="제네우 생크리"}, [23]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항"}, [24]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."}, [25]={npc="제네우 생크리", tgt="제네우 생크리"}, [26]={npc="바샤나 룬토템", tgt="바샤나 룬토템"}}},
    ["03-15"] = {name="힐스브래드 구릉지", tips={{k="取捨", text="31레벨이 안 됐다면 구릉지 동굴에서 설인을 잡아 부족분을 채우세요."}, {k="取捨", text="달라란 순찰과 결속의 팔 보호구는 앞 단계를 제출해야 열립니다. 서쪽에서 한 번에 진행하세요. 도시로 통하는 열쇠는 가는 길에 받아도 되고, 달라란 던전은 건너뛰어도 됩니다."}, {k="取捨", text="침투는 포로 구출을 먼저 완료해야 받을 수 있으며, 알터랙 산맥에서 받도록 남겨 두세요. 죽음의 비약 앞부분을 하지 않았다면 해안 분기는 건너뛰세요."}, {k="提醒", text="헬쿨라의 무덤은 얼라이언스 마을 사우스쇼어 가까이에 있으니 마을 밖에서 접근하세요.", s={{"헬쿨라의 무덤은 얼라이언스 마을 사우스쇼어 가까이에 있으니 마을 밖에서 접근하세요"}}}, {k="提醒", text="30~32레벨 구간은 아라시 고원 해머폴과 함께 진행해 경험치를 쌓을 수 있습니다. 경험치가 부족하면 힐스브래드 서쪽 산기슭(약 45, 29)의 일반 설인을 먼저 잡거나 해머폴에서 보충하세요.", s={{"30~32레벨 구간은 아라시 고원 해머폴과 함께 진행해 경험치를 쌓을 수 있습니다"}, {"경험치가 부족하면 힐스브래드 서쪽 산기슭(약 45, 29)의 일반 설인을 먼저 잡거나 해머폴에서 보충하세요"}}}}, danger={[1]="사우스쇼어에는 55레벨 얼라이언스 경비병이 있습니다. 헬쿨라의 복수를 제출할 때는 마을 밖으로 묘지에 가고, 마을을 가로지르지 마세요.", [2]="설인 동굴 입구에는 몹이 몰려 있습니다. 헬쿨라의 마법봉을 찾으면서 바깥쪽을 먼저 정리하고, 동굴에 들어가기 전에 퇴로를 하나 확보하세요."}, grind={[1]={mob="동굴 설인", note="서쪽 설인 동굴 밖 비탈에 일반 몹이 밀집해 있습니다. 동굴 밖에서 한 마리씩 유인하고, 입구에 겹치는 몹 위치는 피하세요. 30레벨부터 시작할 수 있습니다."}, [2]={mob="사나운 설인", note="설인 동굴 입구 근처에 일반 몹이 밀집해 있고 동굴 안 설인과 섞여 있습니다. 바깥쪽부터 정리한 뒤 31~32레벨 경험치를 채우세요."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="토막나무 초소 이후 비행선을 이미 탔다면 브릴 남쪽 탑에서 언더시티로 가세요. 칼림도어에서 중간에 합류하는 경우에만 오그리마로 날아가 기술을 훈련한 뒤 비행선을 타세요. 언더시티 비행 지점을 아직 열지 않았다면 마이클 가렛(63.25, 48.56)을 찾으세요."}, [2]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="언더시티 선행 퀘스트가 있을 때만 수락, 선택사항"}, [3]={text="언더시티에서 타렌 밀농장으로 날아가세요."}, [4]={text="타렌 밀농장 비행 지점(60.14, 18.62)을 열고 귀환석 위치를 설정하세요."}, [5]={npc="수련사 사이반드", tgt="수련사 사이반드"}, [6]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [7]={npc="관리인 벨바릴", tgt="관리인 벨바릴"}, [8]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [9]={npc="탈로우", tgt="탈로우"}, [10]={text="구릉지 동굴 → 달라란 야영지"}, [11]={hint="설인에게서 헬쿨라의 마법봉을 되찾아 타렌 밀농장에 있는 수련사 사이반드에게 가져가야 합니다.", desc="마지막으로 사우스쇼어 밖에서 묘비를 찾으세요. 가까이 가기 전에 얼라이언스 경비병을 피하세요."}, [12]={npc="수련사 사이반드", tgt="수련사 사이반드"}, [13]={npc="수련사 사이반드", 