    ["05-d10"] = {name="달라란", entrance="알터랙 산맥 8.46, 59.21", pickup="타렌 밀농장에서 멜리사라에게 무덤 기사을 먼저 받고, 언더시티를 지날 때 박사 마틴 펠벤에게 힘의 원천을 받으세요. 힐스브래드 구릉지 타렌 밀농장에서 30레벨이 되면 학자 워딘 보이드글레어에게 감옥 습격와 도시로 통하는 열쇠을 받고, 로다미어 호수 남동쪽의 수용소로 가서 같은 판에 혈석과 더러운 열쇠를 얻으세요. 타렌 밀농장에 돌아가 제출한 뒤 달라란 순찰를 받고, 완료하면 피로 물든 거리를 받으세요. 호숫가를 돌아 대마법사 모데라의 환영에게 가서 분열의 심장를 받고, 하수도 열쇠는 몸에 지니세요.", pickupS={{"타렌 밀농장에서 멜리사라에게 무덤 기사을 먼저 받고, 언더시티를 지날 때 박사 마틴 펠벤에게 힘의 원천을 받으세요"}, {"힐스브래드 구릉지 타렌 밀농장에서 30레벨이 되면 학자 워딘 보이드글레어에게 감옥 습격와 도시로 통하는 열쇠을 받고, 로다미어 호수 남동쪽의 수용소로 가서 같은 판에 혈석과 더러운 열쇠를 얻으세요"}, {"타렌 밀농장에 돌아가 제출한 뒤 달라란 순찰를 받고, 완료하면 피로 물든 거리를 받으세요"}, {"호숫가를 돌아 대마법사 모데라의 환영에게 가서 분열의 심장를 받고, 하수도 열쇠는 몸에 지니세요"}}, tips={{k="動線", text="입구에서 하수도 입구의 고블린 퀘스트를 받습니다 → 아트렉시스를 처치하고, 린을 원하면 룬 방에 들어갑니다 → 오른쪽 길로 거리에 올라 구조체 핵을 모으고, 성채 왼쪽 위층 책장에서 책을 찾습니다 → 보랏빛 성채 응접실에서 차원문을 열고 대마법사의 망령을 처치합니다. 던전을 나가기 전에 하수도 입구의 렉시에게 책을 전달하세요."}, {k="取捨", text="호드의 선행 퀘스트는 30레벨부터 시작합니다. 입구 퀘스트를 먼저 완료한 뒤 파티를 모집하세요. 파티에서 누가 열쇠를 가졌는지 확인하고, 다시 올 때를 위해 자기 열쇠도 챙기세요. 숨겨진 우두머리 외면받는 린을 원하면 그림자송곳니 성채에서 시작해 만든 달라란의 고서를 가져오세요."}, {k="說明", text="모데라의 환영과 정식 입구는 위치가 다릅니다. 로다미어 호수의 하수도 쪽으로 가세요. 야외 달라란 성문과 도시 안 NPC는 진영 규칙에 따라 접근이 제한됩니다.", s={{"모데라의 환영과 정식 입구는 위치가 다릅니다"}, {"로다미어 호수의 하수도 쪽으로 가세요"}, {"야외 달라란 성문과 도시 안 NPC는 진영 규칙에 따라 접근이 제한됩니다"}}}}, steps={[1]={npc="박사 마틴 펠벤", tgt="박사 마틴 펠벤"}, [2]={npc="멜리사라", tgt="멜리사라"}, [3]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [4]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [5]={hint="배반자들을 찾아내 유물을 되찾은 다음에 돌아가야 합니다."}, [6]={hint="타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란 하수도 열쇠를 입수해야 합니다."}, [7]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [8]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [9]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", preText="감옥 습격, 도시로 통하는 열쇠"}, [10]={hint="달라란 소환사 6명과 노예 바위 정령 8마리를 처치한 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다."}, [11]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [12]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", preText="달라란 순찰, 도시로 통하는 열쇠"}, [13]={hint="로다미어 호수에서 달라란에 들어갈 길을 찾아야 합니다."}, [14]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영"}, [15]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영", desc="퀘스트를 받으면 달라란 하수도 열쇠(아이템 277507)를 얻습니다. 더러운 열쇠는 선행 조건일 뿐입니다.", preText="피로 물든 거리"}, [16]={text="달라란 입구"}, [17]={npc="Rexxie Copperclutch", tag="게임 내 확인이 필요합니다", desc="던전에 들어가면 먼저 하수도 오른쪽 우리 안의 고블린을 찾으세요."}, [18]={hint="타렌 밀농장에 있는 멜리사라를 위해 달라란에서 무덤 기사 아트렉시스를 처치해야 합니다.", desc="위치: 입구에서 하수도 큰길을 따라 깊숙이 들어가 탁 트인 곳에서 아트렉시스를 처치하세요.", spot="입구에서 하수도 큰길을 따라 깊숙이 들어가 탁 트인 곳에서 아트렉시스를 처치하세요."}, [19]={hint="언더시티에 있는 박사 마틴 펠벤을 위해 달라란에서 금이 간 파수꾼 핵 6개를 모아야 합니다.", desc="위치: 무덤 기사를 지나 오른쪽 길로 거리에 올라가 길을 따라 부서진 파수꾼을 정리하세요.", spot="무덤 기사를 지나 오른쪽 길로 거리에 올라가 길을 따라 부서진 파수꾼을 정리하세요."}, [20]={hint="하수도 입구 주위에 있는 렉시 코퍼클러치를 위해 달라란에서 달라란 건국사를 입수해야 합니다.", desc="위치: 성채 계단 왼쪽 건물의 위층으로 올라가 조각상 뒤 책장을 찾으세요.", spot="성채 계단 왼쪽 건물의 위층으로 올라가 조각상 뒤 책장을 찾으세요."}, [21]={npc="Rexxie Copperclutch", tag="게임 내 확인이 필요합니다"}, [22]={hint="타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌을 모아야 합니다.", desc="위치: 보랏빛 성채에서 차원문을 열고 응접실로 가 대마법사의 망령을 처치하세요.", spot="보랏빛 성채에서 차원문을 열고 응접실로 가 대마법사의 망령을 처치하세요."}, [23]={npc="멜리사라", tgt="멜리사라"}, [24]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [25]={npc="박사 마틴 펠벤", tgt="박사 마틴 펠벤"}, [26]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", desc="호드는 던전을 나와 호숫가의 환영에게 제출하세요. 캐릭터의 현재 퀘스트 표시를 따르세요.", preText="분열의 심장"}, [27]={hint="달라란 근처에 있는 대마법사 모데라의 환영과 대화해야 합니다.", desc="호드는 던전을 나와 호숫가의 환영에게 제출하세요. 캐릭터의 현재 퀘스트 표시를 따르세요."}, [28]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영", desc="호드는 던전을 나와 호숫가의 환영에게 제출하세요. 캐릭터의 현재 퀘스트 표시를 따르세요."}}},
    ["05-d9"] = {name="붉은십자군 수도원: 묘지", entrance="티리스팔 숲 85.20, 32.10", pickup="힐스브래드 구릉지 타렌 밀농장을 지나갈 때 비행 지점을 먼저 열어 두세요. 언더시티에서는 티리스팔 숲 북쪽 길을 따라 수도원으로 가세요. 먼저 가시덩굴 우리의 조분석을 나에게!를 완료하세요(버섯구름 봉우리를 먼저 가고 가시덩굴 우리를 나중에 간다면 열정의 증거은 알터랙 산맥으로 가는 길에 받으세요. 묘지에서는 먼저 보렐을 처치해도 됩니다). 언더시티 연금술 구역에서 파라넬을 만나세요. 묘지를 나온 뒤에는 알터랙 호숫가와 타렌 밀농장으로 가세요.", pickupS={{"힐스브래드 구릉지 타렌 밀농장을 지나갈 때 비행 지점을 먼저 열어 두세요"}, {"언더시티에서는 티리스팔 숲 북쪽 길을 따라 수도원으로 가세요"}, {"먼저 가시덩굴 우리의 조분석을 나에게!를 완료하세요(버섯구름 봉우리를 먼저 가고 가시덩굴 우리를 나중에 간다면 열정의 증거은 알터랙 산맥으로 가는 길에 받으세요"}, {"묘지에서는 먼저 보렐을 처치해도 됩니다)"}, {"언더시티 연금술 구역에서 파라넬을 만나세요"}, {"묘지를 나온 뒤에는 알터랙 호숫가와 타렌 밀농장으로 가세요"}}, tips={{k="動線", text="입구 복도에서 십자군을 정리하고 심장을 줍습니다 → 심문실에서 비샤스를 처치하고 고문대에 있는 보렐을 찾습니다 → 야외 묘지를 가로질러 지하묘지 계단으로 내려가 혈법사 탈노스를 처치합니다."}, {k="取捨", text="묘지는 초반에 파티를 모으기 쉽습니다. 조분석을 나에게!를 받지 않았어도 먼저 보렐을 처치하세요."}, {k="說明", text="가장 왼쪽 입구를 확인하세요. 묘지에는 붉은십자군 열쇠가 필요 없습니다.", s={{"가장 왼쪽 입구를 확인하세요"}, {"묘지에는 붉은십자군 열쇠가 필요 없습니다"}}}}, steps={[1]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="가시덩굴 우리를 먼저 돌 때만 받으세요. 버섯구름 봉우리 반짝이는 평원에서도 할 수 있습니다."}, [2]={hint="언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", tag="선택사항", desc="이 단계는 가시덩굴 우리에서 합니다."}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항"}, [4]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="조분석을 나에게!의 전체 경로는 가시덩굴 우리를 참조하세요. 네 구역 모두에서 심장이 누적되니, 네 구역을 같이 돌 때 받으세요.", preText="조분석을 나에게!"}, [5]={text="붉은십자군 수도원: 묘지 입구"}, [6]={npc="보렐 센구츠", tgt="보렐 센구츠", tag="게임 내 확인이 필요합니다", desc="앞쪽 심문 구역의 고문대에서 보렐을 찾으세요."}, [7]={hint="언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다.", tag="선택사항", desc="위치: 현관부터 심문실까지 살아있는 붉은십자군을 처치하세요.", spot="현관부터 심문실까지 살아있는 붉은십자군을 처치하세요."}, [8]={hint="타렌 밀농장에 있는 모니카 센구츠에게 보렐의 결혼반지를 가져가야 합니다.", desc="같은 방에 정예가 하나 더 있을 수 있습니다. 부두로 순찰해 올 때까지 기다려도 됩니다."}, [9]={npc="모니카 센구츠", tgt="모니카 센구츠"}, [10]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="언더시티에 제출하기 전에 20개를 모두 수집하세요."}}},
    ["03-16"] = {name="아라시 고원", nameA="아라시 고원: {a:321}", tips={{k="取捨", text="해머폴 근처의 랩터, 비밀결사 몹, 남동쪽의 마른나무껍질 몹을 먼저 정리하세요. 이미 32레벨이라면 이어지는 전장으로, 랩터의 기민함은 아라시 고원 해머폴에 다시 올 때를 위해 남겨 두세요."}, {k="取捨", text="병동 보급 작전과 비단결 봉합사는 영구 버전에서 추가된 퀘스트입니다. 를 먼저 제출해야 를 받을 수 있습니다. 이미 32레벨이라면 두 번째 방문 때로 남겨 두세요."}, {k="提醒", text="버섯구름 봉우리로 가기 전에 32레벨이 안 됐다면 해머폴에서 마른나무껍질 마을 외곽(약 68, 69)의 일반 마른나무껍질 트롤을 잡으세요. 몹이 많은 야영지 안쪽으로는 들어가지 마세요.", s={{"버섯구름 봉우리로 가기 전에 32레벨이 안 됐다면 해머폴에서 마른나무껍질 마을 외곽(약 68, 69)의 일반 마른나무껍질 트롤을 잡으세요"}, {"몹이 많은 야영지 안쪽으로는 들어가지 마세요"}}}}, danger={[1]="마른나무껍질 마을 집 안의 주술사는 치유를 하고, 집 앞에는 더 높은 레벨의 사냥꾼이 있습니다. 밭 가장자리부터 정리하고, 차단 기술은 아껴 두세요."}, grind={[1]={mob="마른나무껍질부족 도끼투척병", note="마른나무껍질 마을 외곽에 원거리 일반 몹이 밀집해 있습니다. 비탈 가장자리에서 한 마리씩 유인하세요. 원래 퀘스트 지역과 가까워 32레벨을 채우기 좋습니다."}, [2]={mob="마른나무껍질부족 의술사", note="마른나무껍질 마을 동쪽에 시전하는 일반 몹이 밀집해 있습니다. 치유를 차단하고 집 밖을 따라 정리하세요. 근처의 더 높은 레벨 마른나무껍질 사냥꾼을 조심하세요."}}, supply={[1]={npc="우르다"}, [2]={npc="여관주인 아데그와"}, [3]={npc="무우타"}, [4]={npc="여관주인 아데그와"}, [5]={npc="그라우드"}}, steps={[1]={hint="돌주먹 오우거 8마리와 돌주먹일족 집행자 10마리를 처치한 다음 아라시 고원의 해머폴로 가서 드럼 펠을 찾아야 합니다."}, [2]={text="해머폴에 도착하면 우르다 비행 지점(73.02, 32.70)을 여세요."}, [3]={npc="드럼 펠", tgt="드럼 펠"}, [4]={npc="고르멀", tgt="고르멀"}, [5]={hint="해머폴에 있는 토건과 대화해야 합니다."}, [6]={npc="토건", tgt="토건"}, [7]={npc="토건", tgt="토건"}, [8]={npc="토건", tgt="토건"}, [9]={npc="드럼 펠", tgt="드럼 펠"}, [10]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [11]={hint="줄무늬 고원랩터와 외뿔 고원랩터에게서 고원 랩터 눈 10개를 구해 해머폴에 있는 토건에게 가져가야 합니다."}, [12]={hint="해머폴에 있는 토건에게 혈석 아뮬렛 10개를 가져가야 합니다."}, [13]={npc="토건", tgt="토건"}, [14]={npc="토건", tgt="토건"}, [15]={npc="토건", tgt="토건"}, [16]={hint="고르멀에게 랩터 발톱 아뮬렛을 전달해야 합니다."}, [17]={npc="고르멀", tgt="고르멀"}, [18]={npc="고르멀", tgt="고르멀"}, [19]={hint="토건과 대화해야 합니다."}, [20]={npc="토건", tgt="토건"}, [21]={hint="마른나무껍질부족 도끼투척병 10명과 인간사냥꾼 10명, 의술사 8명을 처치하고 해머폴 전초기지에 있는 드럼 펠에게 돌아가야 합니다."}, [22]={hint="아라시 고원 해머폴에 있는 의사 그레고리 빅터에게 외과용 거미줄 12개를 가져가야 합니다."}, [23]={npc="드럼 펠", tgt="드럼 펠"}, [24]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [25]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터", desc="같은 의사에게 먼저 비단결 봉합사를 제출해야 보급 퀘스트가 나옵니다."}, [26]={hint="고셰크 농장 조렐의 실험실에서 포장된 강장제 보관함을 획득한 후, 해머폴에 있는 의사 그레고리 빅터에게 반환해야 합니다."}, [27]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [28]={text="언더시티로 날아가 기술을 훈련하고 가방을 정리한 뒤, 브릴 남쪽 비행선 탑에서 오그리마행 비행선을 타세요. 오그리마에 도착하면 프리윈드 초소 비행 지점을 이미 열었다면 바로 선택하고, 열지 않았다면 타우라조 야영지로 날아가 남쪽 길의 대승강기로 골짜기 바닥에 내려간 뒤 동쪽 프리윈드 초소 승강기를 타세요."}}},
    ["05-d13"] = {name="붉은십자군 수도원: 대성당", entrance="티리스팔 숲 85.20, 32.10", pickup="아라시 고원 해머폴에서 언더시티로 날아가, 35레벨이 되면 도서관, 무기고와 같은 판에 하세요. 힐스브래드 구릉지로 가는 길에 언더시티를 지날 때 왕실 구역의 바리마트라스를 확인하고, 33레벨에 붉은십자군 수도원으로을 받으세요. 아직 35레벨이 아니면 동부 왕국으로 돌아가 알터랙 산맥으로 갈 때 함께 하세요. 붉은십자군 열쇠와 도서관, 무기고의 처치 진행 상황을 유지하세요.", pickupS={{"아라시 고원 해머폴에서 언더시티로 날아가, 35레벨이 되면 도서관, 무기고와 같은 판에 하세요"}, {"힐스브래드 구릉지로 가는 길에 언더시티를 지날 때 왕실 구역의 바리마트라스를 확인하고, 33레벨에 붉은십자군 수도원으로을 받으세요"}, {"아직 35레벨이 아니면 동부 왕국으로 돌아가 알터랙 산맥으로 갈 때 함께 하세요"}, {"붉은십자군 열쇠와 도서관, 무기고의 처치 진행 상황을 유지하세요"}}, tips={{k="動線", text="분수 안뜰을 지나 계단을 올라갑니다 → 본당에서 모그레인을 처치합니다 → 화이트메인이 모그레인을 부활시킵니다 → 두 명을 모두 처치합니다."}, {k="取捨", text="록시나 헤로드가 아직 남았다면 먼저 해당 구역으로 돌아간 뒤 함께 도시로 돌아가세요."}, {k="說明", text="붉은십자군 열쇠를 가져오거나, 자물쇠 따기 별 관측 이상의 도적에게 문을 열어 달라고 하세요.", s={{"붉은십자군 열쇠를 가져오거나, 자물쇠 따기 별 관측 이상의 도적에게 문을 열어 달라고 하세요"}}}}, steps={[1]={text="선행 퀘스트: 붉은십자군 수도원으로"}, [2]={text="붉은십자군 수도원: 대성당 입구"}, [3]={hint="종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 돌아가 보고해야 합니다.", desc="대성당에서는 먼저 방 주변을 정리하세요. 화이트메인이 모그레인을 부활시킵니다. 위치: 분수 안뜰을 지나 계단을 올라가 본당에서 두 우두머리를 처치하세요. 순서: 모그레인 → 화이트메인이 부활시킴 → 두 명 모두 처치.", spot="분수 안뜰을 지나 계단을 올라가 본당에서 두 우두머리를 처치하세요."}, [4]={npc="바리마트라스", tgt="바리마트라스", desc="우두머리 네 명이 모두 집계되면 언더시티 왕실 구역으로 돌아가세요."}}},
    ["05-d12"] = {name="붉은십자군 수도원: 무기고", entrance="티리스팔 숲 85.20, 32.10", pickup="아라시 고원 해머폴에서 언더시티로 날아가 도서관과 같은 판에 하세요. 언더시티 왕실 구역의 바리마트라스에게 33레벨에 붉은십자군 수도원으로을 받으세요. 도서관에서 이미 받았다면 퀘스트를 유지하고 붉은십자군 열쇠를 챙기세요. 언더시티에서 티리스팔 숲 북쪽 길을 따라 수도원으로 가세요.", pickupS={{"아라시 고원 해머폴에서 언더시티로 날아가 도서관과 같은 판에 하세요"}, {"언더시티 왕실 구역의 바리마트라스에게 33레벨에 붉은십자군 수도원으로을 받으세요"}, {"도서관에서 이미 받았다면 퀘스트를 유지하고 붉은십자군 열쇠를 챙기세요"}, {"언더시티에서 티리스팔 숲 북쪽 길을 따라 수도원으로 가세요"}}, tips={{k="動線", text="무기고 문을 열고 → 병영과 긴 복도를 따라 끝까지 가서 → 대전당에서 헤로드를 처치하고 → 뒤이어 들어오는 붉은십자군 훈련생을 정리하세요."}, {k="取捨", text="열쇠가 있는 파티는 바로 무기고를 정리해도 됩니다."}, {k="說明", text="붉은십자군 열쇠를 가져오거나, 자물쇠 따기 별 관측 이상의 도적에게 문을 열어 달라고 하세요.", s={{"붉은십자군 열쇠를 가져오거나, 자물쇠 따기 별 관측 이상의 도적에게 문을 열어 달라고 하세요"}}}}, steps={[1]={text="선행 퀘스트: 붉은십자군 수도원으로"}, [2]={text="붉은십자군 수도원: 무기고 입구"}, [3]={text="용사 헤로드를 처치하면 붉은십자군 수도원으로 에 기록됩니다. 소용돌이 중에는 근접 공격을 멈추고 거리를 두세요."}, [4]={text="붉은십자군 수도원으로는 대성당까지 유지하세요. 우두머리 네 명을 모두 처치한 뒤 언더시티에 제출합니다.", desc="무기고를 마친 뒤 퀘스트를 유지하고 대성당을 계속 진행하세요."}}},
    ["05-d11"] = {name="붉은십자군 수도원: 도서관", entrance="티리스팔 숲 85.20, 32.10", pickup="아라시 고원 해머폴에서 언더시티로 돌아가 도서관을 가세요. 버섯구름 봉우리 높새바람 봉우리에서는 먼저 도른의 믿음의 시험 → 인내의 시험 → 용기의 시험을 하세요. 돌발톱 산맥 해바위 야영지를 이미 지났다면 잿빛 골짜기 남쪽 터널로 브라우그에게 간 뒤 언더시티에서 파쿠알을 찾으세요. 썬더 블러프를 지날 때 타락의 개요를 함께 받으세요(오크, 타우렌, 트롤만 해당). 버섯구름 봉우리 반짝이는 평원과 먼지진흙 습지대 장벽 마을에서 타베사와 티르스의 선행 퀘스트를 진행할 수 있고, 책은 나중에 동부 왕국으로 돌아갔을 때 챙겨도 됩니다(마법사만 해당).", pickupS={{"아라시 고원 해머폴에서 언더시티로 돌아가 도서관을 가세요"}, {"버섯구름 봉우리 높새바람 봉우리에서는 먼저 도른의 믿음의 시험 → 인내의 시험 → 용기의 시험을 하세요"}, {"돌발톱 산맥 해바위 야영지를 이미 지났다면 잿빛 골짜기 남쪽 터널로 브라우그에게 간 뒤 언더시티에서 파쿠알을 찾으세요"}, {"썬더 블러프를 지날 때 타락의 개요를 함께 받으세요(오크, 타우렌, 트롤만 해당)", {race={"Orc", "Tauren", "Troll"}}}, {"버섯구름 봉우리 반짝이는 평원과 먼지진흙 습지대 장벽 마을에서 타베사와 티르스의 선행 퀘스트를 진행할 수 있고, 책은 나중에 동부 왕국으로 돌아갔을 때 챙겨도 됩니다(마법사만 해당)", {class={"MAGE"}}}}, tips={{k="動線", text="입구 회랑을 지나 왼쪽 작은 방에서 책을 챙깁니다 → 앞마당을 지나 사냥개조련사 록시를 처치합니다 → 긴 복도 끝과 도안 앞 책장에서 각각 책을 챙깁니다 → 신비술사 도안을 처치하고 뒤의 상자에서 붉은십자군 열쇠를 얻습니다."}, {k="取捨", text="먼저 붉은십자군 열쇠를 얻으면 무기고와 대성당을 이어서 열 수 있습니다. 책 퀘스트도 함께 주우세요."}, {k="說明", text="붉은십자군 수도원으로은 세 구역에 걸쳐 있습니다. 전체 진행과 제출은 대성당 항목에 있습니다.", s={{"붉은십자군 수도원으로은 세 구역에 걸쳐 있습니다"}, {"전체 진행과 제출은 대성당 항목에 있습니다"}}}}, steps={[1]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", desc="이미 버섯구름 봉우리 높새바람 봉우리에서 했다면 건너뛰세요."}, [2]={hint="믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.", tag="선택사항", desc="이미 버섯구름 봉우리 높새바람 봉우리에서 했다면 건너뛰세요."}, [3]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", desc="이미 버섯구름 봉우리 높새바람 봉우리에서 했다면 건너뛰세요."}, [4]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="믿음의 시험"}, [5]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다.", tag="선택사항"}, [6]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항"}, [7]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="인내의 시험"}, [8]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다.", tag="선택사항"}, [9]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항"}, [10]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="용기의 시험"}, [11]={hint="돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿을 찾아야 합니다.", tag="선택사항"}, [12]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항"}, [13]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", desc="책은 동굴 안에 있습니다. 찾은 뒤 브라우그에게 돌아가 제출하세요.", preText="지혜의 시험"}, [14]={hint="고대의 유산을 찾아 돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿에게 가져가야 합니다.", tag="선택사항", desc="책은 동굴 안에 있습니다. 찾은 뒤 브라우그에게 돌아가 제출하세요."}, [15]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", desc="책은 동굴 안에 있습니다. 찾은 뒤 브라우그에게 돌아가 제출하세요."}, [16]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", preText="지혜의 시험"}, [17]={hint="브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.", tag="선택사항"}, [18]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항"}, [19]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", preText="지혜의 시험"}, [20]={hint="언더시티에서 파쿠알 핀탈라스를 찾아야 합니다.", tag="선택사항"}, [21]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항"}, [22]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항", preText="지혜의 시험"}, [23]={npc="현자 트루스시커", tgt="현자 트루스시커"}, [24]={npc="바리마트라스", tgt="바리마트라스", desc="최소 33레벨입니다. 이번에 레벨이 부족하면 나중에 퀘스트를 받고 돌아와 록시를 다시 처치하세요."}, [25]={npc="다이노", tgt="다이노", tag="선택사항", desc="같은 퀘스트를 오슨 그룰에게서도 받을 수 있습니다(25.70, 14.19). 아나스타샤 하트웰(85.14, 10.03)에게서도 받을 수 있습니다."}, [26]={hint="타베사와 대화하십시오.", tag="선택사항"}, [27]={npc="타베사", tgt="타베사", tag="선택사항"}, [28]={npc="타베사", tgt="타베사", tag="선택사항", preText="습지대로의 여행"}, [29]={hint="소금 평원에 있는 학자 틸스와 대화하십시오.", tag="선택사항"}, [30]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [31]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", preText="숨겨진 비밀"}, [32]={hint="틸스의 금고를 여는 주문을 알아서 틸스에게 돌아가야 합니다.", tag="선택사항"}, [33]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [34]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", preText="주문 알아오기"}, [35]={text="붉은십자군 수도원: 도서관 입구"}, [36]={hint="언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 가져가야 합니다.", tag="선택사항", desc="위치: 입구 회랑 앞쪽 왼쪽 작은 방의 탁자에서 언데드 위협의 기원을 챙기세요.", spot="입구 회랑 앞쪽 왼쪽 작은 방의 탁자에서 언데드 위협의 기원을 챙기세요."}, [37]={hint="티리스팔 숲의 붉은십자군 수도원에서 타락의 개요를 찾아 썬더 블러프에 있는 현자 트루스시커에게 가져가야 합니다.", desc="위치: 록시를 지나 마지막 모퉁이로 가서 도안이 있는 복도 시작 지점의 책장을 찾으세요.", spot="록시를 지나 마지막 모퉁이로 가서 도안이 있는 복도 시작 지점의 책장을 찾으세요."}, [38]={hint="먼지진흙 습지대에 있는 타베사에게 마력의 의식을 가져가야 합니다.", tag="선택사항", desc="위치: 마지막 복도 시작 지점에서 왼쪽 책장에 튀어나온 책을 찾으세요.", spot="마지막 복도 시작 지점에서 왼쪽 책장에 튀어나온 책을 찾으세요."}, [39]={text="사냥개조련사 록시를 처치하면 붉은십자군 수도원으로 에 기록됩니다."}, [40]={text="신비술사 도안을 처치하고 뒤의 금고를 열어 붉은십자군 열쇠를 얻으세요."}, [41]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항"}, [42]={npc="현자 트루스시커", tgt="현자 트루스시커"}, [43]={npc="타베사", tgt="타베사", tag="선택사항"}}},
    ["03-17"] = {name="버섯구름 봉우리", nameA="버섯구름 봉우리: {a:484} & {a:439}", shortA="버섯구름 봉우리: {a:484} +", tips={{k="取捨", text="반짝이는 평원의 퀘스트 6개는 서로 가까우니, 모두 받은 뒤 한 바퀴 도세요. 경주 배달 은 다음에 톱니항을 지날 때만 하세요. 제출한 뒤 부두주임 디지위그에게서 크레이블의 부품을 받아 두었다가 다음에 반짝이는 평원 경주장에 들를 때 제출하세요."}, {k="取捨", text="망명자 마르텍 은 황야의 땅 카르가스, 형제 형제애은 잊혀진 땅 그늘수렵 마을, 네싱워리 헤멧 네싱워리는 가시덤불 골짜기 그롬골과 무법항 구간을 위해 남겨 두세요."}, {k="提醒", text="곤충 떼의 위협을 아직 제출하지 않았다면 곤충 떼의 위협은 건너뛰세요. 영상에서는 벌레 굴 안 몹의 레벨이 높으니 입구 일대만 잡고 돌아오라고 안내합니다. 실리시드 등껍질을 완료했다면 먼지진흙 습지 브래큰월 마을로 가는 길에 크로스로드에서 제출하세요.", s={{"곤충 떼의 위협을 아직 제출하지 않았다면 곤충 떼의 위협은 건너뛰세요"}, {"영상에서는 벌레 굴 안 몹의 레벨이 높으니 입구 일대만 잡고 돌아오라고 안내합니다"}, {"실리시드 등껍질을 완료했다면 먼지진흙 습지 브래큰월 마을로 가는 길에 크로스로드에서 제출하세요"}}}, {k="提醒", text="32~34레벨 구간은 잊혀진 땅 그늘수렵 마을과 함께 진행해 경험치를 쌓을 수 있습니다. 반짝이는 평원에서 33레벨이 안 됐다면 경주장 남쪽(약 76, 85)에서 거북, 독수리, 전갈을 잡은 뒤 잊혀진 땅으로 가세요.", s={{"32~34레벨 구간은 잊혀진 땅 그늘수렵 마을과 함께 진행해 경험치를 쌓을 수 있습니다"}, {"반짝이는 평원에서 33레벨이 안 됐다면 경주장 남쪽(약 76, 85)에서 거북, 독수리, 전갈을 잡은 뒤 잊혀진 땅으로 가세요"}}}}, danger={[1]="반짝이는 평원 벌레 굴 깊은 곳에는 높은 레벨의 실리시드가 밀집해 있습니다. 곤충 떼의 위협을 마친 뒤 입구까지 왔던 길로 나오세요."}, grind={[1]={mob="소금바위 수정바실리스크", note="반짝이는 평원 경주장 남쪽에 일반 몹이 밀집해 있습니다. 지형이 탁 트여 있으니 소금 평원에서 한 마리씩 골라 잡으세요. 32레벨 경험치를 채우기 좋습니다."}, [2]={mob="굼벵이 소금껍질거북", note="같은 소금 평원 동쪽에 일반 몹이 보통 밀도로 있습니다. 도마뱀과 번갈아 잡으며 소금껍질 거북 껍질도 모으세요."}, [3]={mob="점박이독전갈", note="경주장 남동쪽에 일반 몹이 보통 밀도로 있습니다. 지상을 돌며 잡고 근처의 다른 소금 평원 야수를 조심하세요. 전갈 독 퀘스트가 있으면 함께 모으세요."}}, supply={[1]={npc="니세"}, [2]={npc="여관주인 아베크와"}, [3]={npc="스타른"}, [4]={npc="여관주인 아베크와"}, [5]={npc="스타른"}, [6]={npc="몬타르"}, [7]={npc="신게"}, [8]={npc="리즈넥"}, [9]={npc="신게"}}, steps={[1]={text="먼저 프리윈드 초소 니세 비행 지점(45.14, 49.11)을 열고, 길을 따라 남동쪽 반짝이는 평원으로 가세요."}, [2]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [3]={npc="목타르 크린", tgt="목타르 크린", tag="선택사항"}, [4]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [5]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [6]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [7]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [8]={npc="포직", tgt="포직"}, [9]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [10]={hint="소금 평원에 있는 피즐 브라스볼츠에게 소금기 있는 전갈 독 6개를 가져가야 합니다."}, [11]={hint="소금 평원에 있는 위즐 브라스볼츠에게 단단한 거북 등껍질 9개를 가져가야 합니다."}, [12]={hint="소금 평원의 크레이블 콜비어드에게 로켓 자동차 부품 30개를 가져가야 합니다."}, [13]={hint="소금 평원에 있는 경주로관리인 제린을 위해 소금바위 바실리스크 10 마리, 소금바위 수정바실리스크 10 마리 및 소금바위 큰눈바실리스크 6 마리를 처치해야 합니다."}, [14]={hint="소금 평원에 있는 포직을 위해 가벼운 독수리 뼈 10개를 구해야 합니다."}, [15]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [16]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [17]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [18]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [19]={npc="포직", tgt="포직"}, [20]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [21]={npc="포직", tgt="포직", tag="톱니항을 지날 때만 진행, 선택사항"}, [22]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드", tag="톱니항을 지날 때만 진행, 선택사항"}, [23]={text="경주 배달 퀘스트를 받았다면 톱니항에 한 번 들르세요."}, [24]={hint="톱니항에 있는 가즈로와 대화하십시오.", tag="톱니항을 지날 때만 진행, 선택사항"}, [25]={hint="톱니항에 있는 부두주임 디지위그에게 크레이블의 부품주문서를 가져가야 합니다.", tag="톱니항을 지날 때만 진행, 선택사항"}, [26]={npc="가즈로", tgt="가즈로", tag="톱니항을 지날 때만 진행, 선택사항"}, [27]={npc="부두주임 디지위그", tgt="부두주임 디지위그", tag="톱니항을 지날 때만 진행, 선택사항"}, [28]={npc="가즈로", tgt="가즈로", tag="선택사항"}, [29]={npc="금이 간 실리시드 등껍질", npcObj=true, tag="곤충 떼의 위협 도중 드랍될 때 수락, 선택사항", desc="곤충 떼의 위협을 하는 동안 부서진 실리시드 껍데기가 드랍됩니다. 주운 뒤 아이템을 우클릭해야 퀘스트를 받습니다."}, [30]={hint="크로스로드에 있는 코란에게 실리시드의 심장 1개, 실리시드의 갈퀴발톱 5개, 온전한 실리시드의 등껍질 3개를 가져가야 합니다.", tag="곤충 떼의 위협과 한 번에 진행, 선택사항"}, [31]={hint="탐색꾼 실리시드 5마리, 일꾼 실리시드 5마리, 병정 실리시드 5마리를 처치하고 버섯구름 봉우리에 있는 목타르 크린에게 돌아가야 합니다.", tag="선택사항"}, [32]={npc="목타르 크린", tgt="목타르 크린", tag="선택사항"}, [33]={hint="불모의 땅에 있는 이슬렌 워터시어에게 물의 결정을 가져가야 합니다.", desc="완료하면 물의 토템을 얻어요."}, [34]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어", desc="완료하면 물의 토템을 얻어요."}, [35]={npc="시안 파이어워더", tgt="시안 파이어워더", desc="오그리마 훈련사에게서 바람의 부름을 받을 수 있고, 썬더 블러프에서는 같은 계열의 대체 안내 퀘스트 바람의 부름를 받을 수 있어요."}, [36]={hint="버섯구름 봉우리에서 프레이트 클라우드시어를 찾아야 합니다.", desc="오그리마 훈련사에게서 바람의 부름을 받을 수 있고, 썬더 블러프에서는 같은 계열의 대체 안내 퀘스트 바람의 부름를 받을 수 있어요."}, [37]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", desc="오그리마 훈련사에게서 바람의 부름을 받을 수 있고, 썬더 블러프에서는 같은 계열의 대체 안내 퀘스트 바람의 부름를 받을 수 있어요."}, [38]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="가시덩굴 우리의 마지막 보스가 메모를 떨어뜨려요. 알터랙 산맥에서 제출할 때까지 보관하세요. 라우 클리프러너(46.14, 51.71)에게서도 같은 퀘스트를 받을 수 있어요."}, [39]={hint="가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다.", tag="선택사항", desc="가시덩굴 우리의 마지막 보스가 메모를 떨어뜨려요. 알터랙 산맥에서 제출할 때까지 보관하세요."}, [40]={text="반짝이는 평원 퀘스트를 마치면 골짜기 바닥으로 왔던 길을 되돌아 프리윈드 초소로 가서 승강기로 비행 지점에 올라가고, 해바위 은거지로 날아가세요. 해바위 은거지에서 남서쪽으로 그을린 골짜기를 가로질러 잊혀진 땅으로 가세요."}}},
    ["05-d14"] = {name="가시덩굴 우리", entrance="불모의 땅 약 42.30, 89.90 (가시나무 길의 던전 입구 근처)", pickup="버섯구름 봉우리로 가는 길에 들를 수 있습니다. 불모의 땅 톱니항에서 청엽수 줄기을 먼저 받고 두더지 도구를 챙기세요. 힐스브래드 구릉지로 가는 길에 언더시티를 지나면서 파라넬에게 조분석을 나에게!를 받으세요. 던전에 들어가기 전에 썬더 블러프를 지난다면 올드에게 운명의 복수를 받으세요. 버섯구름 봉우리 높새바람 봉우리에서 출발하면 대형 승강기를 타고 불모의 땅으로 돌아가 서쪽 가시나무 길로 던전에 들어가세요.", pickupS={{"버섯구름 봉우리로 가는 길에 들를 수 있습니다"}, {"불모의 땅 톱니항에서 청엽수 줄기을 먼저 받고 두더지 도구를 챙기세요"}, {"힐스브래드 구릉지로 가는 길에 언더시티를 지나면서 파라넬에게 조분석을 나에게!를 받으세요"}, {"던전에 들어가기 전에 썬더 블러프를 지난다면 올드에게 운명의 복수를 받으세요"}, {"버섯구름 봉우리 높새바람 봉우리에서 출발하면 대형 승강기를 타고 불모의 땅으로 돌아가 서쪽 가시나무 길로 던전에 들어가세요"}}, tips={{k="動線", text="입구 가시나무 길을 따라 두더지로 청엽수 줄기를 찾습니다 → 곁길의 루구그 → 자그바 → 람타스크 → 박쥐 동굴에서 배설물 수집 → 차를가의 오두막에서 우두머리를 처치하고 심장과 퀘스트 아이템을 얻습니다 → 길을 정리한 뒤 마지막 우두머리 옆 천막으로 돌아가 윌릭스를 입구까지 호위합니다."}, {k="取捨", text="열정의 증거와 가시덩굴 구릉 후속 퀘스트를 열려면 마지막 우두머리와 앞쪽 홀의 박쥐를 모두 처치해야 합니다. 시간이 짧으면 길가의 두더지나 호위만 먼저 하세요."}, {k="說明", text="대형 승강기 서쪽이 가시덩굴 우리이고 동쪽이 가시덩굴 구릉입니다. 42.30, 89.90은 영원 버전 클라이언트의 입구 표시입니다. 큰길에서 서쪽 가시나무 터널을 따라 입구를 찾으세요.", s={{"대형 승강기 서쪽이 가시덩굴 우리이고 동쪽이 가시덩굴 구릉입니다"}, {"42.30, 89.90은 영원 버전 클라이언트의 입구 표시입니다"}, {"큰길에서 서쪽 가시나무 터널을 따라 입구를 찾으세요"}}}}, steps={[1]={npc="메보크 미지릭스", tgt="메보크 미지릭스", desc="톱니항에서 같은 NPC 옆에 있는 상자, 지휘봉, 안내 물건을 챙기세요. 던전에 들어갈 때 필요합니다."}, [2]={npc="아울드 스톤스파이어", tgt="아울드 스톤스파이어"}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="제출하면 붉은십자군 수도원 퀘스트 열정의 증거이 열립니다."}, [4]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항"}, [5]={hint="타우라조 야영지에 있는 루가 레이지토템에게 꿈틀거리는 더듬이 5개를 가져가야 합니다.", tag="선택사항"}, [6]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항"}, [7]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항", preText="거인의 들판에서의 시험"}, [8]={hint="불모의 땅에 있는 툰그림 파이어게이즈와 대화하십시오.", tag="선택사항"}, [9]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [10]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="연기 자욱한 철괴 15개, 청동 가루 10개, 철괴 10개를 먼저 준비하세요. 마지막 재료는 가시덩굴 우리에서 얻습니다.", preText="거인의 들판에서의 시험, 툰그림과의 대화"}, [11]={npc="시안 파이어워더", tgt="시안 파이어워더", tag="던전 선행"}, [12]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="던전 선행"}, [13]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="30레벨 토템 연계입니다. 직업에 따라 버섯구름 봉우리에서 퀘스트를 주는 NPC를 찾으세요. 같은 퀘스트를 라우 클리프러너(46.14, 51.71)에게서도 받을 수 있습니다."}, [14]={text="가시덩굴 우리 입구"}, [15]={hint="구멍 난 상자를 집어야 합니다.", desc="위치: 가시나무 길을 따라 덩이줄기를 캐세요. 윌릭스를 호위해 돌아오는 길에도 캘 수 있습니다.", spot="가시나무 길을 따라 덩이줄기를 캐세요. 윌릭스를 호위해 돌아오는 길에도 캘 수 있습니다."}, [16]={hint="툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", tag="선택사항", desc="위치: 입구 앞쪽에서 루구그가 있는 곁길로 들어가 먼저 그 옆의 잡몹을 정리하세요.", spot="입구 앞쪽에서 루구그가 있는 곁길로 들어가 먼저 그 옆의 잡몹을 정리하세요."}, [17]={npc="수입업자 윌릭스", tgt="수입업자 윌릭스", tag="게임 내 확인이 필요합니다", desc="호위 퀘스트는 던전 안의 NPC에게서 시작합니다."}, [18]={hint="수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.", desc="호위 퀘스트는 던전 안의 NPC에게서 시작합니다. 위치: 마지막 우두머리 옆 천막에서 출발해 윌릭스와 함께 입구로 돌아가세요. 순서: 17~20단계를 먼저 끝낸 뒤 호위를 시작하세요.", spot="마지막 우두머리 옆 천막에서 출발해 윌릭스와 함께 입구로 돌아가세요."}, [19]={npc="수입업자 윌릭스", tgt="수입업자 윌릭스", tag="게임 내 확인이 필요합니다", desc="호위 퀘스트는 던전 안의 NPC에게서 시작합니다.", spot="던전 입구, 호위가 끝나는 곳"}, [20]={hint="언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", desc="위치: 마지막 우두머리 앞 박쥐 동굴에서 동굴 박쥐를 처치하세요.", spot="마지막 우두머리 앞 박쥐 동굴에서 동굴 박쥐를 처치하세요."}, [21]={hint="썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다.", desc="위치: 박쥐 동굴을 나와 단상으로 올라가 끝의 오두막에서 차를가를 처치하세요.", spot="박쥐 동굴을 나와 단상으로 올라가 끝의 오두막에서 차를가를 처치하세요."}, [22]={hint="가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다.", tag="선택사항", desc="위치: 18단계와 함께 끝의 오두막에서 차를가를 처치하세요. 순서: 18단계와 함께 주우세요.", spot="18단계와 함께 끝의 오두막에서 차를가를 처치하세요."}, [23]={npc="작은 두루마리", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="서슬깃 차를가가 작은 두루마리를 떨어뜨립니다. 우클릭해 퀘스트를 받고 언더시티까지 남겨 두세요."}, [24]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [25]={npc="아울드 스톤스파이어", tgt="아울드 스톤스파이어"}, [26]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="언더시티에서 제출한 뒤 열정의 증거 을 받으세요."}, [27]={hint="작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다.", tag="선택사항"}, [28]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항"}, [29]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [30]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="알터랙 산맥의 알터랙에서 제출하세요. 로그에 높새바람 봉우리로 표시되면 안내에 따라 라우 클리프러너(46.14, 51.71)에게 제출하세요."}}},
    ["03-18"] = {name="잊혀진 땅", nameA="잊혀진 땅: {a:2408}", tips={{k="取捨", text="노상강도와 뼈 수집가를 함께 진행하세요. 비블리의 오두막으로 가는 길에 모닥불도 클릭하세요. 세 퀘스트는 모두 퀘스트 레벨 40이며 최소 30레벨이 필요합니다. 도망자는 무법항에서 제출하도록 남겨 두세요."}, {k="取捨", text="겔키스 라인 겔키스 동맹/보급품 훔치기은 남쪽 길에서 진행하세요. 마그람을 선택했거나 평판이 반대이면 이 두 단계와 잊혀진 땅 그늘수렵 마을의 겔키스 후속 퀘스트는 건너뛰세요."}, {k="取捨", text="그늘수렵 마을에서 서해안으로 갈 때 물 퀘스트 두 개와 고대의 책을 함께 하세요. 천둥도끼 요새에서는 빛의 홀과 이룩소스의 손을 먼저 하고, 진행도가 부족하면 두 번째 방문 때 제출하세요."}, {k="取捨", text="대상 행렬을 만나지 못했다면 그냥 가고, 제자리에서 호위를 기다리지 마세요. 가시덤불 골짜기의 사냥꾼 은 다음 정류장까지 보관하세요."}, {k="提醒", text="가시덤불 골짜기로 가기 전에 34레벨이 안 됐다면 코도 무덤 주변(약 56, 60~68)의 일반 켄타우로스나 서해안의 슬리더블레이드 나가(35.91, 28.84)를 잡으세요.", s={{"가시덤불 골짜기로 가기 전에 34레벨이 안 됐다면 코도 무덤 주변(약 56, 60~68)의 일반 켄타우로스나 서해안의 슬리더블레이드 나가(35.91, 28.84)를 잡으세요"}}}}, danger={[1]="서해안 나가는 수중 갑각 마크루라 가까이에 있습니다. 시전하는 몹을 먼저 모래사장으로 유인해 물속에서 두 무리가 함께 붙지 않게 하세요."}, grind={[1]={note="코도 무덤 동쪽 외곽에 일반 몹이 드물게 있습니다. 근처의 다른 부패한 새를 조심하세요. 묘지 퀘스트와 가까워 소량의 경험치를 채우기 좋습니다."}, [2]={mob="뱀갈퀴일족 나가", note="서해안 물가에 일반 몹이 밀집해 있습니다. 해안을 따라 혼자 있는 몹을 고르고 같은 구역의 무녀를 조심하세요. 서해안 퀘스트와 함께 정리할 수 있습니다."}, [3]={mob="뱀갈퀴일족 여마법사", note="서해안 나가 지역 남쪽 끝에 시전하는 일반 몹이 보통 밀도로 있습니다. 해안 쪽으로 유인해 싸워 수중 마크루라가 함께 붙지 않게 하세요."}}, supply={[1]={npc="탈론"}, [2]={npc="여관주인 시케와"}, [3]={npc="해윌라니"}, [4]={npc="여관주인 시케와"}, [5]={npc="투크"}}, steps={[1]={npc="펠굴 투커츠", tgt="펠굴 투커츠"}, [2]={npc="구르다 와일드메인", tgt="구르다 와일드메인"}, [3]={npc="구르다 와일드메인", tgt="구르다 와일드메인"}, [4]={npc="나타카 롱혼", tgt="나타카 롱혼"}, [5]={hint="절벽파수꾼 롱혼의 보고서를 잊혀진 땅의 침묵의 초소에 있는 나타카 롱혼에게 가져가야 합니다."}, [6]={npc="나타카 롱혼", tgt="나타카 롱혼"}, [7]={npc="스미드 스크래블스크류", tgt="스미드 스크래블스크류"}, [8]={hint="길들인 코도 5마리와 코도 유인기를 자신의 야영지에 있는 스미드 스크래블스크류에게 가져가야 합니다."}, [9]={npc="스미드 스크래블스크류", tgt="스미드 스크래블스크류"}, [10]={text="남쪽 길로 겔키스 마을을 지나 그늘수렵 마을에서 탈론 비행 지점(21.60, 74.13)을 열고 귀환석 위치를 설정하세요."}, [11]={npc="룬 와일드메인", tgt="룬 와일드메인"}, [12]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [13]={npc="마이라힐", tgt="마이라힐"}, [14]={npc="드룰제가르 스크락후크", tgt="드룰제가르 스크락후크"}, [15]={npc="아카라이", tgt="아카라이"}, [16]={text="해안 → 천둥도끼 요새 → 동쪽 사티로스"}, [17]={npc="랙모어의 기록", npcObj=true}, [18]={npc="아조레 알다모트", tgt="아조레 알다모트"}, [19]={npc="악마의 가죽", npcObj=true, tag="드랍될 때만 진행, 선택사항", desc="몹이 떨어뜨린 악마의 가죽을 우클릭해야 퀘스트 라인이 시작됩니다. 드랍되지 않으면 그냥 계속 가세요."}, [20]={hint="잊혀진 땅에 있는 마우린 본스플리터에게 악마의 가죽을 가져다주십시오.", tag="드랍될 때만 진행, 선택사항"}, [21]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="드랍될 때만 진행, 선택사항"}, [22]={hint="빛의 홀을 얻은 후 에텔 레소르의 탑에 있는 아조레 알다모트에게 돌아가야 합니다."}, [23]={hint="천둥도끼 요새에서 악마의 상자를 찾아서 그늘수렵 마을에 있는 타이가 와이즈메인에게 가져가십시오. 악마의 곡괭이도 함께 돌려줘야 합니다.", desc="천둥도끼 요새의 붉은 수정에 악마의 곡괭이를 사용하고, 나타난 악마의 영혼을 처치해 악마의 상자를 얻으세요."}, [24]={npc="아조레 알다모트", tgt="아조레 알다모트"}, [25]={npc="아조레 알다모트", tgt="아조레 알다모트"}, [26]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="선택사항"}, [27]={hint="잊혀진 땅의 살게론에서 여러 종류의 서릿발분노의 사티로스를 처치한 후, 그늘수렵 마을에 있는 아카라이에게 가야 합니다."}, [28]={hint="잊혀진 땅에 있는 마우린 본스플리터에게 그림자추적자 머릿가죽을 가져가야 합니다.", tag="선택사항"}, [29]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="선택사항"}, [30]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="선택사항"}, [31]={hint="칸 데즈헤파를 처치하고 그 증거로 그의 머리카락을 잊혀진 땅에 있는 펠굴 투커츠에게 가져가야 합니다."}, [32]={npc="펠굴 투커츠", tgt="펠굴 투커츠"}, [33]={npc="펠굴 투커츠", tgt="펠굴 투커츠"}, [34]={npc="비블리 푸츠버클", tgt="비블리 푸츠버클"}, [35]={hint="겔키스에게서 우호적인 평판을 얻은 다음 현자 우텍과 대화해야 합니다."}, [36]={npc="현자 우텍", tgt="현자 우텍"}, [37]={npc="현자 우텍", tgt="현자 우텍"}, [38]={hint="잊혀진 땅의 펠굴 투커츠에게 켄타우로스의 귀걸이 15개를 가져가야 합니다."}, [39]={hint="잊혀진 땅 전역의 켄타우로스를 처치해 조각한 켄타우로스 토템을 5개 입수한 후, 입수한 토템을 침묵의 초소에 있는 구르다 와일드메인에게 제출해야 합니다."}, [40]={hint="겔키스 마을에 있는 현자 우텍에게 말린 고기 6개를 가져가야 합니다."}, [41]={npc="펠굴 투커츠", tgt="펠굴 투커츠"}, [42]={npc="구르다 와일드메인", tgt="구르다 와일드메인"}, [43]={npc="현자 우텍", tgt="현자 우텍"}, [44]={npc="꺼진 모닥불", npcObj=true, desc="코도 무덤 북서쪽에서 꺼진 모닥불을 클릭해 받으세요. 30레벨이 필요합니다."}, [45]={hint="코르메크의 오두막에 있는 비블리 푸츠버클에게 코도 무덤에서 코도 뼈 10개를 가져가야 합니다."}, [46]={npc="비블리 푸츠버클", tgt="비블리 푸츠버클"}, [47]={hint="잊혀진 땅에서 약탈당한 야영지에 관해 아는 인물을 찾아야 합니다."}, [48]={npc="비블리 푸츠버클", tgt="비블리 푸츠버클"}, [49]={npc="비블리 푸츠버클", tgt="비블리 푸츠버클", desc="노상강도를 마친 자리에서 받고, 무법항 여관에서 제출하세요."}, [50]={text="서해안의 나가와 섬을 마친 뒤 그늘수렵 마을로 돌아가세요"}, [51]={hint="그늘수렵 마을에 있는 지나르질렌과 대화한 후 나타카 롱혼에게 붉은복어 2마리를 가져가야 합니다.", desc="그늘수렵 마을의 지나르질렌에게서 물고기 두 마리를 받으세요. 서해안 퀘스트와 함께 진행하세요."}, [52]={hint="연갑 조갯살 10개를 찾은 후, 그늘수렵 마을에 있는 마이라힐에게 가져가야 합니다."}, [53]={hint="뱀갈퀴일족 미르미돈 7마리, 뱀갈퀴일족 나가 7마리, 뱀갈퀴일족 여마법사 5마리를 처치한 후, 잊혀진 땅의 그늘수렵 마을에 있는 드룰제가르와 대화해야 합니다."}, [54]={hint="고대의 책을 손에 넣은 다음 에텔 레소르의 탑에 있는 아조레 알다모트에게 가져가야 합니다."}, [55]={hint="잊혀진 땅에 있는 마우린 본스플리터에게 예언의 수정구를 가져가야 합니다.", tag="선택사항"}, [56]={hint="랙모어의 은열쇠와 랙모어의 황금열쇠를 찾아 랙모어의 궤짝을 열어야 합니다.", desc="은 열쇠와 금 열쇠는 각각 마크루라와 나가가 드랍합니다. 둘 다 얻은 뒤 헤엄쳐 작은 섬의 상자를 여세요."}, [57]={npc="랙모어의 궤짝", npcObj=true}, [58]={npc="아조레 알다모트", tgt="아조레 알다모트"}, [59]={npc="나타카 롱혼", tgt="나타카 롱혼"}, [60]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="선택사항"}, [61]={npc="마우린 본스플리터", tgt="마우린 본스플리터", tag="선택사항"}, [62]={hint="잊혀진 땅에 있는 타카타 스틸블레이드와 대화하십시오.", tag="선택사항"}, [63]={npc="타카타 스틸블레이드", tgt="타카타 스틸블레이드", tag="선택사항"}, [64]={text="귀환석으로 그늘수렵 마을에 돌아가세요."}, [65]={npc="마이라힐", tgt="마이라힐"}, [66]={npc="드룰제가르 스크락후크", tgt="드룰제가르 스크락후크"}, [67]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [68]={npc="아카라이", tgt="아카라이"}, [69]={npc="제브로스트", tgt="제브로스트", tag="선택사항", desc="오그리마 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [70]={hint="불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", tag="선택사항", desc="오그리마 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [71]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="오그리마 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [72]={npc="카알 소울리퍼", tgt="카알 소울리퍼", tag="선택사항", desc="언더시티 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [73]={hint="불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", tag="선택사항", desc="언더시티 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [74]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="언더시티 시작 퀘스트. 이 퀘스트나 오라힐 보주의 지혜 중 하나를 고르거나 곧장 톱니항으로 가세요."}, [75]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="수락한 뒤 탑 안의 시종 둘 중 한 명을 골라 보상 분기를 선택하세요."}, [76]={npc="수행사제 위툴라", tgt="수행사제 위툴라", tag="선택사항", desc="두 지선 중 하나만 고르세요. 루비로 마나먹는 지옥사냥개나 마법사 사냥개의 영혼을 포획해 메나라에게 전달하세요."}, [77]={hint="지옥의 루비를 가지고 가서 잊혀진 땅에 서식하는 지옥사냥개 중 한 마리에게 사용해야 합니다. 성공하면 지옥의 루비와 사로잡은 지옥사냥개의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", tag="선택사항", desc="두 지선 중 하나만 고르세요. 루비로 마나먹는 지옥사냥개나 마법사 사냥개의 영혼을 포획해 메나라에게 전달하세요."}, [78]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="두 지선 중 하나만 고르세요. 루비로 마나먹는 지옥사냥개나 마법사 사냥개의 영혼을 포획해 메나라에게 전달하세요."}, [79]={npc="수행사제 마가즈", tgt="수행사제 마가즈", tag="선택사항", desc="두 지선 중 하나만 고르세요. 에메랄드로 하급 지옥불정령의 영혼을 포획해 메나라에게 전달하세요."}, [80]={hint="지옥불 에메랄드를 가지고 가서 잊혀진 땅의 지옥불정령 중 하나에게 사용해 영혼을 사로 잡아야 합니다. 성공하면 지옥불 에메랄드와 사로잡은 지옥불정령의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", tag="선택사항", desc="두 지선 중 하나만 고르세요. 에메랄드로 하급 지옥불정령의 영혼을 포획해 메나라에게 전달하세요."}, [81]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="두 지선 중 하나만 고르세요. 에메랄드로 하급 지옥불정령의 영혼을 포획해 메나라에게 전달하세요."}, [82]={hint="톱니항이 내려다보이는 탑 안에 살고 있는 미네라의 조수들과 대화하고 그들이 제시하는 길 중 하나를 따라가야 합니다.", tag="선택사항"}, [83]={npc="타베사", tgt="타베사", tag="선택사항"}, [84]={npc="타베사", tgt="타베사", tag="선택사항"}, [85]={hint="보주의 악마를 물리치고 타베사와 대화하십시오.", tag="선택사항"}, [86]={npc="타베사", tgt="타베사", tag="선택사항"}, [87]={npc="타베사", tgt="타베사", tag="선택사항"}, [88]={hint="정화된 지옥의 보주를 불모의 땅의 미네라에게 가져가야 합니다.", tag="선택사항"}, [89]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항"}, [90]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [91]={hint="미네라 보이드렌더가 다르오라힐의 보주를 완성시킬 때까지 기다렸다가 그녀에게 말을 걸어야 합니다.", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [92]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [93]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [94]={hint="미네라 보이드렌더가 노오라힐의 보주를 완성하길 기다렸다가 그녀에게 말을 걸어야 합니다.", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [95]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="선택한 지선에 실제로 나타나는 마지막 단계만 수행하세요. 애드온이 완성된 다르오라힐의 보주나 완성된 노오라힐의 보주를 표시하지 않으면 정화의 보주 가져가기을 제출한 뒤 바로 메나라를 확인하세요."}, [96]={text="그늘수렵 마을에서 오그리마로 날아가 도시를 나와 듀로타 비행선 탑(50.80, 13.60)에서 가시덤불 골짜기 그롬골행 비행선을 타세요."}}},
    ["03-19"] = {name="가시덤불 골짜기", tips={{k="取捨", text="무법항에 처음 가면 도망자를 제출하고, 술을 사서 술과 정보를 완료하세요. 이후 아라시 고원 남동쪽 외딴 섬에 가서 이어지는 후속 퀘스트를 받으세요."}, {k="取捨", text="줄쿤다에서 기믹스를 찾았을 때만 열쇠와 호위를 진행하세요. 열쇠와 도난당한 화물은 같은 구역에 있습니다. 이미 다른 사람이 호위 중이라면 그대로 주요 경로를 이어가세요. [대만 서버 퀘스트 기록](https://wowamobi.com/quests/열쇠는 어디에?)"}, {k="取捨", text="무법항에 처음 방문하면 비행 지점을 열고 퀘스트를 받으세요. 35레벨 즈음에는 첫 묶음만 제출하세요: 붉은머리부족의 귀, 야영지 조사, 민물 악어 가죽, 노래하는 수정 조각, 적대적 탈취, 그리고 이미 완료한 돈 될 만한 물건/지믹스의 대탈출. 민물 악어 가죽와 노래하는 수정 조각를 제출해야 무쇠턱 악어 가죽과 투자개발회사 채광이 열립니다."}, {k="取捨", text="투자개발회사 채광과 덩치큰 바다악어 가죽은 아직 제출하지 말고, 가시덤불 골짜기 무법항에서 남쪽 골짜기 퀘스트와 함께 돌아와 제출하도록 남겨 두세요. 무쇠턱 악어 가죽을 완료하면 무법항에서 먼저 제출한 뒤 을 받으세요."}, {k="取捨", text="42레벨에 돌아올 때 블러드세일 붉은해적단 → 붉은해적단 → 붉은해적단 → 붉은해적단 → 붉은해적단을 진행하고, 잃어버린 눈/코담배를 찾아서, 잔질의 비법, 겁쟁이 → 맥킨리에게 돌아가기 → 빚 돌려받기와 함께 묶으세요. 가시덤불 골짜기의 열병/가시덤불 골짜기의 열병 열병, 쪽지가 든 병 → 쪽지가 든 병 병 속의 편지, 선장의 상자, 위스키 슬림의 잃어버린 술병 술, 선물로 받은 OOX OOX는 아직 배치하지 마세요. 가시덤불 골짜기 무법항의 45레벨 이후 목록을 참고하세요. 영상의 나눠 제출하는 원칙은 유지하며, 구체적인 ID는 경로 설정입니다."}, {k="取捨", text="먼저 랩터 사냥법 익히기를 까지 진행한 뒤 그롬골 방어과 함께 채찍꼬리 랩터를 처치하세요. 노래하는 수정 조각는 북쪽의 수정가시 바실리스크를 먼저 잡으세요. 첫 방문에서는 남쪽 골짜기로 돌아갈 필요가 없습니다."}, {k="取捨", text="34레벨에 처음 시작한다면 사냥 퀘스트 라인 3개의 앞 두 차례와 그롬골 및 블러드스칼프 트롤 퀘스트를 먼저 하세요. 그림자아귀 표범은 퓨마 사냥법 익히기/모크타르딘의 마법을 함께 진행하고, 일반 신달 호랑이 사냥법 익히기도 같은 루프에서 처리하세요. 네즐뤼크와의 대화의 전리품 3개는 가시덤불 골짜기 무법항에서 부서진 뼈목걸이와 함께 하도록 남겨 두세요. 가시덤불 골짜기 푸른 언덕(가시덤불 골짜기의 푸른 언덕~제 4 장)에 흩어진 페이지가 있으면 제출하세요."}, {k="提醒", text="35레벨에 가라앉은 도시(The Drowned City, 35~40)를 파티로 갈 수 있습니다. 파티와 관련 퀘스트를 먼저 확인하고, 그롬골 서쪽 해저에서 입장하세요.", s={{"35레벨에 가라앉은 도시(The Drowned City, 35~40)를 파티로 갈 수 있습니다"}, {"파티와 관련 퀘스트를 먼저 확인하고, 그롬골 서쪽 해저에서 입장하세요"}}}, {k="提醒", text="34~35레벨에는 먼저 북쪽 골짜기에서 블러드스칼프 트롤(29.76, 21.62)을 잡고, 36레벨 이후에는 그롬골 남동쪽 오우거 야영지(35.55, 30.92)로 옮겨 37레벨까지 부족한 만큼 채운 뒤 비행선을 타세요. 야영지에서 완료한 퀘스트는 먼저 제출하세요.", s={{"34~35레벨에는 먼저 북쪽 골짜기에서 블러드스칼프 트롤(29.76, 21.62)을 잡고, 36레벨 이후에는 그롬골 남동쪽 오우거 야영지(35.55, 30.92)로 옮겨 37레벨까지 부족한 만큼 채운 뒤 비행선을 타세요"}, {"야영지에서 완료한 퀘스트는 먼저 제출하세요"}}}}, danger={[1]="썩은내 산호초 유적에는 엘리트 소금비늘 멀록이 있습니다. 해수면 아래로 잠수해 외벽을 따라 석판을 찾고, 돌아올 숨이 남도록 하세요.", [2]="줄쿤다 폐허에서 기믹스의 호위가 순찰 경로를 지나갑니다. 호위를 받기 전에 야영지 바깥쪽을 먼저 정리하세요."}, grind={[1]={mob="붉은머리부족 전사", note="북쪽 골짜기 블러드스칼프 유적에 일반 몹이 보통 밀도로 있습니다. 외벽을 따라 혼자 있는 몹을 한 마리씩 유인하고 근처의 블러드스칼프 주술사를 조심하세요. 34레벨 경험치를 채우기 좋습니다. 같은 길에서 소용돌이 무기 퀘스트용 블러드스칼프 엄니를 모을 수 있습니다. 전사 전용."}, [2]={mob="채찍꼬리랩터", note="그롬골 북쪽 숲에 일반 몹이 밀집해 있습니다. 길을 따라 혼자 있는 몹을 고르고, 물에 들어가면 나오는 엘리트 소금비늘 멀록은 피하세요. 랩터 사냥 퀘스트와 함께 진행할 수 있습니다."}, [3]={mob="모쉬오그일족 투사", note="그롬골 남동쪽 오우거 야영지 외곽에 일반 몹이 보통 밀도로 있습니다. 주술사와 희귀 몹 로로크를 피하세요. 36레벨 이후 가까운 곳에서 37레벨까지 채울 수 있습니다."}}, supply={[1]={npc="시스타"}, [2]={npc="여관주인 툴벡"}, [3]={npc="크래크"}, [4]={npc="나르가트"}, [5]={npc="우톡"}, [6]={npc="그링거"}, [7]={npc="여관주인 스킨들"}, [8]={npc="주타크"}, [9]={npc="닉스락스 필라머그"}, [10]={npc="하렌 칸메"}}, steps={[1]={text="오그리마 성 밖 비행선 탑에서 그롬골행 비행선을 타고, 도착하면 시스타 비행 지점(32.54, 29.35)을 여세요. 이미 가시덤불 골짜기에 있다면 바로 야영지로 가세요."}, [2]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬"}, [3]={npc="님보야", tgt="님보야", tag="밀집된 몹, 선택사항"}, [4]={npc="킨윌레이", tgt="킨윌레이", tag="밀집된 몹, 선택사항"}, [5]={npc="예언자 모크타르딘", tgt="예언자 모크타르딘"}, [6]={npc="님보야", tgt="님보야"}, [7]={npc="킨윌레이", tgt="킨윌레이"}, [8]={npc="식충 잡초", tgt="젬밀", desc="크랭크 피즐버브(27.12, 77.21)에게서도 같은 퀘스트를 받을 수 있습니다."}, [9]={hint="그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.", desc="석판은 수중 유적 외벽에 있습니다. 바깥쪽에서 헤엄쳐 가서, 순찰하는 엘리트 멀록을 피하세요."}, [10]={npc="킨윌레이", tgt="킨윌레이"}, [11]={npc="킨윌레이", tgt="킨윌레이", desc="이것을 먼저 제출해야 물속의 적을 받을 수 있습니다."}, [12]={text="무법항 비행 지점을 이미 열었다면 그롬골에서 날아가세요. 처음이라면 가시덤불 골짜기 남쪽 대로를 따라 무법항에 가서 그링거 비행 지점(26.87, 77.10)을 여세요. 첫 번째 퀘스트 묶음을 받은 뒤 그롬골로 돌아가세요."}, [13]={npc="케복", tgt="케복", tag="밀집된 몹, 선택사항"}, [14]={npc="크라젝", tgt="크라젝"}, [15]={npc="크라젝", tgt="크라젝"}, [16]={npc="크라젝", tgt="크라젝"}, [17]={npc="드리즐릭", tgt="드리즐릭"}, [18]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [19]={hint="잊혀진 땅 약탈자를 찾아야 합니다."}, [20]={npc="토칼", tgt="토칼"}, [21]={npc="토칼", tgt="토칼"}, [22]={hint="무법항에 있는 토칼에게 체리 그로그주를 가져간 후 이야기를 마저 들어야 합니다.", desc="사서 그대로 제출하세요. 마시지 마세요."}, [23]={npc="토칼", tgt="토칼", desc="제출한 뒤 도둑의 명예 따윈 없다를 받으세요. 아라시 고원 남동쪽 해안에 갈 때 