    ["05-d16"] = {name="The Drowned City", entrance="가시덤불 골짜기 21.50, 27.70", pickup="가시덤불 골짜기 첫 방문은 주 경로에 포함되어 있습니다. 그롬골에서 를 받아 썩은내 산호초를 먼저 하고 제출한 뒤 구루바시의 옛 전설을 받으세요. 무법항에서 크라젝에게 수상쩍은 소금선견자와 소금선견자 대장을 받고, 줄쿤다에서 구루바시의 옛 전설 탁본을 하세요. 그롬골로 돌아가 잃어버린 도시를 찾아과 물속의 적을 받아 서쪽 해안에서 함께 끝내고, 제출한 뒤 가라앉은 도시와 착한 소금비늘은 죽은 소금비늘뿐...을 받으세요. 썬더 블러프 비행 지점을 열었다면 던전에 들어가기 전에 썬더 블러프로 날아가 멀고어 길을 따라 하늘감시 고원에서 마주콘을 찾으세요. 모두 받은 뒤 그롬골로 돌아가 서쪽 해안에서 물속으로 헤엄쳐 수중 차원문으로 가세요.", pickupS={{"가시덤불 골짜기 첫 방문은 주 경로에 포함되어 있습니다"}, {"그롬골에서 를 받아 썩은내 산호초를 먼저 하고 제출한 뒤 구루바시의 옛 전설을 받으세요"}, {"무법항에서 크라젝에게 수상쩍은 소금선견자와 소금선견자 대장을 받고, 줄쿤다에서 구루바시의 옛 전설 탁본을 하세요"}, {"그롬골로 돌아가 잃어버린 도시를 찾아과 물속의 적을 받아 서쪽 해안에서 함께 끝내고, 제출한 뒤 가라앉은 도시와 착한 소금비늘은 죽은 소금비늘뿐...을 받으세요"}, {"썬더 블러프 비행 지점을 열었다면 던전에 들어가기 전에 썬더 블러프로 날아가 멀고어 길을 따라 하늘감시 고원에서 마주콘을 찾으세요"}, {"모두 받은 뒤 그롬골로 돌아가 서쪽 해안에서 물속으로 헤엄쳐 수중 차원문으로 가세요"}}, tips={{k="動線", text="줄알라이 → 바르타카 → 선장 드레드라이즈 → 불멸의 골수 → 신성한 뱀 민로스. 가는 길에 입구 웅덩이 왼쪽, 바르타카 왼쪽, 배 구역의 해골 입, 민로스 뒤에서 석판을 탁본하세요. 배 구역에서는 해적을 정리하면서 유물도 모으세요. 태초의 정령과 길은 선택입니다."}, {k="取捨", text="그롬골의 선행 퀘스트 두 개를 먼저 하세요. 헤엄쳐 가서 배 구역만 해결하고 돌아오는 일을 피할 수 있습니다. 멀고어의 제출 한 건이 너무 멀면 건너뛰어도 됩니다."}, {k="說明", text="입구는 그롬골 서쪽 물속 동굴에 있습니다. 수중 호흡 물약을 챙기거나 기술이 있는 파티원에게 부탁하세요.", s={{"입구는 그롬골 서쪽 물속 동굴에 있습니다"}, {"수중 호흡 물약을 챙기거나 기술이 있는 파티원에게 부탁하세요"}}}}, steps={[1]={npc="킨윌레이", tgt="킨윌레이", desc="이미 가시덤불 골짜기 그롬골과 무법항에서 했다면 건너뛰세요."}, [2]={hint="그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.", desc="이미 가시덤불 골짜기 그롬골과 무법항에서 했다면 건너뛰세요."}, [3]={npc="킨윌레이", tgt="킨윌레이", desc="이미 가시덤불 골짜기 그롬골과 무법항에서 했다면 건너뛰세요."}, [4]={npc="킨윌레이", tgt="킨윌레이", preText="썩은내 산호초"}, [5]={hint="가죽과 목탄을 사용해 트롤의 전설 3부 서판의 탁본을 만들어야 합니다."}, [6]={npc="킨윌레이", tgt="킨윌레이"}, [7]={npc="킨윌레이", tgt="킨윌레이", preText="구루바시의 옛 전설"}, [8]={hint="썩은내 산호초를 살펴 동굴 입구를 찾아야 합니다."}, [9]={npc="킨윌레이", tgt="킨윌레이"}, [10]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", desc="가시덤불 골짜기 그롬골과 무법항에서 이미 하는 단계입니다. 썩은내 산호초를 먼저 제출한 뒤 지휘관에게 확인하세요. 퀘스트가 이미 나타났다면 킨윌레이를 오가는 길에 함께 하세요.", preText="썩은내 산호초, 구루바시의 옛 전설"}, [11]={hint="소금비늘 척후병에게서 소금비늘 삼지창 10개를 입수해야 합니다.", tag="대상: 소금비늘 척후병", desc="가시덤불 골짜기 그롬골과 무법항에서 이미 하는 단계입니다. 썩은내 산호초를 먼저 제출한 뒤 지휘관에게 확인하세요. 퀘스트가 이미 나타났다면 킨윌레이를 오가는 길에 함께 하세요."}, [12]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", desc="가시덤불 골짜기 그롬골과 무법항에서 이미 하는 단계입니다. 썩은내 산호초를 먼저 제출한 뒤 지휘관에게 확인하세요. 퀘스트가 이미 나타났다면 킨윌레이를 오가는 길에 함께 하세요."}, [13]={npc="킨윌레이", tgt="킨윌레이", preText="잃어버린 도시를 찾아"}, [14]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", preText="물속의 적, 잃어버린 도시를 찾아"}, [15]={npc="크라젝", tgt="크라젝"}, [16]={npc="크라젝", tgt="크라젝"}, [17]={npc="마주콘", tgt="마주콘", tag="선택사항", desc="마주콘은 멀고어 하늘감시 고원에 있습니다. 그곳 이동 지점을 이미 열었을 때만 돌아가세요."}, [18]={text="The Drowned City 입구"}, [19]={hint="가죽과 목탄을 사용해 가라앉은 도시에서 발견된 서판의 탁본을 만들어야 합니다.", desc="위치: 웅덩이 왼쪽 → 바르타카 왼쪽 → 선장 옆 해골 입 → 마지막 우두머리 뒤. 순서: 네 곳의 지표를 따라 가면서 탁본하세요.", spot="웅덩이 왼쪽 → 바르타카 왼쪽 → 선장 옆 해골 입 → 마지막 우두머리 뒤"}, [20]={hint="가라앉은 도시에서 바르타카를 처치해야 합니다.", desc="우두머리 옆의 사제를 먼저 처치하세요. 수중 호흡에 주의하세요. 위치: 줄알라이를 지나 수중 기록 보관소로 들어가 두 사제 옆의 우두머리를 찾으세요.", spot="줄알라이를 지나 수중 기록 보관소로 들어가 두 사제 옆의 우두머리를 찾으세요."}, [21]={hint="가라앉은 도시의 소금선견자 해적에게서 부두가 깃든 유물 10개를 수집해야 합니다.", desc="모자라면 배 구역의 해적을 계속 처치하세요. 위치: 솔트시어 해적선 구역에 들어가 길을 따라 해적을 정리하고 유물을 모으세요. 순서: 21단계와 같은 구역에서 정리하세요.", spot="솔트시어 해적선 구역에 들어가 길을 따라 해적을 정리하고 유물을 모으세요."}, [22]={hint="가라앉은 도시에서 소금선견자 검시관 3명과 대장 드레드라이즈를 처치해야 합니다.", desc="위치: 배 구역으로 가서 선장 근처 통로를 따라 검시관을 정리하세요. 순서: 선장을 처치한 뒤 빛나는 진주와 상호작용하세요.", spot="배 구역으로 가서 선장 근처 통로를 따라 검시관을 정리하세요."}, [23]={hint="가라앉은 도시에서 고대 구루바시 우상을 회수해야 합니다.", tag="선택사항", desc="위치: 선장과 진주 장벽을 지나 안쪽으로 들어가 불멸의 골수를 처치하세요.", spot="선장과 진주 장벽을 지나 안쪽으로 들어가 불멸의 골수를 처치하세요."}, [24]={npc="킨윌레이", tgt="킨윌레이"}, [25]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬"}, [26]={npc="크라젝", tgt="크라젝"}, [27]={npc="크라젝", tgt="크라젝"}, [28]={npc="마주콘", tgt="마주콘", tag="선택사항"}, [29]={npc="킨윌레이", tgt="킨윌레이", tag="선택사항", desc="오그리마로 돌아갈 일이 있다면 그때 함께 제출하세요. 이번 던전 진행에는 영향이 없습니다.", preText="가라앉은 도시"}, [30]={hint="서판 탁본을 듀로타 센진 마을에 있는 장로 가드린에게 가져가야 합니다.", tag="선택사항", desc="오그리마로 돌아갈 일이 있다면 그때 함께 제출하세요. 이번 던전 진행에는 영향이 없습니다."}, [31]={npc="장로 가드린", tgt="장로 가드린", tag="선택사항", desc="오그리마로 돌아갈 일이 있다면 그때 함께 제출하세요. 이번 던전 진행에는 영향이 없습니다."}}},
    ["05-d15"] = {name="놈리건", entrance="가시덤불 골짜기 27.60, 77.48", pickup="가시덤불 골짜기 무법항으로 가기 전에 오그리마 명예의 골짜기에서 소빅과 노그를 먼저 찾으세요. 톱니항에서 배를 타고 무법항으로 가거나, 그롬골에서 무법항으로 비행하세요. 스쿠티와 선임기술자 스쿠티 → 놈리거어어어언!을 마친 뒤 고블린 중계기를 지닌 채 입장하세요.", pickupS={{"가시덤불 골짜기 무법항으로 가기 전에 오그리마 명예의 골짜기에서 소빅과 노그를 먼저 찾으세요"}, {"톱니항에서 배를 타고 무법항으로 가거나, 그롬골에서 무법항으로 비행하세요"}, {"스쿠티와 선임기술자 스쿠티 → 놈리거어어어언!을 마친 뒤 고블린 중계기를 지닌 채 입장하세요"}}, tips={{k="動線", text="입장 후 왼쪽 비탈을 내려가 청정 구역으로 갑니다 → 오른쪽 숙소에서 케르노비를 호위합니다 → 전기 충격기 → 대량 타격기 → 텔마플러그를 처치하고 암호를 얻어 금고를 엽니다. 꼬질꼬질한 반지가 나왔다면 청정 구역으로 돌아가 삐까뻔쩍세척기를 사용하세요."}, {k="取捨", text="장비나 퀘스트 경험치가 아쉬울 때 돌고, 무법항 퀘스트와 함께 제출하면 가장 효율적입니다."}, {k="說明", text="던 모로의 시설로 순간이동한 뒤 지하 통로를 따라 던전 입구로 가세요. 아이언포지는 거치지 않습니다. 스쿠티 퀘스트를 끝내지 않았다면 순간이동 연계를 먼저 완료하세요.", s={{"던 모로의 시설로 순간이동한 뒤 지하 통로를 따라 던전 입구로 가세요"}, {"아이언포지는 거치지 않습니다"}, {"스쿠티 퀘스트를 끝내지 않았다면 순간이동 연계를 먼저 완료하세요"}}}}, steps={[1]={npc="노그", tgt="노그"}, [2]={npc="소빅", tgt="소빅", preText="기술 전쟁"}, [3]={hint="무법항에 있는 스쿠티와 대화하십시오."}, [4]={npc="스쿠티", tgt="스쿠티"}, [5]={npc="스쿠티", tgt="스쿠티", preText="선임기술자 스쿠티"}, [6]={hint="스쿠티가 고블린 응답장치를 조절하는 동안 기다려야 합니다."}, [7]={npc="스쿠티", tgt="스쿠티"}, [8]={text="놈리건 입구"}, [9]={hint="놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", desc="전투 중에 한 사람이 엄폐물 옆 버튼을 눌러 폭탄을 제어하세요. 위치: 작업장 안쪽 통로를 따라 마지막 우두머리의 원형 방으로 가세요. 우두머리를 처치한 뒤 상자를 여세요.", spot="작업장 안쪽 통로를 따라 마지막 우두머리의 원형 방으로 가세요. 우두머리를 처치한 뒤 상자를 여세요."}, [10]={npc="케르노비", tgt="케르노비", tag="게임 내 확인이 필요합니다", desc="청정 구역 근처에서 케르노비를 찾으세요. 호위 경로를 먼저 정리하세요."}, [11]={hint="태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", desc="위치: 청정 구역 옆 숙소에서 케르노비를 만나 태엽 오솔길을 따라 정문으로 돌아가세요. 순서: 마지막 우두머리로 깊이 들어가기 전에 9~10단계를 먼저 할 수 있습니다.", spot="청정 구역 옆 숙소에서 케르노비를 만나 태엽 오솔길을 따라 정문으로 돌아가세요."}, [12]={npc="꼬질꼬질한 반지", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="은화 3개를 챙기고 기계의 대화에 따라 조작하세요."}, [13]={hint="꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", tag="선택사항", desc="은화 3개를 챙기고 기계의 대화에 따라 조작하세요. 위치: 입장하면 왼쪽 비탈을 내려가 청정 구역 벽가에서 세척기를 찾으세요. 순서: 먼저 검은무쇠단 첩보원에게서 반지를 얻으세요.", spot="입장하면 왼쪽 비탈을 내려가 청정 구역 벽가에서 세척기를 찾으세요."}, [14]={npc="삐까뻔쩍세척기 5200", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="은화 3개를 챙기고 기계의 대화에 따라 조작하세요.", spot="입구 왼쪽 경사 아래, 세척 구역 벽의 삐까뻔쩍세척기"}, [15]={npc="삐까뻔쩍세척기 5200", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", preText="꼬질꼬질한 반지"}, [16]={npc="스쿠티", tgt="스쿠티"}, [17]={npc="노그", tgt="노그"}, [18]={hint="반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", tag="선택사항"}, [19]={npc="노그", tgt="노그", tag="선택사항"}}},
    ["03-20"] = {name="먼지진흙 슾지대", nameA="먼지진흙 슾지대: {a:496}", tips={{k="取捨", text="검은 방패, 수상한 발굽 자국, 리테 대위(부관 파발 리테) 퀘스트는 같은 불탄 여관에 있습니다. 마을에 들어가기 전에 모두 받으세요."}, {k="取捨", text="마을을 떠나기 전에 독특한 양념 3개를 챙기세요. 달의 강철 브로드소드가 이미 있으면 제출하고, 일부러 사거나 제작하면 돌아가는 길이 늘어납니다. 말썽꾼의 탈출은 톱니항에서 제출하며, 그때 지나지 않으면 보관하거나 건너뛰세요."}, {k="提醒", text="브래큰월 마을과 잊혀진 땅 그늘수렵 마을은 37→38 경험치 구간을 함께 맡습니다. 잊혀진 땅 재방문 퀘스트를 이미 제출했다면 먼지진흙 습지 북쪽에서 일반 거미와 랩터를 잡고, 북쪽 늪지 퀘스트 몹 위치에서 38레벨까지 채우세요.", s={{"브래큰월 마을과 잊혀진 땅 그늘수렵 마을은 37→38 경험치 구간을 함께 맡습니다"}, {"잊혀진 땅 재방문 퀘스트를 이미 제출했다면 먼지진흙 습지 북쪽에서 일반 거미와 랩터를 잡고, 북쪽 늪지 퀘스트 몹 위치에서 38레벨까지 채우세요"}}}}, danger={[1]="북쪽 늪지에서는 독거미와 랩터의 순찰 경로가 겹칩니다. 바깥쪽에서 한 마리씩 유인하고, 수풀 속 순찰이 만나는 지점은 피하세요."}, grind={[1]={mob="시든덩굴 수렁괴물", note="북쪽 늪지 시든덩굴 지역에 일반 몹이 밀집해 있고 다른 시든덩굴 몹과 섞여 있습니다. 육지를 따라 한 마리씩 정리하며 떠날 기준 레벨에 맞추세요."}, [2]={mob="검은송곳니 독거미", note="북쪽 늪지 동쪽에 일반 몹이 보통 밀도로 있습니다. 독 피해와 랩터 순찰을 조심하세요. 시든덩굴 지역을 다른 사람이 정리 중이면 자리를 옮기세요."}, [3]={mob="긴송곳니 붉은늪지랩터", note="북쪽 늪지 숲 가장자리에 일반 몹이 밀집해 있습니다. 옆에 악어와 다른 랩터가 있으니 물가를 따라 혼자 있는 몹을 골라 잡고, 38레벨이 되면 떠나세요."}}, supply={[1]={npc="샤르디"}, [2]={npc="크라크"}, [3]={npc="오그마르"}, [4]={npc="자나라"}, [5]={npc="발라이 로크웨인"}}, steps={[1]={npc="코란", tgt="코란", tag="선택사항"}, [2]={text="타우라조 야영지에서 동쪽 먼지진흙 습지로 가서, 먼저 길가의 불탄 여관에 들르세요 (29.70, 48.20)."}, [3]={npc="검은 방패", npcObj=true}, [4]={npc="발굽 자국", npcObj=true}, [5]={npc="테라모어 경비병 휘장", npcObj=true}, [6]={nodeA="{a:496}", desc="샤르디에게서 비행 지점을 여세요."}, [7]={text="이전에 잊혀진 땅 그늘수렵 마을에 설정해 둔 귀환석은 다음 구간에서 돌아올 때를 위해 그대로 두세요."}, [8]={hint="담쟁이 마을에 있는 크로그에게 타락의 철제 방패를 가져가야 합니다."}, [9]={hint="담쟁이 마을에 있는 크로그에게 그늘 쉼터 여관의 수상한 흔적에 대해 보고해야 합니다."}, [10]={hint="담쟁이 마을에 있는 크로그에게 리테의 배지를 가져가야 합니다."}, [11]={npc="크로그", tgt="크로그"}, [12]={npc="크로그", tgt="크로그"}, [13]={npc="크로그", tgt="크로그"}, [14]={npc="크로그", tgt="크로그"}, [15]={hint="담쟁이 마을에 있는 도골에게 타락의 철제 방패를 보여 주십시오."}, [16]={npc="도골", tgt="도골"}, [17]={npc="도골", tgt="도골"}, [18]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [19]={npc="머드크러쉬 더트피트", tgt="머드크러쉬 더트피트"}, [20]={npc="오그론", tgt="오그론"}, [21]={hint="오그론과 함께 가서 리테를 심문한 다음 담쟁이 마을에 있는 크로그에게 돌아가야 합니다."}, [22]={npc="크로그", tgt="크로그"}, [23]={hint="테라모어 첩보원 9명을 처치한 다음 담쟁이 마을에 있는 나지르 블러드파이크에게 돌아가야 합니다."}, [24]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [25]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [26]={text="북쪽 도로 호위 → 늪지기 오두막 → 해안"}, [27]={npc="말썽꾼 이그나츠", tgt="말썽꾼 이그나츠", tag="톱니항을 지날 때만 제출, 선택사항"}, [28]={hint="\"말썽꾼\" 이그나츠를 호위한 다음 톱니항에 있는 메보크 미지릭스와 대화해야 합니다.", tag="선택사항"}, [29]={npc="늪지눈알 자를", tgt="늪지눈알 자를"}, [30]={hint="먼지진흙 습지대에 있는 \"늪지눈알\" 자를에게 독특한 양념 3개를 가져가야 합니다."}, [31]={npc="늪지눈알 자를", tgt="늪지눈알 자를"}, [32]={npc="늪지눈알 자를", tgt="늪지눈알 자를"}, [33]={npc="푸석푸석한 흙더미", npcObj=true}, [34]={hint="늪지기 오두막에 있는 \"늪지눈알\" 자를에게 터지지 않은 암흑안개거미의 눈 40개를 가져가야 합니다."}, [35]={hint="담쟁이 마을에 있는 나지르 블러드파이크에게 밀정의 보고서를 가져가야 합니다."}, [36]={hint="담쟁이 마을에 있는 도골을 위해 산성 독주머니 6개를 구해야 합니다."}, [37]={hint="담쟁이 마을에 있는 나지르 블러드파이크에게 선장의 서류를 가져가야 합니다."}, [38]={hint="먼지진흙 습지대 북쪽에 있는 머드크러쉬 더트피트가 진흙아가미 멀록의 머리 12개를 가져다 달라고 부탁했습니다."}, [39]={npc="늪지눈알 자를", tgt="늪지눈알 자를"}, [40]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [41]={npc="도골", tgt="도골"}, [42]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [43]={npc="머드크러쉬 더트피트", tgt="머드크러쉬 더트피트"}, [44]={npc="도골", tgt="도골"}, [45]={hint="담쟁이 마을에 있는 크로그와 대화해야 합니다."}, [46]={npc="크로그", tgt="크로그"}, [47]={npc="크로그", tgt="크로그", tag="선택사항"}, [48]={text="선택 복귀 경로와 지역 간 퀘스트"}, [49]={npc="늪지눈알 자를", tgt="늪지눈알 자를", tag="달의 강철 브로드소드 보유 시, 선택사항"}, [50]={hint="먼지진흙 습지대에 있는 자를에게 달의 강철 브로드소드를 가져가야 합니다.", tag="달의 강철 브로드소드 보유 시, 선택사항", desc="달의 강철 브로드소드가 필요합니다. 완성품이 있을 때 제출하세요."}, [51]={npc="늪지눈알 자를", tgt="늪지눈알 자를", tag="달의 강철 브로드소드 보유 시, 선택사항"}, [52]={npc="푸석푸석한 흙더미", npcObj=true, tag="선택사항"}, [53]={hint="담쟁이 마을에 있는 나지르 블러드파이크에게 험상궂은 오크 가면을 가져가야 합니다.", tag="선택사항"}, [54]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크", tag="선택사항"}, [55]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크", tag="선택사항"}, [56]={npc="다이노", tgt="다이노", tag="선택사항", desc="이 경로는 오그리마를 거쳐요. 이미 썬더 블러프에 있다면 오손 그룰(25.70, 14.19)에게, 언더시티에 있다면 아나스타샤 하트웰(85.14, 10.03)에게 가세요."}, [57]={hint="타베사와 대화하십시오.", tag="선택사항"}, [58]={npc="타베사", tgt="타베사", tag="선택사항"}, [59]={npc="타베사", tgt="타베사", tag="선택사항", desc="토템 묶음 10개는 갖고 있다가 외부 봉인 마법진에서 상호작용해 합치세요."}, [60]={hint="먼지진흙 습지대에 있는 타베사에게 비취 1개와 벼락 맞은 나뭇가지를 가져가야 합니다.", tag="선택사항", desc="토템 묶음 10개는 갖고 있다가 외부 봉인 마법진에서 상호작용해 합치세요."}, [61]={npc="타베사", tgt="타베사", tag="선택사항", desc="토템 묶음 10개는 갖고 있다가 외부 봉인 마법진에서 상호작용해 합치세요."}, [62]={npc="타베사", tgt="타베사", tag="선택사항"}, [63]={hint="소금 평원에 있는 학자 틸스와 대화하십시오.", tag="선택사항"}, [64]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [65]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="병아리를 선택하고 /beckon을 입력한 뒤, 사람으로 변하면 말을 거세요."}, [66]={hint="틸스의 금고를 여는 주문을 알아서 틸스에게 돌아가야 합니다.", tag="선택사항", desc="병아리를 선택하고 /beckon을 입력한 뒤, 사람으로 변하면 말을 거세요."}, [67]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="병아리를 선택하고 /beckon을 입력한 뒤, 사람으로 변하면 말을 거세요."}, [68]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="파티로 도서관에 들어가 책장에서 책을 찾으세요."}, [69]={hint="먼지진흙 습지대에 있는 타베사에게 마력의 의식을 가져가야 합니다.", tag="선택사항", desc="파티로 도서관에 들어가 책장에서 책을 찾으세요. 붉은십자군 수도원에 들어가면 도서관 구역으로 가세요."}, [70]={npc="타베사", tgt="타베사", tag="선택사항", desc="파티로 도서관에 들어가 책장에서 책을 찾으세요."}, [71]={npc="타베사", tgt="타베사", tag="선택사항", desc="마법봉 재료 연계 두 가지를 모두 끝낸 뒤 보고하세요.", star={"맹위의 얼음마법봉 / 황천의 마법봉 / 맹위의 화염마법봉"}}, [72]={hint="의식이 끝나면 타베사와 대화하십시오.", tag="선택사항", desc="마법봉 재료 연계 두 가지를 모두 끝낸 뒤 보고하세요."}, [73]={npc="타베사", tgt="타베사", tag="선택사항", desc="마법봉 재료 연계 두 가지를 모두 끝낸 뒤 보고하세요.", star={"맹위의 얼음마법봉 / 황천의 마법봉 / 맹위의 화염마법봉"}}, [74]={text="브래큰월 마을로 돌아가 비행 지도에서 그늘수렵 마을을 선택하세요. 항로가 표시되지 않으면 먼저 크로스로드로 날아가 환승하세요. 귀환석은 잊혀진 땅 그늘수렵 마을의 만노로크 소굴에서 돌아올 때를 위해 남겨 두세요."}}},
    ["03-21"] = {name="잊혀진 땅", nameA="잊혀진 땅: {a:2408}", tips={{k="取捨", text="영상에도 이번 재방문이 나옵니다. 37레벨에 경험치가 부족하면 남동쪽 켄타우로스와 근처 불타는 군단 차원문을 보충으로 하세요. 잊혀진 땅 그늘수렵 마을에서 이룩소스의 손을 제출해야 악마의 차원문을 받을 수 있습니다. 유령의 플라스마는 상자로 몹을 끌어낸 뒤 한 마리씩 처리할 수 있습니다."}, {k="取捨", text="온게쿠 의 목표는 슬픔의 늪에 있습니다. 먼저 받아 두고 슬픔의 늪 스토나드에서 가는 길에 하세요. 칸 젠는 마을로 돌아가 을 제출해야 받을 수 있으니 나중으로 남겨 두세요."}, {k="提醒", text="38레벨이 안 됐다면 만노로크 소굴 외곽(약 50.40, 70.40)에서 일반 악마를 잡으세요. 처치 속도가 느리면 코도 무덤 남동쪽 켄타우로스 지역으로 돌아가세요.", s={{"38레벨이 안 됐다면 만노로크 소굴 외곽(약 50.40, 70.40)에서 일반 악마를 잡으세요"}, {"처치 속도가 느리면 코도 무덤 남동쪽 켄타우로스 지역으로 돌아가세요"}}}}, danger={[1]="만노로크 소굴 남쪽에는 엘리트 군주가 있습니다. 경험치나 재료만 필요하다면 동쪽의 마법사 사냥꾼을 잡으세요."}, grind={[1]={mob="하급 지옥불정령", note="만노로크 소굴 북쪽 외곽에 일반 몹이 밀집해 있습니다. 주변의 다른 악마를 조심하세요. 흑마법사의 로브 퀘스트에 필요한 하급 지옥정령석을 얻을 수 있습니다. 흑마법사 전용."}, [2]={note="소굴 외곽 같은 지대에 시전하는 일반 몹이 보통 밀도로 있습니다. 지형을 이용해 무리에서 끌어내세요. 하급 지옥정령석 몹과 번갈아 잡을 수 있습니다."}, [3]={mob="마법사 사냥개", note="소굴 동쪽에 일반 몹이 보통 밀도로 있습니다. 외곽을 따라 혼자 있는 몹을 고르고 남쪽의 엘리트 군주를 피하세요. 외곽 쪽에 사람이 많으면 여기로 옮겨 경험치를 채우세요."}}, supply={[1]={npc="탈론"}, [2]={npc="여관주인 시케와"}, [3]={npc="해윌라니"}, [4]={npc="여관주인 시케와"}, [5]={npc="투크"}}, steps={[1]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [2]={text="그늘수렵 마을에서 출발해 먼저 침묵의 초소를 지나고, 남쪽 길을 따라 만노로크 소굴로 가세요."}, [3]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [4]={npc="현자 우텍", tgt="현자 우텍", tag="겔키스 라인, 선행 퀘스트 필요, 선택사항"}, [5]={hint="만노로크 소굴에서 악마의 차원문 6개를 없애고 타이가 와이즈메인에게 돌아가야 합니다.", desc="소굴의 차원문에서 타이가가 준 이룩소스의 손을 사용해 6번 추방하세요."}, [6]={hint="잊혀진 땅의 호르니즈 브림버즐에게 유령의 플라스마 8개와 유령 유인기 상자를 가져가야 합니다.", desc="뼈의 골짜기에 자석 상자를 내려놓고, 먼저 물러난 뒤 다가오는 유령을 한 마리씩 처치하세요."}, [7]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [8]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [9]={npc="다이노", tgt="다이노", tag="선택사항", desc="이 경로는 오그리마를 거쳐요. 이미 썬더 블러프에 있다면 오손 그룰(25.70, 14.19)에게, 언더시티에 있다면 아나스타샤 하트웰(85.14, 10.03)에게 가세요."}, [10]={hint="타베사와 대화하십시오.", tag="선택사항"}, [11]={npc="타베사", tgt="타베사", tag="선택사항"}, [12]={npc="타베사", tgt="타베사", tag="선택사항"}, [13]={hint="먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다.", tag="선택사항"}, [14]={npc="타베사", tgt="타베사", tag="선택사항"}, [15]={npc="타베사", tgt="타베사", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [16]={hint="보주의 악마를 물리치고 타베사와 대화하십시오.", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [17]={npc="타베사", tgt="타베사", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [18]={npc="타베사", tgt="타베사", tag="선택사항", desc="흑요석 파수꾼으로 이어지는 입구로 가는지 먼저 파티에 확인하세요."}, [19]={hint="흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.", tag="선택사항", desc="흑요석 파수꾼으로 이어지는 입구로 가는지 먼저 파티에 확인하세요. 울다만 뒷문으로 들어가 흑요석 파수꾼을 찾으세요."}, [20]={npc="타베사", tgt="타베사", tag="선택사항", desc="흑요석 파수꾼으로 이어지는 입구로 가는지 먼저 파티에 확인하세요."}, [21]={npc="타베사", tgt="타베사", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [22]={hint="주어진 시간 안에 마력의 폭풍 12마리를 물리쳐야 합니다.", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [23]={npc="타베사", tgt="타베사", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [24]={npc="타베사", tgt="타베사", tag="선택사항"}, [25]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [26]={npc="타베사", tgt="타베사", tag="선택사항"}, [27]={text="아직 그늘수렵 마을에 귀환석이 설정돼 있다면 귀환석으로 돌아가고, 다른 정류장에서 합류해 다른 곳에 설정했다면 걸어서 비행 지점으로 돌아가세요. 이어서 오그리마로 날아가 기술을 훈련하세요."}}},
    ["03-22"] = {name="알터랙 산맥", tips={{k="取捨", text="타렌 밀농장에서 포로 구출과 비밀결사대원 현상수배를 먼저 확인하세요. 두 선행 퀘스트는 던홀드 요새에서 한 번에 할 수 있습니다. 산에 들어가 침투을 제출해야 을 받을 수 있으며, 골디르와 바르두스의 비밀결사 야영지 목표는 함께 찾으세요."}, {k="提醒", text="아라시 고원 해머폴과 합쳐 40레벨까지 올리세요. 아라시 고원 해머폴에 도착하면 부족한 경험치를 확인하세요. 경험치가 조금 부족하면 해머폴로 가기 전에 비밀결사 야영지의 일반 조직원(58.44, 70.00)을 먼저 잡으세요.", s={{"아라시 고원 해머폴과 합쳐 40레벨까지 올리세요"}, {"아라시 고원 해머폴에 도착하면 부족한 경험치를 확인하세요"}, {"경험치가 조금 부족하면 해머폴로 가기 전에 비밀결사 야영지의 일반 조직원(58.44, 70.00)을 먼저 잡으세요"}}}}, danger={[1]="크러시리지 요새 폐허 안에는 엘리트 오우거가 있습니다. 일반 야만인을 잡을 때는 바깥 산길에 머물고, 파티가 도착하면 들어가세요."}, grind={[1]={mob="비밀결사대 염탐꾼", note="비밀결사 야영지 외곽에 일반 몹이 밀집해 있습니다. 은신한 몹과 마법사를 조심하고, 야영지 가장자리를 따라 혼자 있는 몹을 고르세요. 조금만 채우고 해머폴로 가세요."}, [2]={note="크러시리지 요새 바깥 산길에 일반 몹이 밀집해 있습니다. 요새 안에는 엘리트가 따로 있으니 바깥에 머물면 돌아가는 길이 줄어, 솔로로 경험치를 채우기 좋습니다."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="오그리마 성 밖 비행선 탑에서 티리스팔 숲행 비행선을 타세요. 브릴 남쪽 탑에서 내려 언더시티로 가고, 타렌 밀농장으로 날아가 귀환석 위치를 설정하세요."}, [2]={npc="멜리사라", tgt="멜리사라", tag="파티가 있을 때, 선택사항"}, [3]={npc="크루스크", tgt="크루스크"}, [4]={npc="현상수배!", npcObj=true, desc="현상수배! 게시판(62.57, 20.66)에서도 같은 퀘스트를 받을 수 있습니다."}, [5]={hint="타렌 밀농장에 있는 크루스크가 던홀드 요새에서 드럴과 토그타르를 구출해 달라고 부탁했습니다.", desc="던홀드 요새 경비병에게서 열쇠 2개를 얻은 뒤 포로 두 명의 족쇄를 푸세요."}, [6]={hint="비밀결사대 도적 10명과 비밀결사대 경비병 10명을 처치해야 합니다. 그런 다음 타렌 밀농장에 있는 고위집행관 다살리아에게 돌아가 보상금을 받으십시오."}, [7]={npc="크루스크", tgt="크루스크"}, [8]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [9]={npc="크루스크", tgt="크루스크"}, [10]={npc="현상수배!", npcObj=true, desc="현상수배! 게시판(62.57, 20.66)에서도 같은 퀘스트를 받을 수 있습니다."}, [11]={hint="타렌 밀농장에 있는 크루스크를 위해 골디르가 어디에 있는지 정보를 찾아야 합니다."}, [12]={hint="타렌 밀농장에 있는 멜리사라를 위해 산사태일족 싸움꾼 14마리를 처치해야 합니다.", tag="파티가 있을 때, 선택사항", desc="크러시리지 학대자는 엘리트이니, 알터랙 폐허에 들어가기 전에 파티부터 구하세요."}, [13]={npc="크루스크", tgt="크루스크"}, [14]={npc="멜리사라", tgt="멜리사라", tag="파티가 있을 때, 선택사항"}, [15]={npc="멜리사라", tgt="멜리사라", tag="선택사항"}, [16]={npc="크루스크", tgt="크루스크"}, [17]={hint="골디르를 구출하여 타렌 밀농장에 있는 크루스크에게 돌아가야 합니다."}, [18]={hint="바르두스 남작을 처치하고 그 증거로 그의 머리카락을 타렌 밀농장에 있는 고위집행관 다살리아에게 가져가야 합니다.", desc="바르두스는 서로 다른 비밀결사 야영지에 나타날 수 있습니다. 먼저 골디르 근처에서 찾고, 그다음 북쪽 야영지를 확인하세요."}, [19]={npc="골디르", tgt="골디르"}, [20]={npc="골디르", tgt="골디르"}, [21]={hint="타렌 밀농장에 있는 크루스크에게 골디르가 수집한 정보를 전해야 합니다."}, [22]={npc="크루스크", tgt="크루스크"}, [23]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [24]={hint="타르그, 무크라케, 글롬무스를 처치하고 그 증거로 그들의 머리카락을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", tag="선택사항"}, [25]={npc="멜리사라", tgt="멜리사라", tag="선택사항"}, [26]={npc="멜리사라", tgt="멜리사라", tag="파티가 있을 때, 선택사항"}, [27]={hint="무그톨을 처치하고 그 증거로 그의 머리카락과 의지의 왕관을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [28]={npc="멜리사라", tgt="멜리사라", tag="파티가 있을 때, 선택사항"}, [29]={npc="멜리사라", tgt="멜리사라", tag="파티가 있을 때, 선택사항"}, [30]={hint="언더시티에 있는 샬린드라에게 의지의 왕관을 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [31]={npc="샬린드라", tgt="샬린드라", tag="파티가 있을 때, 선택사항"}, [32]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="최소 레벨 24부터 받을 수 있고 퀘스트 레벨은 36이에요. 이번 알터랙 방문에서 처리하세요."}, [33]={hint="바턴을 소매치기하여 바턴의 정찰 보고서를 훔친 후, 라벤홀트 장원의 미로코스 사일런트폼에게 가져가야 합니다.", tag="선택사항, 대상: 바턴", desc="최소 레벨 24부터 받을 수 있고 퀘스트 레벨은 36이에요. 이번 알터랙 방문에서 처리하세요."}, [34]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="최소 레벨 24부터 받을 수 있고 퀘스트 레벨은 36이에요. 이번 알터랙 방문에서 처리하세요."}, [35]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="먼저 사물함에서 제복을 얻으세요. 다음 단계를 위해 스트롬가드에서 변장 상태를 유지하세요."}, [36]={hint="북부습곡 장원에서 비밀결사대 제복을 훔쳐 스트롬가드 요새에 잠입해야 합니다.", tag="선택사항", desc="먼저 사물함에서 제복을 얻으세요. 다음 단계를 위해 스트롬가드에서 변장 상태를 유지하세요."}, [37]={npc="비밀결사대 사물함", npcObj=true, tag="선택사항", desc="먼저 사물함에서 제복을 얻으세요. 다음 단계를 위해 스트롬가드에서 변장 상태를 유지하세요."}, [38]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="가시덩굴 우리의 메모를 가져가세요. 퀘스트 로그가 여전히 높새바람 봉우리를 가리키면 라우 클리프러너(46.14, 51.71)에게 제출하세요."}, [39]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="정기의 도움을 제출한 뒤 바스라를 먼저 확인하세요. 높새바람 봉우리에서 이전 단계를 제출했다면 라우 클리프러너에게서 바로 받을 수 있어요."}, [40]={hint="버섯구름 봉우리에 있는 프레이트 클라우드시어와 대화해야 합니다.", tag="선택사항", desc="정기의 도움 이후에 수락하세요."}, [41]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="정기의 도움 이후에 수락하세요."}, [42]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="바스라가 이 퀘스트를 주면 미리 받아 두세요. 불과 땅은 25번째와 27번째 지점에서 겸사겸사 구할 수 있고, 잊혀진 땅과 먼지진흙 습지대의 토템은 다시 와야 해요."}, [43]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항, 게임 내 확인이 필요합니다", desc="바스라가 이 사이드 퀘스트를 줄 때만 진행하세요. 주 레벨링 경로와는 따로 진행할 수 있어요."}, [44]={hint="버섯구름 봉우리의 높새바람 봉우리에 있는 라우 클리프러너에게 가야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="바스라가 이 사이드 퀘스트를 줄 때만 진행하세요. 주 레벨링 경로와는 따로 진행할 수 있어요."}, [45]={npc="라우 클리프러너", tgt="라우 클리프러너", tag="선택사항, 게임 내 확인이 필요합니다", desc="바스라가 이 사이드 퀘스트를 줄 때만 진행하세요. 주 레벨링 경로와는 따로 진행할 수 있어요."}, [46]={text="비밀결사 야영지를 마친 뒤 동쪽으로 소라딘 성벽을 지나 아라시 고원으로 돌아가세요."}}},
    ["03-23"] = {name="아라시 고원", nameA="아라시 고원: {a:321}", tips={{k="取捨", text="볼더피스트, 랩터, 비밀결사의 상급 퀘스트는 재방문 때 함께 정리할 수 있습니다. 하위 단계를 한 적이 없다면 같은 이름의 후속 퀘스트는 건너뛰세요. 마법진의 돌 은 순환 경로에서 함께 만지고, 쐐기돌 깨기 포즈루크는 파티가 있을 때만 쫓으세요."}, {k="取捨", text="팔디르의 만에서 인양, 가라앉은 보물, 비통한 마음을 한 번에 받으세요. 를 먼저 완료해 을 열고, 에서 보물찾기 고글을 받아 수중의 심해의 인양 작업/도 함께 하세요. 는 가시덤불 골짜기 무법항을 위해 남겨 두고, 은 팔디르의 만에 다시 들를 때 제출하세요."}, {k="取捨", text="영상에서는 여력이 있을 때 스트롬가드를 하라고 안내합니다. 이동을 줄이려면 수정과 해머폴 근처를 먼저 하고, 스트롬가드 후반 아라소르의 인장~트롤칼라은 건너뛰어도 됩니다."}, {k="提醒", text="스토나드를 지날 때 먼저 비행 지점을 여세요. 슬픔의 늪 퀘스트는 슬픔의 늪 스토나드에서 하도록 남겨 두세요.", s={{"스토나드를 지날 때 먼저 비행 지점을 여세요"}, {"슬픔의 늪 퀘스트는 슬픔의 늪 스토나드에서 하도록 남겨 두세요"}}}, {k="提醒", text="큰강 숲지대로 가기 전에 40레벨이 안 됐다면 해머폴 동쪽 마른수염 골짜기에서 일반 코볼트(약 84, 31)를 먼저 잡으세요. 몹 이름이 회색으로 바뀌면 마른나무껍질 마을 외곽(약 68, 69)의 일반 마른나무껍질 트롤로 바꾸세요.", s={{"큰강 숲지대로 가기 전에 40레벨이 안 됐다면 해머폴 동쪽 마른수염 골짜기에서 일반 코볼트(약 84, 31)를 먼저 잡으세요"}, {"몹 이름이 회색으로 바뀌면 마른나무껍질 마을 외곽(약 68, 69)의 일반 마른나무껍질 트롤로 바꾸세요"}}}}, danger={[1]="스트롬가드 경비병은 문 앞에 모입니다. 인장 사슬을 제출하기 전에 경비병을 따로따로 유인하고, 건물 안에서 두 무리를 동시에 건드리지 마세요.", [2]="팔디르의 만 난파선에는 수중 몹이 있습니다. 배에 들어가기 전에 보물찾기 고글을 착용하고 호흡 게이지를 확인하세요."}, grind={[1]={mob="마른수염일족 흙점쟁이", note="해머폴 동쪽 마른수염 골짜기 깊은 곳에 일반 몹이 보통 밀도로 있습니다. 통로가 좁고 희귀 몹 흙점쟁이 플린트대거를 만날 수 있으니 입구에서 구간별로 나아가세요."}, [2]={mob="마른수염일족 채굴꾼", note="마른수염 골짜기 통로에 일반 몹이 밀집해 있고 탐사자와 섞여 있습니다. 수정 퀘스트와 함께 진행하되, 동굴 안에서 돌아올 때의 재생성을 조심하세요."}, [3]={mob="떠도는 물의 정령", note="해머폴 북서쪽 물 정령 지역에 일반 몹이 밀집해 있습니다. 코볼트보다 약간 레벨이 높아 40레벨까지 잡기 좋습니다. 같은 길에서 소용돌이 무기 퀘스트용 정령 부적을 모을 수 있습니다. 전사 전용."}}, supply={[1]={npc="우르다"}, [2]={npc="여관주인 아데그와"}, [3]={npc="무우타"}, [4]={npc="여관주인 아데그와"}, [5]={npc="그라우드"}}, steps={[1]={npc="미즈라엘의 결정", npcObj=true}, [2]={npc="토건", tgt="토건"}, [3]={npc="드럼 펠", tgt="드럼 펠"}, [4]={npc="토건", tgt="토건", tag="선택사항"}, [5]={hint="아라시 고원의 해머폴로 가서 젠구와 대화해야 합니다."}, [6]={npc="젠구", tgt="젠구"}, [7]={npc="젠구", tgt="젠구", tag="선택사항"}, [8]={hint="미즈라엘의 결정 파편을 12개 모아서 마른수염 골짜기에 있는 오색 결정에 가져가야 합니다."}, [9]={npc="오색 결정", npcObj=true}, [10]={npc="오색 결정", npcObj=true}, [11]={hint="식인 고원랩터에게서 랩터 심장 12개를 얻어 토건에게 가져가야 합니다."}, [12]={hint="돌주먹일족 투사 10마리와 돌주먹일족 사제 4마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다."}, [13]={hint="마레즈 코울의 더럽혀진 혈석 수정구를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", tag="선택사항"}, [14]={npc="토건", tgt="토건"}, [15]={npc="드럼 펠", tgt="드럼 펠"}, [16]={npc="토건", tgt="토건", tag="선택사항"}, [17]={npc="토건", tgt="토건"}, [18]={hint="고르멀에게 토건의 수정구를 전달해야 합니다."}, [19]={npc="고르멀", tgt="고르멀"}, [20]={npc="고르멀", tgt="고르멀"}, [21]={hint="토건과 대화해야 합니다."}, [22]={npc="토건", tgt="토건"}, [23]={npc="드럼 펠", tgt="드럼 펠", tag="선택사항"}, [24]={npc="코린 펠", tgt="코린 펠", tag="선택사항"}, [25]={hint="돌주먹일족 주술사 15마리와 돌주먹일족 우두머리 10마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다.", tag="선택사항"}, [26]={hint="오르칼라를 처치하고 그 증거로 그의 머리카락을 해머폴 전초 기지에 있는 코린 펠에게 가져가야 합니다.", tag="선택사항"}, [27]={npc="드럼 펠", tgt="드럼 펠", tag="선택사항"}, [28]={npc="코린 펠", tgt="코린 펠", tag="선택사항"}, [29]={hint="해머폴에 있는 젠구에게 스트롬의 인장을 가져가야 합니다.", tag="선택사항"}, [30]={npc="젠구", tgt="젠구", tag="선택사항"}, [31]={npc="젠구", tgt="젠구", tag="선택사항"}, [32]={hint="스트롬가드의 수호병들에게서 인장 조각 11개를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", tag="선택사항"}, [33]={npc="토건", tgt="토건", tag="선택사항"}, [34]={npc="토건", tgt="토건", tag="선택사항"}, [35]={hint="해머폴에 있는 젠구에게 소라딘의 인장을 가져가야 합니다.", tag="선택사항"}, [36]={npc="젠구", tgt="젠구", tag="선택사항"}, [37]={hint="서부 봉인석, 동부 봉인석, 외부 봉인석에서 각각 불타는 열쇠, 용마루장식 열쇠, 천둥 열쇠를 구해야 합니다."}, [38]={npc="내부 봉인석", npcObj=true}, [39]={npc="내부 봉인석", npcObj=true, tag="파티가 있을 때, 선택사항"}, [40]={hint="포즈루크를 찾아 처치해야 합니다. 아라시 고원에 있는 쐐기돌에 질서의 마법봉을 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [41]={npc="쐐기돌", npcObj=true, tag="파티가 있을 때, 선택사항"}, [42]={npc="쐐기돌", npcObj=true, tag="파티가 있을 때, 선택사항"}, [43]={hint="해머폴에 있는 자루크와 대화해야 합니다.", tag="파티가 있을 때, 선택사항"}, [44]={npc="자루크", tgt="자루크", tag="파티가 있을 때, 선택사항"}, [45]={npc="자루크", tgt="자루크", tag="선택사항", desc="호드는 해머폴에서 미즈라엘의 친구들을 제출한 뒤 자루크에게서 받으세요. 황야의 땅에서 쓰도록 남겨 두세요."}, [46]={text="팔디르의 만"}, [47]={npc="망꾼 롤로", tgt="망꾼 롤로"}, [48]={hint="팔디르의 만에 있는 선장 오브린과 대화해야 합니다."}, [49]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [50]={npc="학자 피즐솔프", tgt="학자 피즐솔프"}, [51]={hint="학자 피즐솔프가 동굴에 들어갔다 나올 수 있도록 호위해야 합니다.", desc="먼저 교수 주변의 몹을 정리하고, 퀘스트를 받은 뒤 교수와 함께 동굴에 들어갔다가 만으로 돌아오세요."}, [52]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [53]={npc="일등항해사 닐즐릭스", tgt="일등항해사 닐즐릭스"}, [54]={npc="선장 스틸구트", tgt="선장 스틸구트"}, [55]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [56]={hint="일등항해사 닐즐릭스가 메이든즈 폴리호와 실버파인 스피릿호에서 해도와 항해일지를 찾아 달라고 부탁했습니다."}, [57]={hint="팔디르의 만에 있는 선장 스틸구트가 비수가시일족 침략자 10마리와 비수가시일족 여마법사 3마리를 처치해 달라고 부탁했습니다."}, [58]={hint="팔디르의 만에 있는 발명가 드랙슬게이지가 엘프의 보석 10개를 주워 오고 이 일을 끝낸 후 보물찾기 고글을 돌려 달라고 부탁했습니다.", desc="가라앉은 보물을 받아 보물찾기 고글을 얻고, 착용해 수중 보석을 찾으세요. 심해의 인양 작업, 비통한 마음와 한 번에 진행하세요."}, [59]={npc="일등항해사 닐즐릭스", tgt="일등항해사 닐즐릭스"}, [60]={npc="선장 스틸구트", tgt="선장 스틸구트"}, [61]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [62]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [63]={hint="선장 오브린에게 엘프의 보석을 가져가야 합니다."}, [64]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [65]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [66]={npc="토건", tgt="토건"}, [67]={npc="바스라의 가마솥", npcObj=true, tag="선택사항", desc="부적은 경매장에서 살 수 있어요. 가마솥은 같은 퀘스트를 받고 제출하는 장소예요."}, [68]={hint="획득처: 마른수염 코볼트, 마른수염일족 흙점쟁이, 마른수염일족 채굴꾼", tag="선택사항", desc="부적은 경매장에서 살 수 있어요. 가마솥은 같은 퀘스트를 받고 제출하는 장소예요."}, [69]={npc="바스라의 가마솥", npcObj=true, tag="선택사항", desc="부적은 경매장에서 살 수 있어요. 가마솥은 같은 퀘스트를 받고 제출하는 장소예요."}, [70]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항"}, [71]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="퀘스트 레벨 40의 정예 퀘스트예요. 먼저 파티를 모은 뒤 시작하세요."}, [72]={hint="바람의감시자 바스라에게 소용돌이의 눈을 가져가야 합니다.", tag="선택사항", desc="퀘스트 레벨 40의 정예 퀘스트예요. 먼저 파티를 모은 뒤 시작하세요."}, [73]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="퀘스트 레벨 40의 정예 퀘스트예요. 먼저 파티를 모은 뒤 시작하세요."}, [74]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", star={"소용돌이 도끼 / 소용돌이 검 / 소용돌이 전투망치"}}, [75]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [76]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", star={"소용돌이 도끼 / 소용돌이 검 / 소용돌이 전투망치"}}, [77]={npc="비밀결사대 사물함", npcObj=true, tag="선택사항", desc="들어가기 전에 먼저 제복을 입으세요. 공격하면 변장이 풀리니 전투를 피하세요."}, [78]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.", tag="선택사항", desc="들어가기 전에 먼저 제복을 입으세요. 공격하면 변장이 풀리니 전투를 피하세요."}, [79]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항", desc="들어가기 전에 먼저 제복을 입으세요. 공격하면 변장이 풀리니 전투를 피하세요."}, [80]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항"}, [81]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="선택사항", desc="스트롬가드 옆 집 2층에서 아나스타샤의 은닉물을 찾으세요."}, [82]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항"}, [83]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [84]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [85]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [86]={text="해머폴로 돌아가세요. 로그마와 스토나드 비행 지점을 이미 열었다면 로그마로 바로 날아가세요. 처음 로그마에 가는데 스토나드 비행 지점을 열었다면 먼저 스토나드를 선택하세요. 스토나드를 열지 않았다면 그롬골로 날아가 가시덤불 골짜기 대로를 따라 북쪽 그늘숲으로 가서, 다크샤이어 경비병을 피하고 동쪽 입구에서 죽음의 고개를 거쳐 슬픔의 늪으로 들어가세요. 그롬골 비행 지점을 열지 않았다면 언더시티에서 브릴 남쪽 비행선 탑으로 가 그롬골행 비행선을 타세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}}},
    ["05-d17"] = {name="가시덩굴 구릉", entrance="불모의 땅 약 49.10, 93.40 (가시나무 길 깊은 곳의 던전 입구)", pickup="아라시 고원 해머폴을 떠날 때는 먼저 언더시티로 날아가세요. 버섯구름 봉우리 반짝이는 평원에서 가시덩굴 우리를 먼저 돌며 사악한 동맹를 얻을 수 있습니다. 알터랙 산맥에서 아라시 고원 해머폴로 가는 길에 언더시티를 지나면 먼저 바리마트라스에게 제출하고, 같은 도시에서 안드류에게 암네나르 처치을 받으세요. 티리스팔에서 비행선으로 오그리마로 돌아가 썬더 블러프로 날아간 뒤, 멀고어 북서쪽에서 수타라를 찾아 혹한의 눈을 받으세요. 타우라조 야영지로 날아가 남쪽으로 가서 입구 밖에서 미리암을 찾으세요. 동부 왕국의 화약심지 항구에서 이동한다면 배로 스팀휘들 항구에 가서 북쪽의 버섯구름 봉우리로 가세요.", pickupS={{"아라시 고원 해머폴을 떠날 때는 먼저 언더시티로 날아가세요"}, {"버섯구름 봉우리 반짝이는 평원에서 가시덩굴 우리를 먼저 돌며 사악한 동맹를 얻을 수 있습니다"}, {"알터랙 산맥에서 아라시 고원 해머폴로 가는 길에 언더시티를 지나면 먼저 바리마트라스에게 제출하고, 같은 도시에서 안드류에게 암네나르 처치을 받으세요"}, {"티리스팔에서 비행선으로 오그리마로 돌아가 썬더 블러프로 날아간 뒤, 멀고어 북서쪽에서 수타라를 찾아 혹한의 눈을 받으세요"}, {"타우라조 야영지로 날아가 남쪽으로 가서 입구 밖에서 미리암을 찾으세요"}, {"동부 왕국의 화약심지 항구에서 이동한다면 배로 스팀휘들 항구에 가서 북쪽의 버섯구름 봉우리로 가세요"}}, tips={{k="動線", text="입구에서 불꽃눈 모드레쉬 근처 감옥까지 정리하세요 → 벨리스트라즈와 맹세의 돌을 교환하고, 그를 호위해 우상을 봉인하세요. 도중에 썩어가는 프레모를 만날 수 있습니다 → 나선형 경사로를 따라 암네나르를 처치하고, 같은 구역에서 혹한의 눈을 찾으세요."}, {k="取捨", text="40레벨 이상 파티가 있을 때 전체 던전을 돌고, 혹한의 눈과 암네나르 처치은 마지막 우두머리에서 함께 얻으세요. 34레벨에는 눈 퀘스트만 먼저 받는 것이 좋고, 가는 길에 던전 밖에서 악의 무리을 할 수 있습니다."}, {k="說明", text="5인 던전이며 열쇠가 필요 없습니다. 입구는 대형 승강기 북쪽 동쪽 길에 있으며, 서쪽의 가시덩굴 우리와는 다릅니다. 이미 강물터로 넘어갔다면 화약심지 항구에서 배를 타고 스팀휘들 항구에 도착한 뒤 북쪽으로 가세요.", s={{"5인 던전이며 열쇠가 필요 없습니다"}, {"입구는 대형 승강기 북쪽 동쪽 길에 있으며, 서쪽의 가시덩굴 우리와는 다릅니다"}, {"이미 강물터로 넘어갔다면 화약심지 항구에서 배를 타고 스팀휘들 항구에 도착한 뒤 북쪽으로 가세요"}}}, {k="提醒", text="5인 던전이며 열쇠가 필요 없습니다. 입구는 대형 승강기 북쪽 동쪽 길에 있으며, 서쪽의 가시덩굴 우리와는 다릅니다. 이미 강물터로 넘어갔다면 화약심지 항구에서 배를 타고 스팀휘들 항구에 도착한 뒤 북쪽으로 가세요.", s={{"5인 던전이며 열쇠가 필요 없습니다"}, {"입구는 대형 승강기 북쪽 동쪽 길에 있으며, 서쪽의 가시덩굴 우리와는 다릅니다"}, {"이미 강물터로 넘어갔다면 화약심지 항구에서 배를 타고 스팀휘들 항구에 도착한 뒤 북쪽으로 가세요"}}}}, steps={[1]={npc="작은 두루마리", npcObj=true, tag="게임 내 확인이 필요합니다", desc="앞서 가시덩굴 우리에서 차를가에게서 작은 두루마리를 얻었다면 건너뛰세요."}, [2]={hint="작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다."}, [3]={npc="바리마트라스", tgt="바리마트라스"}, [4]={npc="바리마트라스", tgt="바리마트라스", desc="사악한 동맹를 제출한 뒤 같은 NPC에게서 받으세요. 목표는 가시덩굴 구릉 입구 밖 가시나무 길에 있습니다.", preText="사악한 동맹"}, [5]={npc="앤드류 브로넬", tgt="앤드류 브로넬", desc="37레벨이 되면 언더시티 마법 구역에서 미리 받을 수 있습니다."}, [6]={npc="수타라 평원추적자", tgt="수타라 평원추적자", desc="포에버에서 새로 추가된 퀘스트입니다."}, [7]={npc="미리암 문싱어", tgt="미리암 문싱어", desc="미리암은 불모의 땅 남쪽 끝 입구 밖에 있습니다(49.01, 94.94). 들어가기 전에 퀘스트를 받고 주변을 정리하세요."}, [8]={hint="사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다."}, [9]={hint="가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다."}, [10]={npc="미리암 문싱어", tgt="미리암 문싱어"}, [11]={text="가시덩굴 구릉 입구"}, [12]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", desc="감옥 구역에서 벨리스트라즈를 찾으세요. 호위를 시작하기 전에 파티원 모두 맹세 대화를 마쳐야 합니다."}, [13]={hint="그가 당신에게 서약의 돌을 줄 것입니다. 벨리스트라즈의 계획을 돕는 것에 동의하면 다시 그와 대화하여 그에게 서약의 돌을 돌려주십시오.", desc="위치: 불꽃눈 모드레쉬 근처 감옥으로 가서 벨리스트라즈를 찾으세요. 순서: 파티원 모두 맹세의 돌을 제출한 뒤 호위를 시작하세요.", spot="불꽃눈 모드레쉬 근처 감옥으로 가서 벨리스트라즈를 찾으세요."}, [14]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", spot="불꽃눈 모드레쉬 근처 감옥, 벨리스트라즈"}, [15]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", desc="시작하면 NPC를 바짝 따라가세요. 파티가 모두 준비된 뒤에 시작하세요.", preText="가시덩굴 구릉의 스컬지"}, [16]={hint="가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다.", desc="위치: 감옥에서 우상까지 벨리스트라즈를 호위하고 보호하세요.", spot="감옥에서 우상까지 벨리스트라즈를 호위하고 보호하세요."}, [17]={npc="벨리스트라즈의 화로", npcObj=true, tag="게임 내 확인이 필요합니다", spot="우상 옆 화로, 벨리스트라즈가 의식을 치르는 곳"}, [18]={hint="앤드류 브로넬이 혹한의 암네나르를 처치하고 혹한의 해골을 가져다 달라고 부탁했습니다.", desc="위치: 감옥 구역을 나와 나선형 높은 비탈을 따라 암네나르에게 올라가세요.", spot="감옥 구역을 나와 나선형 높은 비탈을 따라 암네나르에게 올라가세요."}, [19]={hint="가시덩굴 구릉에서 혹한의 눈을 회수해야 합니다.", desc="위치: 암네나르의 둥지로 들어가 혹한의 눈을 찾으세요. 순서: 17단계와 같은 구역입니다.", spot="암네나르의 둥지로 들어가 혹한의 눈을 찾으세요."}, [20]={npc="수타라 평원추적자", tgt="수타라 평원추적자"}, [21]={npc="앤드류 브로넬", tgt="앤드류 브로넬"}, [22]={npc="바리마트라스", tgt="바리마트라스"}}},
    ["03-24"] = {tips={{k="取捨", text="처음에는 로그마 주변의 농장, 놀, 강둑, 짐승을 정리하세요. 초그자크(황혼은 이제 끝이다!)와 이어지는 머리 가져오기 퀘스트는 파티가 있을 때 하세요. 볼데로크의 멧돼지와 채석장 퀘스트는 바로 받아도 돼요. 레벨 42 이상 황혼 및 해안 퀘스트는 볼데로크와 화약심지 항구를 위해 남겨 두고, 영상대로 두 번에 나눠 진행하세요."}, {k="取捨", text="이 지점에서 로그마 비행 지점을 먼저 개방하세요. 카르가스나 스토나드를 오갈 때 지상 이동이 줄어요. 보급품은 Toka에게서 구하세요."}, {k="提醒", text="퀘스트를 마쳤는데 레벨 41이 안 됐나요? 나조크 농장 남쪽(70.62, 33.08)의 일반 멧돼지나 로그마 남쪽 짐승 지역(약 61, 50)에서 더 처치하세요. 볼데로크의 상위 황혼 퀘스트는 볼데로크와 화약심지 항구를 위해 남겨 두세요.", s={{"퀘스트를 마쳤는데 레벨 41이 안 됐나요?"}, {"나조크 농장 남쪽(70.62, 33.08)의 일반 멧돼지나 로그마 남쪽 짐승 지역(약 61, 50)에서 더 처치하세요"}, {"볼데로크의 상위 황혼 퀘스트는 볼데로크와 화약심지 항구를 위해 남겨 두세요"}}}}, danger={[1]="로그마 남쪽에 파홀드 정찰병과 사제가 있어요. 혼자 있는 정찰병을 먼저 끌어서 사제가 함께 전투에 합류하지 않게 하세요.", [2]="햇살숲의 황혼 의식 동굴은 좁아요. 먼저 입구를 정리한 뒤 의식진을 파괴하고, 뒤에서 섀도우맨서가 다시 나타나지 않게 하세요."}, grind={[1]={mob="저지대 평원 대머리수리", note="로그마 남쪽 초원. 몹 밀집, 일반 몹. 근처에 레벨 41~42 정예 짐승이 있으니 길을 따라 한 마리씩 처치하세요. 화살깃에 쓸 깃털용 깃털도 함께 모으세요."}, [2]={mob="파홀드 정찰병", note="로그마 남쪽 파홀드 정찰병 지역. 몹 밀집, 일반 몹. 사제가 다른 정찰병과 함께 전투에 합류하지 않게 주의하세요. 강 바깥쪽부터 정리하며 그거 그렇게 하는 거 아닌데도 함께 진행하세요."}, [3]={mob="파홀드 사제", note="남쪽 강둑 서쪽. 몹 밀도 보통, 일반 시전 몹. 먼저 치유를 차단하고 정찰병을 동시에 끌지 마세요. 그거 그렇게 하는 거 아닌데 서쪽 구간을 이미 지났다면 겸사겸사 처치하세요."}}, supply={[1]={npc="그라크나"}, [2]={npc="여관주인 토카"}, [3]={npc="구르도크"}, [4]={npc="날루크"}, [5]={npc="마카"}, [6]={npc="브레이크"}, [7]={npc="툴타조르"}}, steps={[1]={nodeA="{a:75}", desc="슬픔의 늪 지상 경로로 왔다면 브레이크에게서 비행 지점을 여세요. 이미 로그마로 직행했다면 건너뛰세요."}, [2]={text="스토나드에서 출발합니다. 로그마 비행 지점을 열었다면 바로 날아가세요. 처음이라면 영상 26:56~27:13처럼 슬픔의 늪에서 큰강 숲지대로 들어가, 남쪽 길로 테랄의 감시터(약 60, 64)를 지나 북쪽 로그마로 가세요. 이미 해머폴에서 로그마로 직행했다면 비행 관리인에게 바로 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [3]={node="로그마", desc="그라크나에게서 비행 지점을 여세요."}, [4]={text="여관주인 토카(57.58, 45.47)에게서 귀환석을 설정하세요."}, [5]={hint="강물터 로그마 전초기지에 있는 크롬로쉬에게 보고해야 합니다."}, [6]={hint="강물터의 로그마에서 탄자니를 찾아야 합니다."}, [7]={npc="크롬로쉬", tgt="크롬로쉬"}, [8]={npc="탄자니", tgt="탄자니"}, [9]={npc="크롬로쉬", tgt="크롬로쉬"}, [10]={npc="크롬로쉬", tgt="크롬로쉬"}, [11]={npc="구르도크", tgt="크레자 다크쏜"}, [12]={npc="탄자니", tgt="탄자니"}, [13]={text="남부 농장과 남서부 놀"}, [14]={hint="풀잎개울에서 풀잎개울 농장 일꾼 12명을 처치하고 크롬로쉬에게 성공 소식을 전해야 합니다.", tag="대상: 풀잎개울 농장 일꾼"}, [15]={hint="풀잎개울 얼라이언스 농장에서 먹이 자루 6개를 훔쳐 크롬로쉬에게 가야 합니다."}, [16]={npc="크롬로쉬", tgt="크롬로쉬"}, [17]={npc="크롬로쉬", tgt="크롬로쉬"}, [18]={npc="크롬로쉬", tgt="크롬로쉬"}, [19]={hint="훔친 먹이를 로그마에 있는 그로그에게 전달해야 합니다."}, [20]={npc="그로그", tgt="그로그"}, [21]={npc="그로그", tgt="그로그"}, [22]={hint="훈련장에서 로그마 훈련생 8명에게 음식을 줘야 합니다.", tag="대상: 로그마 훈련생"}, [23]={npc="그로그", tgt="그로그"}, [24]={npc="크롬로쉬", tgt="크롬로쉬"}, [25]={hint="강 남쪽에서 파홀드 사제 8명과 파홀드 정찰병 12명을 처치해야 합니다.", tag="대상: 파홀드 사제 / 파홀드 정찰병"}, [26]={npc="크롬로쉬", tgt="크롬로쉬"}, [27]={npc="트란굴", tgt="트란굴"}, [28]={npc="트란굴", tgt="트란굴"}, [29]={text="강변 목재 캠프 및 햇살숲"}, [30]={hint="터너의 벌목지에 있는 벌목꾼에게서 로그마의 크레자 다크쏜에게 줄 목공의 도끼 10개를 회수해야 합니다.", tag="대상: 터너의 제재소 벌목꾼"}, [31]={hint="터너의 벌목지에 있는 인부 장작더미에서 목재 묶음을 획득한 후, 급조한 찌르기 창 20개에 사용해야 합니다."}, [32]={npc="구르도크", tgt="크레자 다크쏜"}, [33]={npc="구르도크", tgt="크레자 다크쏜", desc="빌린 검을 완료한 뒤 여기에서 받으세요. 검은 일단 갖고 있다가 화약심지 항구에서 Friz에게 전달하세요."}, [34]={npc="탄자니", tgt="탄자니"}, [35]={npc="탄자니", tgt="탄자니"}, [36]={hint="민물악어 10마리를 꿰뚫은 후 로그마에 있는 탄자니에게 가야 합니다.", tag="대상: 민물악어"}, [37]={npc="탄자니", tgt="탄자니"}, [38]={hint="로그마의 트란굴을 위해 황혼의 약탈병 8명과 황혼의 수련사 8명을 처치해야 합니다.", tag="대상: 황혼의 약탈병/황혼의 망치단 흑마술사/황혼의 수련사"}, [39]={hint="햇살숲에 있는 황혼의 망치단 흑마술사에게서 황혼의 서신 3개를 회수해 로그마에 있는 트란굴에게 반납해야 합니다.", tag="대상: 황혼의 망치단 흑마술사"}, [40]={npc="트란굴", tgt="트란굴"}, [41]={npc="트란굴", tgt="트란굴"}, [42]={npc="트란굴", tgt="트란굴"}, [43]={hint="햇살숲의 황혼의 망치단 광부를 설득해 비밀을 실토하게 해야 합니다."}, [44]={npc="몽둥이발", tgt="몽둥이발"}, [45]={npc="몽둥이발", tgt="몽둥이발"}, [46]={hint="몽둥이발을 위해 햇살숲 지하 동굴에서 실종된 오우거를 찾아야 합니다."}, [47]={npc="강화된 투사", tgt="황혼의 투사"}, [48]={npc="강화된 투사", tgt="황혼의 투사"}, [49]={npc="몽둥이발", tgt="몽둥이발"}, [50]={hint="강화된 투사 5명과 황혼의 의식술사 10명을 처치한 후 햇살숲에 있는 몽둥이발에게 가야 합니다.", tag="대상: 강화된 투사/황혼의 의식술사"}, [51]={hint="햇살숲 지하 동굴에 설치된 황혼의 의식진 5개를 파괴해야 합니다."}, [52]={npc="몽둥이발", tgt="몽둥이발"}, [53]={npc="몽둥이발", tgt="몽둥이발"}, [54]={npc="몽둥이발", tgt="몽둥이발", tag="파티가 있을 때, 선택사항"}, [55]={hint="햇살숲 동굴에서 초그자크를 처치하고 머리카락을 수집해 몽둥이발에게 전달해야 합니다.", tag="파티가 있을 때, 선택사항, 대상: 초그자크", desc="초그자크는 클리어우드 동굴 안에 있는 레벨 41 정예예요."}, [56]={npc="몽둥이발", tgt="몽둥이발", tag="파티가 있을 때, 선택사항"}, [57]={npc="몽둥이발", tgt="몽둥이발", tag="파티가 있을 때, 선택사항"}, [58]={hint="초그의 머리카락을 로그마에 있는 트란굴에게 전달해야 합니다.", tag="파티가 있을 때, 선택사항"}, [59]={npc="트란굴", tgt="트란굴", tag="파티가 있을 때, 선택사항"}, [60]={npc="트란굴", tgt="트란굴", tag="파티가 있을 때, 선택사항"}, [61]={text="로그마 주변 사냥"}, [62]={npc="뜯긴 사체", tgt="뜯긴 사체", desc="남쪽 짐승 지역 바닥에 갉아먹힌 시체가 있어요. 찾아서 상호작용해 퀘스트를 받으세요."}, [63]={hint="갉아 먹힌 해골을 로그마에 있는 핏빛코 네자에게 가져가야 합니다."}, [64]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [65]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [66]={hint="온전한 타조 부리를 로그마에 있는 핏빛코 네자에게 가져가야 합니다.", tag="대상: 떠도는 타조"}, [67]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [68]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [69]={hint="평원 대머리수리 깃털 6개를 로그마에 있는 핏빛코 네자에게 가져가야 합니다.", tag="대상: 저지대 평원 대머리수리"}, [70]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [71]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [72]={hint="숲살무사 독 표본 4개를 로그마에 있는 핏빛코 네자에게 가져가야 합니다.", tag="대상: 공터 살무사"}, [73]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [74]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [75]={hint="귀한 사자 가죽 6개를 로그마에 있는 핏빛코 네자에게 가져가야 합니다.", tag="대상: 야생평원 우두머리/야생평원 사냥꾼"}, [76]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [77]={npc="핏빛코 네자", tgt="핏빛코 네자", tag="선택사항", star={"핏빛주둥이 격퇴창", {"WARRIOR", "PALADIN"}}}, [78]={hint="뾰족털 언덕에서 스나글을 찾아 처치한 뒤, 핏빛코 네자에게 줄 스나글의 주둥이를 회수해야 합니다.", tag="선택사항, 대상: 스나글"}, [79]={npc="핏빛코 네자", tgt="핏빛코 네자", tag="선택사항", star={"핏빛주둥이 격퇴창", {"WARRIOR", "PALADIN"}}}, [80]={npc="구르도크", tgt="크레자 다크쏜"}, [81]={hint="뾰족털 언덕에 있는 놀에게서 도둑맞은 광물 40개를 모아 크레자 다크쏜에게 전달해야 합니다.", tag="대상: 붉은마루일족 투사 / 붉은마루일족 비술사 / 붉은마루일족 덫사냥꾼"}, [82]={npc="구르도크", tgt="크레자 다크쏜"}, [83]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [84]={hint="로그마의 핏빛코 네자가 부탁한 대로 붉은마루일족 비술사 8명과 붉은마루일족 덫사냥꾼 8명, 붉은마루일족 투사 6명을 처치해야 합니다.", tag="대상: 붉은마루일족 비술사 / 붉은마루일족 덫사냥꾼 / 붉은마루일족 투사"}, [85]={npc="핏빛코 네자", tgt="핏빛코 네자"}, [86]={text="레벨 40~41: 짧은 북쪽 루프"}, [87]={hint="초그의 머리카락을 북쪽의 오우거 도시로 전달해야 합니다.", tag="파티가 있을 때, 선택사항"}, [88]={npc="뭉치주먹", tgt="뭉치주먹", tag="파티가 있을 때, 