화해 지옥마 소환 능력을 배워야 합니다.", desc="현재 지역의 시작 퀘스트를 먼저 제출한 뒤 스트라하드에게서 받으세요."}, [118]={npc="스트라드 파선", tgt="스트라드 파선", desc="현재 지역의 시작 퀘스트를 먼저 제출한 뒤 스트라하드에게서 받으세요."}, [119]={text="카르가스를 개방했다면 로그마에서 바로 비행하세요. 처음 방문이라면 영상 27:55~28:03 경로를 따라 황혼 캠프 북쪽의 서쪽 고개로 황야의 땅에 들어간 뒤, 북서쪽 카르가스 비행 지점으로 가세요. 귀환석은 이후 재방문을 위해 로그마에 설정해 두세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}}},
    ["03-25"] = {name="황야의 땅", nameA="황야의 땅: {a:340}", tips={{k="取捨", text="바위 정령은 황야의 땅 시약(황야의 땅에서 재료 찾기)과 몹 위치 일부가 겹치니, 두 퀘스트를 모두 받은 뒤 시작하세요. 코요테 턱뼈는 30개 필요하니 길을 따라 계속 정리하다가 충분하면 이동하세요."}, {k="取捨", text="냉기 오일, 태엽장치 동기 조정 자이로스코프, 물약이 모두 준비된 경우에만 최고의 냉각제-액체 돌를 진행하세요. 깨어진 동맹은 더 높은 레벨이거나 파티가 있을 때를 위해 남겨 두세요."}, {k="提醒", text="영상에서는 레벨 40 탈것 숙련을 이번 도시 이동 때 배워요. 이미 레벨 40이고 골드가 있다면 지나는 길에 해당 종족 교관에게서 먼저 배워도 돼요. 아래 \"직업 퀘스트\"와 \"레벨 40 종족별 탈것\"을 참고하세요.", s={{"영상에서는 레벨 40 탈것 숙련을 이번 도시 이동 때 배워요"}, {"이미 레벨 40이고 골드가 있다면 지나는 길에 해당 종족 교관에게서 먼저 배워도 돼요"}, {"아래 \"직업 퀘스트\"와 \"레벨 40 종족별 탈것\"을 참고하세요"}}}, {k="提醒", text="카르가스를 떠나기 전에 레벨 42가 안 됐다면 황야의 땅 남서쪽(약 6.65, 73.85)에서 일반 Greater Rock Elementals를 처치하세요. 그곳이 붐비면 카르가스 남동쪽 능선의 코요테와 독수리를 처치하세요.", s={{"카르가스를 떠나기 전에 레벨 42가 안 됐다면 황야의 땅 남서쪽(약 6.65, 73.85)에서 일반 Greater Rock Elementals를 처치하세요"}, {"그곳이 붐비면 카르가스 남동쪽 능선의 코요테와 독수리를 처치하세요"}}}}, danger={[1]="황야의 땅 동쪽에 레벨 39~40 정예 Stonevault Seer와 Basher가 있어요. 울다만 외곽을 지날 때는 거리를 두세요."}, grind={[1]={mob="상급 바위 정령", note="카르가스 남쪽 절벽. 몹 밀집, 일반 몹. 근처에 Firegut Ogres가 있으니 암벽을 따라 바깥쪽부터 정리하세요. 레벨 42 전에 힘들면 능선으로 옮기세요."}, [2]={note="카르가스 남동쪽 능선. 몹 밀도 보통, 일반 몹. 정예와 희귀 순찰 몹을 피하세요. 레벨 41 솔로 사냥이나 정령 지역이 붐빌 때 이곳으로 옮기세요."}, [3]={mob="거대한 대머리수리", note="카르가스 남동쪽 비탈. 몹 밀도 보통, 일반 몹. 능선 몹과 번갈아 사냥하세요. 독수리 날개나 모래주머니 퀘스트가 있으면 함께 모으세요."}}, supply={[1]={npc="고릭"}, [2]={npc="여관주인 술카르"}, [3]={npc="스란다"}, [4]={npc="여관주인 술카르"}, [5]={npc="그롤"}}, steps={[1]={nodeA="{a:340}", desc="고릭에게서 비행 지점을 개방하세요."}, [2]={text="기술 훈련과 탈것 숙련이 필요하면 이때 떠나고, 돌아올 때는 카르가스로 비행하세요."}, [3]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [4]={npc="니카 블러드스카", tgt="니카 블러드스카"}, [5]={npc="니카 블러드스카", tgt="니카 블러드스카"}, [6]={npc="고른", tgt="고른", tag="선택사항"}, [7]={text="바위 정령과 중앙 몹 루프"}, [8]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [9]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스", tag="재료가 모이면 진행, 선택사항"}, [10]={hint="황야의 땅에 있는 로트윌 베리아투스에게 냉기 오일을 가져가야 합니다.", tag="재료가 모이면 진행, 선택사항", desc="냉기 오일을 먼저 구한 뒤 로트윌 베리아투스에게 전달하세요. 여기서 제출하세요. 냉기 기름은 연금술사가 만들 수 있습니다."}, [11]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스", tag="재료가 모이면 진행, 선택사항"}, [12]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스", tag="재료가 모이면 진행, 선택사항"}, [13]={hint="황야의 땅에 있는 로트윌 베리아투스에게 태엽장치를 가져가야 합니다.", tag="재료가 모이면 진행, 선택사항", desc="태엽장치 동기 조정 자이로스코프를 먼저 준비하세요. 기술자가 제작할 수 있어요."}, [14]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스", tag="재료가 모이면 진행, 선택사항"}, [15]={npc="루시앙 토셀렌치", tgt="루시앙 토셀렌치", tag="재료가 모이면 진행, 선택사항"}, [16]={hint="황야의 땅에 있는 루시앙 토셀렌치에게 치유 물약과 하급 투명 물약을 가져가야 합니다.", tag="재료가 모이면 진행, 선택사항"}, [17]={npc="루시앙 토셀렌치", tgt="루시앙 토셀렌치", tag="재료가 모이면 진행, 선택사항"}, [18]={hint="황야의 땅에 있는 로크윌 베리아투스에게 작은 돌조각 10개를 가져가야 합니다."}, [19]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [20]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [21]={hint="황야의 땅에 있는 망명자 마르텍에게 피즐의 편지를 가져가야 합니다."}, [22]={npc="망명자 마르텍", tgt="망명자 마르텍"}, [23]={npc="망명자 마르텍", tgt="망명자 마르텍"}, [24]={npc="리글퍼즈", tgt="리글퍼즈"}, [25]={hint="실성한 텔두린을 찾아야 합니다.", tag="선택사항"}, [26]={npc="실성한 텔두린", tgt="실성한 텔두린", tag="선택사항"}, [27]={npc="실성한 텔두린", tgt="실성한 텔두린", tag="선택사항"}, [28]={hint="황야의 땅에 있는 로트윌 베리아투스에게 큰 돌조각 3개를 가져가야 합니다."}, [29]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [30]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [31]={hint="황야의 땅에 있는 로트윌 베리아투스에게 바위 결속의 팔보호구 5개를 가져가야 합니다.", desc="남서쪽의 일반 상급 바위 정령에게서 돌결속 팔보호구를 얻으세요."}, [32]={hint="황야의 땅에 있는 망명자 마르텍에게 인듀리움 조각 10개를 가져가야 합니다."}, [33]={hint="리글퍼즈에게 대머리수리 날개 4개를 가져가야 합니다."}, [34]={hint="실성한 텔두린에게 찢어진 두루마리 조각, 구겨진 두루마리 조각, 그을린 두루마리 조각을 가져가야 합니다.", tag="선택사항"}, [35]={npc="로트윌 베리아투스", tgt="로트윌 베리아투스"}, [36]={npc="망명자 마르텍", tgt="망명자 마르텍"}, [37]={npc="리글퍼즈", tgt="리글퍼즈"}, [38]={npc="실성한 텔두린", tgt="실성한 텔두린", tag="선택사항"}, [39]={hint="황야의 땅에서 자칼 모스멜드에게 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가야 합니다."}, [40]={hint="카르가스에 있는 니카 블러드스카에게 코요테 턱뼈 30개를 가져가야 합니다."}, [41]={hint="우두머리 토그룬을 처치하고 카르가스에 있는 고른에게 대지의 봉인을 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [42]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [43]={npc="니카 블러드스카", tgt="니카 블러드스카"}, [44]={npc="고른", tgt="고른", tag="파티가 있을 때, 선택사항"}, [45]={npc="자칼 모스멜드", tgt="자칼 모스멜드", tag="울다만에 갈 때만 수락, 선택사항"}, [46]={text="탈것 숙련을 익혔다면 카르가스에서 그롬골로 바로 비행한 뒤, 그롬골에서 무법항으로 가세요. 아직 익히지 않았다면 종족별 탈것 교관에게 가세요. 오그리마나 언더시티 근처라면 그롬골행 비행선을 타세요."}}},
    ["05-d18"] = {name="울다만", entrance="황야의 땅 약 42.60, 10.80 (정문 기준, 발굴 현장을 따라 지하로 이동). 후문의 실제 입구 위치는 알 수 없습니다.", pickup="황야의 땅 카르가스에서 울다만으로 갑니다. 알터랙 산맥, 아라시 고원 해머폴에서 언더시티를 지날 때 먼저 패트릭에게 보물 되찾기를 받으세요. 해머폴이나 그롬골에서 황야의 땅 카르가스로 날아가 자칼 모스멜드에게 황야의 땅에서 재료 찾기 → 울다만에서 재료 찾기를 받고, 리글퍼즈와 셀두린을 찾으세요. 35레벨이 되면 먼지진흙 습지대에서 타베사의 선행 퀘스트를 먼저 할 수 있습니다(마법사만 해당). 목걸이를 만들려면 첫 번째에 부서진 목걸이까지 처치하고, 오그리마를 오갈 때 드란에게 제출한 뒤 두 번째에 카르가스에서 던전으로 들어가세요.", pickupS={{"황야의 땅 카르가스에서 울다만으로 갑니다"}, {"알터랙 산맥, 아라시 고원 해머폴에서 언더시티를 지날 때 먼저 패트릭에게 보물 되찾기를 받으세요"}, {"해머폴이나 그롬골에서 황야의 땅 카르가스로 날아가 자칼 모스멜드에게 황야의 땅에서 재료 찾기 → 울다만에서 재료 찾기를 받고, 리글퍼즈와 셀두린을 찾으세요"}, {"35레벨이 되면 먼지진흙 습지대에서 타베사의 선행 퀘스트를 먼저 할 수 있습니다(마법사만 해당)", {class={"MAGE"}}}, {"목걸이를 만들려면 첫 번째에 부서진 목걸이까지 처치하고, 오그리마를 오갈 때 드란에게 제출한 뒤 두 번째에 카르가스에서 던전으로 들어가세요"}}, tips={{k="動線", text="정문 → 레벨로쉬 → 시신에서 일지를 얻고, 먼저 카르가스로 돌아가 번역한 뒤 던전으로 돌아오세요. 후문으로 바로 가서 흑요석 파수꾼을 처치할 수도 있습니다(마법사만 해당). 두 번째 발굴 현장 → 갈간 → 그림로크 → 아카에다스 → 노르간논의 원반."}, {k="取捨", text="울다만에서 재료 찾기, 보물 되찾기, 마법석을 가는 길에 먼저 받으세요. 40레벨이 되면 원반을 얻고 가방을 받을 수 있습니다. 목걸이는 두 번 이상 오가야 하니 빠르게 레벨을 올릴 때는 건너뛰어도 됩니다."}, {k="說明", text="5인 던전입니다. 34레벨에 먼저 언더시티에서 보물 되찾기를 받고, 황야의 땅을 지나면서 바깥 동굴을 처리하세요. 마지막 우두머리는 42레벨을 권장합니다. 정문은 전체 정리와 목걸이에, 후문은 후반부만 할 때 알맞습니다. 마법사 퀘스트는 후문으로 가세요(마법사만 해당). 일부 자료에는 지상 동굴 입구만 표시되니, 입구를 찾을 때는 동굴 안 큰길을 따라가세요.", s={{"5인 던전입니다"}, {"34레벨에 먼저 언더시티에서 보물 되찾기를 받고, 황야의 땅을 지나면서 바깥 동굴을 처리하세요"}, {"마지막 우두머리는 42레벨을 권장합니다"}, {"정문은 전체 정리와 목걸이에, 후문은 후반부만 할 때 알맞습니다"}, {"마법사 퀘스트는 후문으로 가세요(마법사만 해당)", {class={"MAGE"}}}, {"일부 자료에는 지상 동굴 입구만 표시되니, 입구를 찾을 때는 동굴 안 큰길을 따라가세요"}}}, {k="提醒", text="5인 던전입니다. 34레벨에 먼저 언더시티에서 보물 되찾기를 받고, 황야의 땅을 지나면서 바깥 동굴을 처리하세요. 마지막 우두머리는 42레벨을 권장합니다. 정문은 전체 정리와 목걸이에, 후문은 후반부만 할 때 알맞습니다. 마법사 퀘스트는 후문으로 가세요(마법사만 해당). 일부 자료에는 지상 동굴 입구만 표시되니, 입구를 찾을 때는 동굴 안 큰길을 따라가세요.", s={{"5인 던전입니다"}, {"34레벨에 먼저 언더시티에서 보물 되찾기를 받고, 황야의 땅을 지나면서 바깥 동굴을 처리하세요"}, {"마지막 우두머리는 42레벨을 권장합니다"}, {"정문은 전체 정리와 목걸이에, 후문은 후반부만 할 때 알맞습니다"}, {"마법사 퀘스트는 후문으로 가세요(마법사만 해당)", {class={"MAGE"}}}, {"일부 자료에는 지상 동굴 입구만 표시되니, 입구를 찾을 때는 동굴 안 큰길을 따라가세요"}}}}, steps={[1]={npc="패트릭 가레트", tgt="패트릭 가레트", desc="33레벨이 되면 언더시티 중앙 구역에서 미리 받을 수 있으며, 상자는 던전 입구 밖에 있습니다."}, [2]={npc="리글퍼즈", tgt="리글퍼즈", desc="마법석은 입구 밖의 암영로 드워프가 떨어뜨리므로 한 번에 정리할 수 있습니다."}, [3]={npc="실성한 텔두린", tgt="실성한 텔두린", desc="셀두린은 황야의 땅 남쪽에 있습니다. 지나가는 길일 때만 받으세요."}, [4]={npc="자칼 모스멜드", tgt="자칼 모스멜드", desc="황야의 땅 카르가스에서 이미 제출했다면 바로 울다만에서 재료 찾기를 받으세요."}, [5]={hint="황야의 땅에서 자칼 모스멜드에게 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가야 합니다."}, [6]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [7]={npc="자칼 모스멜드", tgt="자칼 모스멜드", desc="자칼 모스멜드는 카르가스에 있습니다. 황야의 땅에서 재료 찾기을 제출한 뒤 바로 받으세요.", preText="황야의 땅에서 재료 찾기"}, [8]={npc="다이노", tgt="다이노", desc="35레벨이 되면 먼지진흙 습지대 장벽 마을과 잊혀진 땅 그늘수렵 마을 사이에서 먼저 할 수 있습니다. 이미 제출했다면 건너뛰세요."}, [9]={hint="타베사와 대화하십시오."}, [10]={npc="타베사", tgt="타베사"}, [11]={npc="타베사", tgt="타베사"}, [12]={hint="먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다."}, [13]={npc="타베사", tgt="타베사"}, [14]={npc="타베사", tgt="타베사", preText="지옥의 보주"}, [15]={hint="보주의 악마를 물리치고 타베사와 대화하십시오."}, [16]={npc="타베사", tgt="타베사"}, [17]={npc="타베사", tgt="타베사", desc="타베사의 퇴마가 끝난 뒤 받으세요. 후문 쪽의 흑요석 파수꾼을 처치할 것이라고 파티에 먼저 알리세요.", preText="악마 퇴치"}, [18]={hint="울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다."}, [19]={hint="황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다."}, [20]={hint="실성한 텔두린에게 류네의 서판을 가져가야 합니다."}, [21]={npc="드란 드로퍼스", tgt="드란 드로퍼스", desc="선택 연계입니다. 발굴 현장이나 던전 안의 암영로 드워프가 부서진 목걸이를 떨어뜨립니다. 얻은 뒤 호드용 목걸이 회수인지 확인하세요."}, [22]={hint="울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다."}, [23]={npc="드란 드로퍼스", tgt="드란 드로퍼스"}, [24]={npc="드란 드로퍼스", tgt="드란 드로퍼스", desc="울다만을 한 번만 돈다면 여러 번 돌아야 하는 이 연계는 포기해도 됩니다. 목걸이 회수을 제출한 뒤 드란에게서 받으세요.", preText="목걸이 회수"}, [25]={text="울다만 입구"}, [26]={hint="카르가스에 있는 자칼 모스멜드에게 자홍버섯 12개를 가져가야 합니다.", desc="자홍버섯은 던전 입구 밖에 자랍니다. 위치: 정문 바깥 동굴에서 자주색 버섯을 먼저 캐고, 던전 안에서는 발굴 통로를 따라 모자란 만큼 채우세요.", spot="정문 바깥 동굴에서 자주색 버섯을 먼저 캐고, 던전 안에서는 발굴 통로를 따라 모자란 만큼 채우세요."}, [27]={hint="흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.", desc="위치: 후문으로 들어가세요. 흑요석 파수꾼이 근처에 있습니다.", spot="후문으로 들어가세요. 흑요석 파수꾼이 근처에 있습니다."}, [28]={hint="울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다.", desc="위치: 정문으로 들어가 레벨로쉬를 처치하고, 그 뒤 방에서 시신을 살펴보세요. 순서: 완료한 뒤 던전을 나와 30, 33단계를 진행하세요.", spot="정문으로 들어가 레벨로쉬를 처치하고, 그 뒤 방에서 시신을 살펴보세요."}, [29]={npc="성기사의 유해", tgt="성기사의 유해", tag="게임 내 확인이 필요합니다", spot="레벨로쉬 뒤쪽 방의 성기사 유해"}, [30]={npc="성기사의 유해", tgt="성기사의 유해", tag="게임 내 확인이 필요합니다", desc="시신에서 일지를 받고, 먼저 카르가스로 돌아가 다음 진행을 여세요.", preText="목걸이 회수 - 2차 시도"}, [31]={hint="성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다."}, [32]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [33]={npc="자칼 모스멜드", tgt="자칼 모스멜드", preText="일지 번역"}, [34]={hint="자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다."}, [35]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [36]={npc="자칼 모스멜드", tgt="자칼 모스멜드", desc="카르가스에서 번역본을 받은 뒤 받으세요. 두 번째 진행에서 전부 정리하세요.", preText="일지 번역"}, [37]={hint="울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.", desc="위치: 두 번째 발굴 현장의 항아리 → 갈간의 방 → 그림로크 → 마지막 우두머리. 순서: 먼저 황옥을 얻고, 그다음 홍옥과 청옥을, 마지막으로 동력원을 얻으세요.", spot="두 번째 발굴 현장의 항아리 → 갈간의 방 → 그림로크 → 마지막 우두머리"}, [38]={npc="노르간논의 원반", npcObj=true, tag="게임 내 확인이 필요합니다", desc="40레벨 이상에서 아카에다스를 처치한 뒤 마지막 방에서 노르간논의 원반을 클릭하세요."}, [39]={hint="바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오.", desc="위치: 아카에다스를 처치하고 뒤쪽 보물 방에서 노르간논의 원반을 클릭하세요. 순서: 먼저 바위 감시자의 말을 들은 뒤 원반을 클릭하세요.", spot="아카에다스를 처치하고 뒤쪽 보물 방에서 노르간논의 원반을 클릭하세요."}, [40]={npc="노르간논의 원반", npcObj=true, tag="게임 내 확인이 필요합니다", spot="아르케다스 뒤쪽 보관실의 노르간논의 원반"}, [41]={npc="노르간논의 원반", npcObj=true, tag="게임 내 확인이 필요합니다", desc="같은 원반에서 호드의 전달 퀘스트를 받고 썬더 블러프로 돌아가세요.", preText="백금 원반"}, [42]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [43]={npc="리글퍼즈", tgt="리글퍼즈"}, [44]={npc="실성한 텔두린", tgt="실성한 텔두린"}, [45]={npc="패트릭 가레트", tgt="패트릭 가레트"}, [46]={npc="타베사", tgt="타베사"}, [47]={hint="썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다."}, [48]={npc="현자 트루스시커", tgt="현자 트루스시커"}, [49]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}, [50]={npc="자칼 모스멜드", tgt="자칼 모스멜드", preText="보석과 마력원천 찾기"}, [51]={hint="오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다."}, [52]={npc="드란 드로퍼스", tgt="드란 드로퍼스"}, [53]={npc="드란 드로퍼스", tgt="드란 드로퍼스", preText="보석 전달"}, [54]={hint="카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오."}, [55]={npc="자칼 모스멜드", tgt="자칼 모스멜드"}}},
    ["03-26"] = {name="가시덤불 골짜기", tips={{k="取捨", text="무법항 두 번째 방문 때는 가라앉은 보물, 투자개발회사 채광, 덩치큰 바다악어 가죽 등 완료한 퀘스트를 먼저 제출하세요. 붉은해적단 → → 는 해안 근처 짧은 구간부터 하고, 를 열어 잃어버린 눈, 코담배를 찾아서과 함께 진행하세요. 를 제출하면 이 열려 세 선장을 처치해요. 빚 퀘스트 빚 돌려받기는 겁쟁이 → 맥킨리에게 돌아가기을 먼저 제출해야 해요. 영상에서 한 바퀴마다 항구로 돌아가므로 이 해금 지점들을 그대로 따르세요."}, {k="取捨", text="붉은해적단 배에서 코르텔로의 수수께끼를 미리 받고, 스토나드를 지날 때 첫 단계를 풀어 두세요. 덩치큰 바다악어 가죽과 투자개발회사 채광을 못 끝냈다면 도중에 마저 해서 한 개 때문에 다시 비행하는 일을 피하세요. 승선 전에 해안의 빚 돌려받기를 먼저 처리하세요."}, {k="提醒", text="가시덤불 골짜기에서는 무법항부터 볼데로크와 화약심지 항구까지 합쳐 레벨 45까지 올려요. 여기서 경험치가 조금 더 필요하면 붉은해적단 배 세 척을 끝낸 뒤 해안의 일반 붉은해적단 해적(약 32, 79)을 처치하세요.", s={{"가시덤불 골짜기에서는 무법항부터 볼데로크와 화약심지 항구까지 합쳐 레벨 45까지 올려요"}, {"여기서 경험치가 조금 더 필요하면 붉은해적단 배 세 척을 끝낸 뒤 해안의 일반 붉은해적단 해적(약 32, 79)을 처치하세요"}}}}, danger={[1]="모쉬오그 구릉에는 정예를 포함한 여러 종류의 오우거가 있어요. 그롬골 공격 계획 때는 언덕 기슭에서 끌어내고, 한 번에 야영지로 들어가지 마세요.", [2]="붉은해적단 배는 계단이 좁고 출구가 적어요. 승선 전에 해안을 정리하고, 층마다 다 처치한 뒤 내려오세요."}, grind={[1]={mob="붉은해적단 칼잡이", note="무법항 바깥 해변. 몹 밀집, 일반 몹. 먼저 해변을 정리하고, 붉은해적단 퀘스트를 하는 다른 플레이어를 살피세요. 배 퀘스트를 마친 뒤 근처에서 경험치를 더 얻을 수 있어요."}, [2]={mob="붉은해적단 흑마법사", note="붉은해적단 남쪽 해안. 몹 밀집, 일반 시전 몹. 같은 무리의 근접 몹을 먼저 처치한 뒤 흑마법사를 끌어오세요. 해안을 돌면 승선 시간을 아낄 수 있어요."}}, supply={[1]={npc="그링거"}, [2]={npc="여관주인 스킨들"}, [3]={npc="주타크"}, [4]={npc="닉스락스 필라머그"}, [5]={npc="하렌 칸메"}, [6]={npc="시스타"}, [7]={npc="여관주인 툴벡"}, [8]={npc="크래크"}, [9]={npc="나르가트"}}, steps={[1]={text="그롬골에 도착하면 먼저 무법항으로 비행해 다음 퀘스트 묶음을 받으세요. 이전 지점이 그롬골 근처였다면 캠프 퀘스트를 먼저 받아도 돼요."}, [2]={hint="무법항에 있는 시혼 함장에게 엘프의 보석 표본을 가져가야 합니다."}, [3]={npc="함장 시혼", tgt="함장 시혼"}, [4]={npc="함장 시혼", tgt="함장 시혼", tag="나중에 지나갈 때 진행, 선택사항"}, [5]={npc="일등항해사 크래즈", tgt="일등항해사 크래즈"}, [6]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [7]={npc="선원 블로즈", tgt="선원 블로즈"}, [8]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [9]={npc="케복", tgt="케복"}, [10]={npc="드리즐릭", tgt="드리즐릭"}, [11]={npc="드리즐릭", tgt="드리즐릭"}, [12]={npc="부두주임 로즈길", tgt="부두주임 로즈길", tag="줄쿤다 호위 후 수락, 선택사항"}, [13]={npc="크라젝", tgt="크라젝", tag="슬픔의 늪의 스토나드에서 수행, 선택사항", desc="선행 퀘스트는 톱니항의 크라벨에게 줄 부품(크레이블의 부품)에서 시작해, Shimmering Flats의 노움 화물(노움에게 배달)을 거쳐, 무법항의 경주 소문(소문을 퍼뜨리는 자)에서 끝나요."}, [14]={text="북쪽 해변을 정찰한 뒤 무법항으로 돌아가 붉은해적단 퀘스트 개방"}, [15]={hint="일등항해사 크래즈가 무법항 북쪽의 작은 만을 조사해 달라고 부탁했습니다."}, [16]={npc="붉은해적단 통신문", npcObj=true}, [17]={npc="붉은해적단 통신문", npcObj=true}, [18]={hint="무법항에 있는 일등항해사 크래즈에게 조사 결과를 보고해야 합니다."}, [19]={npc="일등항해사 크래즈", tgt="일등항해사 크래즈"}, [20]={npc="일등항해사 크래즈", tgt="일등항해사 크래즈"}, [21]={hint="함장 시혼에게 붉은해적단의 공격 계획을 보고해야 합니다."}, [22]={npc="함장 시혼", tgt="함장 시혼"}, [23]={npc="함장 시혼", tgt="함장 시혼"}, [24]={npc="애꾸눈 디지", tgt="애꾸눈 디지"}, [25]={npc="디그", tgt="디그"}, [26]={text="캠프 퀘스트를 추가로 하려면 무법항에서 그롬골로 비행한 뒤, 남쪽으로 몹을 정리하며 항구로 돌아오세요."}, [27]={hint="가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 혼이 깃든 오크의 가면을 가져가야 합니다.", tag="선택사항"}, [28]={npc="킨윌레이", tgt="킨윌레이", tag="선택사항"}, [29]={npc="끓고 있는 가마솥", npcObj=true, tag="먼지진흙 습지대에서 제출, 선택사항"}, [30]={npc="킨윌레이", tgt="킨윌레이", tag="피묻은 뼈목걸이 및 썩은내 산호초 필요"}, [31]={npc="끓고 있는 가마솥", npcObj=true}, [32]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리"}, [33]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", tag="선택사항"}, [34]={hint="헤멧 네싱워리가 줄무늬정글랩터 10마리를 처치해 달라고 부탁했습니다."}, [35]={hint="그롬골 주둔지에 있는 예언자 모크타르딘에게 줄무늬정글랩터 깃털 10개를 가져가야 합니다.", tag="랩터 사냥법 익히기과 함께 진행"}, [36]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리"}, [37]={npc="예언자 모크타르딘", tgt="예언자 모크타르딘", tag="랩터 사냥법 익히기과 함께 진행"}, [38]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리", tag="파티가 있거나 솔로 가능할 때, 선택사항"}, [39]={hint="헤멧 네싱워리가 가시덤불 골짜기에 있는 잡기 힘들고 위험한 랩터인 테디스를 처치해 달라고 부탁했습니다.", tag="파티가 있거나 솔로 가능할 때, 선택사항"}, [40]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리", tag="파티가 있거나 솔로 가능할 때, 선택사항"}, [41]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리", tag="파티가 있거나 솔로 가능할 때, 선택사항", star={"전문 사냥꾼의 활 / 전문 사냥꾼의 라이플"}}, [42]={hint="헤멧 네싱워리가 거대한 백색 호랑이인 야수왕 뱅갈라시의 머리를 가져다 달라고 부탁했습니다.", tag="파티가 있거나 솔로 가능할 때, 선택사항"}, [43]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리", tag="파티가 있거나 솔로 가능할 때, 선택사항", star={"전문 사냥꾼의 활 / 전문 사냥꾼의 라이플"}}, [44]={hint="그롬골 주둔지의 사령관 아그로고쉬를 위해 모쉬오그 오우거 소굴의 오우거를 처치해야 합니다.", tag="선택사항", desc="모쉬오그의 4가지 목표는 모두 정예예요. 파티를 꾸려서 처치하세요."}, [45]={hint="그롬골 주둔지에 있는 킨윌레이에게 부서진 뼈목걸이 25개를 가져가야 합니다."}, [46]={hint="그롬골 주둔지에 있는 끓고 있는 가마솥으로 발리아마 전리품 해골과 지아타자이 전리품 해골, 줄맘웨 전리품 해골을 가져가야 합니다."}, [47]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", tag="선택사항"}, [48]={npc="킨윌레이", tgt="킨윌레이"}, [49]={npc="끓고 있는 가마솥", npcObj=true}, [50]={text="가시덤불 골짜기 중남부 겸사겸사 처리 → 붉은해적단 야영지"}, [51]={hint="백골가루부족 어금니 18개를 모아 케복에게 돌아가야 합니다."}, [52]={hint="무법항에 있는 크랭크 피즐버브에게 노래하는 파란 수정 10개를 가져가야 합니다."}, [53]={hint="무법항에 있는 드리즐릭에게 덩치큰 바다악어 가죽을 가져가야 합니다."}, [54]={hint="무법항에 있는 선원 블로즈에게 아키리스 갈대 묶음 10개를 가져가야 합니다.", tag="대상: 나가 탐험가 / 소금비늘 척후병"}, [55]={hint="무법항에 있는 크랭크 피즐버브에게 잔질의 혼합물 12개를 가져가야 합니다."}, [56]={hint="무법항에 있는 겁쟁이 필립에게 안개계곡고릴라 내장 5개를 가져가야 합니다."}, [57]={hint="무법항에 있는 함장 시혼이 붉은해적단 칼잡이 10명을 처치하고 붉은해적단 해도와 붉은해적단의 명령서를 가지고 와 달라고 부탁했습니다."}, [58]={hint="무법항에 있는 애꾸눈 디지가 붉은해적단에게서 그의 눈을 찾아달라고 부탁했습니다."}, [59]={hint="무법항에 있는 디그가 코담배 15개를 가져다 달라고 부탁했습니다."}, [60]={npc="케복", tgt="케복"}, [61]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [62]={npc="드리즐릭", tgt="드리즐릭"}, [63]={npc="선원 블로즈", tgt="선원 블로즈"}, [64]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [65]={npc="겁쟁이 필립", tgt="겁쟁이 필립"}, [66]={npc="겁쟁이 필립", tgt="겁쟁이 필립"}, [67]={hint="'바다늑대' 맥킨리에게 겁쟁이 필립의 빚진 돈을 가져가야 합니다."}, [68]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [69]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [70]={npc="함장 시혼", tgt="함장 시혼"}, [71]={npc="애꾸눈 디지", tgt="애꾸눈 디지"}, [72]={npc="디그", tgt="디그"}, [73]={npc="함장 시혼", tgt="함장 시혼"}, [74]={text="마지막 순회: 승선과 빚 수금"}, [75]={hint="무법항에 있는 \"바다늑대\" 맥킨리에게 마우리의 의족, 존존의 황금 망원경과 처키의 큰 반지를 가져가야 합니다."}, [76]={hint="무법항에 있는 함장 시혼이 선장 스틸워터, 선장 킬하울과 함장 피랠론을 암살해 달라고 부탁했습니다."}, [77]={npc="코르텔로의 수수께끼", npcObj=true, desc="붉은해적단 배 위의 수수께끼 아이템으로 퀘스트를 받으세요. 제출은 다음 지역인 슬픔의 늪 다리 아래에서 해요."}, [78]={npc="함장 시혼", tgt="함장 시혼"}, [79]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [80]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리", tag="선택사항"}, [81]={hint="무법항에 있는 \"바다늑대\" 맥킨리에게 마우리의 열쇠를 가져가야 합니다.", tag="선택사항"}, [82]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리", tag="선택사항"}, [83]={text="붉은해적단과 빚 퀘스트를 마친 뒤에는 현재 있는 무법항이나 그롬골에서 스토나드로 비행하세요. 스토나드 비행 지점이 없다면 먼저 그롬골로 날아가, 그늘숲 동쪽 입구와 저승바람 고개를 지나는 지상 경로로 가세요."}}},
    ["03-27"] = {name="슬픔의 늪", nameA="슬픔의 늪: {a:75}", tips={{k="取捨", text="갈렌 구출은 영상에서 언급한 호위 퀘스트예요. 길을 따라 몹을 정리한 뒤 우리를 여세요. 제출은 금고에서 하니 우리로 돌아올 필요 없어요."}, {k="取捨", text="보급품 보충( →), 바다의 위협( → → 1427 → 계속되는 위협), 신선한 고기는 레벨 47 이후 남동 해안으로 돌아올 때를 위해 남겨 두세요. 영상은 약 30:50에야 이 일대를 지나요."}, {k="提醒", text="서쪽에서 코르텔로의 두루마리를 전달한 뒤 Harbourage로 가서, 수정 퀘스트와 함께 길 잃은 자 연계 퀘스트 두 개를 마무리하세요. 경험치가 조금 더 필요하면 눈물의 연못 외곽의 일반 늪지 몹(약 60, 55)을 처치하거나, 다음 지역인 샛바람 해안에서 보충하세요.", s={{"서쪽에서 코르텔로의 두루마리를 전달한 뒤 Harbourage로 가서, 수정 퀘스트와 함께 길 잃은 자 연계 퀘스트 두 개를 마무리하세요"}, {"경험치가 조금 더 필요하면 눈물의 연못 외곽의 일반 늪지 몹(약 60, 55)을 처치하거나, 다음 지역인 샛바람 해안에서 보충하세요"}}}}, danger={[1]="갈렌에게 말을 걸기 전에 우리 옆과 야영지 출구를 먼저 정리하세요. 우리를 연 뒤 몹을 끌면 호위 대상과 내 체력을 동시에 챙기기 어려워요."}, grind={[1]={note="눈물의 연못 북쪽 외곽. 몹 밀도 보통, 일반 몹. 근처의 녹색 용족과 엮이지 않게 육지 쪽에서 끌어오세요. 기존 경로와 가까워 잠깐 경험치를 보충하기 좋아요."}, [2]={mob="늪지멀록 먹물쟁이", note="스토나드 남동쪽 멀록 지역. 몹 밀도 보통, 일반 몹. 야영지 밖의 혼자 있는 멀록을 한 마리씩 끌어서 무리에 휘말리지 마세요. 레벨 42~43에 알맞아요."}, [3]={mob="늪지멀록 청소부", note="같은 멀록 지역의 남쪽 가장자리. 몹 밀도 보통, 일반 몹. 같은 지역의 더 높은 레벨 점쟁이를 조심하고, 레벨 44 전에는 잉크스피터와 번갈아 처치하세요."}}, supply={[1]={npc="브레이크"}, [2]={npc="여관주인 카라쿨"}, [3]={npc="가라쉬"}, [4]={npc="툴타쉬"}, [5]={npc="툴타조르"}}, steps={[1]={text="스토나드에서 브랙 비행 지점(46.07, 54.83)을 확인하세요."}, [2]={hint="스토나드에 있는 날쌘돌이 헬그럼에게 니카의 보고서를 가져가야 합니다."}, [3]={npc="날쌘돌이 헬그럼", tgt="날쌘돌이 헬그럼"}, [4]={npc="펠제룰", tgt="펠제룰"}, [5]={text="서쪽 다리 아래와 Harbourage"}, [6]={hint="수수께끼를 풀어야 합니다."}, [7]={npc="젖은 두루마리", npcObj=true}, [8]={npc="젖은 두루마리", npcObj=true, tag="나중에 지나갈 때 진행"}, [9]={npc="막투르", tgt="막투르"}, [10]={npc="카라나", tgt="카라나"}, [11]={npc="펠루크", tgt="펠루크"}, [12]={hint="무법항에 있는 크라젝에게 꿈가루 10줌을 가져가야 합니다. 꿈가루는 슬픔의 늪에 있는 용들에게서 얻을 수 있습니다.", tag="선택사항"}, [13]={hint="겔키스에게 우호적인 평판을 유지하면서 잊혀진 땅의 겔키스 마을에 있는 현자 우텍에게 드레니시스트 파편 하나를 가져가야 합니다.", tag="선택사항"}, [14]={hint="드레노어 성역에 있는 잃어버린 드레나이 10명을 처치해야 합니다."}, [15]={hint="펠루크의 미끼를 훔친 잃어버린 드레나이 난민 낚시꾼을 찾아 미끼를 되찾아야 합니다."}, [16]={hint="슬픔의 늪의 피난처에 있는 막투르에게 드레니시스트 수정 6개를 가져가야 합니다."}, [17]={npc="노보루의 곤봉", npcObj=true, tag="드랍될 때만 진행, 선택사항", desc="순찰 중인 곤봉잡이 노보루를 처치하고 곤봉을 마우스 오른쪽 버튼으로 클릭하여 시작하세요."}, [18]={hint="슬픔의 늪에 있는 피난처의 우두머리에게 노보루의 곤봉을 가져가야 합니다.", tag="드랍될 때만 진행, 선택사항"}, [19]={npc="막투르", tgt="막투르", tag="드랍될 때만 진행, 선택사항"}, [20]={text="북동쪽 호위 및 눈물의 연못"}, [21]={npc="갈렌 굿워드", tgt="갈렌 굿워드"}, [22]={hint="갈렌이 위험에서 벗어나도록 호위한 다음 슬픔의 늪에 있는 그의 야영지를 찾아 갈렌의 금고를 열어야 합니다.", desc="우리 주변과 출구의 몹을 먼저 정리하고, 우리를 연 뒤 갈렌을 따라가세요. 제출은 경로 끝의 금고에서 해요."}, [23]={npc="갈렌의 금고", npcObj=true}, [24]={npc="막투르", tgt="막투르"}, [25]={npc="카라나", tgt="카라나"}, [26]={npc="펠루크", tgt="펠루크"}, [27]={hint="스토나드에 있는 펠제룰이 아탈라이 유물 10개를 모아 달라고 부탁했습니다."}, [28]={npc="펠제룰", tgt="펠제룰"}, [29]={npc="펠제룰", tgt="펠제룰", tag="가라앉은 사원 이후에 진행, 선택사항"}, [30]={npc="오웬 사드", tgt="오웬 사드", tag="선택사항", desc="야외와 던전 재료를 모두 모은 뒤 도서관으로 돌아가세요."}, [31]={hint="사서가 요청한 마법책 재료를 찾아 수집해야 합니다.", tag="선택사항", desc="야외와 던전 재료를 모두 모은 뒤 도서관으로 돌아가세요."}, [32]={npc="오웬 사드", tgt="오웬 사드", tag="선택사항", desc="야외와 던전 재료를 모두 모은 뒤 도서관으로 돌아가세요."}, [33]={text="스토나드에서 로그마로 바로 비행하세요. 이 구간 도중에 합류해 로그마 비행 지점이 없다면 강물터에서 로그마로 가는 지상 경로를 따라가고, 도착하면 먼저 비행 지점을 개방하세요."}}},
    ["03-28"] = {tips={{k="取捨", text="북쪽 순환과 황혼의 장막 연계는 전부 선택 사항이에요. 황혼 연계(No More!)를 이미 마쳤다면 먼저 볼데로크로 돌아가 뭉치주먹의 선포를 제출하고, 로그마에서 날뛰는 전사를 받으세요. 화약심지 항구 첫 방문 때는 해적을 정리하며 밀수품을 챙기세요. 두 번째 방문 때는 화약통을 모으고 폭탄병을 처치하고 밀수 택배를 전달한 뒤, 바다로 나가 선박을 폭파하세요. 바다 괴물 퀘스트는 동굴을 돌아가야 하니, 경험치가 부족하고 NPC가 퀘스트를 줄 때만 하세요."}, {k="提醒", text="레벨 45가 안 됐다면 샛바람 해안(약 84, 35-43)을 따라 동쪽바다 해적단원과 총병을 처치하세요. 항구 근처에서 보급할 수 있어요. 레벨 40~45에 파티가 있다면 Krol'dok Stronghold에 갈 수 있으니, 먼저 로그마에서 머그의 눈 / 황혼의 고서를 받으세요.", s={{"레벨 45가 안 됐다면 샛바람 해안(약 84, 35-43)을 따라 동쪽바다 해적단원과 총병을 처치하세요"}, {"항구 근처에서 보급할 수 있어요"}, {"레벨 40~45에 파티가 있다면 Krol'dok Stronghold에 갈 수 있으니, 먼저 로그마에서 머그의 눈 / 황혼의 고서를 받으세요"}}}, {k="交通", text="레벨 45가 되면 화약심지 항구(80.60, 54.60)에서 중립 배를 타고 타나리스 스팀휘들 항구(68.60, 23.00)로 간 뒤 가젯잔으로 가세요. 동부 왕국에 남으려면 육로로 로그마 비행 지점으로 돌아가세요. 타나리스에서 항구로 도착한 호드 캐릭터도 육로로 로그마로 가서 비행 지점을 개방하세요."}}, danger={[1]="정찰대장 바르가스는 정예예요. 파티를 모은 뒤 접근하고, 주변 순찰 몹을 먼저 따로 끌어내세요.", [2]="샛바람 해안의 총병은 멀리서 전투에 합류하기 쉬워요. 해적을 정리할 때는 해변을 따라 끌어 떼어 놓고, 배를 폭파하기 전에 승선 경로를 정리하세요."}, grind={[1]={mob="동쪽바다 해적단원", note="화약심지 항구 북쪽 샛바람 해안. 몹 밀집, 일반 몹. 총병들과 섞여 있으니 해변을 따라 한 마리씩 끌어오세요. 적대적인 경쟁도 함께 진행할 수 있어요."}, [2]={mob="동쪽바다 총병", note="샛바람 해안 중부. 몹 밀집, 일반 원거리 몹. 해적들과 섞여 있어요. 근접 직업은 지형을 이용해 해안 쪽으로 끌어오세요. 레벨 45까지 올리기에 알맞아요."}}, supply={[1]={npc="그라크나"}, [2]={npc="여관주인 지즈플링크"}, [3]={npc="미카 다비"}, [4]={npc="여관주인 지즈플링크"}, [5]={npc="그리젝"}, [6]={npc="크릭생크"}}, steps={[1]={text="황혼 연계(No More!)를 마치고 거인의 땅까지 갖고 있을 때만 북쪽 순환으로 뭉치주먹을 찾아가세요. 북쪽 순환을 마치면 먼저 로그마로 돌아가 뭉치주먹의 선포를 제출한 뒤, 서쪽 황혼의 장막으로 가세요. 이 연계를 건너뛰면 로그마에서 곧장 동쪽 화약심지 항구로 가세요.", tag="선택사항"}, [2]={npc="뭉치주먹", tgt="뭉치주먹", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [3]={npc="뭉치주먹", tgt="뭉치주먹", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [4]={hint="볼데로크의 뭉치주먹을 위해 황혼의 싸움꾼 7명과 황혼의 불꽃소환사 7명을 처치해야 합니다.", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항, 대상: 황혼의 싸움꾼/황혼의 불꽃소환사"}, [5]={hint="볼데로크에 있는 뭉치주먹을 위해 클렁크에게서 해골분쇄기를 입수해야 합니다.", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항, 대상: 클렁크"}, [6]={npc="좀좀", tgt="좀좀", tag="지나는 길에 진행, 선택사항"}, [7]={hint="좀좀을 볼데로크에 있는 뭉치주먹에게로 호위해야 합니다.", tag="지나는 길에 진행, 선택사항"}, [8]={npc="뭉치주먹", tgt="뭉치주먹", tag="지나는 길에 진행, 선택사항"}, [9]={npc="뭉치주먹", tgt="뭉치주먹", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [10]={npc="뭉치주먹", tgt="뭉치주먹", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [11]={npc="뭉치주먹", tgt="뭉치주먹", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [12]={hint="로그마에 있는 크롬로쉬에게 보고해야 합니다.", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [13]={npc="크롬로쉬", tgt="크롬로쉬", tag="북쪽 선행 퀘스트가 있으면 진행, 선택사항"}, [14]={text="로그마 서쪽에 있는 황혼 캠프"}, [15]={npc="크롬로쉬", tgt="크롬로쉬", tag="선택사항"}, [16]={hint="로그마 서쪽 언덕에서 다그로쉬를 찾아야 합니다.", tag="선택사항"}, [17]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [18]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [19]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [20]={hint="다그로쉬를 위해 황혼의 장막에서 황혼의 광신자 8명과 황혼의 타락자 8명, 황혼의 용사 8명을 처치해야 합니다.", tag="대상: 황혼의 광신자/황혼의 타락자/황혼의 용사, 선택사항"}, [21]={hint="다그로쉬를 위해 황혼의 장막에서 로그마 정찰병 5명을 구출해야 합니다.", tag="대상: 로그마 정찰병, 선택사항", desc="황혼 광신도를 처치해 열쇠 5개를 얻은 뒤, 로그마 정찰병이 갇힌 우리 다섯 개를 여세요."}, [22]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [23]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [24]={npc="다그로쉬", tgt="다그로쉬", tag="높은 레벨 몹을 잡을 수 있을 때 진행, 선택사항"}, [25]={hint="황혼의 장막에서 대군주 킬가르를 처치하고 머리카락을 다그로쉬에게 전달해야 합니다.", tag="높은 레벨 몹을 잡을 수 있을 때 진행, 선택사항, 대상: 대군주 킬가르"}, [26]={npc="다그로쉬", tgt="다그로쉬", tag="높은 레벨 몹을 잡을 수 있을 때 진행, 선택사항"}, [27]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항"}, [28]={hint="서신을 로그마에 있는 크롬로쉬에게 전달해야 합니다.", tag="선택사항"}, [29]={npc="크롬로쉬", tgt="크롬로쉬", tag="선택사항"}, [30]={text="선택 파티: 정찰대장 바르가스"}, [31]={npc="현상수배", npcObj=true, tag="파티가 있을 때, 선택사항, 게임 내 확인이 필요합니다"}, [32]={hint="정찰대장의 눈을 로그마에 있는 핏빛코 네자에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항, 대상: 정찰대장 바르가스 / 스카우트 레이놀즈", desc="정찰대장은 정예예요. 파티를 먼저 구하고, 처치한 뒤 로그마에 증거를 제출하세요."}, [33]={npc="핏빛코 네자", tgt="핏빛코 네자", tag="파티가 있을 때, 선택사항"}, [34]={text="화약심지 항구 남쪽 → 항구에서 퀘스트 수락 → 샛바람 해안"}, [35]={npc="색을 입힌 가죽", npcObj=true, tag="선택사항", desc="바다 괴물 퀘스트는 성채 근처 동굴을 돌아가야 해요. 시간이 되고 수락할 수 있을 때 진행하세요."}, [36]={hint="화약심지 항구에서 색칠된 가죽을 보고 괴물의 정체를 알아낼 수 있는 사람을 찾아야 합니다.", tag="선택사항"}, [37]={npc="덫발톱", tgt="아르고 브라인휘슬", tag="선택사항"}, [38]={npc="덫발톱", tgt="아르고 브라인휘슬", tag="선택사항", desc="바다 괴물 퀘스트는 성채 근처 동굴을 돌아가야 해요. 시간이 되고 수락할 수 있을 때 진행하세요."}, [39]={hint="두 번 재주문된 소포를 강물터 화약심지 항구에 있는 부두장 위즈버즈에게 가져가야 합니다.", tag="선택사항"}, [40]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈", tag="선택사항"}, [41]={hint="검을 로그마 동쪽 부두에 있는 크레자 다크쏜의 지인에게 전달해야 합니다."}, [42]={npc="프리즈 프래즐스파크", tgt="프리즈 프래즐스파크"}, [43]={npc="프리즈 프래즐스파크", tgt="프리즈 프래즐스파크", desc="호드는 로그마의 검 연계를 진행하세요. Friz가 이 단계를 주지 않으면 부두 퀘스트를 먼저 하세요."}, [44]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [45]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [46]={npc="핌보 그리스미츠", tgt="핌보 그리스미츠"}, [47]={npc="현상수배!", npcObj=true, tag="게임 내 확인이 필요합니다"}, [48]={hint="샛바람 해안에서 멀록 점쟁이 8마리와 멀록 전사 8마리를 처치해야 합니다.", tag="대상: 멀록 전사 / 멀록 점쟁이"}, [49]={hint="핌보 그리스미츠에게 줄 멀록 눈알 12개와 모래 집게발 고기 6개를 모아야 합니다.", tag="대상: 멀록 점쟁이 / 멀록 파도살이 / 멀록 약탈꾼 / 모래게 / 큰집게발 바닷게"}, [50]={hint="덫발톱의 집게발을 핌보 그리스미츠에게 전달해야 합니다.", tag="대상: 덫발톱"}, [51]={hint="화약심지 항구 북쪽의 샛바람 해안에서 동쪽바다 해적단원 10명과 동쪽바다 총병 10명을 처치해야 합니다.", tag="대상: 동쪽바다 해적단원 / 동쪽바다 총병"}, [52]={hint="화약심지 항구에 있는 프리즈 프래즐스파크를 위해 밀수된 물품 8개를 모아야 합니다."}, [53]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [54]={npc="핌보 그리스미츠", tgt="핌보 그리스미츠"}, [55]={npc="핌보 그리스미츠", tgt="핌보 그리스미츠"}, [56]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [57]={npc="프리즈 프래즐스파크", tgt="프리즈 프래즐스파크"}, [58]={npc="프리즈 프래즐스파크", tgt="프리즈 프래즐스파크"}, [59]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [60]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [61]={hint="동쪽바다 화약통 5개를 훔쳐 부두장 위즈버즈에게 가져가야 합니다."}, [62]={hint="부두장 위즈버즈를 위해 동쪽바다 약탈병 8명과 동쪽바다 폭격수 8명을 처치해야 합니다."}, [63]={hint="아르고 브라인휘슬에게 줄 야수 내장 15개와 부패살점 버섯 8개를 수집해야 합니다.", tag="선택사항", desc="첫 번째 핀: 다 자란 멧돼지. 두 번째: 동굴 입구. 내부에는 오우거가 있습니다."}, [64]={hint="프리즈 특제품을 샛바람 해안에 있는 대장 벤트코인에게 전달해야 합니다."}, [65]={npc="대장 헤인스", tgt="선장 벤트코인"}, [66]={npc="덫발톱", tgt="아르고 브라인휘슬", tag="선택사항"}, [67]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [68]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [69]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈", desc="화약통과 걷잡을 수 없는 확장을 한 번에 제출한 뒤 선박 폭파 퀘스트를 받으세요."}, [70]={hint="동쪽바다 해적단의 배 3척에 각각 원격 폭발물을 설치해야 합니다.", desc="퀘스트로 받은 폭약을 가지고 해적선 세 척에 가서, 한 척당 하나씩 설치하세요. 동해 해적은 해안가에 있습니다. 배에 올라 2층 갑판 대포 옆의 포탄 더미를 찾으세요."}, [71]={npc="부두장 위즈버즈", tgt="부두장 위즈버즈"}, [72]={npc="덫발톱", tgt="아르고 브라인휘슬", tag="선택사항"}, [73]={hint="큼직한 미끼 덩어리를 사용해 바다 괴물을 유인해야 합니다. 그런 다음 머리를 아르고 브라인휘슬에게 전달해야 합니다.", tag="대상: 거대한 트레샤돈, 선택사항", desc="멀록 섬의 수중 난파선 옆에서 큰 미끼 덩어리를 사용해 바다 괴물을 불러내고, 처치한 뒤 머리를 주우세요."}, [74]={npc="덫발톱", tgt="아르고 브라인휘슬", tag="선택사항"}, [75]={text="선택 던전: Krol'dok Stronghold"}, [76]={npc="크롬로쉬", tgt="크롬로쉬", tag="파티가 있을 때만 입장, 선택사항"}, [77]={npc="트란굴", tgt="트란굴", tag="파티가 있을 때만 입장, 선택사항"}, [78]={hint="크롤도크 보루에 침투한 뒤, 우두머리가 죽었다는 증거를 확보해 크롬로쉬에게 가야 합니다.", tag="파티가 있을 때만 입장, 선택사항"}, [79]={hint="크롤도크 보루에서 황혼의 고서를 회수해야 합니다.", tag="파티가 있을 때만 입장, 선택사항", desc="책은 던전 우두머리 나르구르크가 떨어뜨립니다."}, [80]={npc="크롬로쉬", tgt="크롬로쉬", tag="파티가 있을 때만 입장, 선택사항"}, [81]={npc="트란굴", tgt="트란굴", tag="파티가 있을 때만 입장, 선택사항"}, [82]={npc="파라드", tgt="파라드", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45 솔로 던전 연계예요. 저택에서 받을 수 있을 때 겸사겸사 진행하세요."}, [83]={hint="계획을 들을 준비가 되는 대로 파라드와 대화해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45 솔로 던전 연계예요. 저택에서 받을 수 있을 때 겸사겸사 진행하세요."}, [84]={npc="파라드", tgt="파라드", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45 솔로 던전 연계예요. 저택에서 받을 수 있을 때 겸사겸사 진행하세요."}, [85]={npc="파라드", tgt="파라드", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45부터 받을 수 있고 퀘스트 레벨은 50이에요. 타나리스에 도착한 뒤 던전에 들어가는 것을 권해요."}, [86]={hint="줄파락에서 카즈도르의 부적을 찾아낸 후, 라벤홀트 장원에 있는 파라드에게 가져가야 합니다. 이 퀘스트는 혼자 수행해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45부터 받을 수 있고 퀘스트 레벨은 50이에요. 타나리스에 도착한 뒤 던전에 들어가는 것을 권해요."}, [87]={npc="파라드", tgt="파라드", tag="선택사항, 게임 내 확인이 필요합니다", desc="레벨 45부터 받을 수 있고 퀘스트 레벨은 50이에요. 타나리스에 도착한 뒤 던전에 들어가는 것을 권해요."}, [88]={hint="뒤틀린 불의 토템 5개, 뒤틀린 대지 토템 5개, 뒤틀린 바람 토템 5개, 뒤틀린 물 토템 5개를 모아 버섯구름 봉우리에 있는 프레이트 클라우드시어에게 전달해야 합니다.", tag="선택사항", desc="불은 황야의 땅, 땅은 슬픔의 늪, 바람은 잊혀진 땅, 물은 먼지진흙 습지대에 있어요. 모두 모으면 버섯구름 봉우리에서 제출하세요."}, [89]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="불은 황야의 땅, 땅은 슬픔의 늪, 바람은 잊혀진 땅, 물은 먼지진흙 습지대에 있어요. 이 구간에서 겸사겸사 모으고, 다 모이면 버섯구름 봉우리로 돌아가 제출하세요. 바스라에게서 받았다면 퀘스트 로그 안내에 따라 알터랙으로 돌아가 제출할 수도 있어요."}, [90]={npc="라우 클리프러너", tgt="라우 클리프러너", tag="선택사항", desc="뒤틀린 토템 네 종류를 모두 먼저 완료해야 해요. 증기 웅덩이를 작동시킨 뒤 가시멧돼지를 조심하세요."}, [91]={hint="뒤틀린 토템을 사용해 가시멧돼지 의식을 막아야 합니다.", tag="선택사항, 대상: 맹렬한 폭풍우", desc="뒤틀린 토템 네 종류를 모두 먼저 완료해야 해요. 증기 웅덩이를 작동시킨 뒤 가시멧돼지를 조심하세요."}, [92]={npc="라우 클리프러너", tgt="라우 클리프러너", tag="선택사항", desc="뒤틀린 토템 네 종류를 모두 먼저 완료해야 해요. 증기 웅덩이를 작동시킨 뒤 가시멧돼지를 조심하세요."}, [93]={npc="라우 클리프러너", tgt="라우 클리프러너", tag="선택사항, 게임 내 확인이 필요합니다", desc="먼저 높새바람 봉우리에서 내 부름에 응하라을 완료해야 해요.", star={"폭풍의 분노 / 번개의 손아귀 / 파도인도자의 발톱"}}, [94]={hint="폭풍우의 눈을 알터랙 산맥에 있는 바람감시자 바스라에게 전달해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="먼저 높새바람 봉우리에서 내 부름에 응하라을 완료해야 해요."}, [95]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항, 게임 내 확인이 필요합니다", desc="먼저 높새바람 봉우리에서 내 부름에 응하라을 완료해야 해요.", star={"폭풍의 분노 / 번개의 손아귀 / 파도인도자의 발톱"}}}},
    ["05-d19"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="강물터 48.60, 26.30", pickup="강물터 로그마에서 먼저 트란굴의 햇살숲과 몽둥이발 연계를 하고, 볼데로크의 뭉치주먹 선행 퀘스트를 하세요. 그다음 로그마에서 서쪽으로 황혼 야영지에 들어가 다그로쉬와 크래그로그를 찾고, 로그마로 돌아가 편지를 제출한 뒤 눈과 고서 퀘스트를 받으세요. 로그마로 날아가거나 카르가스에서 걸어 강물터에 들어가, 햇살숲 정북쪽 고지에서 입구를 찾으세요. 두꺼운 가죽 4개와 철괴 12개는 거푸집 후속 퀘스트를 위해 미리 챙기세요.", pickupS={{"강물터 로그마에서 먼저 트란굴의 햇살숲과 몽둥이발 연계를 하고, 볼데로크의 뭉치주먹 선행 퀘스트를 하세요"}, {"그다음 로그마에서 서쪽으로 황혼 야영지에 들어가 다그로쉬와 크래그로그를 찾고, 로그마로 돌아가 편지를 제출한 뒤 눈과 고서 퀘스트를 받으세요"}, {"로그마로 날아가거나 카르가스에서 걸어 강물터에 들어가, 햇살숲 정북쪽 고지에서 입구를 찾으세요"}, {"두꺼운 가죽 4개와 철괴 12개는 거푸집 후속 퀘스트를 위해 미리 챙기세요"}}, tips={{k="動線", text="광산에서 노예파괴자 그록스 → 황혼의 사령관 자르모크 → 아슈카 옆 대장간에서 거푸집 → 나르구르크에게서 황혼의 고서 → 다리의 투프 → 군주 머그에게서 머그의 눈. 가는 길에 황혼 신도의 귀를 모두 모으세요."}, {k="取捨", text="강물터 로그마, 강물터 볼데로크, 화약심지 항구의 선행 퀘스트를 먼저 끝낸 뒤 파티를 모으면 한 번에 세 가지를 완료할 수 있습니다. 거푸집 재료는 미리 준비해 두고, 얻으면 제출하세요."}, {k="說明", text="입구는 Sunnyglade 바로 북쪽에 있으며, 요새 문 옆에 또 다른 차원문이 있습니다.", s={{"입구는 Sunnyglade 바로 북쪽에 있으며, 요새 문 옆에 또 다른 차원문이 있습니다"}}}}, steps={[1]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [2]={hint="풀잎개울에서 풀잎개울 농장 일꾼 12명을 처치하고 크롬로쉬에게 성공 소식을 전해야 합니다.", tag="던전 선행"}, [3]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [4]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [5]={hint="풀잎개울 얼라이언스 농장에서 먹이 자루 6개를 훔쳐 크롬로쉬에게 가야 합니다.", tag="던전 선행"}, [6]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [7]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [8]={hint="강 남쪽에서 파홀드 사제 8명과 파홀드 정찰병 12명을 처치해야 합니다.", tag="던전 선행"}, [9]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [10]={npc="트란굴", tgt="트란굴"}, [11]={npc="트란굴", tgt="트란굴"}, [12]={hint="로그마의 트란굴을 위해 황혼의 약탈병 8명과 황혼의 수련사 8명을 처치해야 합니다.", tag="대상: 황혼의 약탈병/황혼의 망치단 흑마술사/황혼의 수련사"}, [13]={hint="햇살숲에 있는 황혼의 망치단 흑마술사에게서 황혼의 서신 3개를 회수해 로그마에 있는 트란굴에게 반납해야 합니다.", tag="대상: 황혼의 망치단 흑마술사"}, [14]={npc="트란굴", tgt="트란굴"}, [15]={npc="트란굴", tgt="트란굴"}, [16]={npc="트란굴", tgt="트란굴", preText="다가오는 황혼, 황혼의 서신"}, [17]={hint="햇살숲의 황혼의 망치단 광부를 설득해 비밀을 실토하게 해야 합니다."}, [18]={npc="몽둥이발", tgt="몽둥이발"}, [19]={npc="몽둥이발", tgt="몽둥이발", preText="답을 캐내다"}, [20]={hint="몽둥이발을 위해 햇살숲 지하 동굴에서 실종된 오우거를 찾아야 합니다."}, [21]={npc="강화된 투사", tgt="황혼의 투사"}, [22]={npc="강화된 투사", tgt="황혼의 투사", preText="보라색 녀석들"}, [23]={npc="몽둥이발", tgt="몽둥이발", preText="보라색 녀석들"}, [24]={hint="강화된 투사 5명과 황혼의 의식술사 10명을 처치한 후 햇살숲에 있는 몽둥이발에게 가야 합니다.", tag="대상: 강화된 투사/황혼의 의식술사"}, [25]={hint="햇살숲 지하 동굴에 설치된 황혼의 의식진 5개를 파괴해야 합니다.", desc="동굴을 따라 찾아보세요."}, [26]={npc="몽둥이발", tgt="몽둥이발"}, [27]={npc="몽둥이발", tgt="몽둥이발"}, [28]={npc="몽둥이발", tgt="몽둥이발", desc="정예입니다. 먼저 파티원과 함께 처치하세요.", preText="보라색 녀석들, 가증스러운 빛"}, [29]={hint="햇살숲 동굴에서 초그자크를 처치하고 머리카락을 수집해 몽둥이발에게 전달해야 합니다.", tag="대상: 초그자크", desc="정예입니다. 먼저 파티원과 함께 처치하세요."}, [30]={npc="몽둥이발", tgt="몽둥이발", desc="정예입니다. 먼저 파티원과 함께 처치하세요."}, [31]={npc="몽둥이발", tgt="몽둥이발", preText="황혼은 이제 끝이다!"}, [32]={hint="초그의 머리카락을 로그마에 있는 트란굴에게 전달해야 합니다."}, [33]={npc="트란굴", tgt="트란굴"}, [34]={npc="트란굴", tgt="트란굴", preText="소식을 퍼뜨려라"}, [35]={hint="초그의 머리카락을 북쪽의 오우거 도시로 전달해야 합니다."}, [36]={npc="뭉치주먹", tgt="뭉치주먹"}, [37]={npc="뭉치주먹", tgt="뭉치주먹", preText="거인들의 땅"}, [38]={hint="볼데로크의 뭉치주먹을 위해 황혼의 싸움꾼 7명과 황혼의 불꽃소환사 7명을 처치해야 합니다.", tag="대상: 황혼의 싸움꾼/황혼의 불꽃소환사"}, [39]={npc="뭉치주먹", tgt="뭉치주먹"}, [40]={npc="뭉치주먹", tgt="뭉치주먹", preText="거인들의 땅"}, [41]={hint="볼데로크에 있는 뭉치주먹을 위해 클렁크에게서 해골분쇄기를 입수해야 합니다.", tag="대상: 클렁크"}, [42]={npc="뭉치주먹", tgt="뭉치주먹"}, [43]={npc="뭉치주먹", tgt="뭉치주먹", preText="자격 없는 투사"}, [44]={hint="로그마에 있는 크롬로쉬에게 보고해야 합니다."}, [45]={npc="크롬로쉬", tgt="크롬로쉬"}, [46]={npc="크롬로쉬", tgt="크롬로쉬", preText="뭉치주먹의 선포"}, [47]={hint="로그마 서쪽 언덕에서 다그로쉬를 찾아야 합니다."}, [48]={npc="다그로쉬", tgt="다그로쉬"}, [49]={npc="다그로쉬", tgt="다그로쉬", preText="날뛰는 전사"}, [50]={npc="다그로쉬", tgt="다그로쉬", preText="날뛰는 전사"}, [51]={npc="다그로쉬", tgt="다그로쉬", tag="선택사항", preText="날뛰는 전사"}, [52]={hint="주변 동굴에서 볼데로크 오우거를 찾아야 합니다.", tag="선택사항"}, [53]={npc="오우거 광부", tgt="크라그로그", tag="선택사항"}, [54]={npc="오우거 광부", tgt="크라그로그", tag="선택사항", desc="황혼의 장막 안의 크래그로그에게서 받으세요.", preText="꿈틀거리는 불만"}, [55]={hint="다그로쉬를 위해 황혼의 장막에서 황혼의 광신자 8명과 황혼의 타락자 8명, 황혼의 용사 8명을 처치해야 합니다.", tag="대상: 황혼의 광신자/황혼의 타락자/황혼의 용사"}, [56]={hint="다그로쉬를 위해 황혼의 장막에서 로그마 정찰병 5명을 구출해야 합니다.", tag="대상: 로그마 정찰병"}, [57]={hint="오우거 광부 5명을 영입해야 합니다.", tag="선택사항", desc="확인된 광부 좌표는 세 곳이고, 다른 위치는 알 수 없습니다."}, [58]={npc="오우거 광부", tgt="크라그로그", tag="선택사항"}, [59]={npc="다그로쉬", tgt="다그로쉬"}, [60]={npc="다그로쉬", tgt="다그로쉬"}, [61]={npc="다그로쉬", tgt="다그로쉬", desc="길을 열어라와 사슬을 부숴라를 완료했는데도 나타나지 않으면, 오우거 광부의 모집 퀘스트를 먼저 끝낸 뒤 다시 확인하세요.", preText="길을 열어라, 사슬을 부숴라"}, [62]={hint="황혼의 장막에서 대군주 킬가르를 처치하고 머리카락을 다그로쉬에게 전달해야 합니다.", tag="대상: 대군주 킬가르"}, [63]={npc="다그로쉬", tgt="다그로쉬"}, [64]={npc="다그로쉬", tgt="다그로쉬", desc="다그로쉬는 Overlord Kilgar의 머리를 제출한 뒤 퀘스트를 줍니다.", preText="적의 숨통을 끊어라"}, [65]={npc="다그로쉬", tgt="다그로쉬", preText="적의 숨통을 끊어라"}, [66]={hint="서신을 로그마에 있는 크롬로쉬에게 전달해야 합니다."}, [67]={npc="크롬로쉬", tgt="크롬로쉬"}, [68]={npc="크롬로쉬", tgt="크롬로쉬", preText="때가 왔다, 형제여..."}, [69]={npc="트란굴", tgt="트란굴", preText="때가 왔다, 형제여..."}, [70]={text="Krol'dok Stronghold 입구"}, [71]={hint="크롤도크 보루 내 황혼의 망치단에게서 이교도 귀 15개를 수집해야 합니다.", desc="먼저 자르모크 주변의 신도를 정리한 뒤 수량이 모자란지 확인하세요. 던전 사용자 지도 자르모크 39.10, 69.40 (황혼 신도의 귀를 떨어뜨리는 우두머리 중 하나) 위치: 광산을 지난 뒤 자르모크 주변을 정리하고, 요새 통로에서 귀를 더 모으세요.", spot="광산을 지난 뒤 자르모크 주변을 정리하고, 요새 통로에서 귀를 더 모으세요."}, [72]={npc="크롤도크 거푸집", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="툰크가 거푸집을 떨어뜨립니다. 우클릭해 퀘스트를 받으세요. 툰크는 전쟁 관리자 아슈카 옆 대장간에 있습니다. 거푸집을 주운 뒤 우클릭하세요."}, [73]={hint="크롤도크 보루에서 황혼의 고서를 회수해야 합니다.", desc="던전 사용자 지도 나르구르크 34.70, 50.30. 위치: 아슈카를 지나 황혼 술사 구역에서 나르구르크를 찾으세요.", spot="아슈카를 지나 황혼 술사 구역에서 나르구르크를 찾으세요."}, [74]={hint="크롤도크 보루에 침투한 뒤, 우두머리가 죽었다는 증거를 확보해 크롬로쉬에게 가야 합니다.", desc="던전 사용자 지도 머그 71.00, 14.30. 위치: 투프가 지키는 다리를 지나 가장 안쪽 방에서 군주 머그를 처치하세요.", spot="투프가 지키는 다리를 지나 가장 안쪽 방에서 군주 머그를 처치하세요."}, [75]={npc="크롬로쉬", tgt="크롬로쉬"}, [76]={npc="트란굴", tgt="트란굴"}, [77]={hint="로그마에서 거푸집에 관해 아는 사람을 찾아야 합니다.", tag="선택사항"}, [78]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항"}, [79]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항", desc="재료는 경매장에서 미리 준비해도 됩니다.", preText="크롤도크 거푸집"}, [80]={hint="두꺼운 가죽 4개와 철 주괴 12개를 크레자 다크쏜에게 가져가야 합니다.", tag="선택사항", desc="재료는 경매장에서 미리 준비해도 됩니다."}, [81]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항", desc="재료는 경매장에서 미리 준비해도 됩니다."}, [82]={npc="다그로쉬", tgt="다그로쉬", desc="로그마에서 서쪽으로 가서 다그로쉬에게 돌아가세요."}}},
    ["04-29"] = {name="타나리스", nameA="타나리스: {a:977} & {a:976}", shortA="타나리스: {a:977} +", tips={{k="取捨", text="열사항 첫 방문 때 해적 모자, 처치, 현상 수배, 화물 상자 퀘스트를 한꺼번에 하세요. TUG는 페랄라스를 먼저 한 뒤 돌아와 항구 해적을 처리해요. 이 경로는 화약심지 항구에서 배로 열사항에 가므로, 먼저 해안을 정리해도 영상의 지점 순서가 그대로 유지돼요."}, {k="取捨", text="계곡천둥매의 영혼은 페랄라스 모자케 야영지에서, 모래망치의 빚은 모래망치 야영지에서 하세요. 맥킨리에게 배달는 슬픔의 늪으로 가는 길에 가시덤불 골짜기 무법항에서 제출하도록 남겨 두세요."}, {k="提醒", text="다음 지점에 필요한 레벨이 안 됐다면 황무지 야영지(59.40, 24.71)나 Lost Rigger Cove 입구(70.90, 42.48)의 일반 몹을 순환하며 처치하세요. 줄파락 파티가 있다면 왕쇠똥구리 껍질, 자동 탐사막대, 트롤 경화제를 받아 가젯잔과 모래망치 야영지에서 제출하세요.", s={{"다음 지점에 필요한 레벨이 안 됐다면 황무지 야영지(59.40, 24.71)나 Lost Rigger Cove 입구(70.90, 42.48)의 일반 몹을 순환하며 처치하세요"}, {"줄파락 파티가 있다면 왕쇠똥구리 껍질, 자동 탐사막대, 트롤 경화제를 받아 가젯잔과 모래망치 야영지에서 제출하세요"}}}}, danger={[1]="칼리프는 순찰하며 호위가 있을 수 있어요. 먼저 길가의 황무지 도적을 정리하고, 그가 트인 곳에 오면 처치하세요."}, grind={[1]={mob="남쪽바다해적단 무법자", note="Lost Rigger Cove 입구. 일반 몹 밀집, 해적 퀘스트를 하는 플레이어와 겹치기 쉬워요. 바깥쪽을 따라 해변 쪽으로 정리하며 해적 퀘스트 드랍품도 함께 모으세요."}, [2]={mob="남쪽바다해적단 칼잡이", note="부두 바깥쪽의 일반 몹. 해적 입구에서 몹을 빼앗기면 이곳으로 옮기세요. 바깥쪽에서 끌어와 부두 경비병을 함께 끌지 않게 하세요."}}, supply={[1]={npc="벌크렉 레이지피스트"}, [2]={npc="여관주인 피즈그림블"}, [3]={npc="링클 굿스틸"}, [4]={npc="여관주인 피즈그림블"}, [5]={npc="브리즈릭 벅샷"}, [6]={npc="긱킥스"}}, steps={[1]={text="강물터의 화약심지 항구(80.60, 54.60)에서 열사항행 배를 타고 타나리스(68.60, 23.00)에서 내리세요. 오그리마에서 출발하고 가젯잔 비행 지점을 이미 개방했다면 비행하세요. 처음 방문이라면 높새바람 봉우리에서 Shimmering Flats 남쪽 경사를 걸어 가젯잔까지 갈 수 있어요."}, [2]={text="항구에서 수락한 후 마을에서 재보급하세요."}, [3]={npc="거만한 의류상", tgt="거만한 의류상"}, [4]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [5]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [6]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [7]={npc="스톨리", tgt="스톨리"}, [8]={npc="예킨야", tgt="예킨야", desc="페랄라스의 모자케 야영지 퀘스트는 페랄라스에서 하고, 타나리스의 가젯잔과 모래망치 야영지 퀘스트는 열사항에서 제출하세요."}, [9]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항", desc="모래망치 야영지에서 겸사겸사 하고, 나중에 열사항에서 제출하세요."}, [10]={text="열사항에서 대로를 따라 서쪽 가젯잔으로 가세요. 호드 비행 조종사 벌크렉 레이지피스트(51.60, 25.44)에게서 비행 지점을 개방하고, 여관주인 피즈그림블(52.51, 27.91)에게 귀환석을 임시로 설정하세요. 페랄라스 모자케 야영지에 가면 다시 설정하세요."}, [11]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [12]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [13]={npc="트란렉", tgt="트란렉", tag="선택사항", desc="줄파락에 갈 계획일 때만 수락하세요."}, [14]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐", tag="선택사항", desc="줄파락 계단 이벤트에서 떨어져요.", star={"석공 조합 반지", {"ROGUE", "HUNTER", "DRUID"}}}, [15]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머", tag="선택사항", desc="줄파락에 갈 계획일 때만 수락하세요."}, [16]={text="황무지 야영지와 Lost Rigger Cove"}, [17]={hint="가젯잔의 동쪽에서 10명의 사막유랑단 약탈자와 좀도둑을 처치한 후, 선임기술자 빌지위즐에게 돌아와 보고하십시오."}, [18]={hint="가젯잔에 있는 양수기기사 루글룬켓에게 사막유랑단 물주머니 5개를 가져가야 합니다."}, [19]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [20]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [21]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [22]={hint="가젯잔에 있는 선임기술자 빌지위즐을 위해 사막유랑단 도적 8명, 사막유랑단 암살자 6명, 그리고 사막유랑단 어둠마법사 10명을 처치해야 합니다.", desc="가젯잔 남동쪽에서 황무지 야영지로 들어가세요."}, [23]={hint="칼리프 스콜피드스팅을 처치하고 그 증거로 그의 머리카락을 칼리프 스콜피드스팅의 머리카락을 가져다주어야 합니다.", desc="수행원이 있을 수 있어요. 그가 야영지 가장자리에 올 때까지 기다렸다가 끌어오세요."}, [24]={hint="타나리스의 스팀휘들 항구에 있는 보안과장 빌지위즐이 남쪽바다해적단 무법자, 약탈자, 부두일꾼, 칼잡이를 각각 10명씩 처치해 달라고 부탁했습니다."}, [25]={hint="타나리스의 스팀휘들 항구에 있는 거만한 의류상의 부탁으로 남쪽바다 해적 모자 20개를 모아서 가져가야 합니다.", desc="남쪽바다해적단 처리반을 진행할 때는 처치한 몹을 모두 약탈하세요."}, [26]={hint="앙드레를 처치하고 그 증거로 그의 머리카락을 스팀휘들 항구에 있는 보안과장 빌지위즐에게 가져가야 합니다."}, [27]={hint="스팀휘들 항구에 있는 스톨리에게 뱃짐을 찾아다 주어야 합니다."}, [28]={npc="선적 일정표", npcObj=true, tag="선택사항", desc="남쪽바다 해적단을 처치해 떨어뜨린 가방을 열어 시간표를 얻고, 인벤토리에서 시간표를 우클릭해 퀘스트를 받으세요."}, [29]={hint="스팀휘들 항구의 관계자에게 선적 일정표에 대해 보고하십시오.", tag="선택사항"}, [30]={text="해안을 따라 북쪽 열사항으로 돌아가 항구의 해적과 화물 퀘스트를 한꺼번에 제출하세요."}, [31]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [32]={npc="거만한 의류상", tgt="거만한 의류상"}, [33]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [34]={npc="스톨리", tgt="스톨리"}, [35]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항"}, [36]={npc="스톨리", tgt="스톨리", desc="스토나드와 샛바람 해안 퀘스트는 남겨 두었다가 무법항에서 제출하세요."}, [37]={text="황무지 두 번째 묶음과 현상 수배 퀘스트를 제출하러 가젯잔으로 돌아가세요. 귀환석이 가젯잔에 설정되어 있으면 바로 귀환하세요."}, [38]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [39]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}}},
    ["04-30"] = {name="페랄라스", nameA="페랄라스: {a:1099}", tips={{k="取捨", text="전투 계획서까지 Woodpaw 놀 선행 연계를 쭉 진행하면, 모자케 야영지 남동쪽에서 함께 할 수 있는 주크애쉬 퀘스트 두 개가 열려요."}, {k="取捨", text="OOX-22/FE 조난 신호기를 얻었다면 가방에 보관하세요. 호위 퀘스트와 해안 거인, 물의 정령은 모자케 야영지에 다시 올 때를 위해 남겨 두세요."}, {k="提醒", text="레벨 47이 안 됐다면 거친흉터 골짜기의 설인(55.29, 53.76)이나 야영지 북쪽의 골두니 오우거(75.13, 34.86)를 처치하세요. 처치한 뒤 야영지로 돌아가 제출하세요.", s={{"레벨 47이 안 됐다면 거친흉터 골짜기의 설인(55.29, 53.76)이나 야영지 북쪽의 골두니 오우거(75.13, 34.86)를 처치하세요"}, {"처치한 뒤 야영지로 돌아가 제출하세요"}}}}, danger={[1]="모자케 북쪽의 골두니 야영지에는 마법사와 야만병이 섞여 있어요. 코발트를 캐기 전에 퇴로를 먼저 정리하고, 야영지 깊숙이 들어가지 마세요."}, grind={[1]={mob="원시설인", note="거친흉터 골짜기 바깥 비탈. 일반 설인이 모여 있어 연달아 처치하며 설인 가죽을 모으기 좋아요. 동굴 입구에 같은 퀘스트를 하는 플레이어가 있으면 비탈을 돌며 번갈아 사냥하세요."}, [2]={mob="덩치큰 원시설인", note="거친흉터 골짜기 남서쪽. 일반 설인의 레벨이 조금 더 높아요. 바깥쪽에서 근접 몹을 끌어오고 붐비는 동굴 입구는 피하세요."}}, supply={[1]={npc="쉬인"}, [2]={npc="여관주인 그룰"}, [3]={npc="카윈드 트루에임"}, [4]={npc="여관주인 그룰"}, [5]={npc="카윈드 트루에임"}, [6]={npc="탈후스"}}, steps={[1]={text="모자케 비행 지점을 개방했다면 가젯잔에서 바로 비행하세요. 처음 방문이라면 영상대로 가젯잔에서 북쪽 Shimmering Flats로 올라가 버섯구름 봉우리를 지나 서쪽 길로 페랄라스에 들어가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={nodeA="{a:1099}", desc="쉬인에게서 비행 지점을 개방하세요."}, [3]={text="여관주인 그룰(74.80, 45.18)에게서 귀환석을 설정하세요."}, [4]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [5]={npc="올윈 기즈믹", tgt="올윈 기즈믹"}, [6]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [7]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [8]={npc="의술사 우제리", tgt="의술사 우제리"}, [9]={npc="로크 올한", tgt="로크 올한"}, [10]={text="캠프 주변과 북쪽 골두니 퀘스트 전반부"}, [11]={hint="모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 갈기 10개를 가져가야 합니다."}, [12]={hint="모자케 야영지에 있는 로크 올한이 골두니 오우거 10명, 골두니일족 오우거 마법사 10명, 골두니일족 투사 5명을 처치해달라고 부탁했습니다."}, [13]={hint="모자케 야영지에 있는 올윈 기즈믹이 골두니 코발트 12개를 가져다 달라고 부탁했습니다.", desc="골두니 야영지의 파란 흙더미 옆에서 퀘스트 삽을 사용하세요."}, [14]={npc="골두니 두루마리", npcObj=true, desc="북쪽 지면에 있는 골두니 두루마리를 클릭하세요."}, [15]={hint="모자케 야영지에 있는 로크 올한에게 골두니 두루마리를 가져가야 합니다."}, [16]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [17]={npc="로크 올한", tgt="로크 올한"}, [18]={npc="올윈 기즈믹", tgt="올윈 기즈믹"}, [19]={npc="로크 올한", tgt="로크 올한"}, [20]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [21]={npc="로크 올한", tgt="로크 올한"}, [22]={npc="로크 올한", tgt="로크 올한"}, [23]={hint="1시간 안에 덩굴발일족 우두머리 5마리를 처치하고 아도겐 스위프트스트라이더에게 되돌아와야 합니다.", desc="제한 시간 1시간. 남쪽 덩굴발 언덕에서 5마리를 처치하고 즉시 돌아와 제출하세요."}, [24]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [25]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [26]={hint="모자케 야영지 남쪽에 있는 놀 야영지에서 덩굴발일족 전투계획서를 찾아야 합니다."}, [27]={npc="덩굴발일족 작전도", npcObj=true}, [28]={npc="덩굴발일족 작전도", npcObj=true}, [29]={hint="모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 전투계획서를 가지고 가야 합니다."}, [30]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [31]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [32]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [33]={text="중앙의 요정용, 서쪽의 거친흉터 골짜기"}, [34]={hint="모자케 야영지에 있는 크루엑 스컬스플리터에게 오색 화살요정용 날개 10개를 가져가야 합니다."}, [35]={hint="페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다.", desc="타나리스의 가젯잔과 모래망치 야영지를 지나 열사항에서 제출하세요."}, [36]={hint="모자케 야영지에 있는 장도르 스위프트스트라이더에게 두꺼운 설인 가죽 10개를 가져가야 합니다.", desc="거친흉터 골짜기 동굴 안팎의 설인이 두꺼운 설인 가죽을 떨어뜨려요."}, [37]={text="거친흉터 골짜기를 마친 뒤 귀환석으로 모자케 야영지에 돌아가 한꺼번에 제출하세요."}, [38]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [39]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [40]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [41]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [42]={hint="모자케 야영지에 있는 크루엑 스컬스플리터에게 그림토템일족 뿔 20개를 가져가야 합니다.", desc="모자케 야영지 북서쪽에 있는 그림토템 캠프에서 뿔피리를 얻은 후 돌아오세요."}, [43]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [44]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [45]={text="슬픔의 늪으로 가는 길에 오그리마에서 페랄라스 후속 퀘스트 받기"}, [46]={text="모자케에서 오그리마로 비행하세요(보통 타우라조 야영지 등 개방한 비행 지점을 경유). 귀환석은 모자케에 그대로 두세요. 슬픔의 늪 동쪽 해안을 마친 뒤 바로 페랄라스로 돌아갈 때 쓸 수 있어요."}, [47]={hint="오그리마에 있는 네루 파이어블레이드에게 구겨진 가면을 가져가야 합니다."}, [48]={hint="오그리마에 있는 벨그롬 록마울에게 그림토템일족 뿔 상자를 가져가야 합니다."}, [49]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드"}, [50]={npc="벨그롬 록마울", tgt="벨그롬 록마울"}, [51]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드", desc="Rage Scar Hold 구간을 위해 남겨 두었다가 모자케 야영지에서 제출하세요."}}},
    ["04-31"] = {name="슬픔의 늪", nameA="슬픔의 늪: {a:75}", tips={{k="取捨", text="슬픔의 늪 스토나드 북쪽의 길 잃은 자 연계와 호위는 이미 완료했어요. 이번에는 해안만 처리하세요. 보급품 보충과 보급품 보충를 먼저 제출해야 멀록 연계가 열려요. 게 다리는 갈 때 모으고 돌아올 때 제출하세요."}, {k="提醒", text="가라앉은 사원 파티가 있다면 슬픔의 늪 스토나드에서 받는 추방된 아탈라이 트롤를 먼저 처리할 수 있어요. 제출 지점은 사실 동부 내륙지이니, 이 연계는 동부 내륙지 이후로 남겨 두세요. 레벨 47이 안 됐다면 샛바람 해안의 일반 거대 바다 게를 91.00, 70.80 근처에서 처치하세요. 레벨 49에 가까워지면 다음 지점에서 더 높은 레벨의 Rage Scar Yeti를 우선 처치하세요.", s={{"가라앉은 사원 파티가 있다면 슬픔의 늪 스토나드에서 받는 추방된 아탈라이 트롤를 먼저 처리할 수 있어요"}, {"제출 지점은 사실 동부 내륙지이니, 이 연계는 동부 내륙지 이후로 남겨 두세요"}, {"레벨 47이 안 됐다면 샛바람 해안의 일반 거대 바다 게를 91.00, 70.80 근처에서 처치하세요"}, {"레벨 49에 가까워지면 다음 지점에서 더 높은 레벨의 Rage Scar Yeti를 우선 처치하세요"}}}}, danger={[1]="샛바람 해안의 멀록은 나란히 서 있는 경우가 많고, 잉크스피터와 현자가 뒤에서 합류해요. 해안에서 한 마리씩 끌어오고 물속까지 쫓아가지 마세요."}, grind={[1]={mob="괴물게", note="슬픔의 늪 동쪽 해안의 일반 게. 매우 밀집해 있고 가죽을 벗길 수 있어요. 지점에 막 도착했거나 경험치가 조금 모자랄 때만 알맞고, 해안 퀘스트를 하는 플레이어와 겹쳐요."}, [2]={mob="덩치큰 무쇠설인", note="레벨 49에 가까우면 다음 지점인 페랄라스까지 기다리세요. Rage Scar Hold의 일반 설인이 레벨이 더 알맞아요. 바깥 비탈에서 한 마리씩 끌어오고, 퀘스트 파티로 붐비는 동굴 입구는 피하세요."}}, supply={[1]={npc="브레이크"}, [2]={npc="여관주인 카라쿨"}, [3]={npc="가라쉬"}, [4]={npc="툴타쉬"}, [5]={npc="툴타조르"}}, steps={[1]={text="오그리마에서 톱니항으로 비행한 뒤 배를 타고 무법항으로 가세요. 귀환석은 모자케에 그대로 두세요."}, [2]={text="무법항에서 겸사겸사 제출"}, [3]={hint="무법항에 있는 \"바다늑대\" 맥킨리에게 칼림도어산 럼주가 든 스톨리의 병을 가져가야 합니다."}, [4]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [5]={npc="크라젝", tgt="크라젝", tag="선택사항", desc="꿈가루를 모두 모았다면 슬픔의 늪 스토나드에서 제출하세요."}, [6]={npc="위스키 슬림", tgt="위스키 슬림", desc="동부 내륙지 해안에서 술을 주운 뒤, 다음에 무법항에 갈 때 제출하세요."}, [7]={text="스토나드 남동쪽 해안"}, [8]={text="무법항에서 슬픔의 늪 스토나드로 비행하세요. 개방하지 않았다면 가시덤불 골짜기 북쪽 길을 따라 그늘숲 동쪽 가장자리와 저승바람 고개를 지나 스토나드로 가서, 브랙(46.07, 54.83)에게서 비행 지점을 개방하세요."}, [9]={npc="다르", tgt="다르"}, [10]={npc="다르", tgt="다르"}, [11]={hint="슬픔의 늪에 있는 톡카르에게 신선한 톱니악어 고기 8개를 가져가야 합니다.", desc="먼저 눈물의 연못 남서쪽 늪에서 Saltjaw Crocolisk를 처치하세요. 부족하면 해안을 따라 더 찾아보세요."}, [12]={hint="슬픔의 늪에 있는 다르에게 괴물게 집게발 10개를 가져가야 합니다.", desc="샛바람 해안 북쪽을 따라 거대 바다 게를 처치하세요. 남쪽으로 내려가기 전에 다리 10개를 모으세요."}, [13]={npc="톡카르", tgt="톡카르"}, [14]={npc="톡카르", tgt="톡카르"}, [15]={hint="슬픔의 늪에 있는 톡카르에게 무쇠턱 톱니악어 발톱 6개를 가져가야 합니다."}, [16]={npc="톡카르", tgt="톡카르"}, [17]={npc="톡카르", tgt="톡카르"}, [18]={hint="슬픔의 늪에 있는 카타르와 대화해야 합니다."}, [19]={npc="카타르", tgt="카타르"}, [20]={npc="카타르", tgt="카타르", desc="남동쪽 해변에서 늪지 멀록 세 종류를 각각 10마리씩 처치한 뒤 카타르에게 돌아가세요."}, [21]={hint="늪지멀록 10마리, 늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가십시오.", desc="남동쪽 해변에서 늪지 멀록 세 종류를 각각 10마리씩 처치한 뒤 카타르에게 돌아가세요."}, [22]={npc="카타르", tgt="카타르", desc="남동쪽 해변에서 늪지 멀록 세 종류를 각각 10마리씩 처치한 뒤 카타르에게 돌아가세요."}, [23]={npc="카타르", tgt="카타르"}, [24]={hint="슬픔의 늪에 있는 톡카르와 대화해야 합니다."}, [25]={npc="톡카르", tgt="톡카르"}, [26]={npc="카타르", tgt="카타르", desc="1427을 제출한 뒤 카타르에게 돌아가 다음 단계를 받으세요. 해안을 따라 북쪽으로 올라가 멀록 현자를 처치하고, 제출 전에 세 종류 모두 10마리인지 확인하세요."}, [27]={hint="늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리, 늪지멀록 점쟁이 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가야 합니다.", desc="1427을 제출한 뒤 카타르에게 돌아가 다음 단계를 받으세요. 해안을 따라 북쪽으로 올라가 멀록 현자를 처치하고, 제출 전에 세 종류 모두 10마리인지 확인하세요."}, [28]={npc="카타르", tgt="카타르", desc="1427을 제출한 뒤 카타르에게 돌아가 다음 단계를 받으세요. 해안을 따라 북쪽으로 올라가 멀록 현자를 처치하고, 제출 전에 세 종류 모두 10마리인지 확인하세요."}, [29]={text="같은 길로 서쪽 스토나드로 돌아가 다르에게 게 다리를 전달하세요."}, [30]={npc="다르", tgt="다르"}, [31]={text="제출한 뒤 귀환석으로 모자케 야영지에 돌아가세요. 귀환석이 모자케에 설정되어 있지 않다면 무법항으로 비행해 톱니항행 배를 타고, 다시 모자케로 비행하세요."}}},
    ["04-32"] = {name="페랄라스: 혈투의 전장", nameA="페랄라스: {a:1099} & 혈투의 전장", shortA="페랄라스: {a:1099} +", tips={{k="取捨", text="Rage Scar Yeti와 거친흉터 골짜기의 설인은 서로 다른 두 묶음이에요. 먼저 페랄라스 모자케 야영지에서 품질 표시를 제출하고, 이번 품질 향상를 처치하세요. 완전한 설인 가죽은 아이템이 떨어질 때만 제출하세요."}, {k="取捨", text="멀록 연계 후 귀환석으로 돌아오면 바다를 한 번 덜 건너도 돼요. 동부 내륙지에서 단지 실험 올빼미야수 정수를 모으고, 이어지는 히포그리프 뮤세크-영혼의 무기는 페랄라스 모자케 야영지에 남겨 두세요."}, {k="提醒", text="영상은 레벨 49 근처에서 페랄라스로 돌아와요. 경험치가 필요하면 Rage Scar Hold 외곽 55.73, 33.05에서 54.39, 33.10까지를 돌며 Rage Scar Yeti를 처치하고, 한 마리씩 끌어오세요.", s={{"영상은 레벨 49 근처에서 페랄라스로 돌아와요"}, {"경험치가 필요하면 Rage Scar Hold 외곽 55.73, 33.05에서 54.39, 33.10까지를 돌며 Rage Scar Yeti를 처치하고, 한 마리씩 끌어오세요"}}}}, danger={[1]="Rage Scar Yeti 동굴 입구는 좁고, 늙은 Rage Scar Yeti가 입구의 몹과 동시에 전투에 합류해요. 외곽을 먼저 정리한 뒤 동굴에 들어가세요."}, grind={[1]={mob="분노한 무쇠설인", note="Rage Scar Hold 바깥 비탈의 일반 설인. 비탈을 한 바퀴 돌며 설인 가죽을 모으고, 동굴 안이 붐비면 바깥쪽에 머무르세요."}, [2]={mob="덩치큰 무쇠설인", note="같은 캠프의 더 높은 레벨 일반 설인. 섞어서 레벨 49까지 올리세요. 좁은 동굴에서는 두 마리가 한꺼번에 끌려오기 쉬우니 입구 쪽부터 정리하세요."}}, supply={[1]={npc="쉬인"}, [2]={npc="여관주인 그룰"}, [3]={npc="카윈드 트루에임"}, [4]={npc="여관주인 그룰"}, [5]={npc="카윈드 트루에임"}, [6]={npc="탈후스"}}, steps={[1]={hint="페랄라스에 있는 의술사 우제리에게 네루의 약초 주머니를 가져가야 합니다."}, [2]={npc="의술사 우제리", tgt="의술사 우제리"}, [3]={npc="의술사 우제리", tgt="의술사 우제리", desc="동부 내륙지에서 올빼미야수를 처치한 뒤 시체에 퀘스트 용기를 사용하세요. 모자케 야영지에서 제출하세요."}, [4]={npc="의술사 우제리", tgt="의술사 우제리", tag="선택사항", desc="진행하면서 천연 재료를 보관하고, 전부 모은 뒤 페랄라스 모자케 야영지에서 제출하세요."}, [5]={npc="의술사 우제리", tgt="의술사 우제리", desc="타나리스의 무너진 기둥에서 마르본에게 제출하세요."}, [6]={npc="탈로 쏜후프", tgt="탈로 쏜후프", desc="먼저 남겨 두고, 악령의 숲에서 회색곰과 약탈자를 처치하세요. 페랄라스 모자케 야영지로 돌아가 제출하세요."}, [7]={hint="페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다."}, [8]={hint="고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다."}, [9]={hint="모자케 야영지에 있는 로크 올한이 골두니일족 주술사 10명, 골두니일족 흑마법사 10명, 그리고 골두니일족 싸움꾼 5명을 처치해 달라고 부탁했습니다."}, [10]={hint="모자케 야영지에 있는 로크 올한이 골두니 수정구를 찾아 와 달라고 부탁했습니다."}, [11]={text="대로를 따라 모자케로 돌아가 페랄라스의 오우거 퀘스트와 주크애쉬 출몰을 제출하세요. 북쪽 설인은 다음 순환으로 남겨 두세요."}, [12]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [13]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [14]={npc="로크 올한", tgt="로크 올한"}, [15]={npc="로크 올한", tgt="로크 올한"}, [16]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더", desc="타나리스 가젯잔과 모래망치 야영지 퀘스트는 오그리마를 거칠 때 함께 제출하도록 남겨 두세요."}, [17]={npc="로크 올한", tgt="로크 올한", desc="타나리스 가젯잔과 모래망치 야영지 퀘스트는 오그리마를 거칠 때 제출하도록 남겨 두세요."}, [18]={text="Rage Scar Yeti와 귀환 이동"}, [19]={hint="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다.", desc="서쪽 대로를 따라 Rage Scar Hold(55.73, 33.05)로 가서 가죽 10장을 모으세요."}, [20]={npc="완전한 설인 가죽", npcObj=true, tag="선택사항", desc="Rage Scar Yeti가 온전한 가죽을 떨어뜨릴 때만 수락하세요."}, [21]={hint="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다.", tag="선택사항"}, [22]={text="설인 퀘스트를 마치면 귀환석으로 모자케 야영지에 돌아가세요. 귀환석이 아직 재사용 대기 중이면 큰길을 걸어가세요. 제출한 뒤 가젯잔으로 비행하세요."}, [23]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [24]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더", tag="선택사항"}}},
    ["05-d20"] = {name="마라우돈", entrance="잊혀진 땅 29.10, 62.50", pickup="그늘수렵 마을로 가기 전, 오그리마의 우텔나이에게서 음영석 조각 퀘스트를 받을 수 있지만 최소 레벨 39입니다. 페랄라스 모자케 야영지를 떠나 잊혀진 땅 그늘수렵 마을로 가서 와루그와 셀렌드라를 먼저 만난 뒤, 윌로우와 켄타우로스 추방자 쪽으로 돌아가세요. 영원판 물병 퀘스트를 하려면 먼저 남동쪽 셴드랄라스로 가서 수정탑과 마법사 안내 퀘스트를 마친 뒤, 잊혀진 정원에서 숲이 전하는 말→부패와 회한를 수락하세요. 셴드랄라스 퀘스트는 최소 레벨 35입니다. 마라우돈 주황색 문에 들어가기 전에 카빈드라에게서 퀘스트를 수락하세요.", pickupS={{"그늘수렵 마을로 가기 전, 오그리마의 우텔나이에게서 음영석 조각 퀘스트를 받을 수 있지만 최소 레벨 39입니다"}, {"페랄라스 모자케 야영지를 떠나 잊혀진 땅 그늘수렵 마을로 가서 와루그와 셀렌드라를 먼저 만난 뒤, 윌로우와 켄타우로스 추방자 쪽으로 돌아가세요"}, {"영원판 물병 퀘스트를 하려면 먼저 남동쪽 셴드랄라스로 가서 수정탑과 마법사 안내 퀘스트를 마친 뒤, 잊혀진 정원에서 숲이 전하는 말→부패와 회한를 수락하세요"}, {"셴드랄라스 퀘스트는 최소 레벨 35입니다"}, {"마라우돈 주황색 문에 들어가기 전에 카빈드라에게서 퀘스트를 수락하세요"}}, tips={{k="動線", text="주황색 길에서는 녹시온과 날카로운 채찍꾼을, 보라색 길에서는 군주 바일텅을 처치하세요. 가는 길에 조각상, 칸 보석, 퀘스트 재료를 모으세요 → 두 길의 드랍을 다 모았으면 합류 지점에서 셀레브라스를 찾아 지팡이 의식을 마치세요 → 대지노래 폭포 → 공주 → 썩은아귀 웅덩이(선택)."}, {k="取捨", text="처음에 지팡이를 얻으려면 주황색, 보라색 길을 모두 돌고, 공주와 악어만 잡는다면 지팡이를 가진 파티원과 함께 안쪽 구역으로 바로 들어갈 수 있습니다. 퀘스트에 입구 밖 암흑 몹이나 다른 갈래가 필요하다면 지름길로 건너뛰지 마세요."}, {k="說明", text="29.10, 62.50은 야외 동굴 입구입니다. 주황색과 보라색 던전 입구는 같은 색 동굴 통로를 따라 찾으세요. 보라색 통로와 주황색 통로는 오염된 우물 폭포 근처에서 만납니다.", s={{"29.10, 62.50은 야외 동굴 입구입니다"}, {"주황색과 보라색 던전 입구는 같은 색 동굴 통로를 따라 찾으세요"}, {"보라색 통로와 주황색 통로는 오염된 우물 폭포 근처에서 만납니다"}}}}, steps={[1]={npc="우텔나이", tgt="우텔나이"}, [2]={npc="바르크 배틀스카", tgt="바르크 배틀스카"}, [3]={npc="셀렌드라", tgt="셀렌드라"}, [4]={npc="윌로우", tgt="윌로우"}, [5]={npc="켄타우로스 추방자", tgt="켄타우로스 추방자", desc="켄타우로스 추방자는 잊혀진 땅 남부를 순찰합니다."}, [6]={npc="셴드랄라 수정탑", npcObj=true, tag="선택사항"}, [7]={hint="셴드랄라스를 탐사하며 전에 발견한 것과 같은 수정탑을 더 찾아야 합니다.", tag="선택사항"}, [8]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항"}, [9]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", preText="이상한 수정탑"}, [10]={hint="마그람과 겔키스 마을에서 경비병이 지키는 수정탑의 조각과 파편을 회수한 후, 모덴트 이븐셰이드에게 가져가야 합니다.", tag="선택사항", desc="좌표는 순서대로 마그람 마을과 겔키스 켄타우로스 마을의 아이템 두 개입니다."}, [11]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항"}, [12]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", desc="마나 수량은 퀘스트 로그를 따르세요.", preText="수정탑의 파편"}, [13]={hint="셴드랄라스 사원 안에서 마나 여과기를 입수하여 고대 마나 결정을 수집해야 합니다. 마나를 충분히 모으면 수정탑에 힘을 불어넣은 뒤, 모덴트 이븐셰이드에게 가야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="마나 수량은 퀘스트 로그를 따르세요. 위쪽 신전 가장 높은 층에서 체를 얻으세요. 마나는 총 8개, 탑마다 4개씩 모읍니다. 서쪽 탑과 동쪽 탑은 은신 상태에서도 상호작용할 수 있습니다."}, [14]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", desc="마나 수량은 퀘스트 로그를 따르세요."}, [15]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다", preText="수정탑 동력 공급"}, [16]={hint="셴드랄라스에 있는 모덴트 이븐셰이드와 대화해 복구한 수정에 관한 정보를 얻어야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [17]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다"}, [18]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다", preText="간략한 역사 수업"}, [19]={hint="셴드랄라스의 사원에서 마법학자 키란디스를 찾아야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [20]={npc="마법학자 키란디스", tgt="마법학자 키란디스", tag="선택사항, 게임 내 확인이 필요합니다"}, [21]={npc="미세라", tgt="미세라", tag="던전 선행"}, [22]={npc="미세라", tgt="미세라", tag="던전 선행"}, [23]={npc="미세라", tgt="미세라", tag="선택사항, 게임 내 확인이 필요합니다", preText="마법학자와의 만남"}, [24]={hint="잊혀진 땅 셴드랄라스에 있는 버려진 정원에서 우드와이어드를 찾아야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [25]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다"}, [26]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다", desc="숲이 전하는 말를 먼저 제출하고, 마라우돈 안쪽 구역으로 가져가세요.", preText="숲이 전하는 말"}, [27]={npc="카빈드라", tgt="카빈드라", desc="카빈드라는 주황색 입구 밖에 서 있습니다. 양쪽 우두머리가 각각 하나씩 떨어뜨립니다."}, [28]={hint="마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다."}, [29]={text="마라우돈 입구"}, [30]={text="주황색 길 (Foulspore Cavern, 45~53). 동굴 깊은 곳에서 주황색 수정과 웅덩이를 찾아 병에 물을 담은 뒤 주황색 차원문으로 들어가세요."}, [31]={hint="마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.", desc="위치: 주황색 입구 밖 웅덩이에서 물을 담고, 입구로 들어간 뒤 길을 따라 덩굴을 찾으세요.", spot="주황색 입구 밖 웅덩이에서 물을 담고, 입구로 들어간 뒤 길을 따라 덩굴을 찾으세요."}, [32]={text="보라색 길 (Wicked Grotto, 45~53). 세 갈래 길에서 보라색 수정 통로로 가세요. 군주 바일텅이 떨어뜨리는 다이아몬드를 얻으세요."}, [33]={hint="트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.", desc="정확한 수량은 퀘스트 목록을 기준으로 하세요. 위치: 주황색, 보라색 바깥 동굴에서 먼저 켄타우로스를 처치하고, 입구로 들어간 뒤 길을 따라 조각상을 주우세요.", spot="주황색, 보라색 바깥 동굴에서 먼저 켄타우로스를 처치하고, 입구로 들어간 뒤 길을 따라 조각상을 주우세요."}, [34]={hint="추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.", desc="첫 번째는 주황색과 보라색 길 사이에 있습니다. 두 번째와 세 번째는 각각 입구 밖 통로에 있고, 네 번째와 다섯 번째는 주황색, 보라색 입구 안쪽에서 각각 순찰합니다. 위치: 주황색, 보라색 갈림길과 바깥 동굴 두 곳에서 앞의 세 명을 찾고, 두 입구 안에서 각각 한 명씩 찾으세요.", spot="주황색, 보라색 갈림길과 바깥 동굴 두 곳에서 앞의 세 명을 찾고, 두 입구 안에서 각각 한 명씩 찾으세요."}, [35]={hint="<name>레브라스의 홀 조각인 <name>레브리안 마법봉과 <name>레브리안 다이아몬드를 찾아야 합니다.", desc="위치: 주황색 길에서는 지팡이를, 보라색 길에서는 다이아몬드를 얻고, 합류 지점에서 셀레브라스를 처치하세요. 순서: 주황색과 보라색 길을 모두 거쳐야 합니다. 재료가 모이면 제출하세요.", spot="주황색 길에서는 지팡이를, 보라색 길에서는 다이아몬드를 얻고, 합류 지점에서 셀레브라스를 처치하세요."}, [36]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="우두머리를 처치한 뒤 회복된 셀레브라스와 대화하세요. 처치한 뒤 같은 방에 있는 구원받은 자에게 제출하세요.", spot="셀레브라스 우두머리 방 안, 구원받은 셀레브라스"}, [37]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요.", preText="마라우돈의 전설"}, [38]={hint="회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요. 위치: 셀레브라스의 우두머리 방에서 회복된 셀레브라스를 따라 의식을 끝까지 진행하세요.", spot="셀레브라스의 우두머리 방에서 회복된 셀레브라스를 따라 의식을 끝까지 진행하세요."}, [39]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요.", spot="셀레브라스 우두머리 방 안, 구원받은 셀레브라스"}, [40]={text="안쪽 구역 대지노래 폭포 (Earth Song Falls, 48~57). 파티는 주황색, 보라색 길이 만나는 곳에서 아래로 내려가거나, 지팡이를 가진 플레이어가 지름길을 열어 줄 수 있습니다."}, [41]={hint="마라우돈으로 이동해 대지의 노래 물병을 회수한 후, 잊혀진 땅 버려진 정원에 있는 우드와이어드에게 제출해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="썩은아귀가 웅덩이를 순찰합니다. 작은 분수는 같은 웅덩이의 수면에 있습니다. 위치: 공주 동굴 아래에서 썩은아귀 웅덩이로 뛰어들어 수면의 분수를 찾으세요. 순서: 물에 들어가기 전에 39단계를 먼저 할 수 있습니다.", spot="공주 동굴 아래에서 썩은아귀 웅덩이로 뛰어들어 수면의 분수를 찾으세요."}, [42]={hint="공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.", desc="위치: 대지노래 폭포를 따라 재타르의 동굴 깊숙이 들어가 공주가 있는 단상으로 가세요.", spot="대지노래 폭포를 따라 재타르의 동굴 깊숙이 들어가 공주가 있는 단상으로 가세요."}, [43]={npc="재타르의 영혼", tgt="재타르의 영혼", tag="게임 내 확인이 필요합니다", desc="재타르의 영혼은 공주 셀리데스가 죽은 뒤에 나타납니다. 먼저 받아 두고, 던전을 나와서 제출하세요."}, [44]={npc="셀렌드라", tgt="셀렌드라"}, [45]={npc="바르크 배틀스카", tgt="바르크 배틀스카"}, [46]={npc="윌로우", tgt="윌로우"}, [47]={npc="켄타우로스 추방자", tgt="켄타우로스 추방자"}, [48]={npc="우텔나이", tgt="우텔나이"}, [49]={hint="마라우돈으로 이동해 대지의 노래 물병을 회수한 후, 잊혀진 땅 버려진 정원에 있는 우드와이어드에게 제출해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [50]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다"}, [51]={hint="달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.", desc="달의 숲을 지나갈 때까지 기다려도 됩니다."}, [52]={npc="수호자 레물로스", tgt="수호자 레물로스", desc="달의 숲까지 기다려도 됩니다."}}},
    ["04-33"] = {name="타나리스: 모래폭풍 야영지", nameA="타나리스: {a:976} & 모래폭풍 야영지", shortA="타나리스: {a:976} +", tips={{k="取捨", text="북쪽 웅덩이에서 제출한 뒤 82를 먼저 받으세요. 82를 제출하면 10이 열리니, 그다음 모래망치, 덤불나무 골짜기, 남쪽 벌집을 한 번에 돌아요."}, {k="取捨", text="파티가 있다면 줄파락에 들어가 던전 퀘스트 4개를 함께 하세요. 파티가 없으면 4개와 고대의 알 모두 건너뛰세요."}, {k="取捨", text="먼저 32와 주크애쉬 보고서를 제출하세요. 실리시드의 행진는 레벨 50이 필요하니, 조건이 되면 어둠의 틈에서 확인하세요. 전체 후속 퀘스트는 타나리스 가젯잔과 무너진 기둥 구간으로 남겨 두세요."}, {k="提醒", text="레벨 50이 안 됐다면 모래망치 야영지(40.75, 50.67)에서 오우거를 처치하세요. 일반 몹이 모여 있고 천을 떨어뜨려요. 이글거리는 협곡에서 레벨업하려면 이 작은 경험치 부족분을 남겨 두세요.", s={{"레벨 50이 안 됐다면 모래망치 야영지(40.75, 50.67)에서 오우거를 처치하세요"}, {"일반 몹이 모여 있고 천을 떨어뜨려요"}, {"이글거리는 협곡에서 레벨업하려면 이 작은 경험치 부족분을 남겨 두세요"}}}}, danger={[1]="Centipaar 벌집 입구는 연달아 끌려오기 쉬워요. 벌집 밖 트인 공터에서만 싸우고, 한 마리 때문에 좁은 통로로 쫓아 들어가지 마세요."}, grind={[1]={mob="모래망치일족 투사", note="모래망치 야영지 바깥쪽. 일반 근접 몹이 많고 천을 떨어뜨리며 오우거 퀘스트와 겹쳐요. 몹을 빼앗기면 바깥쪽을 따라 이동하세요."}, [2]={mob="우두머리 센티파르", note="서쪽 실리시드 벌집 밖의 일반 몹은 밀집하고 레벨이 더 높아요. 벌집 입구에서 한 마리씩만 끌어오세요. 좁은 통로에서는 무리째 끌려오기 쉬워요."}}, supply={[1]={npc="벌크렉 레이지피스트"}, [2]={npc="여관주인 피즈그림블"}, [3]={npc="링클 굿스틸"}, [4]={npc="여관주인 피즈그림블"}, [5]={npc="브리즈릭 벅샷"}}, steps={[1]={text="모자케에서 가젯잔으로 비행하고, 가젯잔에 귀환석을 임시로 설정하세요."}, [2]={text="가젯잔에서 퀘스트를 받은 뒤 서쪽으로 가 물 샘플과 맹독의 둥지를 먼저 끝내세요."}, [3]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [4]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [5]={npc="앤디 린", tgt="앤디 린"}, [6]={npc="트란렉", tgt="트란렉"}, [7]={npc="쿠인", tgt="쿠인", tag="선택사항", desc="지나가다 보이면 사막 폐기물을 주우세요."}, [8]={hint="슬픈모래 감시탑의 물 웅덩이 부근에서 추출 전의 탐사장치를 사용하십시오. 다 채웠으면 가젯잔에 있는 선임측량사 피즐도저에게 추출한 탐사장치를 가져가야 합니다.", desc="슬픈모래 감시탑 웅덩이에서 미사용 탐수기를 사용하고, 물 샘플을 준비하면 바로 마을로 돌아가세요."}, [9]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [10]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [11]={hint="맹독의 둥지에서 센티파르 곤충 기관 5개를 구해 가젯잔에 있는 연금술사 페슬저그에게 가져가야 합니다."}, [12]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [13]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [14]={text="남쪽 모래망치와 덤불나무 골짜기를 거쳐 산기슭을 따라 실리시드 벌집까지"}, [15]={hint="가젯잔에 있는 앤디 린이 모래망치일족 투사, 모래망치일족 집행자를 각각 10명씩 처치하고 파괴자 고르마로크를 처단하여 모래망치 주둔지를 없애 달라고 부탁했습니다."}, [16]={hint="타나리스 스팀휘들 항구의 보안과장 빌지위즐을 위해 모래망치 오우거 주둔지 근처에서 잃어버린 유난히 반짝이는 팔찌를 회수해야 합니다.", tag="선택사항", desc="열사항과 가젯잔에서 받았을 때만 진행하세요."}, [17]={hint="가득 찬 이슬샘을 모아 가젯잔에 있는 마린 노겐포저에게 가져가야 합니다.", desc="덤불나무 골짜기에서 이슬 수집가를 처치하고 가득 찬 이슬샘 1개를 얻으세요."}, [18]={hint="가젯잔에 있는 트란렉이 옹이진 덤불나무괴물 8마리와 억센뿌리 덤불나무괴물 8마리를 처치해달라고 부탁했습니다."}, [19]={hint="후임측량사 슈섕크가 어떻게 되었는지 알아보고 가젯잔에 있는 선임측량사 피즐도저에게 데려오거나 그의 측량 장비라도 찾아서 가져가야 합니다.", desc="남쪽 균열의 지하로 가서 슈섕크의 측량 장비를 찾으세요."}, [20]={hint="사막 잔해 7개를 회수한 후, 가젯잔에 있는 쿠인에게 가야 합니다.", tag="선택사항", desc="표시는 실제로 확인된 생성 지점이에요. 얼라이언스 퀘스트가 폐기물을 떨어뜨릴 수 있으니, 보이지 않으면 가젯잔 외곽을 찾아보세요."}, [21]={text="가젯잔으로 돌아가 퀘스트를 제출하세요. 귀환석이 있다면 바로 사용하세요. 가는 길에 맛의 달인과 곤충 기관 분석도 받으세요."}, [22]={npc="앤디 린", tgt="앤디 린"}, [23]={npc="트란렉", tgt="트란렉"}, [24]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [25]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [26]={npc="쿠인", tgt="쿠인", tag="선택사항"}, [27]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [28]={hint="마린 노겐포저가 가젯잔에 있는 스프링클과 대화할 것을 부탁했습니다."}, [29]={npc="스프링클", tgt="스프링클"}, [30]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [31]={hint="가젯잔에 가서 연금술사 페슬저그를 만나 곤충 기관의 분석이 끝났는지 알아보아야 합니다."}, [32]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [33]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [34]={hint="가젯잔에 있는 선임측량사 피즐도저에게 곤충 분석 보고서를 가져가야 합니다. 연금술사 페슬저그가 요청한 대로 피즐도저로부터 보고서의 사본을 꼭 받아야 합니다."}, [35]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [36]={npc="스프링클", tgt="스프링클", desc="동부 내륙지 돌개바람 호수에서 제비수염버섯을 모은 뒤 가젯잔에서 제출하세요."}, [37]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저", desc="오그리마 어둠의 틈을 지날 때 제출하세요. 주크애쉬 보고서와 함께 선행 퀘스트를 완료하세요."}, [38]={text="선택: 열사항과 줄파락"}, [39]={npc="예킨야", tgt="예킨야", desc="모자케 야영지에서 계곡천둥매의 영혼 3개를 이미 완료해야 해요."}, [40]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항"}, [41]={npc="예킨야", tgt="예킨야", tag="선택사항", desc="선행 퀘스트 계곡천둥매의 영혼을 제출했고 줄파락 파티가 있을 때만 수락하세요."}, [42]={hint="타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.", tag="선택사항"}, [43]={hint="가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다.", tag="선택사항", desc="줄파락 묘지의 풍뎅이를 처치하세요."}, [44]={hint="가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다.", tag="선택사항", desc="계단 이벤트를 완료한 뒤 하사관 블라이에게서 막대를 받으세요."}, [45]={hint="가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.", tag="선택사항"}, [46]={npc="예킨야", tgt="예킨야", tag="선택사항"}, [47]={npc="예킨야", tgt="예킨야", tag="선택사항", desc="모쉬아루의 예언을 제출한 뒤에만 받을 수 있어요. 동부 내륙지에서 고대의 알을 얻고, 타나리스 열사항에서 제출하세요."}, [48]={npc="트란렉", tgt="트란렉", tag="선택사항"}, [49]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐", tag="선택사항", star={"석공 조합 반지", {"ROGUE", "HUNTER", "DRUID"}}}, [50]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머", tag="선택사항"}, [51]={text="가젯잔에서 오그리마로 비행하세요. 어둠의 틈에서 질지빈 드럼로어를 먼저 만난 뒤, Darkbriar Lodge에서 골두니 수정구를 제출하세요."}, [52]={hint="오그리마에 있는 질지빈 드럼로어에게 보고서를 가져가야 합니다."}, [53]={hint="오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다."}, [54]={hint="오그리마의 검은장미 오두막에 있는 우텔나이에게 골두니 수정구를 가져가야 합니다."}, [55]={npc="질지빈 드럼로어", tgt="질지빈 드럼로어"}, [56]={npc="질지빈 드럼로어", tgt="질지빈 드럼로어"}, [57]={npc="우텔나이", tgt="우텔나이"}}},
    ["05-d21"] = {name="줄파락", entrance="타나리스 38.70, 20.00", pickup="타나리스 가젯잔에서 지역 퀘스트 3개를 받고, 스팀휘들 항구에서 예킨야에게 계곡천둥매의 영혼을 받으세요. 페랄라스에서 영혼을 잡고, 타나리스로 돌아와 스팀휘들 항구에서 계곡천둥매의 영혼을 제출하고 모쉬아루의 예언을 받은 뒤 가젯잔에서 파티와 합류하세요. 버섯구름 봉우리 반짝이는 평원을 지날 때 가즈릴라을 받으세요. 슬픔의 늪으로 가기 전에 먼지진흙 습지대에서 타베사의 곁퀘스트를 할 수 있습니다(마법사만 해당).", pickupS={{"타나리스 가젯잔에서 지역 퀘스트 3개를 받고, 스팀휘들 항구에서 예킨야에게 계곡천둥매의 영혼을 받으세요"}, {"페랄라스에서 영혼을 잡고, 타나리스로 돌아와 스팀휘들 항구에서 계곡천둥매의 영혼을 제출하고 모쉬아루의 예언을 받은 뒤 가젯잔에서 파티와 합류하세요"}, {"버섯구름 봉우리 반짝이는 평원을 지날 때 가즈릴라을 받으세요"}, {"슬픔의 늪으로 가기 전에 먼지진흙 습지대에서 타베사의 곁퀘스트를 할 수 있습니다(마법사만 해당)"}}, tips={{k="動線", text="안투술 곁길 → 데카의 딱정벌레 방에서 첫 번째 모쉬아루 석판을 얻고 → Zum'rah 묘지 → 피라미드 계단 이벤트 → 유체술사 벨라타에게서 두 번째 모쉬아루 석판과 자동 탐사막대를 얻고(웅덩이에서 가즈릴라를 소환할 수 있습니다) → 우코르즈. 가는 길에 스카라베 껍질과 트롤 경화제를 모으세요."}, {k="取捨", text="가젯잔 퀘스트 세 개와 모쉬아루 석판을 우선 처리하세요. 망치가 있다면 가즈릴라까지 잡으세요. 타베사는 먼지진흙 습지대를 지나는 캐릭터를 위해 남겨 두세요."}, {k="說明", text="타나리스 스팀휘들 항구와 가젯잔에서 먼저 한 번 돌 수 있습니다. 예킨야의 전체 선행 퀘스트를 끝낸 뒤에 타나리스 가젯잔과 모래망치 야영지를 돌기를 권합니다. 모쉬아루 석판은 학카르 연계의 선행 퀘스트이기도 합니다.", s={{"타나리스 스팀휘들 항구와 가젯잔에서 먼저 한 번 돌 수 있습니다"}, {"예킨야의 전체 선행 퀘스트를 끝낸 뒤에 타나리스 가젯잔과 모래망치 야영지를 돌기를 권합니다"}, {"모쉬아루 석판은 학카르 연계의 선행 퀘스트이기도 합니다"}}}}, steps={[1]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [2]={npc="트란렉", tgt="트란렉"}, [3]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머"}, [4]={npc="예킨야", tgt="예킨야", desc="먼저 스팀휘들 항구에서 받고 페랄라스로 가세요. 스팀휘들 항구로 돌아와 제출한 뒤 바로 모쉬아루의 예언을 받으세요."}, [5]={hint="페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다."}, [6]={npc="예킨야", tgt="예킨야"}, [7]={npc="예킨야", tgt="예킨야", preText="계곡천둥매의 영혼"}, [8]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠", tag="선택사항", desc="파티에서 한 명 이상이 가즈릴라의 망치를 가지고 있으면 징을 칠 수 있습니다. 먼저 동부 내륙지를 지난다면 줄의 제단에서 신성한 망치를 얻고, 진타알로 제단에서 변환하세요."}, [9]={npc="타베사", tgt="타베사", tag="선택사항", desc="타베사에게서 바로 받을 수 있습니다. 40레벨 언더시티 타베사의 임무은 건너뛰어도 되는 안내 퀘스트입니다."}, [10]={text="줄파락 입구"}, [11]={hint="가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다.", desc="위치: 순교자 데카의 방으로 가서 근처의 스카라베를 처치하세요. 순서: 15단계의 첫 번째 석판도 함께 얻으세요.", spot="순교자 데카의 방으로 가서 근처의 스카라베를 처치하세요."}, [12]={hint="가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.", desc="파티에서 먼저 분배 방식을 정하세요. 한 번 돌아서는 드랍이 모자랄 수 있습니다. 위치: 입구에서 큰길을 따라 각 구역의 성난모래 트롤을 처치하세요.", spot="입구에서 큰길을 따라 각 구역의 성난모래 트롤을 처치하세요."}, [13]={hint="먼지진흙 습지대에 있는 타베사에게 심연의 티아라를 가져가야 합니다.", tag="선택사항", desc="위치: 피라미드 이벤트 구역을 지나 길을 따라 웅덩이 옆의 벨라타를 찾으세요. 순서: 15단계의 두 번째 석판도 함께 얻으세요.", spot="피라미드 이벤트 구역을 지나 길을 따라 웅덩이 옆의 벨라타를 찾으세요."}, [14]={hint="소금 평원에 있는 위즐 브라스볼츠에게 가즈릴라의 전기 비늘을 가져가야 합니다.", tag="선택사항", desc="위치: 벨라타 옆 웅덩이 가장자리에서 징을 치고 가즈릴라가 나타날 때까지 기다리세요. 순서: 같은 구역에서 먼저 벨라타를 처치한 뒤 징을 치세요.", spot="벨라타 옆 웅덩이 가장자리에서 징을 치고 가즈릴라가 나타날 때까지 기다리세요."}, [15]={hint="가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다.", desc="먼저 우리를 열어 계단 이벤트를 진행하고, 아래쪽 무리를 모두 정리한 뒤 적대 상태로 바뀌는 무리를 상대하세요. 위치: 큰길을 따라 피라미드 꼭대기에서 우리를 열고, 계단을 내려가 몹 무리를 막아 내세요. 순서: 몹 무리를 모두 막아 낸 뒤 하사관 블라이에 도전하세요.", spot="큰길을 따라 피라미드 꼭대기에서 우리를 열고, 계단을 내려가 몹 무리를 막아 내세요."}, [16]={hint="타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.", desc="위치: 데카는 딱정벌레 방에, 벨라타는 웅덩이 옆에 있습니다. 각각 얻으세요. 순서: 딱정벌레 방에서는 10단계를, 웅덩이에서는 12~13단계를 진행하세요.", spot="데카는 딱정벌레 방에, 벨라타는 웅덩이 옆에 있습니다. 각각 얻으세요."}, [17]={npc="트란렉", tgt="트란렉"}, [18]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머"}, [19]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [20]={npc="예킨야", tgt="예킨야"}, [21]={npc="예킨야", tgt="예킨야", desc="지금은 받기만 하고 남겨 두세요. 진타알로에서 알을 얻은 뒤 아탈학카르 신전으로 들어가세요.", preText="모쉬아루의 예언"}, [22]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠", tag="선택사항"}, [23]={npc="타베사", tgt="타베사", tag="선택사항"}}},
    ["04-34"] = {name="이글거리는 협곡", nameA="이글거리는 협곡: {a:1446}", tips={{k="交通", text="먼저 토륨 조합 거점에서 호드 비행 지점을 개방하세요. 완료한 뒤 언더시티나 해머폴로 비행해 동부 내륙지로 이어가세요."}, {k="取捨", text="처치 목표 네 가지는 한 바퀴로 끝낼 수 있어요. 도난품: 가열로 바람구멍 및 감시병의 망원경 드랍이 부족하면 다른 퀘스트부터 제출하세요. 현상수배: 감독관 말토류스과 불꽃 융해촉진제?는 같은 동굴에 있으니 파티가 있다면 겸사겸사 정리하세요."}, {k="取捨", text="토륨 조합 거점에서 제출을 마치면 레벨 50이 되니 이 지점을 떠나도 돼요. 횃불 후반부와 남동쪽 나무 간이화장실은 각각 되돌아가야 하니, 경험치가 모자랄 때만 하세요."}, {k="提醒", text="경험치가 조금 모자라나요? 가마솥 동쪽 외곽(44.76, 38.72)의 Heavy War Golem이나 북쪽 비탈(41.21, 23.33)의 일반 검은무쇠 감독관을 처치하세요.", s={{"경험치가 조금 모자라나요?"}, {"가마솥 동쪽 외곽(44.76, 38.72)의 Heavy War Golem이나 북쪽 비탈(41.21, 23.33)의 일반 검은무쇠 감독관을 처치하세요"}}}}, danger={[1]="감독관 마르토리우스는 슬래그 구덩이 일대 검은무쇠 광산 깊은 곳에 있어요. 파티로 통로를 구간별로 정리하고, 솔로라면 현상금 퀘스트는 건너뛰세요."}, grind={[1]={mob="육중한 전투골렘", note="가마솥 동쪽 가장자리의 일반 골렘. 높은 쪽 외곽을 따라 처치하며 처치 퀘스트도 함께 진행하세요. 퀘스트 플레이어가 많으면 가마솥 바닥으로 내려가지 마세요."}, [2]={mob="검은무쇠단 감독관", note="토륨 조합 거점 남쪽의 일반 검은무쇠 몹. 비행 지점으로 돌아가기 전에 연달아 처치하며 퀘스트 드랍도 모으세요. 캠프 안에서는 몹이 연달아 끌려올 수 있어요."}}, supply={[1]={npc="그리샤"}, [2]={npc="수석대장장이 버니네이트"}, [3]={npc="수석대장장이 버니네이트"}, [4]={npc="수석대장장이 버니네이트"}}, steps={[1]={text="오그리마에서 톱니항으로 비행하세요. 바다를 건너기 전에 톱니항 부두에서 운고로 시작 퀘스트를 받으세요. 이어서 배로 무법항에 간 뒤 황야의 땅 카르가스로 비행하세요."}, [2]={npc="리브 리즐픽스", tgt="리브 리즐픽스", desc="최소 레벨 49예요. 운고로 분화구 마샬의 야영지의 불기둥 용광로에서 하고, 톱니항에서 제출하세요."}, [3]={text="카르가스에서 남서쪽 도로를 따라 이글거리는 협곡에 들어가 북쪽 대로를 따라 토륨 조합 거점으로 가세요."}, [4]={nodeA="{a:1446}", desc="호드 비행 조종사 그리샤에게서 비행 지점을 개방하세요."}, [5]={text="토륨 조합 거점에서 퀘스트를 모두 받은 뒤 가마솥과 슬래그 구덩이 일대를 순회하세요."}, [6]={npc="구인광고/분실물센터/지명수배", npcObj=true}, [7]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [8]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [9]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [10]={npc="구인광고/분실물센터/지명수배", npcObj=true, tag="선택사항", desc="몹을 처치하면서 두 가지 드랍을 모두 얻으세요."}, [11]={npc="구인광고/분실물센터/지명수배", npcObj=true, tag="선택사항", desc="마르토리우스는 정예예요. 파티가 있을 때만 수락하세요."}, [12]={npc="수석대장장이 버니네이트", tgt="수석대장장이 버니네이트", tag="선택사항", desc="마르토리우스 파티 진행 때 함께 받으세요."}, [13]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [14]={hint="벨라로크 윈드블레이드가 하는 이야기를 들으십시오."}, [15]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [16]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [17]={hint="이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다."}, [18]={hint="검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다."}, [19]={hint="이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}, [20]={hint="화염의 심장 4개와 골렘 기름 4개를 모아 벨라로크 윈드블레이드에게 가져가야 합니다.", desc="가마솥 주변의 골렘과 불의 정령을 겸사겸사 처치하세요."}, [21]={hint="이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다.", tag="선택사항"}, [22]={hint="용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", desc="슬래그 구덩이 광산에 들어가 인센도사우루스를 처치하세요. 동굴 안의 검은무쇠 몹도 함께 정리하세요."}, [23]={hint="용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다.", tag="선택사항", desc="슬래그 구덩이 깊은 곳 마르토리우스 근처에 설계도가 있어요. 안전할 때 주우세요."}, [24]={hint="이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다.", tag="선택사항"}, [25]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [26]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="경험치가 부족하고 가마솥에 한 번 더 들어갈 의향이 있을 때 수락하세요."}, [27]={hint="벨라로크 윈드블레이드에게 토륨 도금 단검 8개를 가져가야 합니다.", tag="선택사항", desc="슬래그 구덩이의 검은무쇠 감독관과 노예상인이 떨어뜨려요."}, [28]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [29]={text="토륨 조합 거점으로 돌아가 가마솥 퀘스트를 한꺼번에 제출하세요."}, [30]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [31]={npc="작업반장 스크랜지", tgt="작업반장 스크랜지"}, [32]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [33]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [34]={npc="작업반장 스크랜지", tgt="작업반장 스크랜지", tag="선택사항"}, [35]={npc="수석대장장이 버니네이트", tgt="수석대장장이 버니네이트", tag="선택사항"}, [36]={npc="감시대장 롤로 롱스트라이커", tgt="감시대장 롤로 롱스트라이커", tag="선택사항"}, [37]={text="경험치를 조금 보충하거나 횃불 퀘스트가 남았을 때"}, [38]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="횃불 자루 만들기을 완료해야 받을 수 있어요. 서쪽 동굴에서 황혼 몹을 처치해 라그나로스의 표식을 얻으세요."}, [39]={hint="벨라로크 윈드블레이드에게 라그나로스의 상징 1개를 찾아 가져가야 합니다.", tag="선택사항", desc="횃불 자루 만들기을 완료해야 받을 수 있어요. 서쪽 동굴에서 황혼 몹을 처치해 라그나로스의 표식을 얻으세요."}, [40]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="횃불 자루 만들기을 완료해야 받을 수 있어요. 서쪽 동굴에서 황혼 몹을 처치해 라그나로스의 표식을 얻으세요."}, [41]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [42]={hint="벨라로크 윈드블레이드가 응보의 횃불을 완성할 동안 기다려야 합니다.", tag="선택사항"}, [43]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [44]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [45]={hint="응보의 횃불을 집어 드십시오.", tag="선택사항"}, [46]={npc="응보의 횃불", npcObj=true, tag="선택사항"}, [47]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [48]={hint="수습기사 몰트레이크와 대화해야 합니다.", tag="선택사항"}, [49]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항"}, [50]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항", desc="네 개의 탑에 각각 불을 붙이세요. 먼저 탑 위의 경비병을 끌어내세요."}, [51]={hint="북쪽, 남쪽, 동쪽과 서쪽 감시탑 내부에서 응보의 횃불을 사용해 불을 지르십시오.", tag="선택사항", desc="네 개의 탑에 각각 불을 붙이세요. 먼저 탑 위의 경비병을 끌어내세요."}, [52]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항", desc="네 개의 탑에 각각 불을 붙이세요. 먼저 탑 위의 경비병을 끌어내세요."}, [53]={npc="검은용군단의 보물", npcObj=true, tag="선택사항"}, [54]={hint="궤짝을 여십시오.", tag="선택사항"}, [55]={npc="검은용군단의 보물", npcObj=true, tag="선택사항"}, [56]={npc="나무 간이화장실", npcObj=true, tag="선택사항", desc="남동쪽으로 갈 예정이거나 경험치가 꽤 모자랄 때만 나무 간이화장실로 돌아가세요. 비단 15개를 먼저 준비하세요."}, [57]={hint="검은무쇠 지질학자 8명을 처치하고 이글거리는 협곡의 화장실에 갇힌 사람에게 비단 옷감 15개를 가져가야 합니다.", tag="선택사항", desc="남동쪽으로 갈 예정이거나 경험치가 꽤 모자랄 때만 나무 간이화장실로 돌아가세요. 비단 15개를 먼저 준비하세요."}, [58]={npc="나무 간이화장실", npcObj=true, tag="선택사항", desc="남동쪽으로 갈 예정이거나 경험치가 꽤 모자랄 때만 나무 간이화장실로 돌아가세요. 비단 15개를 먼저 준비하세요."}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="먼지진흙 습지대 75.30, 14.10", pickup="슬픔의 늪으로 가기 전 48레벨이 안 되었다면 먼지진흙 습지대 장벽 마을 비행 지점을 먼저 여세요. 이글거리는 협곡으로 가기 전에 오그리마 지혜의 골짜기 스랄의 대전당에서 아이트리그에게 실종된 코르크론을 받고(34.28, 39.35), 장벽 마을로 날아가 나지르 블러드파이크를 만나세요. 북동쪽 해안을 따라 오카즈 섬으로 헤엄쳐 가서, 섬 쪽의 하사관에게 정예 중의 정예, 적절한 장소, 잘못된 시간를 차례로 제출하고 오크를 구하라를 받은 뒤 섬 탑 지하로 들어가세요. Thrall Needs to Know은 다음에 오그리마에 갈 때까지 남겨 두세요.", pickupS={{"슬픔의 늪으로 가기 전 48레벨이 안 되었다면 먼지진흙 습지대 장벽 마을 비행 지점을 먼저 여세요"}, {"이글거리는 협곡으로 가기 전에 오그리마 지혜의 골짜기 스랄의 대전당에서 아이트리그에게 실종된 코르크론을 받고(34.28, 39.35), 장벽 마을로 날아가 나지르 블러드파이크를 만나세요"}, {"북동쪽 해안을 따라 오카즈 섬으로 헤엄쳐 가서, 섬 쪽의 하사관에게 정예 중의 정예, 적절한 장소, 잘못된 시간를 차례로 제출하고 오크를 구하라를 받은 뒤 섬 탑 지하로 들어가세요"}, {"Thrall Needs to Know은 다음에 오그리마에 갈 때까지 남겨 두세요"}}, tips={{k="動線", text="입구 위층 감옥에서 Folkar를 찾습니다 → 간수장 렉스를 처치하고 열쇠를 얻습니다 → 심문관과 해일여제를 정리하며 두건을 모읍니다 → 아래층 감옥 문을 열고 '청소부' 카테리나와 불길포효를 처치합니다 → 마지막 우두머리 뒤 밀실에서 쪽지를 확인한 뒤 위층 감옥의 Folkar에게 돌아갑니다."}, {k="取捨", text="실종된 코르크론부터 Thrall Needs to Know까지의 코르크론 구출 연계를 우선하세요. 한 번에 두건이 모자라면 제출을 미루세요."}, {k="說明", text="호드는 테라모어를 피할 수 있습니다. 장벽 마을에서 북동쪽 해안으로 가서 헤엄쳐 건너세요. 하사관은 섬 쪽에 있고, 던전 입구는 섬 탑 지하 복도에 있습니다.", s={{"호드는 테라모어를 피할 수 있습니다"}, {"장벽 마을에서 북동쪽 해안으로 가서 헤엄쳐 건너세요"}, {"하사관은 섬 쪽에 있고, 던전 입구는 섬 탑 지하 복도에 있습니다"}}}}, steps={[1]={npc="아이트리그", tgt="아이트리그", desc="48레벨부터 지혜의 골짜기 스랄의 대전당에서 아이트리그를 찾으세요."}, [2]={hint="담쟁이 마을에서 나지르 블러드파이크와 대화해야 합니다."}, [3]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [4]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크", preText="실종된 코르크론"}, [5]={hint="실종된 코르크론 정예병을 찾아야 합니다."}, [6]={npc="하사관 울카", tgt="하사관 울카"}, [7]={npc="하사관 울카", tgt="하사관 울카", preText="정예 중의 정예"}, [8]={hint="하사관 울카와 대화하여 알카즈 섬의 상황을 자세히 알아봐야 합니다."}, [9]={npc="하사관 울카", tgt="하사관 울카"}, [10]={npc="하사관 울카", tgt="하사관 울카", preText="적절한 장소, 잘못된 시간"}, [11]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항", desc="가는 길에 오그리마에서 섬 쪽까지 실종된 코르크론~적절한 장소, 잘못된 시간를 먼저 끝낸 뒤 하사관의 퀘스트 목록을 확인하세요."}, [12]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항", desc="게임 기록상 하사관에게서 받을 수 있지만 열리는 조건은 확인되지 않았습니다. 먼저 실종된 코르크론~적절한 장소, 잘못된 시간를 진행하세요."}, [13]={text="Alcaz Prison 입구"}, [14]={hint="알카즈 감옥에 진입해 사령관 폴카르를 찾아야 합니다.", desc="위치: 입장해서 위층 복도를 따라 감옥 안의 지휘관을 찾으세요.", spot="입장해서 위층 복도를 따라 감옥 안의 지휘관을 찾으세요."}, [15]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", spot="위층 복도의 감옥, Commander Folkar"}, [16]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", preText="오크를 구하라"}, [17]={hint="알카즈 감옥에 진입해 스트라샤즈 병사 15명과 스트라샤즈 요술사 8명을 처치하고 해일여제 카자스의 머리카락을 하사관 울카에게 가져가야 합니다.", tag="선택사항", desc="위치: 위층 감옥 근처에서 해일여제를 찾고, 복도를 따라 나가를 정리하세요.", spot="위층 감옥 근처에서 해일여제를 찾고, 복도를 따라 나가를 정리하세요."}, [18]={hint="알카즈 감옥에 진입해 인간 경비병에게서 핏빛 붉은 복면 8개를 입수해야 합니다.", tag="선택사항", desc="한 번 더 돌아야 할 수도 있으니 던전을 나가기 전에 수량을 확인하세요. 위치: 위층 감옥 복도에서 인간 경비병을 먼저 처치하고, 가는 길에 부족한 만큼 채우세요.", spot="위층 감옥 복도에서 인간 경비병을 먼저 처치하고, 가는 길에 부족한 만큼 채우세요."}, [19]={hint="Look for King Varian Wrynn in Alcaz Prison.", desc="위치: 아래층 문을 열고 마지막 우두머리를 처치한 뒤, 뒤쪽 밀실에서 바닥의 쪽지를 찾으세요. 순서: 먼저 간수장에게서 열쇠를 얻으세요.", spot="아래층 문을 열고 마지막 우두머리를 처치한 뒤, 뒤쪽 밀실에서 바닥의 쪽지를 찾으세요."}, [20]={npc="퀘스트 물체", npcObj=true, tag="게임 내 확인이 필요합니다", spot="블레이즈로어 뒤 비밀 방 바닥의 쪽지"}, [21]={npc="퀘스트 물체", npcObj=true, tag="게임 내 확인이 필요합니다", preText="The Honor of the Kor'kron"}, [22]={hint="Report back to Commander Folkar.", desc="위치: 마지막 우두머리의 밀실에서 위층으로 돌아가 원래 감옥의 지휘관에게 제출하세요. 순서: 먼저 18단계의 쪽지를 읽으세요.", spot="마지막 우두머리의 밀실에서 위층으로 돌아가 원래 감옥의 지휘관에게 제출하세요."}, [23]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", spot="위층 복도의 감옥, Commander Folkar"}, [24]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", preText="Bad News for Folkar"}, [25]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항"}, [26]={hint="Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."}, [27]={npc="스랄", tgt="스랄"}, [28]={npc="아이트리그", tgt="아이트리그", tag="선택사항"}}},
    ["04-35"] = {name="동부 내륙지", nameA="동부 내륙지: {a:3317} & {a:354}", shortA="동부 내륙지: {a:3317} +", tips={{k="取捨", text="추천: 거북이 퀘스트와 같은 해변에서 위스키 슬림의 잃어버린 술병을 하세요. 포악한 올빼미야수 사냥와 단지 실험을 위해 올빼미야수를 함께 처치하세요."}, {k="取捨", text="건너뛰기: 구인광고: 레반터스크 마을의 경비대장는 정예 80마리를 처치해야 하니, 준비된 파티가 없으면 건너뛰세요. 진타알로를 혼자 하기 어렵다면 해안과 내륙 퀘스트를 먼저 하세요."}, {k="取捨", text="아직 반납 금지: 무법항에서 위스키 슬림의 잃어버린 술병을, 모자케 야영지에서 단지 실험을 반납하세요. 스프링클의 비밀 재료과 고대의 알은 타나리스 구간(가젯잔과 무너진 기둥)을 위해 남겨 두세요."}, {k="提醒", text="레벨 52가 안 됐다면 동부 내륙지 해안에서 거북이와 올빼미야수를 처치하거나, 파티로 진타알로를 정리하세요.", s={{"레벨 52가 안 됐다면 동부 내륙지 해안에서 거북이와 올빼미야수를 처치하거나, 파티로 진타알로를 정리하세요"}}}}, danger={[1]="진타알로 상층에는 Vilebranch 정예 트롤 무리와 치유 몹이 있어요. 파티로 계단을 따라 층별로 정리하고, 파티가 없으면 해안에 머무르세요.", [2]="감메리타는 해안을 순찰하는 정예 거북이예요. 일반 거북이를 잡는 동안 주의하고, 파티가 없으면 피하세요."}, grind={[1]={mob="무쇠턱바다거북", note="레반터스크 마을 북쪽 해변의 일반 거북이. 해안을 따라 일직선으로 번갈아 처치하며 가죽을 벗길 수 있어요. 거북이 고기를 모으는 플레이어와 함께 쓰는 지점이며, 진타알로 정예 구역에 들어갈 필요는 없어요."}}, supply={[1]={npc="고르카스"}, [2]={npc="라드"}, [3]={npc="대장장이 슬래그트리"}, [4]={npc="라드"}, [5]={npc="레나즈"}, [6]={npc="비술사 야요진"}}, steps={[1]={text="이글거리는 협곡에서 레반터스크 마을로 비행하세요. 비행 지점이 없다면 먼저 타렌 밀농장으로 날아가 던홀드 요새 북쪽 고개로 동부 내륙지에 들어가고, 대로를 따라 동쪽으로 간 뒤 해안을 따라 남쪽으로 레반터스크 마을까지 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={nodeA="{a:3317}", desc="고르카스에게서 비행 지점을 개방하세요."}, [3]={text="퀘스트를 진행하는 동안 레반터스크 마을에 귀환석을 설정해도 좋아요."}, [4]={text="레반터스크 마을에서 수락 → 해안"}, [5]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [6]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [7]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [8]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [9]={npc="라드", tgt="라드"}, [10]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [11]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [12]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [13]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르", tag="선택사항", desc="길에서 희귀한 칼부리 그리폰이 보일 때만 처치하세요."}, [14]={npc="대장장이 슬래그트리", tgt="대장장이 슬래그트리", tag="선택사항", desc="북동쪽 사원으로 돌아가야 해요."}, [15]={npc="전장으로!", npcObj=true, tag="선택사항", desc="진타알로 고지대의 정예예요. 파티가 있을 때 수락하세요."}, [16]={npc="전장으로!", npcObj=true, tag="선택사항", desc="정예 80마리를 처치해야 해요. 진타알로에서 많이 사냥할 계획일 때만 수락하세요.", star={"수호대장의 룬", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다."}, [18]={hint="감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.", desc="무쇠턱바다거북 처치, 위스키 슬림의 잃어버린 술병과 같은 연계예요. 보이면 처치하세요."}, [19]={hint="무법항에 있는 위스키 슬림이 잃어버린 퍼플리버보스 포트 와인을 찾아 달라고 부탁했습니다.", desc="슬픔의 늪 스토나드와 샛바람 해안에서 먼저 받으세요. 마을 밖에서 북쪽으로 해변을 따라 병을 찾으세요."}, [20]={hint="동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니<name>."}, [21]={hint="수수께끼를 풀어야 합니다.", tag="선택사항", desc="코르텔로의 수수께끼를 제출했고 코르텔로의 수수께끼을 갖고 있어야 해요. 코르텔로의 수수께끼는 먼지진흙 습지대 나무다리 아래의 곰팡이 핀 두루마리에서 제출하세요."}, [22]={npc="코르텔로의 보물", npcObj=true, tag="선택사항", desc="코르텔로의 수수께끼이 없으면 건너뛰세요."}, [23]={text="내륙 올빼미야수와 은빛갈기 늑대 → 진타알로 제단"}, [24]={hint="긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다."}, [25]={hint="포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다."}, [26]={hint="동부 내륙지로 가서 올빼미야수를 찾아 10마리를 처치하고 뮤세크 단지를 사용해 죽은 올빼미야수를 갈무리해서 담아와야 합니다.", desc="페랄라스 모자케 야영지와 Rage Scar Hold에서 받고, 페랄라스에서 제출하세요."}, [27]={hint="우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다.", tag="선택사항", desc="보이면 처치하세요."}, [28]={hint="동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다.", tag="선택사항"}, [29]={hint="가젯잔에 있는 스프링클이 제비수염버섯을 하나 구해 가지고 올 것을 부탁했습니다.", desc="타나리스 가젯잔과 모래망치 야영지에서 먼저 받고, 가젯잔에서 제출하세요."}, [30]={hint="진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니<name>.", desc="장로 쏜터스크 퀘스트와 함께 진행하세요. 계단의 순찰 몹을 조심하세요."}, [31]={hint="레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니<name>.", desc="목표가 두 곳으로 나뉘어 있으니 두 아이템을 모두 얻으세요."}, [32]={hint="동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니<name>."}, [33]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [34]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [35]={hint="수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다."}, [36]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [37]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [38]={hint="고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다.", tag="선택사항", desc=