    ["05-d29"] = {name="혈투의 전장: 서쪽", entrance="페랄라스 60.30, 30.20 (안뜰 서쪽 구역 차원문)", pickup="페랄라스 모자케 야영지에서 현자 코로루스크를 찾고, 54레벨이 되면 페랄라스 모자케 야영지에서 먼저 엘프의 전설을 받으세요. 모자케로 날아가 큰길을 따라 서쪽으로 가세요. 파티에 초승달 열쇠가 있는지 먼저 확인하고, 없으면 동쪽 구역을 먼저 돌세요.", pickupS={{"페랄라스 모자케 야영지에서 현자 코로루스크를 찾고, 54레벨이 되면 페랄라스 모자케 야영지에서 먼저 엘프의 전설을 받으세요"}, {"모자케로 날아가 큰길을 따라 서쪽으로 가세요"}, {"파티에 초승달 열쇠가 있는지 먼저 확인하고, 없으면 동쪽 구역을 먼저 돌세요"}}, tips={{k="動線", text="서문 → 정원에서 수정탑 정리 → 텐드리스 워프우드 → 위층에서 고대인에게 퀘스트를 받고 탑 정리(칼렌드리스, 일리아나는 선택) → 감옥에서 이몰타르 처치 → 도서관에서 토르텔드린 처치 → 고대인에게 돌아가 제출하고, 다시 도서관으로 돌아가 보물과 유해를 찾으세요."}, {k="取捨", text="엘프의 전설, 내면의 광기, 셴드랄라의 보물을 같은 판에 끝내세요. 마법 부여 재료 교환과 여러 던전을 잇는 긴 연계는 장비 여정으로 남겨 두세요."}, {k="說明", text="5인 던전입니다. 초승달 열쇠는 동쪽 구역의 푸실린에게서 얻을 수 있습니다. 이몰타르를 처치하려면 수정탑 다섯 개를 모두 정리해야 합니다. 도서관의 직업 서적은 북쪽 구역 설명을 보세요.", s={{"5인 던전입니다"}, {"초승달 열쇠는 동쪽 구역의 푸실린에게서 얻을 수 있습니다"}, {"이몰타르를 처치하려면 수정탑 다섯 개를 모두 정리해야 합니다"}, {"도서관의 직업 서적은 북쪽 구역 설명을 보세요"}}}, {k="提醒", text="5인 던전입니다. 초승달 열쇠는 동쪽 구역의 푸실린에게서 얻을 수 있습니다. 이몰타르를 처치하려면 수정탑 다섯 개를 모두 정리해야 합니다. 도서관의 직업 서적은 북쪽 구역 설명을 보세요.", s={{"5인 던전입니다"}, {"초승달 열쇠는 동쪽 구역의 푸실린에게서 얻을 수 있습니다"}, {"이몰타르를 처치하려면 수정탑 다섯 개를 모두 정리해야 합니다"}, {"도서관의 직업 서적은 북쪽 구역 설명을 보세요"}}}}, steps={[1]={npc="현자 코로루스크", tgt="현자 코로루스크", desc="모자케 야영지에서 받으세요. 도서관은 서쪽 구역으로 통과하거나 북쪽 구역 옆 통로로 가세요."}, [2]={text="혈투의 전장: 서쪽 입구"}, [3]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", desc="서쪽 구역 위층에서 먼저 셴드랄라 고대인과 대화하세요."}, [4]={hint="이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.", desc="먼저 수정탑 다섯 개를 모두 파괴하세요. 위치: 정원과 위층에서 수정탑 다섯 개를 정리하고, 잠긴 문을 지나 이몰타르와 왕자를 처치하세요. 순서: 수정탑 다섯 개 → 이몰타르 → 도서관의 왕자.", spot="정원과 위층에서 수정탑 다섯 개를 정리하고, 잠긴 문을 지나 이몰타르와 왕자를 처치하세요."}, [5]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", spot="도서관의 셴드랄라 고대인"}, [6]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", desc="고대인에게 제출한 뒤 받으세요. 내면의 광기과 같은 판에 진행하세요.", preText="내면의 광기"}, [7]={hint="도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!", desc="위치: 이몰타르의 감옥에서 복도를 지나 도서관으로 가서 계단 아래의 보물 상자를 찾으세요.", spot="이몰타르의 감옥에서 복도를 지나 도서관으로 가서 계단 아래의 보물 상자를 찾으세요."}, [8]={npc="셴드랄라의 보물", npcObj=true, tag="게임 내 확인이 필요합니다", spot="도서관 계단 아래 셴드랄라 보물 상자"}, [9]={hint="혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.", desc="위치: 감옥에서 복도를 지나 도서관으로 들어가 책장 옆의 유해를 찾으세요.", spot="감옥에서 복도를 지나 도서관으로 들어가 책장 옆의 유해를 찾으세요."}, [10]={npc="현자 코로루스크", tgt="현자 코로루스크"}}},
    ["05-d28"] = {name="혈투의 전장: 동쪽", entrance="페랄라스 64.80, 30.20 (투기장 동쪽 벽 오목한 곳의 차원문)", pickup="아주라 발로르모크에서 오그리마를 지나는 54레벨이라면 징집관 고를라취에게 를 받을 수 있습니다. 페랄라스 모자케 야영지에서 탈로에게 제출하고 먼저 레스텐드리스의 그물를 받은 뒤, 페랄라스 모자케 야영지로 날아가 라리스 정자의 아즈토르딘을 찾으세요. 정화의 성물함은 달의 숲에서 받을 수 있고, 실리더스 세나리온 요새 마파람 마을에서 성물함을 얻어 달의 숲 나이트헤이븐에 제출해야 악령덩굴 조각이 열리니 나중 진행으로 미뤄도 됩니다.", pickupS={{"아주라 발로르모크에서 오그리마를 지나는 54레벨이라면 징집관 고를라취에게 를 받을 수 있습니다"}, {"페랄라스 모자케 야영지에서 탈로에게 제출하고 먼저 레스텐드리스의 그물를 받은 뒤, 페랄라스 모자케 야영지로 날아가 라리스 정자의 아즈토르딘을 찾으세요"}, {"정화의 성물함은 달의 숲에서 받을 수 있고, 실리더스 세나리온 요새 마파람 마을에서 성물함을 얻어 달의 숲 나이트헤이븐에 제출해야 악령덩굴 조각이 열리니 나중 진행으로 미뤄도 됩니다"}}, tips={{k="動線", text="주 입구에서 푸실린을 먼저 쫓아가 끝에서 전투를 시작합니다 → 레스텐드리스와 히드로스폰은 갈림길에 따라 가는 길에 처치합니다 → 사티로스 제단에서 제브림 쏜후프를 처치합니다 → 마지막 우두머리 알진. 도서관은 서쪽 구역이나 북쪽 구역으로 따로 들어갑니다."}, {k="取捨", text="혈투의 전장 동쪽에서 초승달 열쇠를 먼저 얻으세요. 탈로와 푸실린 퀘스트 두 개가 가장 편합니다. 악령덩굴 조각이 아직 열리지 않았다면 성물함 때문에 두 지도를 오가지 않아도 됩니다."}, {k="說明", text="5인 던전입니다. 동문으로 바로 들어갈 수 있습니다. 우두머리만 건너뛰다가 푸실린을 놓치지 마세요. 열쇠는 서쪽과 북쪽 구역을 열 때 쓰니 남겨 두세요.", s={{"5인 던전입니다"}, {"동문으로 바로 들어갈 수 있습니다"}, {"우두머리만 건너뛰다가 푸실린을 놓치지 마세요"}, {"열쇠는 서쪽과 북쪽 구역을 열 때 쓰니 남겨 두세요"}}}, {k="提醒", text="5인 던전입니다. 동문으로 바로 들어갈 수 있습니다. 우두머리만 건너뛰다가 푸실린을 놓치지 마세요. 열쇠는 서쪽과 북쪽 구역을 열 때 쓰니 남겨 두세요.", s={{"5인 던전입니다"}, {"동문으로 바로 들어갈 수 있습니다"}, {"우두머리만 건너뛰다가 푸실린을 놓치지 마세요"}, {"열쇠는 서쪽과 북쪽 구역을 열 때 쓰니 남겨 두세요"}}}}, steps={[1]={npc="징집관 고를라취", tgt="징집관 고를라취", desc="도시 안내 퀘스트입니다. 탈로에게서 바로 레스텐드리스의 그물를 받아도 됩니다."}, [2]={hint="페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오."}, [3]={npc="탈로 쏜후프", tgt="탈로 쏜후프"}, [4]={npc="탈로 쏜후프", tgt="탈로 쏜후프", desc="호드 버전입니다. 모자케 야영지는 선택 안내 퀘스트이며 바로 받을 수 있습니다."}, [5]={npc="아즈토르딘", tgt="아즈토르딘", desc="모자케 야영지 북쪽의 라리스 정자입니다."}, [6]={npc="라빈 사투르나", tgt="라빈 사투르나", desc="주 경로 52, 56, 59번 지점에서 이미 하는 퀘스트입니다. 제출했다면 건너뛰세요."}, [7]={hint="실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다."}, [8]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [9]={npc="라빈 사투르나", tgt="라빈 사투르나", desc="정화의 성물함을 챙기세요. 페랄라스 소란깃 고원에서 을 아직 끝내지 않았다면 다음에 하세요.", preText="정화의 성물함"}, [10]={text="혈투의 전장: 동쪽 입구"}, [11]={hint="혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.", desc="푸실린을 쫓아가며 각 지점마다 말을 걸어 마지막까지 따라가세요. 위치: 동문에서 먼저 푸실린과 대화하고, 통로를 따라 끝까지 계속 쫓아가세요. 순서: 전투를 시작하려면 길 곳곳에서 여러 번 대화하세요.", spot="동문에서 먼저 푸실린과 대화하고, 통로를 따라 끝까지 계속 쫓아가세요."}, [12]={hint="페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.", desc="위치: 정원에서 위층 통로를 따라 레스텐드리스의 단상으로 가세요.", spot="정원에서 위층 통로를 따라 레스텐드리스의 단상으로 가세요."}, [13]={hint="혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다.", desc="악령덩굴 조각은 알진 근처에 있습니다. 위치: 마지막 통로를 따라 알진의 방으로 가서, 처치한 뒤 조각을 얻어 봉인하세요.", spot="마지막 통로를 따라 알진의 방으로 가서, 처치한 뒤 조각을 얻어 봉인하세요."}, [14]={npc="현자 리드로스", tgt="현자 리드로스", tag="게임 내 확인이 필요합니다", desc="60레벨이 되면 도서관의 리드로스에게서 받을 수 있습니다. 서쪽 또는 북쪽 구역에서 이미 받았다면 동쪽 구역으로 오세요."}, [15]={hint="혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.", desc="위치: 혈투의 전장 동쪽의 아래층 수로로 가서 웅덩이 옆의 히드로스폰을 처치하세요.", spot="혈투의 전장 동쪽의 아래층 수로로 가서 웅덩이 옆의 히드로스폰을 처치하세요."}, [16]={npc="아즈토르딘", tgt="아즈토르딘"}, [17]={npc="탈로 쏜후프", tgt="탈로 쏜후프"}, [18]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [19]={npc="현자 리드로스", tgt="현자 리드로스", tag="게임 내 확인이 필요합니다", desc="도서관으로 돌아가 제출하면 최고 등급 음료 창조를 배울 수 있습니다."}}},
    ["04-55"] = {name="운고로 분화구", tips={{k="交通", text="1단계와 11단계에서 가젯잔을 지나며 도중에 기계 설인을 사용하세요. 마지막 단계에서는 북서쪽 비탈로 실리더스에 가세요."}, {k="取捨", text="아직 반납 금지: 새로운 온천은 여명의 설원 얼음불꽃 온천에서, 깜짝 기계설인 대작전은 눈망루 마을에서 반납하세요. 링쿠의 기억는 악령의 숲 강철나무 숲에 남겨 두세요."}, {k="取捨", text="건너뛰기: 고성능 자동부화기은 알을 주웠고 아직 반납할 수 있을 때만 가세요. 줍지 못했다면 되돌아가지 마세요."}, {k="提醒", text="같은 레벨 57~59 구간이에요. 경험치가 모자라면 불기둥 용광로의 일반 정령이나 북쪽 고릴라를 처치하세요. 평원을 순찰하는 데빌사우루스를 조심하세요.", s={{"같은 레벨 57~59 구간이에요"}, {"경험치가 모자라면 불기둥 용광로의 일반 정령이나 북쪽 고릴라를 처치하세요"}, {"평원을 순찰하는 데빌사우루스를 조심하세요"}}}}, danger={[1]="불기둥 용광로 남쪽 평원에는 레벨 54~56 정예 데빌사우루스가 있어요. 링고를 호위하기 전에 경로를 살펴 두고, 평원을 피해 산허리를 따라가세요."}, grind={[1]={mob="살아있는 불길", note="불기둥 용광로의 일반 정령. 레벨이 더 높고 화산 퀘스트도 함께 진행할 수 있어요. 산허리를 따라 끌고, 데빌사우루스가 순찰하는 평원에는 들어가지 마세요."}, [2]={mob="우두머리 송진괴물", note="마샬의 야영지 근처의 일반 타르 몹. 레벨업까지 조금 모자랄 때 야영지에서 출발해 몇 바퀴 돌 수 있어요. 웅덩이 가장자리에서 한 마리씩 끌어오세요."}}, supply={[1]={npc="그리페"}, [2]={npc="기버트"}, [3]={npc="네르갈"}, [4]={npc="네르갈"}, [5]={npc="여관주인 피즈그림블"}}, steps={[1]={text="먼저 가젯잔에서 묘지 퀘스트를 제출하세요. 기계 설인 퀘스트를 하는 캐릭터도 마을에 남아 설인을 사용한 뒤 남쪽 길로 가세요."}, [2]={npc="자동부화기", npcObj=true, tag="선택사항", desc="페랄라스 공작날개 고원에서 주운 알 1개를 사용하세요. 이미 했다면 건너뛰세요."}, [3]={hint="사용/수집: 히포그리프 알", tag="선택사항"}, [4]={npc="자동부화기", npcObj=true, tag="선택사항"}, [5]={hint="가젯잔 밖에 있는 무덤으로 가서 앞날의 비약을 사용하십시오. 도노바의 지시에 따라 개리얀을 찾아야 합니다.", desc="마시면 죽어요. 먼저 영혼 상태로 대화를 마친 뒤 묘지로 돌아가 부활하세요."}, [6]={npc="개리얀", tgt="개리얀"}, [7]={npc="개리얀", tgt="개리얀"}, [8]={hint="부활한 후, 개리얀이 말한 묘비를 찾아야 합니다."}, [9]={npc="눈에 띄는 묘비", npcObj=true}, [10]={npc="눈에 띄는 묘비", npcObj=true}, [11]={text="먼저 가젯잔의 스프링클(51.06, 26.87)에게 기계 설인을 사용한 뒤, 남쪽 길로 운고로 분화구에 들어가세요."}, [12]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [13]={hint="운고로 분화구에 있는 동쪽 수정탑의 위치를 알아내야 합니다."}, [14]={hint="토르와의 주머니에 든 물건들로 라르코르위를 불러내 물리친 후 라르코르위의 머리를 운고로 분화구 입구에 있는 토르와 패스파인더에게 가져가야 합니다.", desc="토르와의 자루를 열고 먼저 고기를 내려놓은 뒤, 페로몬을 사용해 라르코르위를 유인하세요."}, [15]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 운고로 고릴라 모피 2개, 운고로 우레고릴라 모피 2개, 운고로 천둥고릴라 모피 2개를 가져가야 합니<name>.", tag="대상: 운고로 고릴라 / 운고로 고릴라 / 운고로 우레고릴라 / 운고로 천둥고릴라"}, [16]={hint="운고로 분화구에 있는 북쪽 수정탑의 위치를 알아내야 합니다."}, [17]={hint="운고로 분화구에 있는 링쿠에게 링쿠의 명검을 가져가야 합니다."}, [18]={npc="링쿠", tgt="링쿠"}, [19]={npc="링쿠", tgt="링쿠"}, [20]={hint="마샬의 야영지에 있는 동굴에서 J.D. 콜리를 찾아야 합니다."}, [21]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [22]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [23]={npc="스프래글 프록", tgt="스프래글 프록"}, [24]={hint="우미의 기계설인을 가지고 가서 아래 친구들에게 겁을 주어야 합니다.", desc="처음 두 대상은 눈망루 마을과 이 구간의 이동 중에 완료하세요. 여기서는 퀵실에게 사용한 뒤 서리속삭임 골짜기에서 제출하세요."}, [25]={hint="운고로 분화구에 있는 서쪽 수정탑의 위치를 알아내야 합니다."}, [26]={npc="크래클", tgt="크래클"}, [27]={hint="운고로 분화구에 있는 크래클이 불기둥 마루에서 가장 뜨거운 자리를 찾도록 요청했습니다.", desc="반응이 있으면 완료예요. 용암에 뛰어들 필요는 없어요."}, [28]={hint="불기둥 마루에서 링고 스타를 찾아야 합니다."}, [29]={npc="링고 스타", tgt="링고 스타"}, [30]={npc="링고 스타", tgt="링고 스타", desc="호위하기 전에 동굴 입구를 정리하세요. 링고가 쓰러지면 스프래글의 물통으로 깨우세요."}, [31]={hint="마샬의 야영지에 있는 스프래글 프록에게 링고 스타를 데려다 주어야 합니다."}, [32]={npc="스프래글 프록", tgt="스프래글 프록"}, [33]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [34]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [35]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [36]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [37]={hint="잠시 기다린 후, J.D. 콜리와 대화해야 합니다."}, [38]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [39]={npc="크래클", tgt="크래클"}, [40]={npc="크래클", tgt="크래클"}, [41]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [42]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [43]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [44]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 우차의 모피를 가져가야 합니다.", desc="동굴에 들어가기 전에 바깥쪽 고릴라를 먼저 처치하세요. 우차는 일반 몹이에요."}, [45]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [46]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="선택사항", desc="남동쪽 입구로 들어갈 때 토르와에게 제출하세요. 가죽 방어구나 지팡이를 선택할 수 있어요.", star={"불곰 모피 조끼", {"DRUID"}}}, [47]={text="운고로 북서쪽 비탈로 실리더스에 들어가 길을 따라 곧장 세나리온 요새로 올라가세요."}}},
    ["05-d31"] = {name="구체자의 정원", entrance="운고로 분화구 동부 내륙지로 48.10, 6.10 (티탄 건물 바깥 이정표, 던전 차원문의 정확한 위치는 알 수 없음)", pickup="달의 숲으로 가는 길에 썬더 블러프를 지난다면 먼저 멀고어 북서쪽의 마예나 어스시커에게 들르세요. 운고로 분화구 마샬 야영지로 돌아온 뒤 북쪽 돌계단을 올라 티탄 건물을 찾으세요. 95928을 제외한 두 퀘스트를 주는 NPC는 아직 확인되지 않았습니다.", pickupS={{"달의 숲으로 가는 길에 썬더 블러프를 지난다면 먼저 멀고어 북서쪽의 마예나 어스시커에게 들르세요"}, {"운고로 분화구 마샬 야영지로 돌아온 뒤 북쪽 돌계단을 올라 티탄 건물을 찾으세요"}, {"95928을 제외한 두 퀘스트를 주는 NPC는 아직 확인되지 않았습니다"}}, tips={{k="動線", text="입구 → 티탄 유적을 따라 네 가지 색 수정을 모으고 → 무색 수정 옆에서 웅덩이 목표도 함께 처리합니다. 티탄 용, 볼트, 비트릭스, 나나야의 정확한 처치 순서는 확인 중입니다."}, {k="取捨", text="NPC가 확인된 Crystalline Elements을 먼저 받으세요. 야영지에서 받을 다른 퀘스트가 없으면 파티와 바로 입장하세요."}, {k="說明", text="영원 버전에서 새로 추가된 5인 던전입니다. 마샬 야영지 북쪽 오르막을 오르세요. 티탄 문 앞에서는 운고로에서 채집한 마력의 수정을 쓸 수 있습니다. 운고로 약 48.10, 6.10은 티탄 건물 바깥 입구 이정표이며, 던전 차원문의 정확한 위치는 알 수 없습니다.", s={{"영원 버전에서 새로 추가된 5인 던전입니다"}, {"마샬 야영지 북쪽 오르막을 오르세요"}, {"티탄 문 앞에서는 운고로에서 채집한 마력의 수정을 쓸 수 있습니다"}, {"운고로 약 48.10, 6.10은 티탄 건물 바깥 입구 이정표이며, 던전 차원문의 정확한 위치는 알 수 없습니다"}}}, {k="提醒", text="영원 버전에서 새로 추가된 5인 던전입니다. 마샬 야영지 북쪽 오르막을 오르세요. 티탄 문 앞에서는 운고로에서 채집한 마력의 수정을 쓸 수 있습니다. 운고로 약 48.10, 6.10은 티탄 건물 바깥 입구 이정표이며, 던전 차원문의 정확한 위치는 알 수 없습니다.", s={{"영원 버전에서 새로 추가된 5인 던전입니다"}, {"마샬 야영지 북쪽 오르막을 오르세요"}, {"티탄 문 앞에서는 운고로에서 채집한 마력의 수정을 쓸 수 있습니다"}, {"운고로 약 48.10, 6.10은 티탄 건물 바깥 입구 이정표이며, 던전 차원문의 정확한 위치는 알 수 없습니다"}}}}, steps={[1]={npc="마예나 어스시커", tgt="마예나 어스시커", desc="썬더 블러프 서쪽 고원에서 받으세요. 퀘스트를 주고받는 NPC는 영원 버전 게임 기록과 대조했습니다."}, [2]={npc="연금술사 퓰리", tgt="연금술사 퓰리", tag="게임 내 확인이 필요합니다"}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="게임 내 확인이 필요합니다"}, [4]={text="구체자의 정원 입구"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="게임 내 확인이 필요합니다", desc="위치: 입구에서 티탄 유적 주 경로를 따라가며 정령에게서 네 가지 색을 얻으세요.", spot="입구에서 티탄 유적 주 경로를 따라가며 정령에게서 네 가지 색을 얻으세요."}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="게임 내 확인이 필요합니다", desc="위치: 던전 안에서 스며나오는 점액괴물을 찾으세요. 정확한 웅덩이 위치는 확인 중입니다.", spot="던전 안에서 스며나오는 점액괴물을 찾으세요. 정확한 웅덩이 위치는 확인 중입니다."}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="위치: 무색 수정 옆에서 수정 주변 바닥의 소진된 조각을 찾으세요.", spot="무색 수정 옆에서 수정 주변 바닥의 소진된 조각을 찾으세요."}, [8]={npc="마예나 어스시커"}, [9]={npc="연금술사 퓰리", tgt="연금술사 퓰리", tag="게임 내 확인이 필요합니다"}, [10]={tag="게임 내 확인이 필요합니다"}}},
    ["04-56"] = {name="실리더스", tips={{k="交通", text="1단계에서 세나리온 요새 비행 지점을 개방하세요. 마지막 단계에서는 비행선을 타고 동부 왕국으로 돌아가세요."}, {k="取捨", text="아직 반납 금지: 정화의 성물함과 기록관 움버는 달의 숲에서 반납하도록 남겨 두세요."}, {k="取捨", text="건너뛰기: 노글의 잃어버린 가방는 요새에서 지도 최남단으로 다시 가야 하고, 현상수배: 사막의 난폭자 죽음의 갈고리은 정예를 처치해야 합니다. 레벨링 중이라면 둘 다 건너뛰세요."}, {k="取捨", text="건너뛰기: 영상에서 언급한 그늘날개 퀘스트(혐오스런 그늘날개)는 동부 역병지대에 있습니다. 실리더스의 이 지점에서도 파티 정예 퀘스트는 건너뛰세요."}, {k="提醒", text="레벨 59가 안 됐어도 먼저 서부 역병지대 Bulwark로 가도 돼요. 경험치를 채우려면 요새 북동쪽(약 55, 29)의 일반 전갈과 거미나 남서쪽(약 38, 44)의 황혼 광신도를 처치하세요.", s={{"레벨 59가 안 됐어도 먼저 서부 역병지대 Bulwark로 가도 돼요"}, {"경험치를 채우려면 요새 북동쪽(약 55, 29)의 일반 전갈과 거미나 남서쪽(약 38, 44)의 황혼 광신도를 처치하세요"}}}}, danger={[1]="남풍 마을 탑 꼭대기에서 실리시드 무리가 나타나요. 먼저 탑 안과 계단을 정리하고, 발동한 뒤의 퇴로를 남겨 두세요."}, grind={[1]={mob="황혼의 복수자", note="황혼 야영지 바깥쪽의 일반 광신도. 레벨이 알맞고 황혼 장비를 떨어뜨리며 광신도 퀘스트도 함께 진행할 수 있어요. 장비를 모으는 플레이어를 만나면 야영지 가장자리에서 처치하세요."}, [2]={mob="작살미늘벌레", note="요새 북동쪽 공터의 일반 몹. 레벨은 조금 낮지만 밀도가 좋고 퀘스트 재료 수집 동선과 겹쳐요. 황혼 야영지가 붐비면 이곳으로 옮기세요."}}, supply={[1]={npc="룬크 윈드테이머"}, [2]={npc="캘랜드라스"}, [3]={npc="바르구스"}, [4]={npc="캘랜드라스"}, [5]={npc="캘랜드라스"}, [6]={npc="쿠르 혼스트라이커"}}, steps={[1]={nodeA="{a:3425}", desc="세나리온 요새에 도착하면 룬크 윈드테이머에게서 호드 비행 지점을 개방하세요."}, [2]={text="용사의 안식처를 마친 뒤 쓸 수 있도록 여관(51.89, 39.16)에서 귀환석을 설정해 두세요."}, [3]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼과 대화해야 합니다."}, [4]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [5]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [6]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [7]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [8]={npc="보르 와일드메인", tgt="보르 와일드메인"}, [9]={hint="실리더스에서 돌꼬리전갈 독침 8개와 모래그물 바위거미 송곳니 8개를 모은 후, 세나리온 요새에 있는 비틱스 픽클스프라그에게 돌아가야 합니다."}, [10]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼이 작살미늘벌레 15마리를 처치해 달라고 부탁했습니다."}, [11]={hint="실리더스의 묘지인 용사의 안식처 근처에 있는 라요 스타스트라이크를 찾아가 라빈의 편지를 보여주어야 합니다."}, [12]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [13]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [14]={hint="실리더스의 세나리온 요새에 있는 지질학자 락스베인이 황혼의 서판 조각 8개를 모아 달라고 부탁했습니다."}, [15]={hint="세나리온 요새에 있는 보르 와일드메인에게 암호화된 황혼의 문서 10개를 가져가야 합니다."}, [16]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [17]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [18]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [19]={npc="보르 와일드메인", tgt="보르 와일드메인"}, [20]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [21]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [22]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [23]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼이 망치미늘벌레 20마리를 처치해 달라고 부탁했습니다."}, [24]={hint="실리더스에서 돌꼬리집게전갈 독침 3개, 돌꼬리채찍전갈 독침 3개, 긴다리 바위거미 송곳니 3개를 모은 후, 세나리온 요새에 있는 비틱스 픽클스프라그에게 돌아가야 합니다."}, [25]={hint="실리더스에 있는 은둔자 오르텔에게 복원한 서판을 가져다줘야 합니다."}, [26]={npc="은둔자 오르텔", tgt="은둔자 오르텔"}, [27]={hint="실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다."}, [28]={hint="마파람 마을에서 고통받는 드루이드 8명과 고통받는 파수꾼 8명의 영혼을 해방한 후, 실리더스, 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 돌아가야 합니다.", desc="언데드가 죽으면 실리시드가 생성될 수 있어요. 먼저 처리한 뒤 다음 몹을 끌어오세요."}, [29]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [30]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [31]={hint="마파람 마을에 있는 탑 위로 올라가 실리시드 소굴을 들쑤셔 놓을 방법을 찾아야 합니다. 그러는 가운데 뭔가 알아낸 것이 있으면 실리더스의 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 보고해야 합니다.", desc="물체를 열기 전에 탑 계단의 몹을 먼저 정리하세요. 탑 안은 시야가 좁아요."}, [32]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [33]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [34]={text="세나리온 요새로 돌아가세요. 이 지점에 귀환석을 설정해 두었다면 지금 사용해도 돼요."}, [35]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [36]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [37]={text="요새에서 오그리마로 비행한 뒤 듀로타르에서 티리스팔행 비행선으로 갈아타세요."}}},
    ["04-57"] = {name="서부 역병지대", tips={{k="交通", text="1단계에서 Bulwark에 들어가세요. 마지막 단계에서는 언더시티 밖에서 비행선을 타세요."}, {k="取捨", text="추천: 펠스톤 농장과 안도할을 연이어 하세요. 마지막 흰개미 퀘스트는 돌아오는 길에 나머지와 함께 반납하세요."}, {k="取捨", text="나중에 지나가며: 크로미의 나머지 연계는 동부 역병지대로 다시 가야 합니다. 일부러 돌아갈 때만 받으세요."}, {k="提醒", text="레벨 59가 안 됐다면 악령의 숲으로 가기 전에 안돌할 동쪽 외곽(약 46, 64)이나 역병 농장에서 일반 언데드를 처치하세요.", s={{"레벨 59가 안 됐다면 악령의 숲으로 가기 전에 안돌할 동쪽 외곽(약 46, 64)이나 역병 농장에서 일반 언데드를 처치하세요"}}}}, danger={[1]="안돌할 시청은 레벨 61 정예 소환사 아라즈 근처에 있어요. 다로우샤이어 연대기를 찾을 때는 외벽을 따라 드나드세요."}, grind={[1]={mob="불타죽은 구울", note="안돌할 동쪽 가장자리의 일반 언데드. 농장으로 돌아가기 전에 연달아 처치할 수 있어요. 도시 안의 정예와 건물 무리는 피하세요."}, [2]={mob="오싹한 환영", note="가론의 흉가의 일반 망령. 아직 동쪽에 있다면 가까워서 보충하기 좋고 레벨도 더 높아요. 농장 외곽을 돌아 집 안에서 몹이 연달아 끌려오는 것을 피하세요."}}, supply={[1]={npc="은빛병참장교 하사나"}, [2]={npc="마이클 가레트"}, [3]={npc="여관주인 노먼"}, [4]={npc="여관주인 노먼"}, [5]={npc="엘리노르 러스크"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="티리스팔 비행선 탑에서 Bulwark로 간 뒤 펠스톤 농장, 안돌할, 북마루 벌목지를 지나세요."}, [2]={hint="서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다."}, [3]={npc="어둠의여사제 반디스", tgt="어둠의여사제 반디스"}, [4]={npc="미키 레빈", tgt="미키 레빈"}, [5]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", star={"용기의 쇼트소드", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="퀘스트 목표를 완료하세요."}, [7]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", star={"용기의 쇼트소드", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="미키 레빈", tgt="미키 레빈"}, [9]={hint="서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다."}, [10]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [11]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [12]={hint="서부 역병지대에 있는 펠스톤 농장에서 행운의 부적 목줄을 찾아 붙이십시오.", desc="구울이 농장 안을 돌아다녀요. 먼저 농장 남쪽부터 찾아보세요."}, [13]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [14]={hint="안돌할 폐허 남쪽에서 말레네와 대화해야 합니다."}, [15]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [16]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [17]={hint="조셉의 결혼반지를 크로미에게 가져가야 합니다.", desc="안돌할 중심부에 정예 리치가 있어요. 외곽으로 여관까지 가세요."}, [18]={npc="크로미", tgt="크로미"}, [19]={npc="크로미", tgt="크로미"}, [20]={npc="크로미", tgt="크로미"}, [21]={hint="안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다.", desc="가짜 책은 적을 끌어낼 수 있어요. 표지를 확인하고 중심부의 정예를 피하세요."}, [22]={hint="안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오."}, [23]={npc="크로미", tgt="크로미"}, [24]={npc="크로미", tgt="크로미"}, [25]={npc="크로미", tgt="크로미"}, [26]={hint="안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다."}, [27]={npc="크로미", tgt="크로미"}, [28]={hint="서부 역병지대의 북마루 벌목지 중앙에 적당한 장소를 찾아 역병지대 흰개미 통을 놓아야 합니다."}, [29]={npc="흰개미 통", npcObj=true}, [30]={npc="흰개미 통", npcObj=true}, [31]={hint="북마루 벌목지에 역병지대 흰개미를 놓아준 다음 역병지대 흰개미 통을 가지고 트리스팔 숲 보루에 있는 미키 레빈에게 돌아가야 합니다.", desc="통을 열면 적이 몰려와요. 열자마자 자리를 피하세요."}, [32]={npc="미키 레빈", tgt="미키 레빈"}, [33]={npc="애도의 기사", tag="선택사항, 게임 내 확인이 필요합니다", desc="티리스팔 숲 남서쪽에서 애도의 기사를 찾으세요. 완료하면 애도의 검(Sword of Mourning)을 보상으로 선택할 수 있어요.", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="언더시티 비행선 탑으로 돌아가 오그리마행 비행선을 타고, 이어서 악령의 숲으로 가세요."}}},
    ["05-d32"] = {name="스칼로맨스", entrance="서부 역병지대 바다의 위협 약 68.90, 72.80 (카엘 다로우 지하 입구)", pickup="서부 역병지대 언데드 보루에서 알렉시에게 바로브 가의 유산과 열쇠 연계의 앞부분을 먼저 받고, 희망의 빛 예배당에서 역병 걸린 작은 새끼용를 받으세요. 언데드 보루에서 남쪽 길로 카엘 다로우 섬에 올라 먼저 에바를 찾고 입구로 들어가세요. 열쇠를 직접 만들려면 언데드 보루에서 뼈조각을 제출하고 거푸집 퀘스트를 받은 뒤, 타나리스 가젯잔과 운고로 분화구 불기둥 용광로에 갔다가 마지막으로 언데드 보루에서 완료하세요.", pickupS={{"서부 역병지대 언데드 보루에서 알렉시에게 바로브 가의 유산과 열쇠 연계의 앞부분을 먼저 받고, 희망의 빛 예배당에서 역병 걸린 작은 새끼용를 받으세요"}, {"언데드 보루에서 남쪽 길로 카엘 다로우 섬에 올라 먼저 에바를 찾고 입구로 들어가세요"}, {"열쇠를 직접 만들려면 언데드 보루에서 뼈조각을 제출하고 거푸집 퀘스트를 받은 뒤, 타나리스 가젯잔과 운고로 분화구 불기둥 용광로에 갔다가 마지막으로 언데드 보루에서 완료하세요"}}, tips={{k="動線", text="입구 다리 → 첫 번째 대전당에서 토지 증서 → 소환의 전당 뒤에서 다른 증서 → 납골당에서 피의 뼈 골렘과 역병 새끼용을 처치 → 라스 프로스트위스퍼의 방에서 증서 → 아래층 여섯 방에서 마지막 증서를 얻고 크라스티노프의 방을 정리 → 암흑스승 간들링."}, {k="取捨", text="토지 증서 네 장, 역병 새끼용, 교수를 한 번에 처리하면 효율이 좋습니다. 파티에 문을 열 수 있는 사람이 있으면 나머지는 열쇠 재료 연계를 통째로 건너뛰어도 됩니다."}, {k="說明", text="5인 던전입니다. 열쇠를 가진 사람이 먼저 바깥 문을 여세요. 교수 이후의 소름끼치는 크라스티노브의 가방, 사자 키르토노스는 던전을 이어서 반복해야 하니, 같은 파티가 다시 오는 일정에 맞춰 남겨 두세요.", s={{"5인 던전입니다"}, {"열쇠를 가진 사람이 먼저 바깥 문을 여세요"}, {"교수 이후의 소름끼치는 크라스티노브의 가방, 사자 키르토노스는 던전을 이어서 반복해야 하니, 같은 파티가 다시 오는 일정에 맞춰 남겨 두세요"}}}, {k="提醒", text="5인 던전입니다. 열쇠를 가진 사람이 먼저 바깥 문을 여세요. 교수 이후의 소름끼치는 크라스티노브의 가방, 사자 키르토노스는 던전을 이어서 반복해야 하니, 같은 파티가 다시 오는 일정에 맞춰 남겨 두세요.", s={{"5인 던전입니다"}, {"열쇠를 가진 사람이 먼저 바깥 문을 여세요"}, {"교수 이후의 소름끼치는 크라스티노브의 가방, 사자 키르토노스는 던전을 이어서 반복해야 하니, 같은 파티가 다시 오는 일정에 맞춰 남겨 두세요"}}}}, steps={[1]={npc="알렉시 바로브", tgt="알렉시 바로브", desc="언데드 보루에서 52레벨이 되면 미리 받을 수 있습니다."}, [2]={npc="베티나 비글징크", tgt="베티나 비글징크", desc="희망의 빛 예배당에서 베티나를 찾으세요."}, [3]={npc="에바 사크호프", tgt="에바 사크호프", desc="카엘 다로우 문 앞에서 에바를 찾으세요."}, [4]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="스칼로맨스 열쇠를 직접 만들어야 할 때만 하세요. 서부 역병지대 언데드 보루에서 이미 했다면 건너뛰어도 됩니다."}, [5]={hint="펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오."}, [6]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [7]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="서부 역병지대 언데드 보루 주 경로에 이미 있습니다.", preText="붉은십자군의 주의 끌기"}, [8]={hint="신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다."}, [9]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [10]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="서부 역병지대 언데드 보루에서 미리 제출할 수 있습니다.", preText="감시탑 공격 준비"}, [11]={hint="서부 역병지대의 보루에 있는 연금술사 디더스와 대화하십시오."}, [12]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [13]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="서부 역병지대 언데드 보루에서 이미 받았거나 제출했다면 이 세 단계는 건너뛰세요. 열쇠를 직접 준비한다면 거푸집 퀘스트를 받으세요.", preText="스칼로맨스"}, [14]={hint="서부 역병지대의 보루에 있는 연금술사 디더스에게 뼈조각 15개를 가져가야 합니다."}, [15]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [16]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="운고로 분화구 마샬 야영지에 가기 전, 가젯잔을 떠나기 전에 토륨 주괴 2개를 준비하세요.", preText="뼈조각"}, [17]={hint="가젯잔에 있는 크린클 굿스틸에게 15골드와 함께 마력 깃든 뼈조각을 가져가야 합니다."}, [18]={npc="크린클 굿스틸", tgt="크린클 굿스틸"}, [19]={npc="크린클 굿스틸", tgt="크린클 굿스틸", desc="운고로 분화구 마샬 야영지에서 불기둥 용광로 퀘스트와 같은 판에 끝낼 수 있습니다.", preText="거푸집과 뼈조각"}, [20]={hint="운고로 분화구에 있는 불기둥 마루 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집으로 불완전한 해골 열쇠를 만들어야 합니다."}, [21]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [22]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="서부 역병지대 언데드 보루에서 안도할을 할 때는 파티가 있을 때만 진행하세요.", preText="불기둥 용광로"}, [23]={hint="소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대에 보루에 있는 연금술사 디더스에게 돌아가야 합니다."}, [24]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [25]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", preText="아라즈의 스카라베"}, [26]={hint="퀘스트 목표를 완료하세요."}, [27]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [28]={text="스칼로맨스 입구"}, [29]={hint="스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.", desc="위치: 첫 번째 대전당, 소환의 전당 뒤, 프로스트위스퍼의 방, 바로브의 방을 차례로 뒤지세요. 순서: 사우스쇼어 → 타렌 밀농장 → 브릴 → 카엘 다로우.", spot="첫 번째 대전당, 소환의 전당 뒤, 프로스트위스퍼의 방, 바로브의 방을 차례로 뒤지세요."}, [30]={hint="역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다.", desc="위치: 소환의 전당을 지나 납골당으로 들어가 피의 뼈 골렘 방에서 새끼용을 처치하세요.", spot="소환의 전당을 지나 납골당으로 들어가 피의 뼈 골렘 방에서 새끼용을 처치하세요."}, [31]={hint="스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.", desc="에바와 루시앙의 유해는 교수의 방에 있습니다. 위치: 마지막 여섯 방에서 크라스티노프를 찾고, 같은 방에서 유해 두 구를 불태우세요. 순서: 유해는 같은 방에 있습니다.", spot="마지막 여섯 방에서 크라스티노프를 찾고, 같은 방에서 유해 두 구를 불태우세요."}, [32]={npc="에바 사크호프", tgt="에바 사크호프", desc="에바에게서 다음 진행용 공포의 주머니를 받을 수 있습니다. 레벨링 첫 진행에서는 교수만 제출해도 됩니다."}, [33]={npc="알렉시 바로브", tgt="알렉시 바로브"}, [34]={npc="베티나 비글징크", tgt="베티나 비글징크"}}},
    ["04-58"] = {name="악령의 숲", tips={{k="交通", text="1단계에서는 잿빛 골짜기에서 북쪽으로 가세요. 마지막 단계에서는 나무구렁 요새를 지나 달의 숲으로 가세요."}, {k="取捨", text="건너뛰기: 마지막 일격는 깊숙한 곳의 목표 세 개를 위해 어둠의 요새를 한 번 더 지나야 합니다. 혼자 하기 힘들면 건너뛰세요."}, {k="取捨", text="아직 반납 금지: 맹독 정령은 여명의 설원 얼음불꽃 온천에 가져가 반납하세요."}, {k="提醒", text="레벨 60이 안 됐다면 강철나무 숲(약 49, 25)에서 맹독 정령과 철목 트렌트를 처치하거나, 부족분은 여명의 설원에서 채우세요.", s={{"레벨 60이 안 됐다면 강철나무 숲(약 49, 25)에서 맹독 정령과 철목 트렌트를 처치하거나, 부족분은 여명의 설원에서 채우세요"}}}}, danger={[1]="어둠의 요새의 화로는 좁은 동굴 통로에 흩어져 있어요. 한 구간을 정리한 뒤 불을 끄고, 물러날 때는 온 길을 되짚으세요."}, grind={[1]={mob="맹독 정령", note="강철나무 숲 웅덩이 옆의 일반 정령. 맹독 물방울도 함께 모을 수 있어요. 레벨이 낮아 부족한 경험치가 적을 때만 알맞고, 웅덩이가 붐비면 여명의 설원으로 가세요."}, [2]={mob="굽이나무 갈퀴늪괴물", note="북쪽 길가의 일반 트렌트. 웅덩이가 붐비면 이어서 처치하고, 길가라서 나무구렁 요새로 계속 가기 편해요. 야영지 안의 시전 몹을 조심하세요."}}, supply={[1]={npc="여관주인 카일리스크"}, [2]={npc="여관주인 카일리스크"}, [3]={npc="브라카르"}, [4]={npc="알트소바 레이지토템"}, [5]={npc="베일"}, [6]={npc="베일"}}, steps={[1]={text="오그리마에서 토막나무 주둔지로 비행하세요. 대로를 따라 북쪽 악령의 숲에 들어가 먼저 에메랄드 성소와 가까운 길가로 가세요."}, [2]={npc="메이베스 리버브리즈", tgt="메이베스 리버브리즈"}, [3]={hint="정화된 달샘 물을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다."}, [4]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [5]={hint="악령의 숲 남부에 있는 에리단 블루윈드를 찾아가야 합니다."}, [6]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [7]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [8]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [9]={hint="정화된 달샘 물을 써서 악령의 숲에 있는 어둠의 요새를 감싸고 있는 화로 4개를 파괴한 후 에메랄드 성소에 있는 그레타 모스후프에게 돌아가야 합니다.", desc="먼저 통로를 정리한 뒤 깊이 들어가세요. 동굴 안에서는 좌표 표시가 겹칠 수 있어요."}, [10]={hint="악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.", desc="늑대와 곰이 은빛 발톱을 떨어뜨려요. 강철나무의 심장은 철목 트렌트에게서 얻으세요."}, [11]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [12]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [13]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="선택사항", desc="함께하는 사람이 있거나 한 마리씩 안정적으로 끌 수 있을 때만 어둠의 요새 깊은 곳에서 하세요."}, [14]={hint="무라와 살리라, 그리고 어둠의 군주 펠단을 처치하십시오. 그리고 그 증거로 펠단의 머리카락을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.", tag="선택사항", desc="경비병 두 명과 영주가 가까이 있으니 근처 순찰부터 정리하세요."}, [15]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="선택사항"}, [16]={npc="트룰 페일베인", tgt="트룰 페일베인"}, [17]={hint="여명의 설원에 있는 도노바 스노우덴에게 맹독 정령 수액 3개를 갖다주어야 합니다."}, [18]={npc="임프시", tgt="임프시", tag="선택사항", desc="영혼 수확기(Soul Harvester) 등을 보상으로 선택할 수 있어요.", star={"영혼 수확기", {"WARLOCK"}}}, [19]={hint="악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다.", tag="선택사항", desc="45, 52, 57번 지점의 이동 중에 이미 다 모았다면 곧장 임프시에게 돌아가세요."}, [20]={npc="임프시", tgt="임프시", tag="선택사항"}, [21]={npc="임프시", tgt="임프시", tag="선택사항", desc="정예 전투는 파티를 권장해요. 니비에게 돌아가 제출하면 지옥불정령 소환(Inferno)이 열려요."}, [22]={hint="악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.", tag="선택사항", desc="정예 전투는 파티를 권장해요. 니비에게 돌아가 제출하면 지옥불정령 소환(Inferno)이 열려요."}, [23]={npc="전지전능한 나이비", tgt="전지전능한 나이비", tag="선택사항", desc="정예 전투는 파티를 권장해요. 니비에게 돌아가 제출하면 지옥불정령 소환(Inferno)이 열려요."}, [24]={text="길을 따라 북쪽으로 나무구렁 요새에 들어가 달의 숲 방향으로 가세요."}}},
    ["04-59"] = {name="달의 숲", tips={{k="交通", text="1단계에서는 나이트헤이븐까지 걸어가세요. 마지막 단계에서는 가진 퀘스트에 따라 온천이나 눈망루 마을을 고르세요."}, {k="取捨", text="추천: 나이트헤이븐의 NPC 두 명에게 한 번의 마을 방문으로 반납하세요."}, {k="取捨", text="나중에 지나가며: 악령덩굴 조각은 혈투의 전장 동쪽이 필요하니 던전 일정에 남겨 두세요."}, {k="提醒", text="여전히 레벨 59~60 구간이에요. 마치면 바로 서리속삭임 골짜기로 가세요.", s={{"여전히 레벨 59~60 구간이에요"}, {"마치면 바로 서리속삭임 골짜기로 가세요"}}}}, danger={[1]="달의 숲에서 여명의 설원으로 갈 때 나무구렁 평판이 여전히 적대적이라면 곧장 동굴을 통과하지 말고, 악령의 숲 쪽에서 평판부터 올리세요."}, grind={[1]={mob="광포한 톱니이빨곰", note="달의 숲에서 제출한 뒤 요새를 지나 여명의 설원으로 가서, 서리속삭임 골짜기 북쪽 입구의 일반 곰을 처치하세요. 레벨이 60에 가까우니 골짜기 아래의 정예는 피하세요."}}, supply={[1]={npc="멜리리"}, [2]={npc="다르곤"}, [3]={npc="대올린 서머리프"}, [4]={npc="파우스트론"}}, steps={[1]={text="나무구렁 요새를 나와 대로를 따라 나이트헤이븐으로 가서, 실리더스에서 받은 아이템 두 개를 제출하세요."}, [2]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [3]={hint="달의 숲의 나이트헤이븐 마을에 있는 세나리온 의회의 기록관, 움버에게 딱딱한 실리시드 조각을 가져가야 합니다."}, [4]={npc="움버", tgt="움버"}, [5]={npc="움버", tgt="움버"}, [6]={hint="달의 숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다."}, [7]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [8]={npc="움버", tgt="움버"}, [9]={hint="퀘스트 목표를 완료하세요."}, [10]={npc="움버", tgt="움버"}, [11]={text="새로운 온천이나 맹독 정령을 갖고 있다면 달의 숲에서 온 길로 나무구렁 요새를 지나 여명의 설원 온천으로 가세요. 둘 다 없고 Donova의 사이드 퀘스트를 건너뛸 때만 파우스트론(32.09, 66.61)에게서 눈망루 마을로 비행하세요."}}},
    ["04-60"] = {name="여명의 설원", tips={{k="交通", text="1단계에서 먼저 얼음불꽃 온천에 들르세요. 눈망루 마을 설인 퀘스트를 제출한 뒤 남쪽으로 가고, 마지막 단계에서는 골짜기 북쪽 입구 밖에서 경험치를 채우세요."}, {k="取捨", text="추천: 눈사태일족 정찰꾼은 혼자 있는 전령을 우선 찾으세요. 이상한 근원는 탐험 퀘스트로, 영상의 사냥 지점으로 가는 길에 있습니다."}, {k="取捨", text="건너뛰기: 대부족장 눈사태은 정예 대상이 있으니, 혼자라면 일반 곰을 잡아 경험치를 채우세요."}, {k="提醒", text="60레벨 미만이면 영상대로 서리속삭임 골짜기 북쪽에서 곰을 잡으세요. 일반 광기의 조각니 곰은 57.63, 70.83 / 66.68, 70.57 부근에 있습니다. 골짜기 바닥의 정예는 피하세요.", s={{"60레벨 미만이면 영상대로 서리속삭임 골짜기 북쪽에서 곰을 잡으세요"}, {"일반 광기의 조각니 곰은 57.63, 70.83 / 66.68, 70.57 부근에 있습니다"}, {"골짜기 바닥의 정예는 피하세요"}}}}, danger={[1]="서리속삭임 골짜기 안에는 레벨 59~60 정예 Frostmaul 거인이 있어요. 북쪽 입구에서 곰을 처치할 때는 비탈을 따라 한 마리씩 끌고, 몹을 골짜기 안으로 끌고 들어가지 마세요.", [2]="레벨 57~60 정예 헤데린 슬레이어가 검은속삭임 협곡에 있어요. 이상한 근원은 북쪽 입구에서 시작되니, 완료하면 길로 돌아오세요."}, grind={[1]={mob="광포한 톱니이빨곰", note="서리속삭임 골짜기 북쪽 입구 서쪽의 일반 곰. 근접 몹이라 한 마리씩 끌어와 가죽을 벗길 수 있어요. 다 처치하면 동쪽으로 돌아가며 번갈아 사냥하고, 골짜기 아래의 정예 구역에는 들어가지 마세요."}, [2]={mob="광포한 톱니이빨곰", note="골짜기 북쪽 입구 동쪽의 일반 곰. 서쪽에 사람이 많거나 아직 다시 생성되지 않았다면 비탈을 따라 이쪽으로 옮기세요. 비탈 쪽으로 끌어 길로 돌아오고, 골짜기 아래의 정예를 피하세요."}}, supply={[1]={npc="유그렉"}, [2]={npc="여관주인 비지"}, [3]={npc="닉스락"}, [4]={npc="여관주인 비지"}, [5]={npc="윅스락"}}, steps={[1]={text="나무구렁 요새를 나와 먼저 온천에서 도노바를 만나 마샬의 야영지와 악령의 숲 강철나무 숲 퀘스트를 제출한 뒤, 눈망루 마을과 남쪽 골짜기로 가세요. 눈망루 마을로 바로 비행하고 온천 퀘스트를 건너뛴다면 우미 럼플스니커부터 시작하세요."}, [2]={hint="여명의 설원으로 가서 도노바 스노우덴과 대화하십시오."}, [3]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [4]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [5]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [6]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [7]={hint="눈사태일족 정찰꾼들을 찾아 눈사태일족 마을로 물건을 전달하는 것을 막아야 합니다.", desc="주 도로의 전령은 무리 지어 있으니, 혼자라면 나무구렁 입구나 죽은나무 솥 근처에서 혼자 있는 전령을 노리세요."}, [8]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [9]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항", desc="레벨 59 정예이고 옆에 다른 펄볼그가 있어요. 파티원이 있을 때 진행하세요."}, [10]={hint="여명의 설원에 있는 도노바 스노우덴이 대부족장 눈사태를 처치해 달라고 부탁했습니다.", tag="선택사항", desc="먼저 바깥 몹을 정리하세요. 전투 후 편지를 얻으면 필요에 따라 후속 퀘스트를 이어 가세요."}, [11]={npc="휘갈겨 쓴 일지", npcObj=true, tag="선택사항", desc="대부족장 눈사태를 처치해 일지를 얻은 뒤에만 우클릭해 퀘스트를 받으세요."}, [12]={hint="여명의 설원에 있는 도노바 스노우덴에게 휘갈겨 쓴 일지를 가져다주어야 합니다.", tag="선택사항"}, [13]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항"}, [14]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항"}, [15]={npc="우미 럼플스니커", tgt="우미 럼플스니커"}, [16]={hint="도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오.", desc="골짜기 입구까지만 가세요. 깊은 곳의 정예는 피하세요."}, [17]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [18]={text="레벨 60이 안 됐다면 골짜기 북쪽 입구 밖에서 일반 광기의 톱니이빨곰을 처치하세요."}}},
    ["05-d34"] = {name="검은바위 첨탑 상층", entrance="이글거리는 협곡 34.80, 85.30 (검은바위 산 바깥 이정표)", pickup="55레벨이 되면 겨울샘 골짜기 눈망루 마을에서 오그리마로 날아가고, 비행선으로 동부 왕국에 가서 먼저 하층 장군의 명령을 하세요. 카르가스의 고어투스에게서 아이트리그의 지혜을 받습니다. 불모의 땅 톱니항을 거친 뒤 오그리마 지혜의 골짜기에서 아이트리그와 스랄에게 제출하고 호드를 위하여!는 남겨 두세요. 57레벨이 되면 언더시티 연금술 구역에서 비비안 라그레이브와 다크스톤 서판를 받고, 카르가스로 날아가 비비안에게 제출한 뒤 다크스톤 서판을 받으세요. 하층에서 최소 한 명이 승천의 인장 → 승천의 인장을 끝내 인장으로 문을 열어야 합니다. 인장을 가진 파티원이 있다면 바로 상층을 돌 수 있습니다.", pickupS={{"55레벨이 되면 겨울샘 골짜기 눈망루 마을에서 오그리마로 날아가고, 비행선으로 동부 왕국에 가서 먼저 하층 장군의 명령을 하세요"}, {"카르가스의 고어투스에게서 아이트리그의 지혜을 받습니다"}, {"불모의 땅 톱니항을 거친 뒤 오그리마 지혜의 골짜기에서 아이트리그와 스랄에게 제출하고 호드를 위하여!는 남겨 두세요"}, {"57레벨이 되면 언더시티 연금술 구역에서 비비안 라그레이브와 다크스톤 서판를 받고, 카르가스로 날아가 비비안에게 제출한 뒤 다크스톤 서판을 받으세요"}, {"하층에서 최소 한 명이 승천의 인장 → 승천의 인장을 끝내 인장으로 문을 열어야 합니다"}, {"인장을 가진 파티원이 있다면 바로 상층을 돌 수 있습니다"}}, tips={{k="動線", text="용 탑 대전당의 룬 일곱 개 → 불의수호자 엠버시어 → 부화장에서 석판 → 블랙핸드 대전당 → 투기장에서 렌드와 게스 처치 → 용광로(비스 괴수는 선택) → 탑 꼭대기 왕좌에서 드라키사스를 처치하고 뒤의 보주 확인."}, {k="取捨", text="카르가스와 오그리마의 퀘스트를 먼저 받으세요. 블랙핸드의 명령서는 공격대 던전 입장 선행 퀘스트이므로 필요할 때 하세요."}, {k="說明", text="하층과 바깥 문을 같이 씁니다. 입장한 뒤 왼쪽 위로 가서 상층의 잠긴 문을 찾으세요. 파티를 모을 때는 승천의 인장을 쓸 수 있는 파티원을 먼저 찾으세요. 출시 후 공략에는 상층 입구의 실제 문 순서가 정리되어 있습니다. 점프 지형이 길을 막으면 상층 바깥쪽 보도로 가세요.", s={{"하층과 바깥 문을 같이 씁니다"}, {"입장한 뒤 왼쪽 위로 가서 상층의 잠긴 문을 찾으세요"}, {"파티를 모을 때는 승천의 인장을 쓸 수 있는 파티원을 먼저 찾으세요"}, {"출시 후 공략에는 상층 입구의 실제 문 순서가 정리되어 있습니다"}, {"점프 지형이 길을 막으면 상층 바깥쪽 보도로 가세요"}}}}, steps={[1]={npc="장군 고어투스", tgt="장군 고어투스", desc="NPC가 바로 수락 창을 열어 주지 않으면, 먼저 대화해 장군의 명령을 얻은 뒤 우클릭으로 사용하세요."}, [2]={hint="대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다.", desc="문서 위치는 바뀔 수 있습니다. 앞의 세 방에 도착하면 먼저 찾아보세요. 문서는 어느 우두머리 방에서든 나올 수 있으니 방마다 확인하세요."}, [3]={npc="장군 고어투스", tgt="장군 고어투스"}, [4]={npc="장군 고어투스", tgt="장군 고어투스", preText="장군의 명령"}, [5]={hint="오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다."}, [6]={npc="스랄", tgt="스랄"}, [7]={npc="스랄", tgt="스랄", preText="아이트리그의 지혜"}, [8]={npc="연금술사 진게", tgt="연금술사 진게", tag="선택사항", desc="57레벨에 언더시티 연금술 구역에서 받으세요. 다크스톤 서판을 이미 받았다면 이 연결 퀘스트는 건너뛰어도 됩니다."}, [9]={hint="어둠마법사 비비안 라그레이브와 대화해야 합니다.", tag="선택사항"}, [10]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브", tag="선택사항"}, [11]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브", desc="비비안이 퀘스트를 주면 바로 받으세요. 아직 나타나지 않으면 언더시티의 비비안 라그레이브와 다크스톤 서판 안내 퀘스트부터 시작하세요."}, [12]={npc="블랙핸드의 명령서", npcObj=true, tag="선택사항", desc="검은바위 첨탑 입구 밖에서 방패부대 병참장교에게 편지를 얻은 뒤 우클릭해 받으세요. 검은날개 둥지를 열 생각이 있을 때만 하세요."}, [13]={text="검은바위 첨탑 상층 입구"}, [14]={hint="검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.", desc="위치: 부화장을 지나 블랙핸드 대전당으로 올라가고, 투기장 북문으로 들어가 렌드를 발동시키세요. 순서: 부화장의 석판을 먼저 얻은 뒤 투기장을 돌파하세요.", spot="부화장을 지나 블랙핸드 대전당으로 올라가고, 투기장 북문으로 들어가 렌드를 발동시키세요."}, [15]={hint="카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다.", desc="길가에 붙어 용알을 피하세요. 알을 밟아 깨뜨리면 새끼용이 나옵니다. 위치: 불의수호자 엠버시어를 처치한 뒤 부화장에 들어가 벽을 따라 바닥의 석판을 찾으세요. 순서: 13단계의 투기장 앞에서 끝내세요.", spot="불의수호자 엠버시어를 처치한 뒤 부화장에 들어가 벽을 따라 바닥의 석판을 찾으세요."}, [16]={hint="아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다.", tag="선택사항", desc="낙인은 드라키사스 뒤에 있습니다. 위치: 투기장 남문으로 나가 용광로를 지나 왕좌로 가세요. 낙인은 우두머리 뒤에 있습니다. 순서: 드라키사스를 처치한 뒤 그 뒤의 낙인을 클릭하세요.", spot="투기장 남문으로 나가 용광로를 지나 왕좌로 가세요. 낙인은 우두머리 뒤에 있습니다."}, [17]={npc="드라키사스의 낙인", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", spot="드라키사스 왕좌 뒤의 낙인"}, [18]={npc="스랄", tgt="스랄"}, [19]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="여명의 설원 66.60, 84.40", pickup="발로르모크에서 제디가에게 Beneath Nordrassil을 받고, 같은 지점의 오그틴크에게 찢는 발톱, 꿰뚫는 엄니를 받으세요. 55레벨이 되면 아즈샤라로 돌아가 에칼을 찾으세요. 불모의 땅 톱니항을 거쳐 칼림도어로 돌아갈 때 먼저 썬더 블러프로 날아가 장로의 봉우리에서 제디가의 편지를 제출하고 뿌리를 찾아서을 받으세요. 멀고어에서는 멀른 어스퓨리를 찾으세요. 마지막으로 발로르모크로 날아가 아즈샤라 지하 통로로 던전에 가세요. 뿌리를 찾아서과 검은아귀 마법은 다음 썬더 블러프와 멀고어 일정까지 남겨 두세요.", pickupS={{"발로르모크에서 제디가에게 Beneath Nordrassil을 받고, 같은 지점의 오그틴크에게 찢는 발톱, 꿰뚫는 엄니를 받으세요"}, {"55레벨이 되면 아즈샤라로 돌아가 에칼을 찾으세요"}, {"불모의 땅 톱니항을 거쳐 칼림도어로 돌아갈 때 먼저 썬더 블러프로 날아가 장로의 봉우리에서 제디가의 편지를 제출하고 뿌리를 찾아서을 받으세요"}, {"멀고어에서는 멀른 어스퓨리를 찾으세요"}, {"마지막으로 발로르모크로 날아가 아즈샤라 지하 통로로 던전에 가세요"}, {"뿌리를 찾아서과 검은아귀 마법은 다음 썬더 블러프와 멀고어 일정까지 남겨 두세요"}}, tips={{k="動線", text="입구 곰 인간 통로를 따라 검은아귀 주머니를 줍고 → 지하 뿌리 구역에서 놀드랏실 뿌리갓을 모으고 → 마른아귀와 해골주둥이의 갈림길 → 핏빛갈기 장로에게서 의식 토템을 얻습니다. 갈림길과 우두머리 순서는 확인 중입니다."}, {k="取捨", text="가는 길에 오그틴크와 엘다라스 폐허 퀘스트를 먼저 준비하세요. 호드 뿌리갓 연계는 썬더 블러프에서 한 번에 끝낼 수 있습니다."}, {k="說明", text="차원문 좌표는 여명의 설원 지도에 표시됩니다. 아즈샤라 38.70, 33.40에서 곰 인간 지하 통로로 들어가 끝까지 걸어 문으로 가세요. 여명의 설원 지상에서는 찾지 마세요.", s={{"차원문 좌표는 여명의 설원 지도에 표시됩니다"}, {"아즈샤라 38.70, 33.40에서 곰 인간 지하 통로로 들어가 끝까지 걸어 문으로 가세요"}, {"여명의 설원 지상에서는 찾지 마세요"}}}}, steps={[1]={npc="제디가", tgt="제디가", tag="게임 내 확인이 필요합니다"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff.", tag="게임 내 확인이 필요합니다"}, [3]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="게임 내 확인이 필요합니다"}, [4]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="게임 내 확인이 필요합니다", preText="Beneath Nordrassil"}, [5]={npc="오그틴크", tgt="오그틴크"}, [6]={npc="알라나 스톰워커", tgt="Muln Earthfury", desc="멀고어에서 썬더 블러프로 이어지는 구역입니다. 멀고어 지도 좌표를 따라 찾으세요."}, [7]={npc="에칼", tgt="에칼"}, [8]={text="Blackmaw Hold 입구"}, [9]={hint="검은아귀 요새에서 놀드랏실 뿌리 버섯 10개를 채집해 썬더 블러프에 있는 나라 와일드메인에게 전달해야 합니다.", tag="게임 내 확인이 필요합니다", desc="위치: 도시 안 통로를 따라 지하 뿌리 구역으로 가서, 뿌리에서 뿌리갓을 채집하세요.", spot="도시 안 통로를 따라 지하 뿌리 구역으로 가서, 뿌리에서 뿌리갓을 채집하세요."}, [10]={hint="위대한 곰의 발톱과 굽히지 않는 자의 엄니를 아즈샤라에 있는 오그틴크에게 가져가야 합니<name>.", tag="대상: 거대 곰 마른아귀 / '꺾이지 않는 자' 해골주둥이, 게임 내 확인이 필요합니다", desc="위치: 곰 인간 통로에서 마른아귀와 해골주둥이를 찾으세요. 갈림길은 확인 중입니다.", spot="곰 인간 통로에서 마른아귀와 해골주둥이를 찾으세요. 갈림길은 확인 중입니다."}, [11]={hint="검은아귀 요새에서 검은아귀 의식 토템을 회수해야 합니다.", tag="게임 내 확인이 필요합니다", desc="위치: 도시에 들어가 우두머리 경로를 따라 핏빛갈기 장로를 찾아 의식 토템을 얻으세요.", spot="도시에 들어가 우두머리 경로를 따라 핏빛갈기 장로를 찾아 의식 토템을 얻으세요."}, [12]={hint="획득처: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", desc="위치: 입구로 들어가 곰 인간 거주 구역에서 타락한 검은아귀를 정리하고, 주머니를 챙기세요.", spot="입구로 들어가 곰 인간 거주 구역에서 타락한 검은아귀를 정리하고, 주머니를 챙기세요."}, [13]={npc="오그틴크", tgt="오그틴크"}, [14]={npc="에칼", tgt="에칼"}, [15]={npc="나라 와일드메인"}, [16]={npc="알라나 스톰워커", tgt="Muln Earthfury"}}},
  },
  quests = {
    [2] = {n="뾰족발톱의 발톱", d="뾰족발톱의 발톱을 잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다."},
