    [6522] = {n="사악한 동맹", d="작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다."},
    [6541] = {n="카드라크에게 보고", d="불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오."},
    [6543] = {n="전쟁노래부족 보고서", d="먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오."},
    [6544] = {n="토렉의 공격", d="은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오."},
    [6545] = {n="전쟁노래부족 길잡이 최신정보"},
    [6546] = {n="전쟁노래부족 척후병 최신정보"},
    [6547] = {n="전쟁노래부족 정찰병 최신정보"},
    [6561] = {n="검은심연의 음모", d="황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", tgo={{"황혼의 군주 켈리스"}}},
    [6562] = {n="검은심연의 나락으로...", d="잿빛 골짜기에 있는 제네우 생크리와 대화하십시오."},
    [6563] = {n="아쿠마이의 정수", d="잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.", objs={"아쿠마이의 사파이어"}},
    [6564] = {n="고대 신들에 대한 충성", d="축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오."},
    [6565] = {n="고대 신들에 대한 충성", d="검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", tgo={{"로구스 제트"}}},
    [6621] = {n="썩은나무일족의 왕", d="썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다.", tgo={{"족장 머구트"}}},
    [6626] = {n="악의 무리", d="가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다.", tgo={{"가시덩굴일족 전투호위병"}, {"가시덩굴일족 가시마술사"}, {"죽음의 머리교 신도"}}},
    [6627] = {n="지혜의 시험", d="브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다."},
    [6641] = {n="채찍꼬리 보르샤", d="머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오.\n성공하면 조람가르 전초기지로 돌아와 전쟁노래부족 길잡이에게 채찍꼬리 보르샤의 죽음을 보고하십시오."},
    [6681] = {n="라벤홀트 장원", d="힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.\n라벤홀트 장원의 입구 근처에서 자신의 실력을 증명할 상자를 발견하게 될 것이며 어떤 기술을 사용하여 이를 증명해야 할지 준비해야 합니다.", tgo={{"라벤홀트"}}},
    [6701] = {n="비밀결사대 문장", d="획득처: 비밀결사대 암살자, 비밀결사대 요술사, 비밀결사대 노상강도", tgo={{"비밀결사대 암살자", "비밀결사대 요술사", "비밀결사대 노상강도"}}},
    [6844] = {n="기록관 움버", d="달의 숲의 나이트헤이븐 마을에 있는 세나리온 의회의 기록관, 움버에게 딱딱한 실리시드 조각을 가져가야 합니다."},
    [6845] = {n="과거의 비밀 밝히기", d="달의 숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다."},
    [6921] = {n="폐허 사이로", d="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.", objs={"심연의 돌"}},
    [6922] = {n="군주 아쿠아니스", d="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."},
    [6981] = {n="빛나는 조각", d="톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오.\n그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.", tgo={{"스퍼터밸브"}}},
    [7003] = {n="변형된 거인", d="페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 15개를 가져가야 합니다.", tgo={{"평지거인", "절벽거인", "성큼걸이 해안거인"}}},
    [7028] = {n="뒤틀린 악마", d="트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.", tgo={{"저주받은 켄타우로스", "타락의 사티로스", "타락의 요술사"}}},
    [7029] = {n="바일텅의 타락", d="마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.\n오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.\n녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다.", tgo={{"녹시온의 후예"}, {}}, objs={"마라우돈 주황색 수정 웅덩이"}},
    [7044] = {n="마라우돈의 전설", d="<name>레브라스의 홀 조각인 <name>레브리안 마법봉과 <name>레브리안 다이아몬드를 찾아야 합니다.\n<name>레브라스와 대화를 나눌 방법을 찾아야 합니다.", tgo={{"군주 바일텅"}, {"녹시온", "녹시온의 피조물"}}},
    [7046] = {n="셀레브라스의 홀", d="회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.\n의식을 마친 후 그와 대화하십시오.", objs={"Incantation of Celebras"}},
    [7064] = {n="대지와 씨앗의 오염", d="공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.", tgo={{"공주 테라드라스"}}},
    [7066] = {n="생명의 씨앗", d="달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다."},
    [7067] = {n="추방자의 지시서", d="추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다."},
    [7068] = {n="음영석 조각", d="마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다.", tgo={{"우레의 음영석정령", "분쇄의 음영석정령", "천둥의 음영석정령"}}},
    [7201] = {n="마지막 원소", d="검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다.", tgo={{"뜨겁게 달궈진 전투골렘", "맹위의 전투골렘", "재앙의 피조물"}}},
    [7441] = {n="푸실린과 노쇠한 아즈토르딘", d="혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.\n마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다.", tgo={{"푸실린"}}},
    [7461] = {n="내면의 광기", d="이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.\n이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오.\n이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다.", tgo={{"이몰타르"}, {"왕자 토르텔드린"}}},
    [7463] = {n="신비의 원기 회복 주문", d="혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.", tgo={{"히드로스폰"}}},
    [7481] = {n="엘프의 전설", d="혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.", objs={"텔미우스 드림시커의 유해"}},
    [7489] = {n="레스텐드리스의 그물", d="페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.", tgo={{"레스텐드리스"}}},
    [7492] = {n="모자케 야영지", d="페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오."},
    [7498] = {n="가로나: 은신과 기만에 대한 연구", d="주인에게 책을 되돌려주십시오."},
    [7499] = {n="방어의 고서", d="주인에게 책을 되돌려주십시오."},
    [7500] = {n="신비술사의 요리책", d="주인에게 책을 되돌려주십시오."},
    [7501] = {n="빛과 정의에 관하여", d="주인에게 책을 되돌려주십시오."},
    [7502] = {n="지배의 그림자", d="주인에게 책을 되돌려주십시오."},
    [7503] = {n="사냥꾼의 위대한 혈통", d="주인에게 책을 되돌려주십시오."},
    [7504] = {n="성스러운 볼로냐: 빛이 알려주지 않는 것들", d="주인에게 책을 되돌려주십시오."},
    [7505] = {n="냉기 충격과 주술", d="주인에게 책을 되돌려주십시오."},
    [7506] = {n="에메랄드의 꿈...", d="주인에게 책을 되돌려주십시오."},
    [7601] = {n="나이비께서 명하사", d="악령의 숲에 있는 임프시와 대화하십시오."},
    [7602] = {n="완전무결한 지옥의 정수", d="악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다.\n아즈샤라에는 레가쉬 사티로스들, 자에데나르에는 자에데나르 부대원들, 그리고 저주받은 땅에서는 지옥군단병 보초들이 각기 그 지역의 완전무결한 지옥의 정수를 갖고 있습니다.\n완전무결한 지옥의 정수 3개를 다 모은 다음에는 악령의 숲에 있는 임프시에게 돌아가야 합니다.", tgo={{"레가쉬 사티로스", "레가쉬 도적", "레가쉬 지옥소환사"}, {"자에데나르 부대원"}, {"지옥군단병 보초"}}},
    [7603] = {n="크로쉬우스의 지옥핵", d="악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.\n크로쉬우스의 지옥핵을 악령의 숲에 있는 전지전능한 나이비에게 가져다주십시오.", tgo={{"크로쉬우스"}, {"크로쉬우스"}}},
    [7701] = {n="현상수배: 감독관 말토류스", d="이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다.", tgo={{"감독관 말토류스"}}},
    [7721] = {n="변환을 위한 연료", d="페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 10개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다.", tgo={{"바다 정령", "바다 물보라 정령"}}},
    [7722] = {n="불꽃 융해촉진제?", d="용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다.", objs={"비밀조제법: 불꽃 융해촉진제"}},
    [7723] = {n="두꺼운 손가락의 슬픔", d="이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", tgo={{"육중한 전투골렘"}}},
    [7724] = {n="뒤꽁무니에서 불을 뿜는 거미", d="이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다.\n불타는 용암거미를 충분히 처치한 후에는 이글거리는 협곡에 있는 한셀 헤비핸드에게 가야 합니다.", tgo={{"불타는 용암거미"}}},
    [7727] = {n="인센도사우루스라니 무슨...", d="용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", tgo={{"인센도사우루스"}}},
    [7728] = {n="도난품: 가열로 바람구멍 및 감시병의 망원경", d="이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다.\n이 물건들에 대해 가지고 있는 유일한 정보는 다음과 같습니다.\n검은무쇠 드워프들이 훔쳐간 것이 분명합니다.\n가열로 바람구멍은 대장장이들이 사용하는 대장 도구입니다.\n감시병의 망원경은 감시병들에게 값으로 따질 수 없을 만큼 중요한 감시 도구입니다.", tgo={{"검은무쇠단 증기기술자"}, {"검은무쇠단 망꾼"}}},
    [7729] = {n="구인광고: 경쟁 선별", d="검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다.", tgo={{"검은무쇠단 감독관"}, {"검은무쇠단 노예상인"}}},
    [7730] = {n="주크애쉬 출몰", d="페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다.", tgo={{"독침 주크애쉬", "병정 주크애쉬", "일꾼 주크애쉬"}}},
    [7731] = {n="채찍쐐기", d="고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다.", tgo={{"채찍쐐기"}}},
    [7732] = {n="주크애쉬 보고서", d="오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다."},
    [7734] = {n="품질 향상", d="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다.", tgo={{"분노한 무쇠설인", "덩치큰 무쇠설인", "사나운 무쇠설인"}}},
    [7738] = {n="완전한 설인 가죽", d="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다."},
    [7761] = {n="블랙핸드의 명령서", d="아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다.\n이 편지에 따르면 드라키사스 사령관이 낙인을 지키고 있다고 하니 조사해 보는 것이 좋겠습니다."},
    [7815] = {n="무쇠턱바다거북 처치", d="무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.", tgo={{"무쇠턱바다거북"}}},
    [7816] = {n="감메리타 처치", d="감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.\n카툼이 감메리타는 해안에서 다른 거북들과 함께 있다고 얘기해 줬습니다.", tgo={{"감메리타"}}},
    [7828] = {n="은빛갈기늑대 추적", d="긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.\n마코르가 이 늑대들은 동부 내륙지의 황야에 숨어 있다고 얘기해 줬습니다.", tgo={{"긴발톱 은빛갈기늑대"}, {"긴울음 은빛갈기늑대"}}},
    [7829] = {n="포악한 올빼미야수 사냥", d="포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.\n마코르가 포악한 올빼미야수는 동부 내륙지의 황야에 서식한다고 얘기해 줬습니다.", tgo={{"포악한 올빼미야수"}}},
    [7830] = {n="트롤의 복수", d="우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다.\n마코르의 얘기로는 우두머리 뾰족부리그리핀은 주로 동부 내륙지의 황야에 서식하는 희귀종이라고 합니다.", tgo={{"우두머리 뾰족부리그리핀"}}},
    [7839] = {n="썩은가지부족 불량배", d="동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다.\n대장장이 슬래그트리의 말에 의하면 그 도구들은 동부 내륙지의 북동쪽 지역에 있는 썩은가지부족 신전들 중 하나에 있을 것이라고 얘기했으며 굼벵이 바위굴도 조사해 보는 것이 좋겠습니다.", objs={"잃어버린 슬래그트리의 연장"}},
    [7840] = {n="잃어버린 라드의 점심", d="동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니<name>.\n라드가 점심을 북쪽에 있는 섬에 두고왔<name>고 했습니<name>. 썩은가지부족 트롤을 조심하십시오.", tgo={{"썩은가지부족 약탈자"}}},
    [7845] = {n="납치된 장로 쏜터스크!", d="동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니<name>.\n장로 쏜터스크는 동부 내륙지의 남쪽에 위치한 썩은가지부족의 수도인 진타알로의 꼭대기에 갇혀 있<name>고 합니<name>."},
    [7846] = {n="열쇠를 찾아서", d="수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다.", tgo={{"수호자 히타야"}}},
    [7847] = {n="주술사 쏜터스크에게로", d="장로 쏜터스크가 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가서 자신이 진타알로에서 풀려났다는 사실을 전해 달라고 부탁했습니다."},
    [7848] = {n="심장부와의 조화", d="검은바위 나락의 화산 심장부 입구에 있는 차원의 문으로 가서 핵 조각을 하나 찾아야 합니다. 핵 조각을 가지고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오.", objs={"핵 조각"}},
    [7849] = {n="동생의 유골", d="레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니<name>.\n마코르가 말하기를 썩은가지부족의 수액괴물과 늑대들이 동생의 유골을 훼손하고 있<name>고 합니<name>. 또한 진타알로의 신전 근처에는 수액괴물이 가득한 쓰레기 폐허와 늑대 우리가 있<name>고 합니<name>.", objs={"해골 더미", "뼈 더미"}},
    [7850] = {n="어둠의 용기", d="진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니<name>.", objs={"얼룩진 피가 담긴 용기"}},
    [7861] = {n="현상 수배: 타락한 여사제 헥스와 그녀의 부하", d="타락한 여사제 헥스와 썩은가지부족 아만자시 경비병 20명을 해치운 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크와 대화해야 합니<name>.\n동부 내륙지의 진타알로 꼭대기에 가면 타락한 여사제 헥스와 아만자시 경비병을 찾을 수 있습니<name>.", tgo={{"타락한 여사제 헥스"}, {"썩은가지부족 아만자시 경비병"}}},
    [7862] = {n="구인광고: 레반터스크 마을의 경비대장", d="썩은가지부족 광전사 20명, 썩은가지부족 어둠사냥꾼 20명, 썩은가지부족 혈투사 20명, 썩은가지부족 영혼사냥꾼 20명을 처치한 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가야 합니<name>.", tgo={{"썩은가지부족 광전사"}, {"썩은가지부족 어둠사냥꾼"}, {"썩은가지부족 혈투사"}, {"썩은가지부족 영혼사냥꾼"}}, star={"수호대장의 룬", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="셴드랄라의 보물", d="도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!"},
    [8151] = {n="사냥꾼의 부적", d="아즈샤라에 있는 오그틴크와 대화해야 합니다."},
    [8153] = {n="순록 뿔", d="아즈샤라에 있는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 완전한 순록 뿔 한 쌍을 가져가야 합니다.", tgo={{"덩치큰 이끼발굽순록"}}},
    [8231] = {n="폭풍히드라 사냥", d="아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져가야 합니다.", tgo={{"어린 폭풍히드라", "폭풍히드라", "거대한 폭풍히드라"}}},
    [8232] = {n="녹색 비룡 몰파즈", d="아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다.", tgo={{"몰파즈"}}, star={"데빌사우루스 눈", {"HUNTER"}}},
    [8233] = {n="간단한 부탁", d="라벤홀트 장원에 있는 조라크 라벤홀트 경과 대화해야 합니다."},
    [8234] = {n="봉인된 하늘색 자루", d="아즈샤라에 있는 나무구렁일족 주술사에게서 봉인된 하늘색 자루를 되찾은 후, 그 가방을 아즈샤라에 있는 대마법사 실렘에게 가져가야 합니다.", tgo={{"나무구렁일족 주술사", "검은아귀 주술사"}}},
    [8235] = {n="암호화된 페이지", d="아즈샤라에 있는 대마법사 실렘에게 암호화 된 페이지 10개를 가져가야 합니다.", tgo={{"숲수액괴물"}}},
    [8236] = {n="하늘색 열쇠", d="조라크 라벤홀트 경에게 하늘색 열쇠를 가져가야 합니다.", tgo={{"몰파즈"}}, star={"그늘박쥐 망토", {"ROGUE"}}},
    [8250] = {n="마법 공예", d="대마법사 실렘을 만나기 위한 허가를 얻기 위해 사나스 림요를 찾아야 합니다."},
    [8251] = {n="마법의 티끌", d="대마법사 실렘에게 반짝이는 가루 10개를 가져가야 합니다.", tgo={{"블러드 엘프 감정관", "블러드 엘프 수색꾼", "블러드 엘프 파수병"}}},
    [8252] = {n="세이렌의 산호", d="대마법사 실렘에게 마력 깃든 산호 6개를 가져가야 합니다.", tgo={{"원한의꼬리일족 세이렌"}}},
    [8253] = {n="몰파즈 처치", d="몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다.", tgo={{"몰파즈"}}, star={"화염 루비", {"MAGE"}}},
